

SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;


CREATE SCHEMA IF NOT EXISTS "eshop";


ALTER SCHEMA "eshop" OWNER TO "postgres";


CREATE SCHEMA IF NOT EXISTS "public";


ALTER SCHEMA "public" OWNER TO "pg_database_owner";


COMMENT ON SCHEMA "public" IS 'standard public schema';



CREATE OR REPLACE FUNCTION "eshop"."get_products_for_ticket_all_available"("ticket_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_occasion_id bigint;
  v_available   jsonb;
BEGIN
  -- find the ticket’s occasion
  SELECT occasion
  INTO   v_occasion_id
  FROM   eshop.tickets
  WHERE  id = ticket_id;

  IF NOT FOUND OR v_occasion_id IS NULL THEN
    RETURN jsonb_build_object(
      'code',    404,
      'message', 'Ticket not found'
    );
  END IF;

  IF NOT get_is_editor_order_view_on_occasion(v_occasion_id) THEN
    RETURN jsonb_build_object(
      'code',    403,
      'message', 'Not authorized'
    );
  END IF;

  -- aggregate all products for that occasion
  SELECT jsonb_agg(
           jsonb_build_object(
             'id',            p.id,
             'title',         p.title,
             'price',         p.price,
             'currency_code', p.currency_code,
             'type_title',    pt.title
           )
         )
  INTO   v_available
  FROM   eshop.products p
  LEFT JOIN eshop.product_types pt
    ON pt.id = p.product_type
  WHERE  p.occasion = v_occasion_id;

  RETURN jsonb_build_object(
    'code', 200,
    'data', COALESCE(v_available, '[]'::jsonb)
  );
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object(
    'code',    500,
    'message', SQLERRM
  );
END;
$$;


ALTER FUNCTION "eshop"."get_products_for_ticket_all_available"("ticket_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_swap_spots_generate_product_json"("p_product_id" bigint, "p_spot_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    AS $$
DECLARE
    product_data RECORD;
BEGIN
    -- This query joins product, its type, and the spot (if provided)
    -- to get all data needed for the JSON object.
    SELECT
        p.id,
        p.price,
        p.title,
        p.description,
        p.currency_code,
        pt.title AS type_title,
        pt.type AS type,
        s.title AS spot_title
    INTO
        product_data
    FROM
        eshop.products AS p
    JOIN
        eshop.product_types AS pt ON p.product_type = pt.id
    LEFT JOIN
        eshop.spots AS s ON s.id = p_spot_id -- Use p_spot_id for spot_title
    WHERE
        p.id = p_product_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Product data not found for product_id %', p_product_id;
    END IF;

    -- Build the JSON object.
    -- jsonb_strip_nulls ensures that if 'spot_title' is NULL
    -- (because p_spot_id was NULL), the key is removed entirely.
    RETURN jsonb_strip_nulls(jsonb_build_object(
        'id', product_data.id,
        'type', product_data.type,
        'price', product_data.price,
        'title', product_data.title,
        'spot_title', product_data.spot_title,
        'type_title', product_data.type_title,
        'description', product_data.description,
        'currency_code', product_data.currency_code
    ));
END;
$$;


ALTER FUNCTION "public"."_swap_spots_generate_product_json"("p_product_id" bigint, "p_spot_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_swap_spots_update_ticket"("p_opt_id" bigint, "p_new_product_id" bigint, "p_new_spot_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    opt RECORD;
    ord RECORD;
    original_product_id BIGINT;
    original_product_json JSONB;
    original_price NUMERIC;

    new_product_json JSONB;
    new_price NUMERIC;
    new_data JSONB;
    new_order_price NUMERIC;
    new_state TEXT;

    price_delta NUMERIC;
    history_needed BOOLEAN;
    now_time TIMESTAMP WITH TIME ZONE := NOW();
BEGIN
    -- 1. Get current ticket and order data
    SELECT * INTO opt FROM eshop.order_product_ticket WHERE id = p_opt_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Order Product Ticket % not found', p_opt_id; END IF;

    SELECT * INTO ord FROM eshop.orders WHERE id = opt."order";
    IF NOT FOUND THEN RAISE EXCEPTION 'Order % not found', opt."order"; END IF;

    original_product_id := opt.product;

    -- 2. Find the *original* product JSON and price from the orders.data
    SELECT prod, (prod->>'price')::numeric
    INTO original_product_json, original_price
    FROM jsonb_array_elements(ord.data->'tickets') tckt,
         jsonb_array_elements(tckt->'products') prod
    WHERE (tckt->>'id')::bigint = opt.ticket
      AND (prod->>'id')::bigint = original_product_id;

    IF original_price IS NULL THEN
        RAISE EXCEPTION 'Could not find original price for product % on ticket %', original_product_id, opt.ticket;
    END IF;

    -- 3. Generate the *new* product JSON
    new_product_json := public._swap_spots_generate_product_json(p_new_product_id, p_new_spot_id);
    new_price := (new_product_json->>'price')::numeric;

    -- 4. Check if an update is even needed.
    -- If the new JSON is identical to the old, nothing needs to be done.
    IF original_product_json = new_product_json THEN
        RETURN;
    END IF;

    -- 5. Calculate financials and state
    price_delta := new_price - original_price;
    history_needed := (original_product_id IS DISTINCT FROM p_new_product_id);
    new_order_price := COALESCE(ord.price, 0) + price_delta;

    -- Recalculate order state
    SELECT CASE
        WHEN COALESCE(pi.paid, 0) >= new_order_price AND new_order_price > 0 THEN 'paid'
        WHEN new_order_price <= 0 THEN 'paid'
        ELSE 'ordered'
    END INTO new_state
    FROM eshop.payment_info pi WHERE pi.id = ord.payment_info;

    -- 6. Build the new orders.data JSON
    new_data := jsonb_set(
        ord.data,
        '{tickets}',
        (SELECT jsonb_agg(
            -- Find the matching ticket
            CASE WHEN (tckt->>'id')::bigint = opt.ticket
            THEN jsonb_set(
                tckt,
                '{products}',
                (SELECT jsonb_agg(
                    -- Find the matching product and replace it
                    CASE
                        WHEN (prod->>'id')::bigint = original_product_id
                        THEN new_product_json -- Swap in the new product JSON
                        ELSE prod
                    END
                ) FROM jsonb_array_elements(tckt->'products') prod)
            )
            ELSE tckt
            END
        ) FROM jsonb_array_elements(ord.data->'tickets') tckt)
    );

    -- 7. Perform all database updates

    -- Update payment info
    IF price_delta <> 0 THEN
        UPDATE eshop.payment_info SET amount = amount + price_delta WHERE id = ord.payment_info;
    END IF;

    -- Update the order itself
    UPDATE eshop.orders
    SET
        price = new_order_price,
        data = new_data,
        state = new_state,
        updated_at = now_time
    WHERE id = ord.id;

    -- Update the link table
    UPDATE eshop.order_product_ticket
    SET
        product = p_new_product_id
    WHERE id = p_opt_id;

    -- 8. Create history log *only if* the product ID actually changed
    IF history_needed THEN
        INSERT INTO eshop.orders_history("order", data, state, price, currency_code)
        VALUES (ord.id, new_data, new_state, new_order_price, ord.currency_code);
    END IF;

END;
$$;


ALTER FUNCTION "public"."_swap_spots_update_ticket"("p_opt_id" bigint, "p_new_product_id" bigint, "p_new_spot_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_image_record"("p_link" "text", "p_occasion_id" bigint, "p_unit_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    -- Permission Check
    IF p_unit_id IS NOT NULL THEN
        -- Unit Editor
        IF (SELECT public.get_is_editor_on_unit(p_unit_id)) IS NOT TRUE THEN
            RAISE EXCEPTION 'Permission denied: User is not an editor of this unit.';
        END IF;
    ELSIF p_occasion_id IS NOT NULL THEN
        -- Occasion Editor OR Occasion Order Editor
        IF (public.get_is_editor_on_occasion(p_occasion_id)) IS NOT TRUE
           AND (public.get_is_editor_order_on_occasion(p_occasion_id)) IS NOT TRUE THEN
             RAISE EXCEPTION 'Permission denied: User is not an editor/order-editor of this occasion.';
        END IF;
    ELSE
        RAISE EXCEPTION 'Entity ID (unit or occasion) must be provided.';
    END IF;

    -- Insert Record
    INSERT INTO public.images (link, occasion, unit)
    VALUES (p_link, p_occasion_id, p_unit_id);
END;
$$;


ALTER FUNCTION "public"."add_image_record"("p_link" "text", "p_occasion_id" bigint, "p_unit_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_sent_to_customer_flag"("history_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  UPDATE eshop.orders_history
  SET
    -- Coalesce ensures that if data is NULL, it starts with an empty JSON object
    -- before merging. The || operator merges the two JSONB objects.
    data = COALESCE(data, '{}'::jsonb) || '{"is_sent_to_customer": true}'::jsonb
  WHERE
    id = history_id;
END;
$$;


ALTER FUNCTION "public"."add_sent_to_customer_flag"("history_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_sync_map"("p_source_name" "text", "p_target_org_id" bigint, "p_target_unit_id" bigint, "p_remote_link_base" "text", "p_remote_org_id" bigint DEFAULT NULL::bigint, "p_remote_unit_id" bigint DEFAULT NULL::bigint) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    -- Security Check
    IF auth.role() <> 'service_role' AND session_user <> 'postgres' THEN
        RAISE EXCEPTION 'Access Denied: Service role required.';
    END IF;

    INSERT INTO public.external_sync_maps
    (source_name, target_org_id, target_unit_id, remote_link_base, remote_org_id, remote_unit_id)
    VALUES
    (p_source_name, p_target_org_id, p_target_unit_id, p_remote_link_base, p_remote_org_id, p_remote_unit_id);
    RETURN 'Map added.';
END;
$$;


ALTER FUNCTION "public"."add_sync_map"("p_source_name" "text", "p_target_org_id" bigint, "p_target_unit_id" bigint, "p_remote_link_base" "text", "p_remote_org_id" bigint, "p_remote_unit_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_transaction_to_payment_info"("p_transaction_id" bigint, "payment_info_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    transaction_amount numeric(12, 2);
    transaction_currency character(3);
    payment_info_currency character(3);
    payment_info_record eshop.payment_info%ROWTYPE;
    associated_order_id bigint;
BEGIN
    -- Check if the transaction already has a payment_info assigned
    IF EXISTS (
        SELECT 1
        FROM eshop.transactions
        WHERE id = p_transaction_id
          AND payment_info IS NOT NULL
    ) THEN
        RAISE EXCEPTION 'Transaction already linked to a payment_info';
    END IF;

    -- Retrieve the transaction amount and currency
    SELECT t.amount, t.currency
    INTO transaction_amount, transaction_currency
    FROM eshop.transactions t
    WHERE t.id = p_transaction_id;

    -- Retrieve the payment_info currency_code
    SELECT pi.currency_code
    INTO payment_info_currency
    FROM eshop.payment_info pi
    WHERE pi.id = payment_info_id;

    -- Check if currencies match
    IF transaction_currency != payment_info_currency THEN
        RAISE EXCEPTION 'Currency mismatch: Transaction currency (%) does not match Payment Info currency (%)', transaction_currency, payment_info_currency;
    END IF;

    -- Update the paid or returned column based on the transaction amount
    IF transaction_amount > 0 THEN
        UPDATE eshop.payment_info
        SET paid = COALESCE(paid, 0) + transaction_amount
        WHERE id = payment_info_id;
    ELSE
        UPDATE eshop.payment_info
        SET returned = COALESCE(returned, 0) + ABS(transaction_amount)
        WHERE id = payment_info_id;
    END IF;

    -- Fetch the updated payment_info record (for logging or return if needed, but primarily we need order id now)
    SELECT *
    INTO payment_info_record
    FROM eshop.payment_info
    WHERE id = payment_info_id;

    -- Find the associated order ID
    SELECT o.id
    INTO associated_order_id
    FROM eshop.orders o
    WHERE o.payment_info = payment_info_id
    LIMIT 1;

    -- Call the Unified Helper to resolve state
    IF associated_order_id IS NOT NULL THEN
        PERFORM public.recalculate_order_payment_status(associated_order_id);
    END IF;

    -- Update the transaction's payment_info reference
    UPDATE eshop.transactions
    SET payment_info = payment_info_id
    WHERE id = p_transaction_id;
END;
$$;


ALTER FUNCTION "public"."add_transaction_to_payment_info"("p_transaction_id" bigint, "payment_info_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_transaction_to_payment_info_ws"("p_transaction_id" bigint, "p_payment_info_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    bank_acc bigint;
    occasion_id bigint;
BEGIN
    -- Retrieve the associated order_id from payment_info
    SELECT pi.bank_account INTO bank_acc
    FROM eshop.payment_info pi
    WHERE pi.id = p_payment_info_id
    LIMIT 1;

    PERFORM public.check_is_admin_for_bank_account(bank_acc);

    SELECT o.occasion
    INTO occasion_id
    FROM eshop.orders o
    WHERE o.payment_info = p_payment_info_id
    LIMIT 1;

    PERFORM public.check_is_editor_order_on_occasion(occasion_id);

    -- Call the original function to add the transaction
    PERFORM public.add_transaction_to_payment_info(p_transaction_id, p_payment_info_id);

    -- Return success message
    RETURN jsonb_build_object(
        'code', 200,
        'message', 'Transaction added successfully.'
    );

EXCEPTION WHEN OTHERS THEN
    -- Handle any exceptions and return as JSON
    RETURN jsonb_build_object(
        'code', 500,
        'message', SQLERRM,
        'detail', COALESCE(SQLERRM, 'An unexpected error occurred.')
    );
END;
$$;


ALTER FUNCTION "public"."add_transaction_to_payment_info_ws"("p_transaction_id" bigint, "p_payment_info_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_user_to_occasion"("oc" bigint, "usr" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_response jsonb;
BEGIN
  v_response:=public.add_user_to_occasion_client_sync_v1(
    oc,usr,extensions.gen_random_uuid());
  RETURN jsonb_build_object('code',(v_response->>'code')::integer)
    ||COALESCE(v_response->'data','{}'::jsonb);
END; $$;


ALTER FUNCTION "public"."add_user_to_occasion"("oc" bigint, "usr" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_user_to_occasion_client_sync_v1"("p_occasion" bigint, "p_user" "uuid", "p_command_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_actor uuid:=auth.uid(); v_begin jsonb; v_hash text; v_before jsonb;
  v_after jsonb; v_result jsonb; v_version bigint; v_replacements jsonb:='[]';
BEGIN
  IF v_actor IS NULL OR p_user IS NULL OR NOT (
    v_actor=p_user OR public.get_is_manager_on_occasion(p_occasion)
    OR public.get_is_admin_on_occasion(p_occasion)) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion membership permission required';
  END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',p_occasion,'userId',p_user)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'profile.membership.ensure',p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  SELECT to_jsonb(ou) INTO v_before FROM public.occasion_users ou
    WHERE ou.occasion=p_occasion AND ou."user"=p_user FOR UPDATE;
  v_result:=public.add_user_to_occasion_internal_v1(p_occasion,p_user);
  IF COALESCE((v_result->>'code')::integer,500)<>200 THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',
      COALESCE((v_result->>'code')::integer,400),v_result); END IF;
  SELECT to_jsonb(ou) INTO v_after FROM public.occasion_users ou
    WHERE ou.occasion=p_occasion AND ou."user"=p_user;
  SELECT COALESCE(v.version,0) INTO v_version FROM (SELECT 1) seed
    LEFT JOIN public.client_aggregate_versions v
      ON v.aggregate_type='occasion_user' AND v.scope_type='occasion'
      AND v.scope_id=p_occasion AND v.aggregate_id=p_user::text;
  IF v_before IS NOT DISTINCT FROM v_after THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
      jsonb_build_object('version',v_version,'userId',p_user)); END IF;
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES ('occasion_user','occasion',p_occasion,p_user::text,1)
  ON CONFLICT (aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE
    SET version=public.client_aggregate_versions.version+1,
      updated_at=clock_timestamp() RETURNING version INTO v_version;
  IF v_actor=p_user THEN v_replacements:=jsonb_build_array(jsonb_build_object(
    'component','private_profile','userId',p_user,
    'payload',public.get_private_profile_payload_v1(p_occasion,p_user))); END IF;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'profile.membership.ensure','profile',jsonb_build_array(jsonb_build_object(
      'entityType','occasion_user','entityId',p_user,'operation',
      CASE WHEN v_before IS NULL THEN 'insert' ELSE 'update' END,
      'safeLabel','Occasion membership','changedFields',jsonb_build_array(
        'membership','rights'))),'{}',jsonb_build_array(jsonb_build_object(
          'component','private_profile','userId',p_user)),'[]',
    jsonb_build_object('version',v_version,'userId',p_user),
    '{}','[]','user',NULL,v_replacements);
END; $$;


ALTER FUNCTION "public"."add_user_to_occasion_client_sync_v1"("p_occasion" bigint, "p_user" "uuid", "p_command_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_user_to_occasion_internal_v1"("oc" bigint, "usr" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
    occasion_open         BOOLEAN;
    user_data             JSONB;
    user_exists           BOOLEAN;
    user_org              BIGINT;
    occasion_org          BIGINT;
    unit_id               BIGINT;

    -- Initialize flags (though SELECT INTO will overwrite these with NULL if no row found)
    unit_is_manager       BOOLEAN := false;
    unit_is_editor        BOOLEAN := false;
    unit_is_editor_view   BOOLEAN := false;

    is_privileged         BOOLEAN := false;
BEGIN
    -- 1. Retrieve the organization, the unit, and the open status of the occasion.
    SELECT organization, unit, is_open
      INTO occasion_org, unit_id, occasion_open
      FROM occasions
     WHERE id = oc;

    -- 2. Get the organization of the user.
    SELECT organization
      INTO user_org
      FROM user_info
     WHERE id = usr;

    -- 3. Ensure the user and the occasion belong to the same organization.
    IF user_org IS DISTINCT FROM occasion_org THEN
        RETURN jsonb_build_object(
                  'code', 403,
                  'message', 'User does not belong to the same organization as the occasion'
              );
    END IF;

    -- 4. Retrieve the unit-level role information from unit_users.
    SELECT is_manager, is_editor, is_editor_view
      INTO unit_is_manager, unit_is_editor, unit_is_editor_view
      FROM unit_users
     WHERE unit = unit_id AND "user" = usr;

    -- CRITICAL FIX: SELECT INTO sets variables to NULL if no row is found.
    -- We must ensure they are boolean FALSE to satisfy NOT NULL constraints later.
    unit_is_manager     := COALESCE(unit_is_manager, false);
    unit_is_editor      := COALESCE(unit_is_editor, false);
    unit_is_editor_view := COALESCE(unit_is_editor_view, false);

    -- 5. Define is_privileged.
    --    User is privileged if they have specific unit roles OR are an admin on the occasion.
    is_privileged := unit_is_manager
                     OR unit_is_editor
                     OR unit_is_editor_view
                     OR (SELECT get_is_admin_on_occasion(oc));

    -- 6. Permission Check: Closed Occasions.
    --    If the occasion is not open, only privileged users can be added/modified.
    IF NOT occasion_open AND NOT is_privileged THEN
        RETURN jsonb_build_object('code', 403);
    END IF;

    -- 7. Retrieve the user info and build a JSON object merging any existing data.
    SELECT COALESCE(ui.data, '{}'::jsonb) || jsonb_build_object(
                'name', ui.name,
                'surname', ui.surname,
                'sex', ui.sex,
                'email', ui.email_readonly
           )
      INTO user_data
      FROM user_info ui
     WHERE ui.id = usr;

    -- 8. Check if the user already exists in the occasion_users table.
    SELECT EXISTS (
             SELECT 1
               FROM occasion_users
              WHERE occasion = oc AND "user" = usr
           ) INTO user_exists;

    IF user_exists THEN
        -- Update the existing row with the new data and the unit role flags.
        UPDATE occasion_users
           SET data           = user_data,
               is_manager     = unit_is_manager,
               is_editor      = unit_is_editor,
               is_editor_view = unit_is_editor_view,
               is_editor_order = unit_is_editor,
               is_editor_order_view = unit_is_editor_view
         WHERE occasion = oc AND "user" = usr;
    ELSE
        -- Insert a new row into occasion_users, using the unit-level role flags.
        INSERT INTO occasion_users (
            occasion,
            "user",
            created_at,
            is_editor,
            is_manager,
            is_editor_view,
            is_editor_order,
            is_editor_order_view,
            is_approved,
            is_approver,
            data,
            role
        )
        VALUES (
            oc,
            usr,
            now(),
            unit_is_editor,
            unit_is_manager,
            unit_is_editor_view,
            unit_is_editor,
            unit_is_editor_view,
            FALSE,
            FALSE,
            user_data,
            NULL
        );
    END IF;

    RETURN jsonb_build_object('code', 200);
END;
$$;


ALTER FUNCTION "public"."add_user_to_occasion_internal_v1"("oc" bigint, "usr" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_user_to_unit"("unit_id" bigint, "usr" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    unit_org BIGINT;
    user_org BIGINT;
    user_exists BOOLEAN;
BEGIN
    -- Get the organization ID of the unit
    SELECT organization INTO unit_org
    FROM public.units
    WHERE id = unit_id;

    IF unit_org IS NULL THEN
      RAISE EXCEPTION 'Unit % not found', unit_id;
    END IF;

    -- Get the organization ID of the user
    SELECT organization INTO user_org
    FROM public.user_info
    WHERE id = usr;

    IF user_org IS NULL THEN
      RAISE EXCEPTION 'User % not found', usr;
    END IF;

    -- Check if the user and unit belong to the same organization
    IF user_org IS DISTINCT FROM unit_org THEN
        RAISE EXCEPTION 'User does not belong to the same organization as the unit';
    END IF;

    -- Check if the user already exists in the unit_users table
    SELECT EXISTS (
        SELECT 1
        FROM public.unit_users
        WHERE unit = unit_id AND "user" = usr
    ) INTO user_exists;

    -- If the user already exists, update the existing row; otherwise, insert a new one
    IF NOT user_exists THEN
        INSERT INTO public.unit_users (
                    unit,
                    "user",
                    created_at,
                    is_editor,
                    is_manager
                )
                VALUES (
                    unit_id,
                    usr,
                    now(),    -- Set created_at to current timestamp
                    FALSE,    -- Default value for is_editor
                    FALSE    -- Default value for is_manager
                );
    END IF;

    -- Return a successful JSON response
    RETURN jsonb_build_object('code', 200, 'message', 'User added/updated successfully');
EXCEPTION WHEN OTHERS THEN
    RAISE;
END;
$$;


ALTER FUNCTION "public"."add_user_to_unit"("unit_id" bigint, "usr" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."adjust_spot_capacity_for_pool"("p_inventory_pool_id" bigint) RETURNS integer
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    v_context RECORD;
    v_resource RECORD;
    v_spots_to_create BIGINT;
    v_spots_to_delete BIGINT;
    v_booked_spots_count BIGINT;
    v_total_spots_count BIGINT;
    v_deletable_spot_ids BIGINT[];
    v_net_change INTEGER := 0;
    v_pool_occasion_id BIGINT;
    v_total_pool_capacity BIGINT;
BEGIN
    -- Step 0: Validate input and get occasion ID.
    SELECT occasion INTO v_pool_occasion_id FROM public.inventory_pools WHERE id = p_inventory_pool_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION '%', jsonb_build_object('code', 'P001', 'message', 'Inventory pool with ID ' || p_inventory_pool_id || ' not found.')::text;
    END IF;

    -- Calculate the total capacity for the entire pool once. This is the target for the generic pool.
    SELECT COALESCE(SUM(capacity), 0) INTO v_total_pool_capacity
    FROM public.resources
    WHERE inventory_pool = p_inventory_pool_id;

    -- =================================================================
    -- Main Synchronization Loop (per context)
    -- =================================================================
    FOR v_context IN
        SELECT id FROM public.inventory_contexts WHERE inventory_pool = p_inventory_pool_id
    LOOP
        -- =============================================================
        -- Part A: Cleanup of RESOURCE-SPECIFIC Spots for this context
        -- =============================================================
        FOR v_resource IN
            SELECT id, capacity FROM public.resources WHERE inventory_pool = p_inventory_pool_id
        LOOP
            -- Count spots for the current resource WITHIN the current context.
            SELECT count(*) INTO v_total_spots_count FROM eshop.spots WHERE inventory_context = v_context.id AND resource = v_resource.id;
            SELECT count(*) INTO v_booked_spots_count FROM eshop.spots WHERE inventory_context = v_context.id AND resource = v_resource.id AND order_product_ticket IS NOT NULL;

            IF v_booked_spots_count > v_resource.capacity THEN
                RAISE EXCEPTION '%', jsonb_build_object(
                    'code', 'S001',
                    'message', 'Overbooking detected for specific resource. Manual intervention required.',
                    'details', jsonb_build_object(
                        'contextId', v_context.id,
                        'resourceId', v_resource.id,
                        'bookedSpots', v_booked_spots_count,
                        'capacity', v_resource.capacity
                    )
                )::text;
            END IF;

            IF v_total_spots_count > v_resource.capacity THEN
                v_spots_to_delete := v_total_spots_count - v_resource.capacity;
                SELECT array_agg(id) INTO v_deletable_spot_ids FROM (
                    SELECT id FROM eshop.spots
                    WHERE inventory_context = v_context.id AND resource = v_resource.id AND order_product_ticket IS NULL
                    ORDER BY created_at DESC
                    LIMIT v_spots_to_delete
                ) AS sub;

                IF array_length(v_deletable_spot_ids, 1) < v_spots_to_delete THEN
                     RAISE EXCEPTION '%', jsonb_build_object(
                        'code', 'S002',
                        'message', 'Cannot delete excess resource-specific spots. Deletion would require removing a booked spot.',
                        'details', jsonb_build_object(
                            'contextId', v_context.id,
                            'resourceId', v_resource.id
                        )
                    )::text;
                END IF;

                DELETE FROM eshop.spots WHERE id = ANY(v_deletable_spot_ids);
                v_net_change := v_net_change - v_spots_to_delete;
            END IF;
        END LOOP;

        -- =============================================================
        -- Part B: Management of GENERIC Spot Pool for this context
        -- =============================================================
        -- Count total and booked spots for the GENERIC pool (resource IS NULL) within the current context.
        SELECT count(*) INTO v_total_spots_count FROM eshop.spots WHERE inventory_context = v_context.id;
        SELECT count(*) INTO v_booked_spots_count FROM eshop.spots WHERE inventory_context = v_context.id AND order_product_ticket IS NOT NULL;

        IF v_booked_spots_count > v_total_pool_capacity THEN
            RAISE EXCEPTION '%', jsonb_build_object(
                'code', 'S003',
                'message', 'Overbooking detected for generic pool. Manual intervention required.',
                'details', jsonb_build_object(
                    'contextId', v_context.id,
                    'bookedSpots', v_booked_spots_count,
                    'capacity', v_total_pool_capacity
                )
            )::text;
        END IF;

        -- DELETION of generic spots
        IF v_total_spots_count > v_total_pool_capacity THEN
            v_spots_to_delete := v_total_spots_count - v_total_pool_capacity;
            SELECT array_agg(id) INTO v_deletable_spot_ids FROM (
                SELECT id FROM eshop.spots
                WHERE inventory_context = v_context.id AND resource IS NULL AND order_product_ticket IS NULL
                ORDER BY created_at DESC
                LIMIT v_spots_to_delete
            ) AS sub;

            IF array_length(v_deletable_spot_ids, 1) < v_spots_to_delete THEN
                 RAISE EXCEPTION '%', jsonb_build_object(
                    'code', 'S004',
                    'message', 'Cannot delete excess generic spots. Deletion would require removing a booked spot.',
                    'details', jsonb_build_object(
                        'contextId', v_context.id
                    )
                )::text;
            END IF;

            DELETE FROM eshop.spots WHERE id = ANY(v_deletable_spot_ids);
            v_net_change := v_net_change - v_spots_to_delete;
        END IF;

        -- CREATION of generic spots
        -- Recount after potential deletion to get the current number.
        SELECT count(*) INTO v_total_spots_count FROM eshop.spots WHERE inventory_context = v_context.id;

        IF v_total_spots_count < v_total_pool_capacity THEN
            v_spots_to_create := v_total_pool_capacity - v_total_spots_count;

            -- Insert the required number of new generic spots.
            -- Per instructions, ONLY occasion and inventory_context are set.
            INSERT INTO eshop.spots (occasion, inventory_context)
            SELECT
                v_pool_occasion_id,
                v_context.id
            FROM generate_series(1, v_spots_to_create);

            v_net_change := v_net_change + v_spots_to_create;
        END IF;
    END LOOP;

    RETURN v_net_change;

END;
$$;


ALTER FUNCTION "public"."adjust_spot_capacity_for_pool"("p_inventory_pool_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."analyze_new_order_spots"("p_spot_ids" bigint[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_conflicts jsonb;
  v_new_order_items jsonb;
  v_occasion_id BIGINT;
BEGIN
  -- =======================================================================
  -- 0. VALIDATION & SECURITY
  -- =======================================================================

  -- Handle empty input
  IF p_spot_ids IS NULL OR array_length(p_spot_ids, 1) IS NULL THEN
     RETURN jsonb_build_object('conflicts', '[]'::jsonb, 'new_order_items', '[]'::jsonb);
  END IF;

  -- Get Occasion ID from the first spot
  SELECT occasion INTO v_occasion_id
  FROM eshop.spots
  WHERE id = p_spot_ids[1];

  IF v_occasion_id IS NULL THEN
     RAISE EXCEPTION 'Spot ID % not found.', p_spot_ids[1];
  END IF;

  -- Consistency Check: Ensure all selected spots belong to the SAME occasion
  PERFORM 1
  FROM eshop.spots
  WHERE id = ANY(p_spot_ids)
  AND occasion != v_occasion_id;

  IF FOUND THEN
     RAISE EXCEPTION 'All selected spots must belong to the same occasion.';
  END IF;

  -- Permission Check: User must have "Order View" rights on this occasion
  IF NOT public.get_is_editor_order_view_on_occasion(v_occasion_id) THEN
     RAISE EXCEPTION 'Permission denied. User does not have view rights for occasion %.', v_occasion_id;
  END IF;

  -- =======================================================================
  -- 1. IDENTIFY CONFLICTS
  -- =======================================================================
  WITH impacted_base AS (
    SELECT
      s.id as spot_id,
      o.id as order_id,
      o.data as order_data,
      o.state as order_state,
      t.id as ticket_id,
      t.ticket_symbol
    FROM eshop.spots s
    JOIN eshop.order_product_ticket opt ON s.order_product_ticket = opt.id
    JOIN eshop.tickets t ON opt.ticket = t.id
    JOIN eshop.orders o ON opt.order = o.id
    WHERE s.id = ANY(p_spot_ids)
    -- Include any state that implies the spot is technically "occupied"
  ),
  impacted_enriched AS (
    -- Safely extract the specific ticket from JSON
    SELECT
      ib.*,
      (
        SELECT item
        FROM jsonb_array_elements(ib.order_data->'tickets') item
        WHERE (item->>'id')::bigint = ib.ticket_id
        LIMIT 1
      ) as ticket_json
    FROM impacted_base ib
  ),
  order_stats AS (
    -- Calculate if whole order is cancelled
    SELECT
      order_id,
      COUNT(DISTINCT ticket_id) as affected_ticket_count,
      COALESCE(jsonb_array_length(order_data->'tickets'), 0) as total_ticket_count
    FROM impacted_enriched
    GROUP BY order_id, order_data
  )
  SELECT jsonb_agg(
    jsonb_build_object(
      'order_id', ie.order_id,
      -- Extract individual fields as requested
      'email', ie.order_data->>'email',
      'name', ie.order_data->>'name',
      'surname', ie.order_data->>'surname',
      'note', ie.order_data->>'note',

      'ticket_id', ie.ticket_id,
      'ticket_symbol', ie.ticket_symbol,
      'is_fully_cancelled', (os.affected_ticket_count >= os.total_ticket_count AND os.total_ticket_count > 0),
      -- The products array from the JSON (Spot + Extras)
      'products', ie.ticket_json->'products',
      -- Sum the price (safely handle nulls)
      'total_price', (
         SELECT COALESCE(SUM((prod->>'price')::numeric), 0)
         FROM jsonb_array_elements(ie.ticket_json->'products') prod
      )
    )
  )
  INTO v_conflicts
  FROM impacted_enriched ie
  JOIN order_stats os ON ie.order_id = os.order_id;

  -- =======================================================================
  -- 2. PREPARE NEW ORDER ITEMS
  -- =======================================================================
  SELECT jsonb_agg(jsonb_build_object(
    'spot_id', s.id,
    'spot_title', s.title,
    'product_title', p.title,
    'price', p.price,
    'currency', p.currency_code
  ))
  INTO v_new_order_items
  FROM eshop.spots s
  LEFT JOIN eshop.products p ON s.product = p.id
  WHERE s.id = ANY(p_spot_ids);

  RETURN jsonb_build_object(
    'conflicts', COALESCE(v_conflicts, '[]'::jsonb),
    'new_order_items', COALESCE(v_new_order_items, '[]'::jsonb)
  );
END;
$$;


ALTER FUNCTION "public"."analyze_new_order_spots"("p_spot_ids" bigint[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_allocations"("p_order_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql"
    AS $_$
DECLARE
    v_order_state TEXT;
    v_item_to_allocate RECORD;
    v_existing_spot_count INT;
    v_spots_to_claim INT;
    v_available_spot_id BIGINT;
    v_occasion_id BIGINT;
    v_spots_to_disallocate BIGINT[];
    v_occasion_features JSONB;
    v_is_blueprint_enabled BOOLEAN;
BEGIN
    -- Initial check for the order's state.
    SELECT state, occasion INTO v_order_state, v_occasion_id
    FROM eshop.orders
    WHERE id = p_order_id;

    SELECT features INTO v_occasion_features FROM public.occasions WHERE id = v_occasion_id;
    v_is_blueprint_enabled := jsonb_path_exists(v_occasion_features, '$[*] ? (@.code == "blueprint" && @.is_enabled == true)');

    -- If the order is not found, raise a structured exception.
    IF NOT FOUND THEN
        RAISE EXCEPTION '%', jsonb_build_object('code', 'A001', 'message', 'Order with ID ' || p_order_id || ' not found.')::text;
    END IF;

    -- If the order state is 'storno', disallocate all spots and exit.
    IF v_order_state = 'storno' THEN
        UPDATE eshop.spots
        SET order_product_ticket = NULL, state = NULL, resource = NULL, updated_at = now()
        WHERE order_product_ticket IN (SELECT id FROM eshop.order_product_ticket WHERE "order" = p_order_id);
        RETURN;
    END IF;

    -- Disallocate spots that are no longer required by the order.
    WITH required_spots AS (
        SELECT opt.id as order_product_ticket_id, pic.inventory_context as inventory_context_id, generate_series(1, pic.quantity)
        FROM eshop.order_product_ticket opt
        JOIN eshop.products p ON opt.product = p.id
        JOIN eshop.product_inventory_contexts pic ON p.id = pic.product
        WHERE opt."order" = p_order_id
    ),
    current_spots AS (
        SELECT s.id, s.order_product_ticket, s.inventory_context
        FROM eshop.spots s
        WHERE s.order_product_ticket IN (SELECT id FROM eshop.order_product_ticket WHERE "order" = p_order_id)
    )
    SELECT array_agg(cs.id)
    INTO v_spots_to_disallocate
    FROM current_spots cs
    LEFT JOIN required_spots rs ON cs.order_product_ticket = rs.order_product_ticket_id AND cs.inventory_context = rs.inventory_context_id
    JOIN eshop.order_product_ticket opt ON cs.order_product_ticket = opt.id
    JOIN eshop.products p ON opt.product = p.id
    JOIN eshop.product_types pt ON p.product_type = pt.id
    WHERE rs.order_product_ticket_id IS NULL
      AND NOT (v_is_blueprint_enabled AND pt.type = 'spot');

    IF v_spots_to_disallocate IS NOT NULL AND array_length(v_spots_to_disallocate, 1) > 0 THEN
        UPDATE eshop.spots
        SET order_product_ticket = NULL, state = NULL, resource = NULL, updated_at = now()
        WHERE id = ANY(v_spots_to_disallocate);
    END IF;

    -- Loop through each product in the order that requires an inventory spot to allocate new spots.
    FOR v_item_to_allocate IN
        SELECT
            opt.id AS order_product_ticket_id,
            opt.product AS product_id,
            pic.inventory_context AS inventory_context_id,
            pic.quantity AS required_quantity
        FROM eshop.orders o
        JOIN eshop.order_product_ticket opt ON o.id = opt."order"
        JOIN eshop.products p ON opt.product = p.id
        JOIN eshop.product_inventory_contexts pic ON p.id = pic.product
        WHERE o.id = p_order_id
    LOOP
        -- Check for existing spots for this specific order item AND inventory context.
        SELECT COUNT(*)
        INTO v_existing_spot_count
        FROM eshop.spots s
        WHERE s.order_product_ticket = v_item_to_allocate.order_product_ticket_id
          AND s.inventory_context = v_item_to_allocate.inventory_context_id;

        -- Calculate exactly how many spots are missing.
        v_spots_to_claim := v_item_to_allocate.required_quantity - v_existing_spot_count;

        IF v_spots_to_claim <= 0 THEN
            CONTINUE;
        END IF;

        -- This loop runs precisely the number of times needed to claim the required spots.
        FOR i IN 1..v_spots_to_claim LOOP
            v_available_spot_id := NULL;

            -- Find an available spot. A spot is available only if it's unassigned.
            WITH available_spot_cte AS (
                SELECT s.id
                FROM eshop.spots s
                WHERE s.inventory_context = v_item_to_allocate.inventory_context_id
                  AND s.order_product_ticket IS NULL -- The only condition for availability
                LIMIT 1
                FOR UPDATE SKIP LOCKED
            )
            SELECT id INTO v_available_spot_id FROM available_spot_cte;

            -- If no available spot is found, we must fail with a structured error.
            IF v_available_spot_id IS NULL THEN
                 DECLARE
                    product_data RECORD;
                 BEGIN
                    -- Fetch the details of the product that could not be allocated.
                    SELECT
                        p.id,
                        p.title,
                        p.description,
                        p.price,
                        pt.type,
                        pt.title as type_title,
                        p.currency_code
                    INTO product_data
                    FROM eshop.products p
                    LEFT JOIN eshop.product_types pt ON p.product_type = pt.id
                    WHERE p.id = v_item_to_allocate.product_id;

                    -- Raise the specific overbooked exception with product details.
                    RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
                        'code', 1017,
                        'message', 'Product is overbooked',
                        'product', jsonb_strip_nulls(JSONB_BUILD_OBJECT(
                            'id', product_data.id,
                            'title', product_data.title,
                            'description', product_data.description,
                            'price', product_data.price,
                            'type', product_data.type,
                            'type_title', product_data.type_title,
                            'currency_code', product_data.currency_code
                        ))
                    )::TEXT;
                 END;
            END IF;

            -- Claim the found spot.
            UPDATE eshop.spots
            SET
                order_product_ticket = v_item_to_allocate.order_product_ticket_id,
                occasion = v_occasion_id,
                state = 'ordered',
                secret = NULL,
                secret_expiration_time = NULL,
                updated_at = now()
            WHERE id = v_available_spot_id;

            -- After claiming the spot, check if it should be automatically assigned to a resource.
            DECLARE
                v_is_auto_assign BOOLEAN;
            BEGIN
                -- Get the auto-assignment setting from the pool associated with the context.
                SELECT (ip.data->>'is_auto_resource_assignment')::boolean
                INTO v_is_auto_assign
                FROM public.inventory_contexts ic
                JOIN public.inventory_pools ip ON ic.inventory_pool = ip.id
                WHERE ic.id = v_item_to_allocate.inventory_context_id;

                -- If auto-assignment is enabled for this pool, call the assignment function.
                IF v_is_auto_assign IS TRUE THEN
                    PERFORM assign_spot_to_resource(v_available_spot_id, v_item_to_allocate.inventory_context_id);
                END IF;
            END;

        END LOOP;
    END LOOP;
END;
$_$;


ALTER FUNCTION "public"."apply_allocations"("p_order_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_allocations_claim_only"("p_order_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_order_state TEXT;
    v_item_to_allocate RECORD;
    v_existing_spot_count INT;
    v_spots_to_claim INT;
    v_available_spot_id BIGINT;
    v_occasion_id BIGINT;
BEGIN
    -- Initial check for the order's state.
    SELECT state, occasion INTO v_order_state, v_occasion_id
    FROM eshop.orders
    WHERE id = p_order_id;

    -- If the order is not found, raise an exception.
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Order with ID % not found.', p_order_id USING ERRCODE = 'P0002';
    END IF;

    -- If the order state is 'storno', exit quietly.
    IF v_order_state = 'storno' THEN
        RETURN;
    END IF;

    -- Loop through each product in the order that requires an inventory spot.
    FOR v_item_to_allocate IN
        SELECT
            opt.id AS order_product_ticket_id,
            pic.inventory_context AS inventory_context_id,
            pic.quantity AS required_quantity
        FROM eshop.orders o
        JOIN eshop.order_product_ticket opt ON o.id = opt."order"
        JOIN eshop.products p ON opt.product = p.id
        JOIN eshop.product_inventory_contexts pic ON p.id = pic.product
        WHERE o.id = p_order_id
    LOOP
        -- Check for existing spots for this specific order item AND inventory context.
        SELECT COUNT(*)
        INTO v_existing_spot_count
        FROM eshop.spots s
        WHERE s.order_product_ticket = v_item_to_allocate.order_product_ticket_id
          AND s.inventory_context = v_item_to_allocate.inventory_context_id;

        -- Calculate exactly how many spots are missing.
        v_spots_to_claim := v_item_to_allocate.required_quantity - v_existing_spot_count;

        IF v_spots_to_claim <= 0 THEN
            CONTINUE;
        END IF;

        -- This loop runs precisely the number of times needed to claim the required spots.
        FOR i IN 1..v_spots_to_claim LOOP
            v_available_spot_id := NULL;

            -- Find an available spot. A spot is available only if it's unassigned.
            WITH available_spot_cte AS (
                SELECT s.id
                FROM eshop.spots s
                WHERE s.inventory_context = v_item_to_allocate.inventory_context_id
                  AND s.order_product_ticket IS NULL -- The only condition for availability
                LIMIT 1
                FOR UPDATE SKIP LOCKED
            )
            SELECT id INTO v_available_spot_id FROM available_spot_cte;

            -- If no available spot is found, we must fail.
            IF v_available_spot_id IS NULL THEN
                RAISE EXCEPTION 'Could not find an available spot for inventory context %. All pre-created spots are occupied.',
                    v_item_to_allocate.inventory_context_id
                    USING ERRCODE = 'P0003', -- New error code for "spots unavailable"
                          HINT = 'Check if enough spots were pre-created for this context.';
            END IF;

            -- Claim the found spot.
            UPDATE eshop.spots
            SET
                order_product_ticket = v_item_to_allocate.order_product_ticket_id,
                occasion = v_occasion_id,
                state = 'ordered',
                secret = NULL,
                secret_expiration_time = NULL,
                updated_at = now()
            WHERE id = v_available_spot_id;

        END LOOP;
    END LOOP;
END;
$$;


ALTER FUNCTION "public"."apply_allocations_claim_only"("p_order_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_planned_changes"() RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT public.apply_planned_changes_client_sync_v1();
$$;


ALTER FUNCTION "public"."apply_planned_changes"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_planned_changes_client_sync_v1"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_change eshop.planned_changes%ROWTYPE; v_occasion bigint;
  v_impacts jsonb; v_changed integer;
BEGIN
  PERFORM public.require_client_sync_service_role_v1();
  FOR v_change IN SELECT pc.* FROM eshop.planned_changes pc
    WHERE pc.change_time<=now() AND NOT pc.applied
    ORDER BY pc.change_time,pc.id FOR UPDATE SKIP LOCKED LOOP
    v_changed:=0; v_occasion:=NULL; v_impacts:='[]'::jsonb;
    IF v_change.change_type='products.price' THEN
      UPDATE eshop.products p SET price=v_change.new_value::numeric
      WHERE p.id=v_change.subject_id
        AND p.price IS DISTINCT FROM v_change.new_value::numeric
      RETURNING p.occasion INTO v_occasion;
      GET DIAGNOSTICS v_changed=ROW_COUNT;
    ELSIF v_change.change_type='products.is_hidden' THEN
      UPDATE eshop.products p SET is_hidden=v_change.new_value::boolean
      WHERE p.id=v_change.subject_id
        AND p.is_hidden IS DISTINCT FROM v_change.new_value::boolean
      RETURNING p.occasion INTO v_occasion;
      GET DIAGNOSTICS v_changed=ROW_COUNT;
    ELSIF v_change.change_type='forms.is_open' THEN
      UPDATE public.forms f SET is_open=v_change.new_value::boolean
      WHERE f.id=v_change.subject_id
        AND f.is_open IS DISTINCT FROM v_change.new_value::boolean;
    ELSE
      RAISE warning 'Unknown planned change type %',v_change.change_type;
    END IF;
    IF v_changed>0 AND v_occasion IS NOT NULL THEN
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'component','private_inventory','userId',ou."user")),'[]'::jsonb)
        INTO v_impacts
      FROM eshop.order_product_ticket opt JOIN public.occasion_users ou
        ON ou.ticket=opt.ticket AND ou.occasion=v_occasion
      WHERE opt.product=v_change.subject_id;
      PERFORM public.record_client_sync_commit_v1(v_occasion,
        'inventory.product.planned','inventory',jsonb_build_array(
          jsonb_build_object('entityType','product','entityId',v_change.subject_id,
            'operation','update','safeLabel','Scheduled product change',
            'changedFields',jsonb_build_array(split_part(
              v_change.change_type,'.',2)))),'{}',v_impacts,'[]','service',
        'planned_change:'||v_change.id::text);
    END IF;
    UPDATE eshop.planned_changes SET applied=true WHERE id=v_change.id;
  END LOOP;
END; $$;


ALTER FUNCTION "public"."apply_planned_changes_client_sync_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_planned_changes_obsolete_v1"() RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    change RECORD;
BEGIN
    -- Security Check
    IF auth.role() <> 'service_role' AND session_user <> 'postgres' THEN
        RAISE EXCEPTION 'Access Denied: Service role required.';
    END IF;

    FOR change IN
        SELECT *
        FROM eshop.planned_changes
        WHERE change_time <= NOW() AND applied = FALSE
        ORDER BY change_time ASC
    LOOP
        IF change.change_type = 'products.price' THEN
            -- Update product price
            UPDATE eshop.products
            SET price = change.new_value::NUMERIC
            WHERE id = change.subject_id;

        ELSIF change.change_type = 'products.is_hidden' THEN
            -- Update product visibility
            UPDATE eshop.products
            SET is_hidden = change.new_value::BOOLEAN
            WHERE id = change.subject_id;

        ELSIF change.change_type = 'forms.is_open' THEN
            -- Update form open state
            UPDATE public.forms
            SET is_open = change.new_value::BOOLEAN
            WHERE id = change.subject_id;

        ELSE
            RAISE NOTICE 'Unknown change_type: %', change.change_type;
        END IF;

        -- Mark the change as applied
        UPDATE eshop.planned_changes
        SET applied = TRUE
        WHERE id = change.id;
    END LOOP;
END;
$$;


