CREATE OR REPLACE FUNCTION "public"."assign_existing_companion_client_sync_v1"("p_occasion" bigint, "p_owner" "uuid", "p_companion" "uuid", "p_command_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE v_actor uuid:=auth.uid(); v_policy jsonb; v_begin jsonb; v_hash text;
BEGIN
  v_policy:=public.get_companion_feature_policy_v1(p_occasion);
  IF v_actor IS NULL OR NOT (public.get_is_manager_on_occasion(p_occasion)
      OR public.get_is_admin_on_occasion(p_occasion)) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion manager required';
  END IF;
  IF NOT COALESCE((v_policy->>'is_enabled')::boolean,false)
      OR NOT COALESCE((v_policy->>'allow_admin_assign')::boolean,false) THEN
    RAISE insufficient_privilege USING MESSAGE='admin companion assignment disabled';
  END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,
    'owner',p_owner,'companion',p_companion)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'profile.companion.assign',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  PERFORM public.check_companion_relation_invariants_v1(p_occasion,p_owner,p_companion);
  IF EXISTS (SELECT 1 FROM public.user_companions uc WHERE uc.occasion=p_occasion
      AND uc."user"=p_owner AND uc.companion=p_companion) THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
      jsonb_build_object('owner',p_owner,'companion',p_companion));
  END IF;
  INSERT INTO public.user_companions(occasion,"user",companion,origin,created_by)
  VALUES(p_occasion,p_owner,p_companion,'admin_assigned',v_actor);
  RETURN public.complete_private_profile_mutation_v1(p_command_id,p_occasion,
    'profile.companion.assign',jsonb_build_array(jsonb_build_object(
      'entityType','companion_assignment','entityId',p_companion,'operation','insert',
      'safeLabel','Companion assignment','changedFields',jsonb_build_array('owner'))),
    ARRAY[p_owner],'{}','[]',jsonb_build_object('owner',p_owner,'companion',p_companion));
END $$;


ALTER FUNCTION "public"."assign_existing_companion_client_sync_v1"("p_occasion" bigint, "p_owner" "uuid", "p_companion" "uuid", "p_command_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assign_spot_to_resource"("p_spot_id" bigint, "p_inventory_context_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    v_pool_id BIGINT;
    v_resource_id BIGINT;
    v_is_spot_assigned BOOLEAN;
BEGIN
    -- 1. Check if the spot is already assigned to prevent overwriting.
    SELECT resource IS NOT NULL INTO v_is_spot_assigned
    FROM eshop.spots
    WHERE id = p_spot_id;

    IF v_is_spot_assigned THEN
        RETURN; -- Spot already has a resource, so we do nothing.
    END IF;

    -- 2. Get the parent inventory_pool from the given context.
    SELECT inventory_pool INTO v_pool_id
    FROM public.inventory_contexts
    WHERE id = p_inventory_context_id;

    -- If the context or pool doesn't exist, we can't proceed.
    IF v_pool_id IS NULL THEN
        RETURN;
    END IF;

    -- 3. Find the first available resource within the pool for the given context.
    --    A resource is "available" if its count of assigned spots is less than its capacity.
    SELECT res.id INTO v_resource_id
    FROM public.resources res
    LEFT JOIN (
        -- Subquery to count assigned spots per resource for this specific context
        SELECT resource as resource_id, COUNT(*) as assigned_spots
        FROM eshop.spots
        WHERE inventory_context = p_inventory_context_id AND resource IS NOT NULL
        GROUP BY resource_id
    ) spot_counts ON res.id = spot_counts.resource_id
    WHERE res.inventory_pool = v_pool_id
    -- Check if the resource's capacity is not yet filled
    AND (spot_counts.assigned_spots IS NULL OR spot_counts.assigned_spots < res.capacity)
    ORDER BY res.id -- Order consistently to always pick the "first" available one
    LIMIT 1;

    -- 4. If an available resource was found, update the spot to link it.
    IF v_resource_id IS NOT NULL THEN
        UPDATE eshop.spots
        SET resource = v_resource_id,
            updated_at = now()
        WHERE id = p_spot_id;
    END IF;
END;
$$;


ALTER FUNCTION "public"."assign_spot_to_resource"("p_spot_id" bigint, "p_inventory_context_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."begin_anonymous_client_mutation_v1"("p_command_id" "uuid", "p_command_name" "text", "p_occasion" bigint, "p_actor_client_id" "uuid", "p_request_sha256" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
DECLARE
  v_receipt public.client_mutation_receipts%ROWTYPE;
  v_inserted integer;
BEGIN
  IF auth.uid() IS NOT NULL OR p_actor_client_id IS NULL
     OR p_command_id IS NULL OR p_occasion IS NULL
     OR p_command_name !~ '^[a-z][a-z0-9_.]{2,95}$'
     OR p_request_sha256 !~ '^[0-9a-f]{64}$' THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid anonymous mutation receipt claim';
  END IF;
  INSERT INTO public.client_mutation_receipts
    (command_id,command_name,occasion,actor_client_id,request_sha256)
  VALUES (p_command_id,p_command_name,p_occasion,p_actor_client_id,p_request_sha256)
  ON CONFLICT (command_id) DO NOTHING;
  GET DIAGNOSTICS v_inserted = ROW_COUNT;
  SELECT * INTO STRICT v_receipt FROM public.client_mutation_receipts
    WHERE command_id=p_command_id FOR UPDATE;
  IF v_receipt.command_name IS DISTINCT FROM p_command_name
     OR v_receipt.occasion IS DISTINCT FROM p_occasion
     OR v_receipt.actor_id IS NOT NULL
     OR v_receipt.actor_client_id IS DISTINCT FROM p_actor_client_id
     OR v_receipt.request_sha256 IS DISTINCT FROM p_request_sha256 THEN
    RAISE invalid_parameter_value
      USING MESSAGE='command id was already used with different request data';
  END IF;
  IF v_receipt.status='completed' THEN
    RETURN jsonb_build_object('disposition','replay','response',v_receipt.response);
  END IF;
  IF v_inserted<>1 THEN
    RAISE serialization_failure
      USING MESSAGE='incomplete mutation receipt cannot be resumed';
  END IF;
  RETURN jsonb_build_object('disposition','claimed');
END;
$_$;


ALTER FUNCTION "public"."begin_anonymous_client_mutation_v1"("p_command_id" "uuid", "p_command_name" "text", "p_occasion" bigint, "p_actor_client_id" "uuid", "p_request_sha256" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."begin_client_mutation_v1"("p_command_id" "uuid", "p_command_name" "text", "p_occasion" bigint, "p_actor_id" "uuid", "p_request_sha256" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
DECLARE
  v_receipt public.client_mutation_receipts%ROWTYPE;
  v_inserted integer;
BEGIN
  IF p_command_id IS NULL OR p_actor_id IS NULL OR p_actor_id IS DISTINCT FROM auth.uid() THEN
    RAISE insufficient_privilege USING MESSAGE='authenticated command actor required';
  END IF;
  IF p_command_name !~ '^[a-z][a-z0-9_.]{2,95}$'
     OR p_request_sha256 !~ '^[0-9a-f]{64}$' THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid mutation receipt metadata';
  END IF;

  INSERT INTO public.client_mutation_receipts
    (command_id,command_name,occasion,actor_id,request_sha256)
  VALUES (p_command_id,p_command_name,p_occasion,p_actor_id,p_request_sha256)
  ON CONFLICT (command_id) DO NOTHING;
  GET DIAGNOSTICS v_inserted = ROW_COUNT;

  SELECT * INTO STRICT v_receipt
  FROM public.client_mutation_receipts
  WHERE command_id=p_command_id
  FOR UPDATE;

  IF v_receipt.command_name IS DISTINCT FROM p_command_name
     OR v_receipt.occasion IS DISTINCT FROM p_occasion
     OR v_receipt.actor_id IS DISTINCT FROM p_actor_id
     OR v_receipt.request_sha256 IS DISTINCT FROM p_request_sha256 THEN
    RAISE invalid_parameter_value
      USING MESSAGE='command id was already used with different request data';
  END IF;
  IF v_receipt.status='completed' THEN
    RETURN jsonb_build_object('disposition','replay','response',v_receipt.response);
  END IF;
  IF v_inserted <> 1 THEN
    RAISE serialization_failure
      USING MESSAGE='incomplete mutation receipt cannot be resumed';
  END IF;
  RETURN jsonb_build_object('disposition','claimed');
END;
$_$;


ALTER FUNCTION "public"."begin_client_mutation_v1"("p_command_id" "uuid", "p_command_name" "text", "p_occasion" bigint, "p_actor_id" "uuid", "p_request_sha256" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."begin_unit_client_mutation_v1"("p_command_id" "uuid", "p_command_name" "text", "p_unit" bigint, "p_actor_id" "uuid", "p_request_sha256" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
DECLARE v_receipt public.client_mutation_receipts%ROWTYPE; v_inserted integer;
BEGIN
  IF p_actor_id IS NULL OR p_actor_id IS DISTINCT FROM auth.uid()
     OR p_command_id IS NULL OR p_unit IS NULL
     OR p_command_name !~ '^[a-z][a-z0-9_.]{2,95}$'
     OR p_request_sha256 !~ '^[0-9a-f]{64}$'
     OR NOT public.get_is_manager_on_unit(p_unit) THEN
    RAISE insufficient_privilege USING MESSAGE='invalid unit mutation receipt claim';
  END IF;
  INSERT INTO public.client_mutation_receipts
    (command_id,command_name,unit,actor_id,request_sha256)
  VALUES (p_command_id,p_command_name,p_unit,p_actor_id,p_request_sha256)
  ON CONFLICT (command_id) DO NOTHING;
  GET DIAGNOSTICS v_inserted = ROW_COUNT;
  SELECT * INTO STRICT v_receipt FROM public.client_mutation_receipts
    WHERE command_id=p_command_id FOR UPDATE;
  IF v_receipt.command_name IS DISTINCT FROM p_command_name
     OR v_receipt.occasion IS NOT NULL OR v_receipt.unit IS DISTINCT FROM p_unit
     OR v_receipt.actor_id IS DISTINCT FROM p_actor_id
     OR v_receipt.actor_client_id IS NOT NULL
     OR v_receipt.request_sha256 IS DISTINCT FROM p_request_sha256 THEN
    RAISE invalid_parameter_value
      USING MESSAGE='command id was already used with different request data';
  END IF;
  IF v_receipt.status='completed' THEN
    RETURN jsonb_build_object('disposition','replay','response',v_receipt.response);
  END IF;
  IF v_inserted<>1 THEN
    RAISE serialization_failure
      USING MESSAGE='incomplete mutation receipt cannot be resumed';
  END IF;
  RETURN jsonb_build_object('disposition','claimed');
END; $_$;


