CREATE OR REPLACE FUNCTION "public"."check_upload_permission"("p_occasion_id" bigint DEFAULT NULL::bigint, "p_unit_id" bigint DEFAULT NULL::bigint) RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
    BEGIN
        IF auth.uid() IS NULL THEN
            RETURN false;
        END IF;

        IF p_unit_id IS NOT NULL THEN
            RETURN public.get_is_editor_on_unit(p_unit_id);
        ELSIF p_occasion_id IS NOT NULL THEN
            RETURN public.get_is_editor_on_occasion(p_occasion_id)
                OR public.get_is_editor_order_on_occasion(p_occasion_id);
        END IF;

        RETURN false;
    END;
    $$;


