CREATE OR REPLACE FUNCTION "public"."claim_account_deletion"("p_token_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE v_request public.account_deletion_requests%ROWTYPE;
BEGIN
  PERFORM public.require_service_role();
  SELECT * INTO v_request FROM public.account_deletion_requests
  WHERE token_hash = p_token_hash OR used_token_hash = p_token_hash
  LIMIT 1 FOR UPDATE;
  IF v_request.id IS NULL THEN RETURN jsonb_build_object('status', 'invalid'); END IF;
  IF v_request.status = 'completed' THEN RETURN jsonb_build_object('status', 'already_completed'); END IF;
  IF v_request.status IN ('deletion_pending','failed') AND v_request.used_token_hash = p_token_hash THEN
    RETURN jsonb_build_object('status','processing','requestId',v_request.id,
      'userId',v_request.user_id,'organization',v_request.organization,
      'publicDeleted',v_request.public_deleted,'authDeleted',v_request.auth_deleted,
      'onesignalDeleted',v_request.onesignal_deleted);
  END IF;
  IF v_request.status <> 'email_sent' THEN RETURN jsonb_build_object('status', 'invalid'); END IF;
  IF v_request.expires_at <= clock_timestamp() THEN RETURN jsonb_build_object('status', 'expired'); END IF;

  UPDATE public.account_deletion_requests SET
    status='deletion_pending', used_token_hash=token_hash, token_hash=NULL,
    masked_email=NULL, claimed_at=clock_timestamp(), attempt_count=attempt_count+1,
    updated_at=clock_timestamp()
  WHERE id=v_request.id RETURNING * INTO v_request;
  -- The claim and first-party cleanup share one transaction. Consequently an
  -- already-issued JWT cannot regain domain access between confirmation and a
  -- later Edge call; its public.user_info row is gone before claim commits.
  PERFORM public.cleanup_account_deletion_domain(v_request.id);
  RETURN jsonb_build_object('status','processing','requestId',v_request.id,
    'userId',v_request.user_id,'organization',v_request.organization,
    'publicDeleted',true,'authDeleted',false,'onesignalDeleted',false);
END;
$$;


ALTER FUNCTION "public"."claim_account_deletion"("p_token_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_client_projection_dirty_internal_v1"("p_scope_ids" bigint[], "p_limit" integer) RETURNS TABLE("component" "text", "scope_type" "text", "scope_id" bigint, "entity_id" bigint, "source_revision" bigint, "claim_token" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  PERFORM public.require_client_sync_service_role_v1();
  RETURN QUERY
  WITH claimed AS (
    SELECT d.component, d.scope_type, d.scope_id, d.entity_id
    FROM public.client_projection_dirty_keys d
    JOIN public.occasions o
      ON d.scope_type = 'occasion'
     AND o.id = d.scope_id
     AND NOT o.is_hidden
    WHERE (p_scope_ids IS NULL OR d.scope_id = ANY(p_scope_ids))
      AND (d.claimed_at IS NULL
        OR d.claimed_at < now() - interval '2 minutes')
    ORDER BY d.dirty_since
    FOR UPDATE OF d SKIP LOCKED
    LIMIT LEAST(p_limit, 1000)
  ), updated AS (
    UPDATE public.client_projection_dirty_keys d
    SET claimed_at = now(), claim_token = gen_random_uuid()
    FROM claimed c
    WHERE (d.component, d.scope_type, d.scope_id, d.entity_id) =
          (c.component, c.scope_type, c.scope_id, c.entity_id)
    RETURNING d.*
  )
  SELECT u.component, u.scope_type, u.scope_id, u.entity_id,
         u.source_revision, u.claim_token
  FROM updated u;
END;
$$;


ALTER FUNCTION "public"."claim_client_projection_dirty_internal_v1"("p_scope_ids" bigint[], "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_client_projection_dirty_scopes_v1"("p_scope_ids" bigint[], "p_limit" integer DEFAULT 200) RETURNS TABLE("component" "text", "scope_type" "text", "scope_id" bigint, "entity_id" bigint, "source_revision" bigint, "claim_token" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  PERFORM public.require_client_sync_service_role_v1();
  IF p_scope_ids IS NULL OR cardinality(p_scope_ids) = 0 THEN
    RAISE EXCEPTION 'at least one publication scope is required';
  END IF;
  RETURN QUERY
  SELECT *
  FROM public.claim_client_projection_dirty_internal_v1(p_scope_ids, p_limit);
END;
$$;


