CREATE OR REPLACE FUNCTION "public"."claim_client_projection_dirty_v1"("p_limit" integer DEFAULT 200) RETURNS TABLE("component" "text", "scope_type" "text", "scope_id" bigint, "entity_id" bigint, "source_revision" bigint, "claim_token" "uuid")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT *
  FROM public.claim_client_projection_dirty_internal_v1(NULL, p_limit);
$$;


