CREATE OR REPLACE FUNCTION "public"."claim_due_queue_emails_v1"("p_limit" integer DEFAULT 25) RETURNS SETOF "public"."queue_emails"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  PERFORM public.require_client_sync_service_role_v1();
  IF p_limit IS NULL OR p_limit<1 OR p_limit>100 THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid queue claim limit'; END IF;
  RETURN QUERY WITH candidates AS (
    SELECT q.id FROM public.queue_emails q
    WHERE q.target_time<=now()
      AND (q.processing_at IS NULL OR q.processing_at<now()-interval '10 minutes')
    ORDER BY q.target_time,q.id FOR UPDATE SKIP LOCKED LIMIT p_limit
  ) UPDATE public.queue_emails q SET processing_at=clock_timestamp(),
      attempt_count=q.attempt_count+1,last_error=NULL
    FROM candidates c WHERE q.id=c.id RETURNING q.*;
END; $$;


ALTER FUNCTION "public"."claim_due_queue_emails_v1"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cleanup_account_deletion_domain"("p_request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE v_user uuid; v_request public.account_deletion_requests%ROWTYPE;
BEGIN
  PERFORM public.require_service_role();
  SELECT * INTO v_request FROM public.account_deletion_requests
  WHERE id=p_request_id FOR UPDATE;
  IF v_request.id IS NULL OR v_request.status NOT IN ('deletion_pending','failed') THEN
    RAISE EXCEPTION 'account_deletion_request_state_conflict' USING ERRCODE = '55000';
  END IF;
  IF v_request.public_deleted THEN RETURN jsonb_build_object('status','already_deleted'); END IF;
  v_user := v_request.user_id;

  PERFORM public.record_account_deletion_sync_v1(
    v_user,v_request.organization);

  UPDATE public.cleaning_reports SET created_by=NULL WHERE created_by=v_user;
  UPDATE public.cleaning_reports SET resolved_by=NULL WHERE resolved_by=v_user;
  UPDATE public.news SET created_by=NULL WHERE created_by=v_user;
  UPDATE eshop.orders_history SET created_by=NULL WHERE created_by=v_user;
  UPDATE eshop.bank_account_requests SET created_by=NULL WHERE created_by=v_user;
  UPDATE eshop.transactions SET created_by=NULL WHERE created_by=v_user;
  UPDATE public.client_commits SET actor_id=NULL, actor_display=NULL WHERE actor_id=v_user;
  DELETE FROM public.event_feedback WHERE "user"=v_user;

  DELETE FROM public.client_mutation_receipts WHERE actor_id=v_user;
  DELETE FROM public.client_sync_private_scopes WHERE user_id=v_user;
  DELETE FROM public.activity_assignments WHERE "user"=v_user;
  DELETE FROM public.activity_history WHERE user_id=v_user;
  DELETE FROM public.event_users_saved WHERE "user"=v_user;
  DELETE FROM public.event_users WHERE "user"=v_user;
  DELETE FROM public.user_groups WHERE "user"=v_user;
  DELETE FROM public.user_companions WHERE "user"=v_user OR companion=v_user;
  DELETE FROM public.user_reset_token WHERE "user"=v_user;
  DELETE FROM eshop.bank_account_users WHERE "user"=v_user;
  DELETE FROM public.occasion_users WHERE "user"=v_user;
  DELETE FROM public.unit_users WHERE "user"=v_user;
  DELETE FROM public.organization_users WHERE "user"=v_user;
  DELETE FROM public.user_info WHERE id=v_user;

  UPDATE public.account_deletion_requests SET public_deleted=true,
    status='deletion_pending', error_class=NULL, updated_at=clock_timestamp()
  WHERE id=p_request_id;
  RETURN jsonb_build_object('status','deleted');
END;
$$;


ALTER FUNCTION "public"."cleanup_account_deletion_domain"("p_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_client_mutation_applied_v1"("p_command_id" "uuid", "p_occasion" bigint, "p_source" "text", "p_change_class" "text", "p_items" "jsonb", "p_public_components" "text"[], "p_private_impacts" "jsonb", "p_dirty_keys" "jsonb", "p_data" "jsonb", "p_immediate_public_components" "text"[] DEFAULT '{}'::"text"[], "p_extra_replacements" "jsonb" DEFAULT '[]'::"jsonb", "p_actor_kind" "text" DEFAULT 'user'::"text", "p_reason" "text" DEFAULT NULL::"text", "p_immediate_private_replacements" "jsonb" DEFAULT '[]'::"jsonb", "p_unit_catalog_fanout_units" bigint[] DEFAULT '{}'::bigint[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_commit jsonb; v_component text; v_component_data jsonb;
  v_private_replacement jsonb; v_private_revision bigint;
  v_replacements jsonb:=COALESCE(p_extra_replacements,'[]'::jsonb);
  v_response jsonb; v_fanout_unit bigint;
BEGIN
  IF p_data IS NULL OR octet_length(p_data::text)>4194304
    OR jsonb_typeof(v_replacements)<>'array'
    OR jsonb_typeof(COALESCE(p_immediate_private_replacements,'[]'))<>'array'
    OR NOT COALESCE(p_immediate_public_components,'{}')
      <@ COALESCE(p_public_components,'{}') THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid applied mutation result';
  END IF;
  v_commit:=public.record_client_sync_commit_v1(p_occasion,p_source,p_change_class,
    p_items,p_public_components,p_private_impacts,p_dirty_keys,p_actor_kind,p_reason);
  FOR v_fanout_unit IN SELECT DISTINCT id FROM unnest(
    COALESCE(p_unit_catalog_fanout_units,'{}')) id LOOP
    PERFORM public.fanout_unit_catalog_v1(
      (v_commit->>'commitId')::uuid,v_fanout_unit);
  END LOOP;
  FOREACH v_component IN ARRAY COALESCE(p_immediate_public_components,'{}') LOOP
    v_component_data:=public.get_public_client_sync_component_v1(
      v_component,'occasion',p_occasion);
    v_replacements:=v_replacements||jsonb_build_array(jsonb_build_object(
      'component',v_component,'revision',v_component_data->'revision',
      'payload',v_component_data->'payload'));
  END LOOP;
  FOR v_private_replacement IN SELECT value FROM jsonb_array_elements(
      COALESCE(p_immediate_private_replacements,'[]')) LOOP
    IF v_private_replacement->>'component' NOT LIKE 'private\_%'
      OR NOT EXISTS (SELECT 1 FROM jsonb_array_elements(
        COALESCE(p_private_impacts,'[]')) impact
        WHERE impact->>'component'=v_private_replacement->>'component'
          AND impact->>'userId'=v_private_replacement->>'userId') THEN
      RAISE invalid_parameter_value USING MESSAGE='invalid immediate private replacement';
    END IF;
    SELECT s.source_revision INTO STRICT v_private_revision
    FROM public.client_sync_private_scopes s
    WHERE s.component=v_private_replacement->>'component'
      AND s.occasion=p_occasion
      AND s.user_id=(v_private_replacement->>'userId')::uuid;
    v_replacements:=v_replacements||jsonb_build_array(jsonb_build_object(
      'component',v_private_replacement->>'component',
      'revision',v_private_revision,'payload',v_private_replacement->'payload'));
  END LOOP;
  v_response:=jsonb_build_object('status','applied','code',200,'data',p_data,
    'mutation',jsonb_build_object('commandId',p_command_id,'receiptId',p_command_id,
      'commitId',v_commit->>'commitId','replayed',false,
      'occurredAt',v_commit->>'occurredAt'),
    'sync',jsonb_build_object('replacements',v_replacements));
  RETURN public.finish_client_mutation_v1(p_command_id,v_response,
    (v_commit->>'commitId')::uuid);
END; $$;


ALTER FUNCTION "public"."complete_client_mutation_applied_v1"("p_command_id" "uuid", "p_occasion" bigint, "p_source" "text", "p_change_class" "text", "p_items" "jsonb", "p_public_components" "text"[], "p_private_impacts" "jsonb", "p_dirty_keys" "jsonb", "p_data" "jsonb", "p_immediate_public_components" "text"[], "p_extra_replacements" "jsonb", "p_actor_kind" "text", "p_reason" "text", "p_immediate_private_replacements" "jsonb", "p_unit_catalog_fanout_units" bigint[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_client_mutation_outcome_v1"("p_command_id" "uuid", "p_status" "text", "p_code" integer, "p_data" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_response jsonb;
BEGIN
  IF p_status NOT IN ('unchanged','rejected','conflict')
    OR p_code NOT BETWEEN 100 AND 599 OR p_data IS NULL
    OR octet_length(p_data::text)>4194304 THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid mutation outcome';
  END IF;
  v_response:=jsonb_build_object('status',p_status,'code',p_code,'data',p_data,
    'mutation',jsonb_build_object('commandId',p_command_id,'receiptId',p_command_id,
      'commitId',NULL,'replayed',false,'occurredAt',clock_timestamp()),
    'sync',jsonb_build_object('replacements','[]'::jsonb));
  RETURN public.finish_client_mutation_v1(p_command_id,v_response,NULL);
END; $$;


ALTER FUNCTION "public"."complete_client_mutation_outcome_v1"("p_command_id" "uuid", "p_status" "text", "p_code" integer, "p_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_client_sync_publication_classes_v1"("p_scope_type" "text", "p_scope_id" bigint, "p_release_revision" bigint, "p_manifest" "jsonb", "p_manifest_url" "text", "p_manifest_sha256" "text", "p_manifest_bytes" bigint, "p_live" "jsonb", "p_head_json" "jsonb", "p_head_etag" "text", "p_catalog_claim_tokens" "uuid"[], "p_live_claim_tokens" "uuid"[]) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_head public.client_sync_public_heads%ROWTYPE; v_component record;
  v_next_catalog bigint := (p_head_json#>>'{catalog,revision}')::bigint;
  v_next_live bigint := (p_head_json#>>'{live,revision}')::bigint;
  v_content_revision bigint;
BEGIN
  PERFORM public.require_client_sync_service_role_v1();
  SELECT * INTO v_head FROM public.client_sync_public_heads
    WHERE scope_type=p_scope_type AND scope_id=p_scope_id FOR UPDATE;
  IF FOUND AND (v_next_catalog < COALESCE(v_head.release_revision,-1)
      OR COALESCE(v_next_live,-1) < COALESCE(v_head.live_revision,-1)
      OR (v_next_catalog = v_head.release_revision
          AND v_next_live IS NOT DISTINCT FROM v_head.live_revision
          AND v_head.head_json IS DISTINCT FROM p_head_json)) THEN
    RETURN false;
  END IF;
  IF p_release_revision IS NOT NULL THEN
    IF p_manifest IS NULL OR p_manifest_sha256 IS NULL
       OR p_release_revision <> v_next_catalog THEN RAISE EXCEPTION 'invalid catalog completion'; END IF;
    INSERT INTO public.client_sync_release_manifests
      (scope_type,scope_id,release_revision,manifest,artifact_url,sha256,byte_size)
    VALUES (p_scope_type,p_scope_id,p_release_revision,p_manifest,p_manifest_url,
      p_manifest_sha256,p_manifest_bytes) ON CONFLICT DO NOTHING;
    FOR v_component IN SELECT key,value FROM jsonb_each(p_manifest->'components') LOOP
      INSERT INTO public.client_sync_publications
        (component,scope_type,scope_id,published_revision,media_type,artifact_url,sha256,byte_size)
      VALUES (v_component.key,p_scope_type,p_scope_id,
        (v_component.value->>'revision')::bigint,v_component.value->>'mediaType',
        v_component.value->>'url',v_component.value->>'sha256',(v_component.value->>'bytes')::bigint)
      ON CONFLICT DO NOTHING;
    END LOOP;
  END IF;
  IF p_live IS NOT NULL THEN
    INSERT INTO public.client_sync_publications
      (component,scope_type,scope_id,published_revision,media_type,artifact_url,sha256,byte_size)
    VALUES ('live_public',p_scope_type,p_scope_id,(p_live->>'revision')::bigint,
      p_live->>'mediaType',p_live->>'url',p_live->>'sha256',(p_live->>'bytes')::bigint)
    ON CONFLICT DO NOTHING;
  END IF;
  INSERT INTO public.client_sync_public_heads
    (scope_type,scope_id,release_revision,manifest_sha256,live_revision,live_sha256,head_etag,head_json)
  VALUES (p_scope_type,p_scope_id,v_next_catalog,p_head_json#>>'{catalog,sha256}',
    v_next_live,p_head_json#>>'{live,sha256}',p_head_etag,p_head_json)
  ON CONFLICT (scope_type,scope_id) DO UPDATE SET
    release_revision=EXCLUDED.release_revision,manifest_sha256=EXCLUDED.manifest_sha256,
    live_revision=EXCLUDED.live_revision,live_sha256=EXCLUDED.live_sha256,
    head_etag=EXCLUDED.head_etag,head_json=EXCLUDED.head_json,updated_at=now();

  -- R2 artifacts and the accepted public head already exist at this point.
  -- Moving ready rows into log_notifications is atomic with recording that head;
  -- its existing AFTER INSERT hook therefore cannot outrun content_catalog.
  v_content_revision:=(p_manifest#>>'{components,content_catalog,revision}')::bigint;
  IF p_scope_type='occasion' AND v_content_revision IS NOT NULL THEN
    WITH ready AS (
      DELETE FROM public.news_notification_outbox q
      WHERE q.occasion=p_scope_id
        AND q.required_content_revision<=v_content_revision
      RETURNING q.*
    )
    INSERT INTO public.log_notifications
      (id,occasion,organization,user_id,"to",heading,content,data,created_at)
    SELECT r.id,r.occasion,r.organization,r.user_id,r."to",r.heading,r.content,
      r.data,r.created_at
    FROM ready r
    ON CONFLICT (id) DO NOTHING;
  END IF;

  DELETE FROM public.client_projection_dirty_keys
    WHERE claim_token=ANY(COALESCE(p_catalog_claim_tokens,'{}')) AND component<>'live_public';
  DELETE FROM public.client_projection_dirty_keys
    WHERE claim_token=ANY(COALESCE(p_live_claim_tokens,'{}')) AND component='live_public';
  RETURN true;
END; $$;


ALTER FUNCTION "public"."complete_client_sync_publication_classes_v1"("p_scope_type" "text", "p_scope_id" bigint, "p_release_revision" bigint, "p_manifest" "jsonb", "p_manifest_url" "text", "p_manifest_sha256" "text", "p_manifest_bytes" bigint, "p_live" "jsonb", "p_head_json" "jsonb", "p_head_etag" "text", "p_catalog_claim_tokens" "uuid"[], "p_live_claim_tokens" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_private_inventory_mutation_v1"("p_command_id" "uuid", "p_occasion" bigint, "p_source" "text", "p_items" "jsonb", "p_impacted_users" "uuid"[], "p_data" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_actor uuid:=auth.uid(); v_impacts jsonb; v_replacements jsonb:='[]'::jsonb;
BEGIN
  SELECT COALESCE(jsonb_agg(jsonb_build_object('component','private_inventory',
    'userId',u.id) ORDER BY u.id),'[]'::jsonb) INTO v_impacts
  FROM (SELECT DISTINCT id FROM unnest(COALESCE(p_impacted_users,'{}')) id) u
  JOIN public.occasion_users ou ON ou.occasion=p_occasion AND ou."user"=u.id;
  IF v_actor IS NOT NULL AND v_actor=ANY(COALESCE(p_impacted_users,'{}'))
    AND EXISTS (SELECT 1 FROM public.occasion_users ou
      WHERE ou.occasion=p_occasion AND ou."user"=v_actor) THEN
    v_replacements:=jsonb_build_array(jsonb_build_object(
      'component','private_inventory','userId',v_actor,
      'payload',public.get_user_inventory_for_occasion_v1(p_occasion)));
  END IF;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    p_source,'inventory',p_items,'{}',v_impacts,'[]',p_data,
    '{}','[]','user',NULL,v_replacements);
END; $$;


ALTER FUNCTION "public"."complete_private_inventory_mutation_v1"("p_command_id" "uuid", "p_occasion" bigint, "p_source" "text", "p_items" "jsonb", "p_impacted_users" "uuid"[], "p_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_private_profile_mutation_v1"("p_command_id" "uuid", "p_occasion" bigint, "p_source" "text", "p_items" "jsonb", "p_impacted_users" "uuid"[], "p_public_components" "text"[], "p_dirty_keys" "jsonb", "p_data" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_actor uuid:=auth.uid(); v_impacts jsonb; v_replacements jsonb:='[]'::jsonb;
BEGIN
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  SELECT 'occasion_user','occasion',p_occasion,u.id::text,1
  FROM (SELECT DISTINCT id FROM unnest(COALESCE(p_impacted_users,'{}')) id) u
  JOIN public.occasion_users ou ON ou.occasion=p_occasion AND ou."user"=u.id
  ON CONFLICT (aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE
    SET version=public.client_aggregate_versions.version+1,
      updated_at=clock_timestamp();
  SELECT COALESCE(jsonb_agg(jsonb_build_object('component','private_profile',
    'userId',u.id) ORDER BY u.id),'[]'::jsonb) INTO v_impacts
  FROM (SELECT DISTINCT id FROM unnest(COALESCE(p_impacted_users,'{}')) id) u
  JOIN public.occasion_users ou ON ou.occasion=p_occasion AND ou."user"=u.id;
  IF v_actor IS NOT NULL AND v_actor=ANY(COALESCE(p_impacted_users,'{}'))
    AND EXISTS (SELECT 1 FROM public.occasion_users ou
      WHERE ou.occasion=p_occasion AND ou."user"=v_actor) THEN
    v_replacements:=jsonb_build_array(jsonb_build_object(
      'component','private_profile','userId',v_actor,
      'payload',public.get_private_profile_payload_v1(p_occasion,v_actor)));
  END IF;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    p_source,'profile',p_items,p_public_components,v_impacts,p_dirty_keys,p_data,
    '{}','[]','user',NULL,v_replacements);
END; $$;


ALTER FUNCTION "public"."complete_private_profile_mutation_v1"("p_command_id" "uuid", "p_occasion" bigint, "p_source" "text", "p_items" "jsonb", "p_impacted_users" "uuid"[], "p_public_components" "text"[], "p_dirty_keys" "jsonb", "p_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_profile_inventory_membership_mutation_v1"("p_command_id" "uuid", "p_occasion" bigint, "p_source" "text", "p_items" "jsonb", "p_before_users" "uuid"[], "p_data" "jsonb", "p_actor_kind" "text" DEFAULT 'user'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_actor uuid:=auth.uid(); v_after_users uuid[]; v_removed uuid[];
  v_impacts jsonb; v_replacements jsonb:='[]'::jsonb;
  v_public text[]:='{}'; v_dirty jsonb:='[]'::jsonb;
BEGIN
  SELECT COALESCE(array_agg(ou."user"),'{}'::uuid[]) INTO v_after_users
    FROM public.occasion_users ou WHERE ou.occasion=p_occasion;
  SELECT ARRAY(SELECT id FROM unnest(COALESCE(p_before_users,'{}')) id
    WHERE NOT id=ANY(v_after_users)) INTO v_removed;
  DELETE FROM public.client_sync_private_scopes s WHERE s.occasion=p_occasion
    AND s.user_id=ANY(v_removed);
  DELETE FROM public.client_aggregate_versions v
    WHERE v.aggregate_type='occasion_user' AND v.scope_type='occasion'
      AND v.scope_id=p_occasion AND v.aggregate_id=ANY(
        ARRAY(SELECT id::text FROM unnest(v_removed) id));
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  SELECT 'occasion_user','occasion',p_occasion,id::text,1
    FROM unnest(v_after_users) id
  ON CONFLICT (aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE
    SET version=public.client_aggregate_versions.version+1,
      updated_at=clock_timestamp();
  SELECT COALESCE(jsonb_agg(jsonb_build_object('component',component,
    'userId',id) ORDER BY id,component),'[]'::jsonb) INTO v_impacts
  FROM unnest(v_after_users) id CROSS JOIN unnest(
    ARRAY['private_profile','private_inventory']) component;
  IF cardinality(v_removed)>0 THEN
    v_public:=ARRAY['live_public'];
    SELECT COALESCE(jsonb_agg(jsonb_build_object('component','live_public',
      'entityId',e.id)),'[]'::jsonb) INTO v_dirty
      FROM public.events e WHERE e.occasion=p_occasion;
  END IF;
  IF v_actor IS NOT NULL AND v_actor=ANY(v_after_users) THEN
    v_replacements:=jsonb_build_array(
      jsonb_build_object('component','private_profile','userId',v_actor,
        'payload',public.get_private_profile_payload_v1(p_occasion,v_actor)),
      jsonb_build_object('component','private_inventory','userId',v_actor,
        'payload',public.get_user_inventory_for_occasion_v1(p_occasion)));
  END IF;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    p_source,'inventory',p_items,v_public,v_impacts,v_dirty,p_data,
    '{}','[]',p_actor_kind,NULL,v_replacements);
END; $$;


ALTER FUNCTION "public"."complete_profile_inventory_membership_mutation_v1"("p_command_id" "uuid", "p_occasion" bigint, "p_source" "text", "p_items" "jsonb", "p_before_users" "uuid"[], "p_data" "jsonb", "p_actor_kind" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."confirm_blueprint_order_change"("p_spot_ids" bigint[], "p_input_data" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  RETURN public.confirm_blueprint_order_change_client_sync_v1(
    p_spot_ids,p_input_data,extensions.gen_random_uuid())->'data';
END; $$;


ALTER FUNCTION "public"."confirm_blueprint_order_change"("p_spot_ids" bigint[], "p_input_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."confirm_blueprint_order_change_client_sync_v1"("p_spot_ids" bigint[], "p_input_data" "jsonb", "p_command_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_actor uuid:=auth.uid(); v_occasion bigint; v_begin jsonb; v_hash text;
  v_result jsonb; v_before_users uuid[];
BEGIN
  SELECT min(s.occasion) INTO v_occasion FROM eshop.spots s
    WHERE s.id=ANY(p_spot_ids);
  IF v_actor IS NULL OR v_occasion IS NULL OR cardinality(p_spot_ids)=0
    OR (SELECT count(*) FROM eshop.spots s
      WHERE s.id=ANY(p_spot_ids) AND s.occasion=v_occasion)
      <>cardinality(ARRAY(SELECT DISTINCT id FROM unnest(p_spot_ids) id))
    OR NOT public.get_is_editor_order_on_occasion(v_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'spots',p_spot_ids,'input',p_input_data)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'inventory.order.prepare_replace',v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  SELECT COALESCE(array_agg(ou."user"),'{}'::uuid[]) INTO v_before_users
    FROM public.occasion_users ou WHERE ou.occasion=v_occasion;
  v_result:=public.confirm_blueprint_order_change_internal_v1(
    p_spot_ids,p_input_data);
  IF COALESCE((v_result->>'success')::boolean,false) IS NOT TRUE THEN
    RETURN public.complete_client_mutation_outcome_v1(
      p_command_id,'rejected',400,v_result); END IF;
  RETURN public.complete_profile_inventory_membership_mutation_v1(
    p_command_id,v_occasion,'inventory.order.prepare_replace',
    jsonb_build_array(jsonb_build_object('entityType','order','entityId',NULL,
      'operation','update','safeLabel','Blueprint order replacement',
      'changedFields',jsonb_build_array('cancellations','allocations'))),
    v_before_users,v_result);
END; $$;


ALTER FUNCTION "public"."confirm_blueprint_order_change_client_sync_v1"("p_spot_ids" bigint[], "p_input_data" "jsonb", "p_command_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."confirm_blueprint_order_change_internal_v1"("p_spot_ids" bigint[], "p_input_data" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_analysis JSONB;
  v_ticket_ids_to_cancel BIGINT[];
  v_occasion_id BIGINT;
  v_form_key UUID;
  v_ticket_payloads JSONB := '[]'::JSONB;
  v_order_details JSONB;
  v_new_spot_rec RECORD;
  v_email TEXT;
BEGIN
  -- Extract Email for validation
  v_email := p_input_data->>'email';

  IF v_email IS NULL OR v_email = '' THEN
      RAISE EXCEPTION 'Email is required in input data.';
  END IF;

  -- 1. Analyze impacts
  v_analysis := public.analyze_new_order_spots(p_spot_ids);

  -- 2. Extract Ticket IDs for Storno
  SELECT ARRAY_AGG((elem->>'ticket_id')::BIGINT)
  INTO v_ticket_ids_to_cancel
  FROM jsonb_array_elements(v_analysis->'conflicts') elem
  WHERE elem->>'ticket_id' IS NOT NULL;

  -- 3. Perform Storno (if any conflicts exist)
  IF v_ticket_ids_to_cancel IS NOT NULL AND array_length(v_ticket_ids_to_cancel, 1) > 0 THEN
      PERFORM public.storno_tickets_bulk(v_ticket_ids_to_cancel);
  END IF;

  -- 4. Clean up Secrets on selected spots
  UPDATE eshop.spots
  SET secret = NULL, secret_expiration_time = NULL
  WHERE id = ANY(p_spot_ids);

  -- 5. Prepare Data for New Order

  -- Get occasion ID
  SELECT occasion INTO v_occasion_id FROM eshop.spots WHERE id = p_spot_ids[1];

  -- Security Check: User must be editor
  IF NOT public.get_is_editor_order_on_occasion(v_occasion_id) THEN
      RAISE EXCEPTION 'Permission denied. User is not an editor for occasion %', v_occasion_id;
  END IF;

  -- Validation: All spots must be on same occasion
  PERFORM 1 FROM eshop.spots
  WHERE id = ANY(p_spot_ids) AND occasion != v_occasion_id;

  IF FOUND THEN
      RAISE EXCEPTION 'All selected spots must belong to the same occasion.';
  END IF;

  -- Find a suitable Form
  SELECT key INTO v_form_key
  FROM public.forms
  WHERE occasion = v_occasion_id AND is_open = true
  ORDER BY type = 'ticket' DESC, id DESC
  LIMIT 1;

  IF v_form_key IS NULL THEN
      RAISE EXCEPTION 'No open form found for this occasion to create the new order.';
  END IF;

  -- Build "ticket" array for the payload
  FOR v_new_spot_rec IN
      SELECT s.id, s.product
      FROM eshop.spots s
      WHERE s.id = ANY(p_spot_ids)
  LOOP
      v_ticket_payloads := v_ticket_payloads || JSONB_BUILD_OBJECT(
          'spot', v_new_spot_rec.id,
          'fields', '[]'::JSONB
      );
  END LOOP;

  -- Construct payload for Edge Function
  -- We start with basic fields, then MERGE (||) the p_input_data
  -- This allows passing 'name', 'surname', 'note' in input_data automatically.
  v_order_details := JSONB_BUILD_OBJECT(
      'form', v_form_key,
      'ticket', v_ticket_payloads,
      'lang', 'cs'
  ) || p_input_data;

  -- Return Success + Payload
  RETURN JSONB_BUILD_OBJECT(
      'success', true,
      'message', 'Storno performed. Ready to create new order.',
      'orderDetails', v_order_details
  );

EXCEPTION WHEN OTHERS THEN
  RETURN JSONB_BUILD_OBJECT('success', false, 'message', SQLERRM);
END;
$$;


ALTER FUNCTION "public"."confirm_blueprint_order_change_internal_v1"("p_spot_ids" bigint[], "p_input_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."copy_form_with_fields"("p_source_form_id" bigint) RETURNS bigint
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    v_new_form_id BIGINT;
    v_source_form_exists BOOLEAN;
    v_new_form_title TEXT;
    v_new_form_link TEXT; -- Declare if you want to modify the link
BEGIN
    -- Check if the source form exists
    SELECT EXISTS (SELECT 1 FROM public.forms WHERE id = p_source_form_id) INTO v_source_form_exists;
    IF NOT v_source_form_exists THEN
        RAISE EXCEPTION 'Source form with ID % does not exist.', p_source_form_id;
    END IF;


    -- If you need to ensure the link is unique, you might modify it.
    -- For example, append a part of a new UUID or timestamp.
    -- SELECT link || '-' || LEFT(gen_random_uuid()::TEXT, 8) INTO v_new_form_link
    -- FROM public.forms
    -- WHERE id = p_source_form_id;
    -- If no modification is needed for the link, you can select it directly in the INSERT statement.

    -- 1. Create a copy of the form record
    INSERT INTO public.forms (
        created_at,
        data,
        key, -- new unique key
        occasion,
        type,
        bank_account,
        deadline_duration_seconds,
        is_open,
        link, -- use original link, or v_new_form_link if modified
        blueprint,
        header,
        header_off,
        updated_at
    )
    SELECT
        NOW(),
        f.data,
        gen_random_uuid(), -- Generate a new unique key
        f.occasion,
        f.type,
        f.bank_account,
        f.deadline_duration_seconds,
        f.is_open,
        f.link, -- Or v_new_form_link if you've defined and populated it
        f.blueprint,
        f.header,
        f.header_off,
        NOW()
    FROM public.forms f
    WHERE f.id = p_source_form_id
    RETURNING id INTO v_new_form_id;

    -- 2. Copy all associated form fields, linking them to the new form
    INSERT INTO public.form_fields (
        created_at,
        title,
        description,
        data,
        type,
        is_required,
        form,           -- This will be the ID of the new form
        is_hidden,
        "order",
        product_type,
        is_ticket_field
    )
    SELECT
        NOW(),
        ff.title,
        ff.description,
        ff.data,
        ff.type,
        ff.is_required,
        v_new_form_id,  -- Link to the newly created form
        ff.is_hidden,
        ff."order",
        ff.product_type,
        ff.is_ticket_field
    FROM public.form_fields ff
    WHERE ff.form = p_source_form_id;

    RETURN v_new_form_id;
END;
$$;


ALTER FUNCTION "public"."copy_form_with_fields"("p_source_form_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."copy_product_type_with_products"("p_source_product_type_id" bigint) RETURNS bigint
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    v_new_product_type_id BIGINT;
    v_source_product_type_exists BOOLEAN;
    v_new_product_type_title TEXT;
BEGIN
    -- Check if the source product_type exists
    SELECT EXISTS (SELECT 1 FROM eshop.product_types WHERE id = p_source_product_type_id) INTO v_source_product_type_exists;
    IF NOT v_source_product_type_exists THEN
        RAISE EXCEPTION 'Source product_type with ID % does not exist.', p_source_product_type_id;
    END IF;

    -- Create a slightly modified title for the copy
    SELECT title || ' (Copy ' || TO_CHAR(NOW(), 'YYYY-MM-DD HH24:MI:SS') || ')' INTO v_new_product_type_title
    FROM eshop.product_types
    WHERE id = p_source_product_type_id;

    -- 1. Create a copy of the product_type record
    INSERT INTO eshop.product_types (
        created_at,
        updated_at,
        title, -- use the modified title
        description,
        type,
        data,
        occasion,
        maximum
    )
    SELECT
        NOW(),
        NOW(),
        v_new_product_type_title, -- Use the new title
        pt.description,
        pt.type,
        pt.data,
        pt.occasion, -- Copied product type will belong to the same occasion
        pt.maximum
    FROM eshop.product_types pt
    WHERE pt.id = p_source_product_type_id
    RETURNING id INTO v_new_product_type_id;

    -- 2. Copy all associated products, linking them to the new product_type
    INSERT INTO eshop.products (
        created_at,
        updated_at,
        title,
        description,
        price,
        data,
        product_type, -- This will be the ID of the new product_type
        occasion,
        is_hidden,
        currency_code,
        title_short,
        "order",
        maximum
    )
    SELECT
        NOW(),
        NOW(),
        p.title, -- Product titles are copied as is
        p.description,
        p.price,
        p.data,
        v_new_product_type_id,  -- Link to the newly created product_type
        p.occasion, -- Copied products will belong to the same occasion as original products
        p.is_hidden,
        p.currency_code,
        p.title_short,
        p."order",
        p.maximum
    FROM eshop.products p
    WHERE p.product_type = p_source_product_type_id;

    RETURN v_new_product_type_id;
END;
$$;


ALTER FUNCTION "public"."copy_product_type_with_products"("p_source_product_type_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_account_deletion_request"("p_user" "uuid", "p_organization" bigint, "p_token_hash" "text", "p_expires_at" timestamp with time zone, "p_masked_email" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $_$
DECLARE
  v_previous public.account_deletion_requests%ROWTYPE;
  v_request public.account_deletion_requests%ROWTYPE;
BEGIN
  PERFORM public.require_service_role();
  IF p_token_hash !~ '^[0-9a-f]{64}$' OR p_expires_at <= clock_timestamp() THEN
    RAISE EXCEPTION 'account_deletion_invalid_request' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.user_info ui
    WHERE ui.id = p_user AND ui.organization = p_organization
  ) THEN
    RAISE EXCEPTION 'account_deletion_account_not_found' USING ERRCODE = 'P0002';
  END IF;

  SELECT * INTO v_previous
  FROM public.account_deletion_requests
  WHERE user_id = p_user
    AND status IN ('email_pending','email_sent','deletion_pending')
  ORDER BY created_at DESC LIMIT 1 FOR UPDATE;

  IF v_previous.status = 'deletion_pending' THEN
    RAISE EXCEPTION 'account_deletion_already_pending' USING ERRCODE = '55000';
  END IF;
  IF v_previous.id IS NOT NULL AND v_previous.cooldown_until > clock_timestamp() THEN
    RAISE EXCEPTION 'account_deletion_cooldown' USING ERRCODE = 'P0001';
  END IF;
  IF v_previous.id IS NOT NULL THEN
    UPDATE public.account_deletion_requests
    SET status = 'revoked', token_hash = NULL, masked_email = NULL,
        updated_at = clock_timestamp()
    WHERE id = v_previous.id;
  END IF;

  INSERT INTO public.account_deletion_requests(
    user_id, organization, token_hash, masked_email, expires_at, cooldown_until
  ) VALUES (
    p_user, p_organization, p_token_hash, p_masked_email, p_expires_at,
    clock_timestamp() + interval '5 minutes'
  ) RETURNING * INTO v_request;

  RETURN jsonb_build_object('requestId', v_request.id, 'expiresAt', v_request.expires_at);
END;
$_$;


ALTER FUNCTION "public"."create_account_deletion_request"("p_user" "uuid", "p_organization" bigint, "p_token_hash" "text", "p_expires_at" timestamp with time zone, "p_masked_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_companion_client_sync_v1"("p_occasion" bigint, "p_name" "text", "p_command_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_actor uuid:=auth.uid(); v_organization bigint; v_begin jsonb; v_hash text;
  v_result jsonb; v_before uuid[]; v_companion uuid; v_replacements jsonb;
BEGIN
  IF v_actor IS NULL OR nullif(btrim(p_name),'') IS NULL
    OR octet_length(p_name)>512 THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid companion'; END IF;
  SELECT o.organization INTO v_organization FROM public.occasions o
    JOIN public.occasion_users ou ON ou.occasion=o.id AND ou."user"=v_actor
    WHERE o.id=p_occasion;
  IF v_organization IS NULL THEN
    RAISE insufficient_privilege USING MESSAGE='occasion participant required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',p_occasion,'name',p_name)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'profile.companion.create',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'companion-owner:'||v_actor::text||':'||p_occasion::text,0));
  SELECT COALESCE(array_agg(uc.companion),'{}'::uuid[]) INTO v_before
    FROM public.user_companions uc WHERE uc.occasion=p_occasion AND uc."user"=v_actor;
  v_result:=public.create_companion_in_organization_internal_v1(
    v_organization,p_occasion,v_actor,p_name);
  IF COALESCE((v_result->>'code')::integer,500)<>200 THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',
      CASE WHEN (v_result->>'code')::integer=403 THEN 403 ELSE 400 END,
      jsonb_build_object('companion',NULL,'domainCode',v_result->'code'));
  END IF;
  SELECT uc.companion INTO v_companion FROM public.user_companions uc
    WHERE uc.occasion=p_occasion AND uc."user"=v_actor AND NOT uc.companion=ANY(v_before)
    ORDER BY uc.companion LIMIT 1;
  IF v_companion IS NULL THEN
    RAISE EXCEPTION 'companion handler did not create a companion'; END IF;
  v_replacements:=jsonb_build_array(jsonb_build_object(
    'component','private_profile','userId',v_actor,
    'payload',public.get_private_profile_payload_v1(p_occasion,v_actor)));
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'profile.companion.create','profile',jsonb_build_array(jsonb_build_object(
      'entityType','companion','entityId',v_companion,'operation','insert',
      'safeLabel','Companion','changedFields',jsonb_build_array('name'))),
    '{}',jsonb_build_array(jsonb_build_object('component','private_profile',
      'userId',v_actor)),'[]',jsonb_build_object('companion',jsonb_build_object(
        'id',v_companion,'name',p_name,'event_ids','[]'::jsonb)),
    '{}','[]','user',NULL,v_replacements);
END; $$;


ALTER FUNCTION "public"."create_companion_client_sync_v1"("p_occasion" bigint, "p_name" "text", "p_command_id" "uuid") OWNER TO "postgres";


