    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT public.create_counseling_slots_internal_v1(p_speaker,p_start,p_end,
    p_slot_minutes,p_place,p_capacity,p_title,p_break_minutes);
$$;


ALTER FUNCTION "public"."create_counseling_slots"("p_speaker" bigint, "p_start" timestamp with time zone, "p_end" timestamp with time zone, "p_slot_minutes" integer, "p_place" bigint, "p_capacity" integer, "p_title" "text", "p_break_minutes" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_counseling_slots_client_sync_v1"("p_speaker" bigint, "p_start" timestamp with time zone, "p_end" timestamp with time zone, "p_slot_minutes" integer, "p_place" bigint, "p_capacity" integer, "p_title" "text", "p_break_minutes" integer, "p_command_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_actor uuid:=auth.uid(); v_occasion bigint; v_begin jsonb; v_hash text;
  v_result jsonb; v_ids bigint[];
BEGIN
  SELECT s.occasion INTO v_occasion FROM public.speakers s WHERE s.id=p_speaker;
  IF v_actor IS NULL OR v_occasion IS NULL
    OR NOT public.get_is_editor_on_occasion(v_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('speaker',p_speaker,
    'start',p_start,'end',p_end,'slotMinutes',p_slot_minutes,'place',p_place,
    'capacity',p_capacity,'title',p_title,'breakMinutes',p_break_minutes)::text,
    'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'program.counseling.create',
    v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  PERFORM 1 FROM public.speakers s WHERE s.id=p_speaker FOR UPDATE;
  PERFORM pg_catalog.pg_advisory_xact_lock(p_speaker);
  v_result:=public.create_counseling_slots_internal_v1(p_speaker,p_start,p_end,
    p_slot_minutes,p_place,p_capacity,p_title,p_break_minutes);
  IF COALESCE((v_result->>'code')::integer,500)<>200 THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',
      COALESCE((v_result->>'code')::integer,400),COALESCE(v_result->'data','{}')); END IF;
  SELECT COALESCE(array_agg(value::bigint),'{}'::bigint[]) INTO v_ids
    FROM jsonb_array_elements_text(v_result#>'{data,event_ids}');
  IF cardinality(v_ids)=0 THEN RETURN public.complete_client_mutation_outcome_v1(
    p_command_id,'unchanged',200,v_result->'data'); END IF;
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  SELECT 'event','occasion',v_occasion,id::text,1 FROM unnest(v_ids) id;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,v_occasion,
    'program.counseling.create','program',jsonb_build_array(jsonb_build_object(
      'entityType','counseling_slot','entityId',NULL,'operation','insert',
      'safeLabel','Counseling slots','changedFields',jsonb_build_array('events','speakers'))),
    ARRAY['program_catalog','content_catalog'],'[]','[]',v_result->'data');
END; $$;


ALTER FUNCTION "public"."create_counseling_slots_client_sync_v1"("p_speaker" bigint, "p_start" timestamp with time zone, "p_end" timestamp with time zone, "p_slot_minutes" integer, "p_place" bigint, "p_capacity" integer, "p_title" "text", "p_break_minutes" integer, "p_command_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_counseling_slots_internal_v1"("p_speaker" bigint, "p_start" timestamp with time zone, "p_end" timestamp with time zone, "p_slot_minutes" integer, "p_place" bigint DEFAULT NULL::bigint, "p_capacity" integer DEFAULT 1, "p_title" "text" DEFAULT NULL::"text", "p_break_minutes" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
    v_occasion      BIGINT;
    v_speaker_title TEXT;
    v_type          TEXT;
    v_title         TEXT;
    v_slot_start    TIMESTAMPTZ;
    v_slot_end      TIMESTAMPTZ;
    v_event_id      BIGINT;
    v_ids           BIGINT[] := ARRAY[]::BIGINT[];
    v_count         INT := 0;
BEGIN
    SELECT occasion, title INTO v_occasion, v_speaker_title
    FROM public.speakers
    WHERE id = p_speaker;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('code', 404);
    END IF;

    IF NOT public.get_is_editor_on_occasion(v_occasion) THEN
        RETURN jsonb_build_object('code', 403);
    END IF;

    -- Parameter validation.
    IF p_slot_minutes IS NULL OR p_slot_minutes < 5
       OR p_start IS NULL OR p_end IS NULL OR p_start >= p_end
       OR p_capacity IS NULL OR p_capacity < 1
       OR p_break_minutes IS NULL OR p_break_minutes < 0 THEN
        RETURN jsonb_build_object('code', 400);
    END IF;

    IF p_place IS NOT NULL THEN
        IF NOT EXISTS (
            SELECT 1 FROM public.places
            WHERE id = p_place AND occasion = v_occasion
        ) THEN
            RETURN jsonb_build_object('code', 400);
        END IF;
    END IF;

    -- Event type comes from the "counseling" feature config (default 'counseling').
    SELECT COALESCE(elem->>'counseling_event_type', 'counseling')
    INTO v_type
    FROM public.occasions o
    CROSS JOIN LATERAL jsonb_array_elements(COALESCE(o.features, '[]'::jsonb)) elem
    WHERE o.id = v_occasion AND elem->>'code' = 'counseling'
    LIMIT 1;

    IF v_type IS NULL THEN
        v_type := 'counseling';
    END IF;

    v_title := COALESCE(p_title, v_speaker_title);

    -- Generate slots: last slot must fully fit within [p_start, p_end].
    v_slot_start := p_start;
    WHILE v_slot_start + make_interval(mins => p_slot_minutes) <= p_end LOOP
        v_slot_end := v_slot_start + make_interval(mins => p_slot_minutes);

        INSERT INTO public.events (occasion, title, start_time, end_time, max_participants, place, type, is_hidden, data)
        VALUES (
            v_occasion,
            v_title,
            v_slot_start,
            v_slot_end,
            p_capacity,
            p_place,
            v_type,
            FALSE,
            jsonb_build_object('is_counseling_slot', true)
        )
        RETURNING id INTO v_event_id;

        INSERT INTO public.event_speakers (event, speaker) VALUES (v_event_id, p_speaker);

        v_ids := array_append(v_ids, v_event_id);
        v_count := v_count + 1;

        v_slot_start := v_slot_start + make_interval(mins => p_slot_minutes + p_break_minutes);
    END LOOP;

    RETURN jsonb_build_object(
        'code', 200,
        'data', jsonb_build_object(
            'created',   v_count,
            'event_ids', to_jsonb(v_ids)
        )
    );
END;
$$;


ALTER FUNCTION "public"."create_counseling_slots_internal_v1"("p_speaker" bigint, "p_start" timestamp with time zone, "p_end" timestamp with time zone, "p_slot_minutes" integer, "p_place" bigint, "p_capacity" integer, "p_title" "text", "p_break_minutes" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_form"("p_occasion_id" bigint, "p_link" "text", "p_title" "text") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT public.create_form_internal_v1(p_occasion_id,p_link,p_title);
$$;


ALTER FUNCTION "public"."create_form"("p_occasion_id" bigint, "p_link" "text", "p_title" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_form_client_sync_v1"("p_occasion_link" "text", "p_link" "text", "p_title" "text", "p_command_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_actor uuid:=auth.uid(); v_occasion bigint; v_unit bigint;
  v_begin jsonb; v_hash text; v_form jsonb;
BEGIN
  SELECT o.id,o.unit INTO v_occasion,v_unit FROM public.occasions o
    WHERE o.link=p_occasion_link;
  IF v_actor IS NULL OR v_occasion IS NULL OR nullif(btrim(p_link),'') IS NULL
    OR length(p_link)>200 OR length(COALESCE(p_title,''))>500
    OR NOT (public.get_is_editor_on_unit(v_unit)
      OR public.get_is_editor_on_occasion(v_occasion)) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',v_occasion,'link',p_link,'title',p_title)::text,'UTF8'),
    'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'inventory.form.create',v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  IF EXISTS (SELECT 1 FROM public.forms f WHERE f.link=p_link) THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',
      409,jsonb_build_object('message','Form link is already in use')); END IF;
  v_form:=public.create_form_internal_v1(v_occasion,p_link,p_title);
  RETURN public.complete_private_inventory_mutation_v1(p_command_id,v_occasion,
    'inventory.form.create',jsonb_build_array(jsonb_build_object(
      'entityType','form','entityId',v_form->>'id','operation','insert',
      'safeLabel',left(p_title,240),'changedFields',jsonb_build_array(
        'configuration','fields','products'))),'{}'::uuid[],
    jsonb_build_object('form',v_form));
END; $$;


ALTER FUNCTION "public"."create_form_client_sync_v1"("p_occasion_link" "text", "p_link" "text", "p_title" "text", "p_command_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_form_internal_v1"("p_occasion_id" bigint, "p_link" "text", "p_title" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    new_form_id BIGINT;
    new_form JSONB;
    new_product_type_id BIGINT;
    now TIMESTAMPTZ := NOW();
BEGIN
    -- The definitive server-side uniqueness check for the form link
    IF EXISTS (SELECT 1 FROM public.forms WHERE link = p_link) THEN
        RAISE EXCEPTION '%',
            JSONB_BUILD_OBJECT('code', 4090, 'message', 'Form link is already in use')::TEXT;
    END IF;

    -- Create the new form
    INSERT INTO public.forms(
        title,
        link,
        occasion,
        created_at,
        updated_at,
        deadline_duration_seconds,
        data
    )
    VALUES (
        p_title,
        p_link,
        p_occasion_id,
        now,
        now,
        604800, -- Default to 7 days
        '{"is_reminder_enabled": true}'::jsonb -- Default reminder setting
    )
    RETURNING to_jsonb(public.forms.*) INTO new_form;

    new_form_id := (new_form->>'id')::BIGINT;

    -- Create default 'email' and 'ticket' fields
    INSERT INTO public.form_fields(title, type, is_required, form, "order")
    VALUES ('', 'email', true, new_form_id, 0),
           ('', 'ticket', true, new_form_id, 1);

    -- Ensure 'spot' product type exists for the occasion
    IF NOT EXISTS (SELECT 1 FROM eshop.product_types WHERE occasion = p_occasion_id AND type = 'spot') THEN
        INSERT INTO eshop.product_types(title, type, occasion)
        VALUES ('Spot', 'spot', p_occasion_id)
        RETURNING id INTO new_product_type_id;
    ELSE
        SELECT id INTO new_product_type_id FROM eshop.product_types WHERE occasion = p_occasion_id AND type = 'spot' LIMIT 1;
    END IF;

    -- Ensure the 'spot' product type has at least one product
    IF NOT EXISTS (SELECT 1 FROM eshop.products WHERE occasion = p_occasion_id AND product_type = new_product_type_id) THEN
        INSERT INTO eshop.products(title, price, product_type, occasion, currency_code, "order")
        VALUES ('Variant 1', 100, new_product_type_id, p_occasion_id, 'CZK', 0);
    END IF;

    -- Create the 'product_type' form field linked to 'spot'
    INSERT INTO public.form_fields(title, type, is_required, form, "order", product_type, is_ticket_field)
    VALUES ('Spot', 'product_type', false, new_form_id, 2, new_product_type_id, true);

    -- Return the raw data of the newly created form
    RETURN new_form;
END;
$$;


ALTER FUNCTION "public"."create_form_internal_v1"("p_occasion_id" bigint, "p_link" "text", "p_title" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_form_ws"("input_data" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_response jsonb;
BEGIN
  IF input_data IS NULL OR jsonb_typeof(input_data)<>'object'
    OR EXISTS (SELECT 1 FROM jsonb_object_keys(input_data) k
      WHERE k NOT IN ('occasion_link','link','title')) THEN
    RETURN jsonb_build_object('code',4000,'message','Invalid form input'); END IF;
  v_response:=public.create_form_client_sync_v1(input_data->>'occasion_link',
    input_data->>'link',input_data->>'title',extensions.gen_random_uuid());
  RETURN jsonb_build_object('code',CASE WHEN v_response->>'status'='applied'
      THEN 201 ELSE (v_response->>'code')::integer END,
    'message',CASE WHEN v_response->>'status'='applied'
      THEN 'Form created successfully' ELSE v_response#>>'{data,message}' END,
    'data',v_response#>'{data,form}');
END; $$;


ALTER FUNCTION "public"."create_form_ws"("input_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_form_ws_obsolete_v1"("input_data" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    result JSONB;
    v_occasion_id BIGINT;
    v_unit_id BIGINT;
    v_link TEXT;
    v_title TEXT;
    v_occasion_link TEXT;
    new_form_data JSONB;
BEGIN
    BEGIN
        -- Check for required input data from the client
        v_occasion_link := input_data->>'occasion_link';
        v_link := input_data->>'link';
        v_title := input_data->>'title';

        IF v_occasion_link IS NULL OR v_link IS NULL THEN
            RAISE EXCEPTION '%',
                JSONB_BUILD_OBJECT('code', 4000, 'message', 'Input data is missing required fields (occasion_link, link)')::TEXT;
        END IF;

        -- Fetch occasion details from the user-friendly link
        SELECT id, unit INTO v_occasion_id, v_unit_id
        FROM public.occasions
        WHERE link = v_occasion_link;

        IF NOT FOUND THEN
             RAISE EXCEPTION '%',
                JSONB_BUILD_OBJECT('code', 4040, 'message', 'Occasion not found')::TEXT;
        END IF;

        -- Perform the required permission checks
        IF NOT (
            (SELECT get_is_editor_on_unit(v_unit_id)) OR
            (SELECT get_is_editor_on_occasion(v_occasion_id))
        ) THEN
            RAISE EXCEPTION '%',
                JSONB_BUILD_OBJECT('code', 4030, 'message', 'Permission denied to create form for this occasion.')::TEXT;
        END IF;

        -- UPDATED: Call the renamed internal function
        new_form_data := create_form(
            p_occasion_id := v_occasion_id,
            p_link := v_link,
            p_title := v_title
        );

        -- Build the success response for the client
        result := JSONB_BUILD_OBJECT(
            'code', 201, -- 201 Created
            'message', 'Form created successfully',
            'data', new_form_data
        );

    EXCEPTION WHEN OTHERS THEN
        -- Catch any exceptions (from this function or the internal one) and format them
        result := CASE
            WHEN left(SQLERRM, 1) = '{' THEN SQLERRM::JSONB
            ELSE JSONB_BUILD_OBJECT('code', 5000, 'message', SQLERRM)
        END;
    END;

    RETURN result;
END;
$$;


ALTER FUNCTION "public"."create_form_ws_obsolete_v1"("input_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_occasion_client_sync_v1"("p_command_id" "uuid", "p_config" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_actor uuid:=auth.uid(); v_unit bigint; v_organization bigint;
  v_occasion bigint; v_begin jsonb; v_hash text; v_commit public.client_commits%ROWTYPE;
  v_entity jsonb;
BEGIN
  IF p_config IS NULL OR jsonb_typeof(p_config)<>'object'
    OR octet_length(p_config::text)>1048576
    OR EXISTS (SELECT 1 FROM jsonb_object_keys(p_config) key WHERE key NOT IN
      ('id','start_time','end_time','is_open','is_hidden','is_promoted','link','title',
       'description','data','services','organization','unit','features','form_link',
       'has_orders','stats'))
    OR p_config->>'id' IS NOT NULL OR nullif(btrim(p_config->>'link'),'') IS NULL
    OR nullif(btrim(p_config->>'title'),'') IS NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid occasion aggregate'; END IF;
  v_unit:=NULLIF(p_config->>'unit','')::bigint;
  v_organization:=NULLIF(p_config->>'organization','')::bigint;
  IF v_actor IS NULL OR v_unit IS NULL OR v_organization IS NULL
    OR NOT EXISTS (SELECT 1 FROM public.units u
      WHERE u.id=v_unit AND u.organization=v_organization)
    OR NOT (public.get_is_manager_on_unit(v_unit)
      OR public.get_is_editor_on_unit(v_unit)) THEN
    RAISE insufficient_privilege USING MESSAGE='unit editor required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(p_config::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_unit_client_mutation_v1(p_command_id,
    'occasion.create',v_unit,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  IF EXISTS (SELECT 1 FROM public.occasions o
    WHERE o.organization=v_organization AND o.link=p_config->>'link') THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',
      409,jsonb_build_object('message','Occasion link is already in use')); END IF;
  PERFORM public.update_occasion_internal_v1(p_config);
  SELECT o.id,to_jsonb(o)||jsonb_build_object('aggregate_version',1)
    INTO v_occasion,v_entity FROM public.occasions o
    WHERE o.organization=v_organization AND o.link=p_config->>'link';
  IF v_occasion IS NULL THEN
    RAISE data_exception USING MESSAGE='occasion create returned no aggregate'; END IF;
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES ('occasion','occasion',v_occasion,v_occasion::text,1);
  INSERT INTO public.client_commits
    (unit,actor_id,actor_display,actor_kind,source,change_class)
  SELECT v_unit,v_actor,nullif(concat_ws(' ',ui.name,ui.surname),''),'user',
    'occasion.create','configuration' FROM public.user_info ui WHERE ui.id=v_actor
  RETURNING * INTO v_commit;
  INSERT INTO public.client_commit_items
    (commit_id,item_index,entity_type,entity_id,operation,safe_label,changed_fields)
  VALUES (v_commit.commit_id,0,'occasion',v_occasion::text,'insert',
    left(v_entity->>'title',240),ARRAY['aggregate']);
  PERFORM public.fanout_unit_catalog_v1(v_commit.commit_id,v_unit);
  RETURN public.finish_client_mutation_v1(p_command_id,jsonb_build_object(
    'status','applied','code',200,'data',jsonb_build_object(
      'occasionId',v_occasion,'occasion',v_entity),
    'mutation',jsonb_build_object('commandId',p_command_id,
      'receiptId',p_command_id,'commitId',v_commit.commit_id,'replayed',false,
      'occurredAt',v_commit.occurred_at),
    'sync',jsonb_build_object('replacements','[]'::jsonb)),v_commit.commit_id);
END; $$;


ALTER FUNCTION "public"."create_occasion_client_sync_v1"("p_command_id" "uuid", "p_config" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_occasion_user_client_sync_v1"("p_occasion" bigint, "p_command_id" "uuid", "p_profile" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_actor uuid:=auth.uid(); v_user uuid; v_begin jsonb; v_hash text;
  v_version bigint;
  v_result jsonb; v_profile jsonb; v_entity jsonb;
BEGIN
  IF v_actor IS NULL OR NOT (public.get_is_manager_on_occasion(p_occasion)
    OR public.get_is_admin_on_occasion(p_occasion)) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion manager required'; END IF;
  IF p_profile IS NULL OR jsonb_typeof(p_profile)<>'object'
    OR octet_length(p_profile::text)>262144
    OR (p_profile->>'occasion')::bigint IS DISTINCT FROM p_occasion
    OR p_profile->>'user' IS NOT NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid new occasion user profile'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,
    'profile',p_profile)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'profile.user.create',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  v_result:=public.update_user_internal_v1(jsonb_build_object(
    'occasion',p_occasion,'user',NULL,'data',p_profile->'data'));
  IF COALESCE((v_result->>'code')::integer,500) NOT IN (200,201) THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',
      COALESCE((v_result->>'code')::integer,400),jsonb_build_object(
        'version',0,'profile',NULL,'message',v_result->>'message')); END IF;
  v_user:=(v_result->>'user')::uuid;
  v_result:=public.add_user_to_occasion_internal_v1(p_occasion,v_user);
  IF COALESCE((v_result->>'code')::integer,500)<>200 THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',
      COALESCE((v_result->>'code')::integer,400),jsonb_build_object(
        'version',0,'profile',NULL,'message',v_result->>'message')); END IF;
  v_profile:=p_profile||jsonb_build_object('user',v_user);
  v_result:=public.save_occasion_user_for_edit_internal_v1(v_profile);
  IF COALESCE((v_result->>'code')::integer,500)<>200 THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',
      COALESCE((v_result->>'code')::integer,400),jsonb_build_object(
        'version',0,'profile',NULL,'message',v_result->>'message')); END IF;
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES ('occasion_user','occasion',p_occasion,v_user::text,1)
  ON CONFLICT (aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE
    SET version=public.client_aggregate_versions.version+1,
      updated_at=clock_timestamp() RETURNING version INTO v_version;
  SELECT public.get_occasion_user_command_data_v1(p_occasion,v_user) INTO v_entity;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'profile.user.create','profile',jsonb_build_array(jsonb_build_object(
      'entityType','occasion_user','entityId',v_user,'operation','insert',
      'safeLabel','Occasion user','changedFields',jsonb_build_array('profile','rights','services'))),
    '{}',jsonb_build_array(jsonb_build_object('component','private_profile',
    'userId',v_user)),'[]',jsonb_build_object('version',v_version,'userId',v_user,
      'profile',v_entity));
END; $$;


ALTER FUNCTION "public"."create_occasion_user_client_sync_v1"("p_occasion" bigint, "p_command_id" "uuid", "p_profile" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_service_item"("oc" bigint, "type" "text", "code" "text", "title" "text", "reference" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN RETURN public.create_service_item_client_sync_v1(
  oc,type,code,title,reference,extensions.gen_random_uuid())->'data'; END; $$;


ALTER FUNCTION "public"."create_service_item"("oc" bigint, "type" "text", "code" "text", "title" "text", "reference" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_service_item_client_sync_v1"("p_occasion" bigint, "p_type" "text", "p_code" "text", "p_title" "text", "p_reference" bigint, "p_command_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_actor uuid:=auth.uid(); v_begin jsonb; v_hash text; v_result jsonb;
  v_before jsonb; v_after jsonb;
BEGIN
  IF v_actor IS NULL OR p_type NOT IN ('food','accommodation')
    OR nullif(btrim(p_code),'') IS NULL OR length(p_code)>100
    OR length(COALESCE(p_title,''))>500
    OR NOT public.get_is_manager_on_occasion(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion manager required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',p_occasion,'type',p_type,'code',p_code,'title',p_title,
    'reference',p_reference)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'occasion.service.create',p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  SELECT o.services INTO v_before FROM public.occasions o
    WHERE o.id=p_occasion FOR UPDATE;
  v_result:=public.create_service_item_internal_v1(
    p_occasion,p_type,p_code,p_title,p_reference);
  IF COALESCE((v_result->>'code')::integer,500)<>200 THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',
      400,v_result); END IF;
  SELECT o.services INTO v_after FROM public.occasions o WHERE o.id=p_occasion;
  IF v_before IS NOT DISTINCT FROM v_after THEN
    RETURN public.complete_client_mutation_outcome_v1(
      p_command_id,'unchanged',200,v_result); END IF;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'occasion.service.create','configuration',jsonb_build_array(jsonb_build_object(
      'entityType','occasion_service','entityId',p_code,'operation','insert',
      'safeLabel',left(p_title,240),'changedFields',jsonb_build_array('services'))),
    ARRAY['occasion_config'],'[]','[]',v_result);
END; $$;


ALTER FUNCTION "public"."create_service_item_client_sync_v1"("p_occasion" bigint, "p_type" "text", "p_code" "text", "p_title" "text", "p_reference" bigint, "p_command_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_service_item_internal_v1"("oc" bigint, "type" "text", "code" "text", "title" "text", "reference" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  existing_codes JSONB;
  new_service_item JSONB;
BEGIN

  IF (SELECT get_is_manager_on_occasion(oc)) <> TRUE THEN
    RETURN jsonb_build_object('code', 403);
  END IF;

  -- Check if the code already exists within the specified type
  SELECT jsonb_agg(item)
  INTO existing_codes
  FROM public.occasions,
       jsonb_array_elements(COALESCE(occasions.services->type, '[]'::jsonb)) AS item
  WHERE occasions.id = oc
    AND (item->>'code') = code;

  IF existing_codes IS NOT NULL THEN
    -- If code exists, return an error response
    RETURN jsonb_build_object(
      'code', 400,
      'message', 'Code must be unique within the specified type'
    );
  END IF;

  -- Build the new service item JSON
  new_service_item := jsonb_build_object(
    'code', code,
    'title', title,
    'reference', reference
  );

  -- Update the occasion to add the new item to the specified type array in services.
  -- Guard against `services` being SQL NULL *or* a JSON scalar/`null` (which
  -- COALESCE does not catch and which makes jsonb_set raise
  -- "cannot set path in scalar"). Same guard for the per-type array.
  UPDATE public.occasions
  SET services = jsonb_set(
    CASE WHEN jsonb_typeof(services) = 'object' THEN services ELSE '{}'::jsonb END,
    ARRAY[type],
    CASE WHEN jsonb_typeof(services->type) = 'array' THEN services->type ELSE '[]'::jsonb END || new_service_item,
    true
  )
  WHERE id = oc;

  -- Return success response
  RETURN jsonb_build_object(
    'code', 200,
    'message', 'Service item created successfully'
  );
END;
$$;


ALTER FUNCTION "public"."create_service_item_internal_v1"("oc" bigint, "type" "text", "code" "text", "title" "text", "reference" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_spots_for_inventory_pool"("p_inventory_pool_id" bigint) RETURNS integer
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    v_context RECORD;
    v_resource RECORD;
    v_spots_to_create BIGINT;
    v_spots_to_delete BIGINT;
    v_booked_spots_count BIGINT;
    v_total_spots_count BIGINT;
    v_deletable_spot_ids BIGINT[];
    v_net_change INTEGER := 0;
    v_pool_occasion_id BIGINT;
    v_total_pool_capacity BIGINT;
BEGIN
    -- Step 0: Validate input and get occasion ID.
    SELECT occasion INTO v_pool_occasion_id FROM public.inventory_pools WHERE id = p_inventory_pool_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Inventory pool with ID % not found.', p_inventory_pool_id;
    END IF;

    -- Calculate the total capacity for the entire pool once. This is the target for the generic pool.
    SELECT COALESCE(SUM(capacity), 0) INTO v_total_pool_capacity
    FROM public.resources
    WHERE inventory_pool = p_inventory_pool_id;

    -- =================================================================
    -- Main Synchronization Loop (per context)
    -- =================================================================
    FOR v_context IN
        SELECT id FROM public.inventory_contexts WHERE inventory_pool = p_inventory_pool_id
    LOOP
        -- =============================================================
        -- Part A: Cleanup of RESOURCE-SPECIFIC Spots for this context
        -- =============================================================
        FOR v_resource IN
            SELECT id, capacity FROM public.resources WHERE inventory_pool = p_inventory_pool_id
        LOOP
            -- Count spots for the current resource WITHIN the current context.
            SELECT count(*) INTO v_total_spots_count FROM eshop.spots WHERE inventory_context = v_context.id AND resource = v_resource.id;
            SELECT count(*) INTO v_booked_spots_count FROM eshop.spots WHERE inventory_context = v_context.id AND resource = v_resource.id AND order_product_ticket IS NOT NULL;

            IF v_booked_spots_count > v_resource.capacity THEN
                RAISE EXCEPTION 'Cannot synchronize. For Context ID % and Resource ID %, there are % booked spots, which exceeds resource capacity of %. Manual intervention required.', v_context.id, v_resource.id, v_booked_spots_count, v_resource.capacity;
            END IF;

            IF v_total_spots_count > v_resource.capacity THEN
                v_spots_to_delete := v_total_spots_count - v_resource.capacity;
                SELECT array_agg(id) INTO v_deletable_spot_ids FROM (
                    SELECT id FROM eshop.spots
                    WHERE inventory_context = v_context.id AND resource = v_resource.id AND order_product_ticket IS NULL
                    ORDER BY created_at DESC
                    LIMIT v_spots_to_delete
                ) AS sub;

                IF array_length(v_deletable_spot_ids, 1) < v_spots_to_delete THEN
                     RAISE EXCEPTION 'Cannot delete excess spots for Context ID % and Resource ID %. Deletion would require removing a booked spot.', v_context.id, v_resource.id;
                END IF;

                DELETE FROM eshop.spots WHERE id = ANY(v_deletable_spot_ids);
                v_net_change := v_net_change - v_spots_to_delete;
            END IF;
        END LOOP;

        -- =============================================================
        -- Part B: Management of GENERIC Spot Pool for this context
        -- =============================================================
        -- Count total and booked spots for the GENERIC pool (resource IS NULL) within the current context.
        SELECT count(*) INTO v_total_spots_count FROM eshop.spots WHERE inventory_context = v_context.id;
        SELECT count(*) INTO v_booked_spots_count FROM eshop.spots WHERE inventory_context = v_context.id AND order_product_ticket IS NOT NULL;

        IF v_booked_spots_count > v_total_pool_capacity THEN
            RAISE EXCEPTION 'Cannot synchronize. Inventory Context ID % has % booked generic spots, which exceeds the total pool capacity of %. Manual intervention required.', v_context.id, v_booked_spots_count, v_total_pool_capacity;
        END IF;

        -- DELETION of generic spots
        IF v_total_spots_count > v_total_pool_capacity THEN
            v_spots_to_delete := v_total_spots_count - v_total_pool_capacity;
            SELECT array_agg(id) INTO v_deletable_spot_ids FROM (
                SELECT id FROM eshop.spots
                WHERE inventory_context = v_context.id AND resource IS NULL AND order_product_ticket IS NULL
                ORDER BY created_at DESC
                LIMIT v_spots_to_delete
            ) AS sub;

            IF array_length(v_deletable_spot_ids, 1) < v_spots_to_delete THEN
                 RAISE EXCEPTION 'Cannot delete excess generic spots for Context ID %. Deletion would require removing a booked spot.', v_context.id;
            END IF;

            DELETE FROM eshop.spots WHERE id = ANY(v_deletable_spot_ids);
            v_net_change := v_net_change - v_spots_to_delete;
        END IF;

        -- CREATION of generic spots
        -- Recount after potential deletion to get the current number.
        SELECT count(*) INTO v_total_spots_count FROM eshop.spots WHERE inventory_context = v_context.id;

        IF v_total_spots_count < v_total_pool_capacity THEN
            v_spots_to_create := v_total_pool_capacity - v_total_spots_count;

            -- Insert the required number of new generic spots.
            -- Per instructions, ONLY occasion and inventory_context are set.
            INSERT INTO eshop.spots (occasion, inventory_context)
            SELECT
                v_pool_occasion_id,
                v_context.id
            FROM generate_series(1, v_spots_to_create);

            v_net_change := v_net_change + v_spots_to_create;
        END IF;
    END LOOP;

    RETURN v_net_change;

END;
$$;


ALTER FUNCTION "public"."create_spots_for_inventory_pool"("p_inventory_pool_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_ticket_order"("input_data" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  RETURN public.create_ticket_order_client_sync_v1(input_data,
    extensions.gen_random_uuid(),COALESCE(auth.uid(),extensions.gen_random_uuid()))->'data';
END; $$;


ALTER FUNCTION "public"."create_ticket_order"("input_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_ticket_order_client_sync_v1"("p_order" "jsonb", "p_command_id" "uuid", "p_client_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_actor uuid:=auth.uid(); v_occasion bigint; v_begin jsonb; v_hash text;
  v_result jsonb; v_before_users uuid[]; v_actor_kind text;
BEGIN
  IF p_order IS NULL OR jsonb_typeof(p_order)<>'object'
    OR octet_length(p_order::text)>4194304 OR p_command_id IS NULL
    OR (v_actor IS NULL AND p_client_id IS NULL) THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid ticket order command'; END IF;
  SELECT f.occasion INTO v_occasion FROM public.forms f
    WHERE f.key=NULLIF(p_order->>'form','')::uuid;
  IF v_occasion IS NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='ticket order form not found'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',v_occasion,'order',p_order)::text,'UTF8'),'sha256'),'hex');
  IF v_actor IS NULL THEN
    v_begin:=public.begin_anonymous_client_mutation_v1(p_command_id,
      'inventory.order.create',v_occasion,p_client_id,v_hash);
    v_actor_kind:='unknown';
  ELSE
    v_begin:=public.begin_client_mutation_v1(p_command_id,
      'inventory.order.create',v_occasion,v_actor,v_hash);
    v_actor_kind:='user';
  END IF;
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  SELECT COALESCE(array_agg(ou."user"),'{}'::uuid[]) INTO v_before_users
    FROM public.occasion_users ou WHERE ou.occasion=v_occasion;
  v_result:=public.create_ticket_order_internal_v1(p_order);
  IF COALESCE((v_result->>'code')::integer,500)<>200 THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',
      CASE WHEN COALESCE((v_result->>'code')::integer,500) BETWEEN 100 AND 599
        THEN (v_result->>'code')::integer ELSE 400 END,v_result); END IF;
  PERFORM public.enqueue_ticket_order_confirmation_v1(
    p_command_id,v_occasion,v_result,p_order->>'lang');
  RETURN public.complete_profile_inventory_membership_mutation_v1(
    p_command_id,v_occasion,'inventory.order.create',jsonb_build_array(jsonb_build_object(
      'entityType','order','entityId',v_result#>>'{order,id}','operation','insert',
      'safeLabel','Ticket order','changedFields',jsonb_build_array(
        'tickets','products','allocations','membership'))),v_before_users,v_result,
    v_actor_kind);
END; $$;


ALTER FUNCTION "public"."create_ticket_order_client_sync_v1"("p_order" "jsonb", "p_command_id" "uuid", "p_client_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_ticket_order_internal_v1"("input_data" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
    result JSONB;
    order_id BIGINT;
    ticket_data JSONB;
    spot_data RECORD;
    spot_id BIGINT;
    spot_product RECORD;
    now TIMESTAMPTZ := NOW();
    calculated_price NUMERIC(10,2) := 0;
    spot_secret UUID;
    product_id BIGINT;
    ordered_count BIGINT;
    used_spots JSONB := '[]'::JSONB;
    occasion_id BIGINT;
    organization_id BIGINT;
    unit_id BIGINT;
    occasion_title TEXT;
    occasion_features JSONB;
    account_number TEXT;
    account_number_human_readable TEXT;
    ticket_details JSONB := '[]'::JSONB;
    product_data RECORD;
    ticket_id BIGINT;
    order_product_ticket_id BIGINT;
    ticket_symbol TEXT;
    ticket_products JSONB := '[]'::JSONB;
    payment_info_id BIGINT;
    generated_variable_symbol BIGINT;
    bank_account_id BIGINT;
    form_key UUID;
    deadline TIMESTAMPTZ;
    form_deadline_duration BIGINT;
    form_data JSONB;
    currency_code TEXT;
    first_currency_code TEXT := NULL;
    field_item JSONB;
    products_array BIGINT[] := '{}';
    form_id BIGINT;
    field_type TEXT;
    key_val RECORD;
    order_data JSONB;
    order_note TEXT;
    ticket_note TEXT;
    reply_to TEXT;
    is_open_val BOOLEAN;
    is_editor BOOLEAN;
    v_product_deposit NUMERIC;
    v_total_deposit NUMERIC := 0;
BEGIN
    -- Wrap the entirelogic in a subtransaction block
    BEGIN
        -- Validate input_data and extract form key and email
        IF input_data IS NULL OR input_data->'form' IS NULL THEN
            RAISE EXCEPTION '%', JSONB_BUILD_OBJECT('code', 1001, 'message', 'Missing form key in input data')::TEXT;
        END IF;

        form_key := (input_data->>'form')::UUID;
        SELECT id, occasion, bank_account, deadline_duration_seconds, data, is_open
        INTO form_id, occasion_id, bank_account_id, form_deadline_duration, form_data, is_open_val
        FROM public.forms
        WHERE key = form_key;

        IF occasion_id IS NULL THEN
            RAISE EXCEPTION '%', JSONB_BUILD_OBJECT('code', 1003, 'message', 'Form is not linked to any occasion')::TEXT;
        END IF;

        is_editor := public.get_is_editor_order_on_occasion(occasion_id);

        IF NOT is_editor THEN
            IF is_open_val IS FALSE THEN
                 RAISE EXCEPTION '%', JSONB_BUILD_OBJECT('code', 1021, 'message', 'Form is closed')::TEXT;
            END IF;

            -- Check for start_time and end_time constraints only if not editor
            IF COALESCE(form_data->'schedule'->>'start_time', form_data->>'start_time') IS NOT NULL THEN
                IF now < (COALESCE(form_data->'schedule'->>'start_time', form_data->>'start_time'))::TIMESTAMPTZ THEN
                    RAISE EXCEPTION '%', JSONB_BUILD_OBJECT('code', 1019, 'message', 'Form is not yet open')::TEXT;
                END IF;
            END IF;

            IF COALESCE(form_data->'schedule'->>'end_time', form_data->>'end_time') IS NOT NULL THEN
                IF now > (COALESCE(form_data->'schedule'->>'end_time', form_data->>'end_time'))::TIMESTAMPTZ THEN
                    RAISE EXCEPTION '%', JSONB_BUILD_OBJECT('code', 1020, 'message', 'Form is closed')::TEXT;
                END IF;
            END IF;
        END IF;

        -- Fetch organization, unit, and occasion title from the occasion
        SELECT organization, unit, title, features
        INTO organization_id, unit_id, occasion_title, occasion_features
        FROM public.occasions
        WHERE id = occasion_id;

        IF organization_id IS NULL THEN
            RAISE EXCEPTION '%', JSONB_BUILD_OBJECT('code', 1005, 'message', 'No organization found for the occasion')::TEXT;
        END IF;

        IF input_data ? 'fields' THEN
            DECLARE
                valid_fields JSONB := '[]'::JSONB;
                elem JSONB;
                field_key TEXT;
            BEGIN
                FOR elem IN SELECT * FROM jsonb_array_elements(input_data->'fields')
                LOOP
                    field_key := (SELECT key FROM jsonb_object_keys(elem) AS key);

                    IF field_key IS NULL THEN
                        CONTINUE;
                    END IF;

                    -- Validate the field against the form_fields table
                    SELECT ff.type INTO field_type
                    FROM public.form_fields ff
                    WHERE ff.id = field_key::BIGINT AND ff.form = form_id AND ff.is_hidden = false;

                    IF FOUND THEN
                        valid_fields := valid_fields || elem;

                        IF field_type IN ('email', 'name', 'surname', 'phone', 'note') THEN
                            input_data := jsonb_set(input_data, ARRAY[field_type], elem->field_key, true);
                        END IF;
                    END IF;
                END LOOP;

                input_data := jsonb_set(input_data, '{fields}', valid_fields);
            END;
        END IF;

        IF input_data->>'email' IS NULL THEN
            RAISE EXCEPTION '%', JSONB_BUILD_OBJECT('code', 1002, 'message', 'Missing email in input data')::TEXT;
        END IF;

        INSERT INTO eshop.orders (created_at, updated_at, occasion, form)
        VALUES (now, now, occasion_id, form_id)
        RETURNING id INTO order_id;

        -- Process each ticket
        FOR ticket_data IN SELECT * FROM JSONB_ARRAY_ELEMENTS(input_data->'ticket') LOOP

            spot_data := NULL;
            spot_product := NULL;
            spot_id := NULL;
            ticket_note := NULL;

            IF ticket_data->>'spot' IS NOT NULL THEN
                SELECT * INTO spot_data
                FROM eshop.spots
                WHERE id = (ticket_data->>'spot')::BIGINT
                  AND occasion = occasion_id;

                IF spot_data IS NULL THEN
                    RAISE EXCEPTION '%', JSONB_BUILD_OBJECT('code', 1007, 'message', 'Invalid or unrelated spot')::TEXT;
                END IF;

                IF spot_data.order_product_ticket IS NOT NULL THEN
                    RAISE EXCEPTION '%', JSONB_BUILD_OBJECT('code', 1008, 'message', 'Spot is already reserved or in use')::TEXT;
                END IF;

                spot_secret := (input_data->>'secret')::UUID;
                IF spot_data.secret IS DISTINCT FROM spot_secret THEN
                    RAISE EXCEPTION '%', JSONB_BUILD_OBJECT('code', 1009, 'message', 'Invalid secret for spot')::TEXT;
                END IF;

                spot_id := spot_data.id;
                used_spots := used_spots || JSONB_BUILD_ARRAY(spot_id);

                SELECT i.*, it.type, it.title as type_title, spot_data.title as spot_title
                INTO spot_product
                FROM eshop.products i
                LEFT JOIN eshop.product_types it ON i.product_type = it.id
                WHERE i.id = spot_data.product;
            END IF;

            products_array := '{}';
            IF ticket_data ? 'fields' THEN
                FOR field_item IN SELECT * FROM JSONB_ARRAY_ELEMENTS(ticket_data->'fields')
                LOOP
                    IF field_item ? 'note' THEN
                        ticket_note := field_item->>'note';
                    END IF;
                    IF field_item ? 'product_type' THEN
                        products_array := products_array || ((field_item->>'product_type')::BIGINT);
                    END IF;
                END LOOP;
            END IF;

            ticket_symbol := generate_ticket_symbol(organization_id, occasion_id);
            INSERT INTO eshop.tickets (state, occasion, ticket_symbol, note, created_at, updated_at)
            VALUES ('ordered', occasion_id, ticket_symbol, ticket_note, now, now)
            RETURNING id INTO ticket_id;

            ticket_products := '[]'::JSONB;

            IF spot_id IS NOT NULL THEN
                products_array := products_array || spot_product.id;
            END IF;

            FOREACH product_id IN ARRAY products_array LOOP

                IF product_id IS NULL THEN
                    CONTINUE;
                END IF;

                SELECT i.*, it.type, it.title AS type_title, '' AS spot_title
                INTO product_data
                FROM eshop.products i
                LEFT JOIN eshop.product_types it ON i.product_type = it.id
                WHERE i.id = product_id
                  AND it.occasion = occasion_id;

                IF product_data IS NULL THEN
                    RAISE EXCEPTION '%',
                        jsonb_build_object(
                            'code', 1011,
                            'message', 'Product not found or not part of occasion',
                            'details', product_id
                        )::text;
                END IF;

                IF COALESCE(product_data.maximum, 0) > 0 THEN
                    SELECT COUNT(*) INTO ordered_count
                    FROM eshop.order_product_ticket
                    WHERE product = product_id;
                    IF ordered_count + 1 > product_data.maximum THEN
                        RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
                            'code', 1017,
                            'message', 'Product is overbooked',
                            'product', jsonb_strip_nulls(JSONB_BUILD_OBJECT(
                                'id', product_data.id,
                                'title', product_data.title,
                                'price', product_data.price,
                                'type', product_data.type,
                                'currency_code', product_data.currency_code
                            ))
                        )::TEXT;
                    END IF;
                END IF;

                IF product_data.type = 'spot' AND spot_product IS NULL THEN
                    spot_product := product_data;
                END IF;

                IF product_data.is_hidden THEN
                    RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
                        'code', 1012,
                        'message', 'Selected product is hidden and cannot be ordered',
                        'id', product_id
                    )::TEXT;
                END IF;

                IF first_currency_code IS NULL THEN
                    first_currency_code := product_data.currency_code;
                ELSE
                    IF product_data.currency_code IS DISTINCT FROM first_currency_code THEN
                        RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
                            'code', 1014,
                            'message', 'Products in the order must have the same currency',
                            'expected_currency', first_currency_code,
                            'actual_currency', product_data.currency_code
                        )::TEXT;
                    END IF;
                END IF;

                -- Build the product details for the ticket
                DECLARE
                    v_spot_title TEXT := NULL;
                    v_spot_description TEXT := NULL;
                BEGIN
                    -- Safe extraction of spot details
                    IF spot_id IS NOT NULL AND spot_product IS NOT NULL THEN
                         -- Only access fields if we have a spot_id (implies spot_product is fully set from spot lookup)
                         -- AND product_id matches.
                         IF product_id = spot_product.id THEN
                             v_spot_title := spot_product.spot_title;
                             v_spot_description := spot_product.description;
                         END IF;
                    END IF;

                    ticket_products := ticket_products || jsonb_strip_nulls(JSONB_BUILD_OBJECT(
                        'id', product_id,
                        'title', product_data.title,
                        'type', product_data.type,
                        'type_title', product_data.type_title,
                        'price', product_data.price,
                        'currency_code', product_data.currency_code,
                        'spot_title', v_spot_title,
                        'description', v_spot_description,
                        'data', product_data.data
                    ));
                END;

                -- Accumulate the product price into the order total
                calculated_price := calculated_price + COALESCE(product_data.price, 0)::NUMERIC(10,2);

                -- Accumulate the product deposit into the order deposit total
                v_product_deposit := COALESCE((product_data.data->'deposit'->>'amount')::NUMERIC, 0);
                IF v_product_deposit > COALESCE(product_data.price, 0) THEN
                    RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
                        'code', 1016,
                        'message', 'Deposit amount cannot exceed product price',
                        'product_id', product_id,
                        'deposit', v_product_deposit,
                        'price', product_data.price
                    )::TEXT;
                END IF;
                v_total_deposit := v_total_deposit + v_product_deposit;

                -- Link the ticket and product to the order
                INSERT INTO eshop.order_product_ticket ("order", product, ticket)
                VALUES (order_id, product_id, ticket_id)
                RETURNING id INTO order_product_ticket_id;

                -- For the spot product, link the generated order product ticket id to the spot record
                IF spot_id IS NOT NULL THEN
                    IF product_id = spot_product.id THEN
                        UPDATE eshop.spots
                        SET order_product_ticket = order_product_ticket_id, updated_at = now
                        WHERE id = spot_id;
                    END IF;
                END IF;
            END LOOP;

            -- If no explicit ticket->spot was provided, then at least one of the fields must be a spot product.
            IF spot_product IS NULL THEN
                RAISE EXCEPTION '%', JSONB_BUILD_OBJECT('code', 1015, 'message', 'Spot product is missing in ticket fields')::TEXT;
            END IF;

            -- Append the ticket details (with its products and the extracted ticket note) to the overall ticket_details array
            ticket_details := ticket_details || JSONB_BUILD_OBJECT(
                'id', ticket_id,
                'ticket_symbol', ticket_symbol,
                'note', ticket_note,
                'products', ticket_products
            );
        END LOOP;

        order_data := input_data - 'ticket' || JSONB_BUILD_OBJECT('tickets', ticket_details);

        -- Determine the bank account details based on the form and supported currency fallback using unit accounts only
        -- Modified Bank Account Selection: Exclude CASH Accounts
        IF bank_account_id IS NULL THEN
            SELECT uba.bank_account, ba.account_number, ba.account_number_human_readable
            INTO bank_account_id, account_number, account_number_human_readable
            FROM eshop.unit_bank_accounts uba
            JOIN eshop.bank_accounts ba ON uba.bank_account = ba.id
            WHERE uba.unit = (SELECT unit FROM public.occasions WHERE id = occasion_id)
              AND ba.supported_currencies @> ARRAY[first_currency_code]
              AND (ba.type IS DISTINCT FROM 'CASH') -- EXCLUDE CASH ACCOUNTS
            ORDER BY uba.priority ASC, ba.id ASC
            LIMIT 1;

            IF bank_account_id IS NULL THEN
                RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
                    'code', 1018,
                    'message', 'No available bank account supports the required currency',
                    'required_currency', first_currency_code
                )::TEXT;
            END IF;
        ELSE
            -- Validate manually selected account: Exclude CASH Accounts
            PERFORM 1
            FROM eshop.unit_bank_accounts uba
            JOIN eshop.bank_accounts ba ON uba.bank_account = ba.id
            WHERE uba.unit = (SELECT unit FROM public.occasions WHERE id = occasion_id)
              AND ba.id = bank_account_id
              AND ba.supported_currencies @> ARRAY[first_currency_code]
              AND (ba.type IS DISTINCT FROM 'CASH'); -- EXCLUDE CASH ACCOUNTS

            IF NOT FOUND THEN
                RAISE EXCEPTION '%', JSONB_BUILD_OBJECT(
                    'code', 1018,
                    'message', 'The specified bank account does not support the required currency, is not linked, or is invalid (CASH type)',
                    'expected_currency', first_currency_code,
                    'provided_bank_account', bank_account_id
                )::TEXT;
            END IF;

            SELECT b.account_number, b.account_number_human_readable
            INTO account_number, account_number_human_readable
            FROM eshop.bank_accounts b
            WHERE b.id = bank_account_id;
        END IF;

        -- If user chose to pay full amount, skip deposit
        IF input_data->>'payment_type' = 'full' THEN
            v_total_deposit := 0;
        END IF;

        -- Generate a variable symbol and create the payment info record
        generated_variable_symbol := generate_payment_variable_symbol(bank_account_id, form_id);
        INSERT INTO eshop.payment_info (bank_account, variable_symbol, amount, deposit_amount, currency_code, created_at)
        VALUES (bank_account_id, generated_variable_symbol, calculated_price, NULLIF(v_total_deposit, 0), first_currency_code, now)
        RETURNING id INTO payment_info_id;

        -- persist all of the non‐state fields
        UPDATE eshop.orders
        SET
          price         = calculated_price,
          currency_code = first_currency_code,
          payment_info  = payment_info_id,
          data          = order_data,
          updated_at    = now
        WHERE id = order_id;

        -- Apply inventory allocations. This will raise an overbooking error if spots are unavailable.
        PERFORM apply_allocations(order_id);

        -- Always mark as 'ordered' initially to satisfy state requirements
        IF calculated_price = 0 THEN
          PERFORM update_order_and_tickets_to_paid(order_id);
        ELSE
          UPDATE eshop.orders
          SET state      = 'ordered'
          WHERE id = order_id;

          -- Calculate deadline if deadline duration is provided
          IF form_deadline_duration IS NOT NULL THEN
              deadline := now + make_interval(secs => form_deadline_duration);
              PERFORM public.set_payment_deadline(payment_info_id, deadline);
          ELSE
              deadline := NULL;
          END IF;
        END IF;

        -- Check via Unified Helper if order is already paid (e.g. price is 0)
        PERFORM public.recalculate_order_payment_status(order_id);

        -- Queue deposit reminder if deposit exists and deadline is days-based (not "on site")
        IF v_total_deposit > 0 THEN
            DECLARE
                v_occ_start_time TIMESTAMPTZ;
                v_deposit_deadline_days INT;
                v_deposit_deadline TEXT;
                v_reminder_interval BIGINT;
                v_reminder_is_enabled BOOLEAN;
                v_deposit_deadline_ts TIMESTAMPTZ;
                v_deposit_feature JSONB;
            BEGIN
                -- Read occasion start_time
                SELECT start_time INTO v_occ_start_time
                FROM public.occasions WHERE id = occasion_id;

                -- Get deposit feature config from features JSONB
                SELECT elem INTO v_deposit_feature
                FROM jsonb_array_elements(occasion_features) elem
                WHERE elem->>'code' = 'deposit';

                v_deposit_deadline_days := (v_deposit_feature->>'deposit_deadline_days')::int;
                v_deposit_deadline := v_deposit_feature->>'deposit_deadline';

                -- Store deposit deadline on payment_info and queue reminder
                IF v_deposit_deadline IS DISTINCT FROM 'on_site' AND v_deposit_deadline_days IS NOT NULL THEN
                    v_deposit_deadline_ts := v_occ_start_time - make_interval(days => v_deposit_deadline_days);

                    -- Store the calculated deposit deadline on the payment_info record
                    UPDATE eshop.payment_info
                    SET deposit_deadline = v_deposit_deadline_ts
                    WHERE id = payment_info_id;

                    -- Only queue reminder if deadline is in the future
                    IF v_deposit_deadline_ts > NOW() THEN
                        -- Get reminder interval from occasion form feature
                        SELECT elem->>'reminder_interval_seconds'
                        INTO v_reminder_interval
                        FROM jsonb_array_elements(occasion_features) elem
                        WHERE elem->>'code' = 'form';

                        -- Check if reminder is enabled on the form feature
                        SELECT (elem->>'reminder_is_enabled')::boolean
                        INTO v_reminder_is_enabled
                        FROM jsonb_array_elements(occasion_features) elem
                        WHERE elem->>'code' = 'form';

                        IF COALESCE(v_reminder_is_enabled, FALSE) AND v_reminder_interval IS NOT NULL THEN
                            INSERT INTO public.queue_emails (target_time, code, data, organization, occasion, unit)
                            VALUES (
                                v_deposit_deadline_ts - make_interval(secs => v_reminder_interval),
                                'TICKET_ORDER_REMINDER',
                                jsonb_build_object('order_id', order_id, 'is_deposit_reminder', true),
                                organization_id,
                                occasion_id,
                                unit_id
                            );
                        END IF;
                    END IF;
                END IF;
                -- Note: if deposit_deadline = 'on_site', deposit_deadline stays NULL → means "Na místě"
            END;
        END IF;

        -- Log the order to orders_history with details
        INSERT INTO eshop.orders_history (created_at, data, "order", state, price, currency_code)
        VALUES (
            now,
            JSONB_BUILD_OBJECT('input_data', input_data, 'tickets', ticket_details),
            order_id,
            'ordered',
            calculated_price,
            first_currency_code
        );

        -- Get the reply-to email for the order
        reply_to := get_reply_to_email_for_order(order_id);

        -- Check features and auto-import users if enabled
        PERFORM public.process_occasion_auto_import(occasion_id);

        -- Prepare the success response JSON
        result := JSONB_BUILD_OBJECT(
            'code', 200,
            'order', JSONB_BUILD_OBJECT(
                'id', order_id,
                'data', order_data,
                'form', JSONB_BUILD_OBJECT(
                    'id', form_id,
                    'data', form_data
                ),
                'payment_info', JSONB_BUILD_OBJECT(
                    'id', payment_info_id,
                    'variable_symbol', generated_variable_symbol,
                    'amount', calculated_price,
                    'deposit_amount', NULLIF(v_total_deposit, 0),
                    'deposit_deadline', (SELECT deposit_deadline FROM eshop.payment_info WHERE id = payment_info_id),
                    'deadline', deadline,
                    'account_number', account_number,
                    'account_number_human_readable', account_number_human_readable,
                    'currency_code', first_currency_code
                ),
                'occasion', JSONB_BUILD_OBJECT(
                    'id', occasion_id,
                    'organization', organization_id,
                    'unit', unit_id,
                    'title', occasion_title,
                    'features', occasion_features,
                    'data', (SELECT data FROM public.occasions WHERE id = occasion_id)
                ),
                'reply_to', reply_to
            )
        );

    EXCEPTION WHEN OTHERS THEN
        -- In case of any error, the inner block is rolled back and we capture the error message.
        result := CASE
            WHEN left(SQLERRM, 1) = '{' THEN SQLERRM::JSONB
            ELSE JSONB_BUILD_OBJECT('code', 1013, 'message', SQLERRM)
        END;
    END;

    RETURN result;
END;
$$;


ALTER FUNCTION "public"."create_ticket_order_internal_v1"("input_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_unit_and_assign_manager"("title" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_user_id uuid;
  v_org_id bigint;
  v_email text;
  v_new_unit_id bigint;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('code', 401, 'message', 'Unauthorized');
  END IF;

  SELECT organization, email_readonly
  INTO v_org_id, v_email
  FROM public.user_info
  WHERE id = v_user_id;

  IF v_org_id IS NULL THEN
     RETURN jsonb_build_object('code', 404, 'message', 'User info or organization not found');
  END IF;

  -- Check if unit creation is enabled for organization
  DECLARE
      v_is_enabled boolean;
  BEGIN
      SELECT (data->>'IS_UNIT_CREATION_ENABLED')::boolean
      INTO v_is_enabled
      FROM public.organizations
      WHERE id = v_org_id;

      IF v_is_enabled IS NOT TRUE THEN
          RETURN jsonb_build_object('code', 403, 'message', 'Unit creation is disabled for this organization');
      END IF;
  END;

  INSERT INTO public.units (title, organization, data)
  VALUES (
    title,
    v_org_id,
    jsonb_build_object(
        'reply_to', lower(trim(COALESCE(v_email, ''))),
        'timezone', 'Europe/Prague'
    )
  )
  RETURNING id INTO v_new_unit_id;

  INSERT INTO public.unit_users (unit, "user", is_manager, is_editor, is_editor_view)
  VALUES (v_new_unit_id, v_user_id, true, true, true);

  RETURN jsonb_build_object(
    'code', 200,
    'message', 'Unit created successfully',
    'data', jsonb_build_object('id', v_new_unit_id)
  );

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('code', 500, 'message', SQLERRM);
END;
$$;


ALTER FUNCTION "public"."create_unit_and_assign_manager"("title" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_user"("oc" bigint, "email" "text", "password" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
  declare
  user_id uuid;
  encrypted_pw text;
  user_meta_data jsonb;
BEGIN
    IF (select get_is_manager_on_occasion(oc)) <> TRUE THEN
          RETURN NULL;
      END IF;

    user_id := gen_random_uuid();
    encrypted_pw := crypt(password, gen_salt('bf'));

    user_meta_data := NULL;

    INSERT INTO auth.users
      (instance_id, id, aud, role, email, encrypted_password, email_confirmed_at, recovery_sent_at, last_sign_in_at, raw_app_meta_data, raw_user_meta_data, created_at, updated_at, confirmation_token, email_change, email_change_token_new, recovery_token)
    VALUES
      ('00000000-0000-0000-0000-000000000000', user_id, 'authenticated', 'authenticated', email, encrypted_pw, now(), NULL, NULL, '{"provider":"email","providers":["email"]}', user_meta_data, now(), now(), '', '', '', '');

    INSERT INTO auth.identities (id, provider_id, user_id, identity_data, provider, last_sign_in_at, created_at, updated_at)
    VALUES
      (gen_random_uuid(), user_id, user_id, format('{"sub":"%s","email":"%s"}', user_id::text, email)::jsonb, 'email', NULL, now(), now());

    RETURN user_id;
END;
$$;


ALTER FUNCTION "public"."create_user"("oc" bigint, "email" "text", "password" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_user_for_test"("test_user_alias" "text", "test_email" "text") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    new_id uuid := gen_random_uuid();
BEGIN
    CREATE TEMP TABLE IF NOT EXISTS _test_user_aliases (alias text PRIMARY KEY, id uuid);
    INSERT INTO auth.users (id, instance_id, email, email_confirmed_at, aud, role, created_at, updated_at)
    VALUES (new_id, '00000000-0000-0000-0000-000000000000', test_email, now(), 'authenticated', 'authenticated', now(), now());
    INSERT INTO public.user_info (id, name, surname, sex) VALUES (new_id, 'Test', 'User', 'male');
    INSERT INTO _test_user_aliases (alias, id) VALUES (test_user_alias, new_id);
END;
$$;


ALTER FUNCTION "public"."create_user_for_test"("test_user_alias" "text", "test_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_user_from_registration"("org" bigint, "email" "text", "password" "text", "data" "jsonb", "unit_title" "text" DEFAULT 'Moje akce'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    is_registration_enabled BOOLEAN;
    new_user_id uuid;
    v_new_unit_id bigint;
BEGIN
    -- Retrieve IS_REGISTRATION_ENABLED value from organizations.data JSON
    SELECT (organizations.data->>'IS_REGISTRATION_ENABLED')::boolean
      INTO is_registration_enabled
    FROM organizations
    WHERE id = org;

    -- CHECK: If registration is enabled OR if the caller is a manager/editor
    IF NOT is_registration_enabled AND NOT (
           get_is_manager_on_any_occasion()
           OR EXISTS (
               SELECT 1
               FROM occasions o
               WHERE o.organization = org
               AND get_is_editor_on_unit(o.unit)
           )
       ) THEN
        RETURN jsonb_build_object('code', 403, 'error', 'Registration is disabled for this organization');
    END IF;

    -- Call the PURE function to create the user
    new_user_id := create_user_in_organization_with_data_pure(org, email, password, data);

    INSERT INTO public.units (title, organization, data)
    VALUES (
        unit_title,
        org,
        jsonb_build_object(
            'reply_to', lower(trim(email)),
            'timezone', 'Europe/Prague'
        )
    )
    RETURNING id INTO v_new_unit_id;

    INSERT INTO public.unit_users (unit, "user", is_manager, is_editor, is_editor_view)
    VALUES (v_new_unit_id, new_user_id, true, true, true);

    RETURN jsonb_build_object('code', 200, 'id', new_user_id);
END;
$$;


ALTER FUNCTION "public"."create_user_from_registration"("org" bigint, "email" "text", "password" "text", "data" "jsonb", "unit_title" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_user_in_organization_with_data"("org" bigint, "email" "text", "password" "text", "data" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    is_registration_enabled BOOLEAN;
    usr uuid;
    encrypted_pw text;
    user_meta_data jsonb := '{}';
    _key   text;
    _value text;
    trimmed_data jsonb := '{}';
    original_email text;
BEGIN
    -- Trim and lower the email input
    original_email := lower(trim(email));

    -- Add organization prefix to the email for auth tables
    email := format('%s+%s', org, original_email);

    -- Retrieve IS_REGISTRATION_ENABLED value from organizations.data JSON
    SELECT (organizations.data->>'IS_REGISTRATION_ENABLED')::boolean
      INTO is_registration_enabled
    FROM organizations
    WHERE id = org;

    -- Check if registration is enabled OR if the caller is a manager on any occasion
    -- OR if the caller is an editor on at least one unit associated with an occasion in this organization.


    -- Trim all values in the data JSONB object and build a new trimmed_data JSONB object
    FOR _key, _value IN
        SELECT key, value FROM jsonb_each_text(data)
    LOOP
        IF _value IS NOT NULL THEN
            trimmed_data := jsonb_set(trimmed_data, array[_key], to_jsonb(trim(_value)), true);
        ELSE
            trimmed_data := jsonb_set(trimmed_data, array[_key], 'null'::jsonb, true);
        END IF;
    END LOOP;

    usr := gen_random_uuid();
    encrypted_pw := crypt(password, gen_salt('bf'));

    -- Insert into auth.users with the email prefixed with organization
    INSERT INTO auth.users
      (instance_id, id, aud, role, email, encrypted_password, email_confirmed_at, recovery_sent_at, last_sign_in_at, raw_app_meta_data, raw_user_meta_data, created_at, updated_at, confirmation_token, email_change, email_change_token_new, recovery_token)
    VALUES
      ('00000000-0000-0000-0000-000000000000', usr, 'authenticated', 'authenticated', email, encrypted_pw, now(), NULL, NULL,
      '{"provider":"email","providers":["email"]}', user_meta_data, now(), now(), '', '', '', '');

    -- Insert into auth.identities with the email prefixed with organization
    INSERT INTO auth.identities (id, provider_id, user_id, identity_data, provider, last_sign_in_at, created_at, updated_at)
    VALUES
      (gen_random_uuid(), usr, usr, format('{"sub":"%s","email":"%s"}', usr::text, email)::jsonb, 'email', NULL, now(), now());

    -- Insert into user_info with the original email (without prefix)
    INSERT INTO user_info (id, email_readonly, name, surname, sex, data, organization)
    VALUES (usr, original_email, COALESCE(trimmed_data->>'name', ''), COALESCE(trimmed_data->>'surname', ''), COALESCE(trimmed_data->>'sex', ''), trimmed_data, org);

    RETURN usr;
END;
$$;


