    AS $$
DECLARE v_response jsonb;
BEGIN
  v_response:=public.delete_unit_user_client_sync_v1(
    usr,unit_id,extensions.gen_random_uuid());
  RETURN jsonb_build_object('code',(v_response->>'code')::integer)
    ||COALESCE(v_response->'data','{}'::jsonb);
END; $$;


ALTER FUNCTION "public"."delete_unit_user"("usr" "uuid", "unit_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_unit_user_client_sync_v1"("p_user" "uuid", "p_unit" bigint, "p_command_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_actor uuid:=auth.uid(); v_begin jsonb; v_hash text; v_before jsonb;
  v_after jsonb; v_result jsonb; v_commit public.client_commits%ROWTYPE;
  v_occasion bigint; v_revision bigint;
BEGIN
  IF v_actor IS NULL OR p_user IS NULL
    OR NOT public.get_is_manager_on_unit(p_unit) THEN
    RAISE insufficient_privilege USING MESSAGE='unit manager required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'unit',p_unit,'userId',p_user)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_unit_client_mutation_v1(p_command_id,
    'profile.unit_access.delete',p_unit,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  SELECT jsonb_build_object('unitUser',(SELECT to_jsonb(uu)
      FROM public.unit_users uu WHERE uu.unit=p_unit AND uu."user"=p_user),
    'occasionUsers',COALESCE((SELECT jsonb_agg(to_jsonb(ou) ORDER BY ou.occasion)
      FROM public.occasion_users ou JOIN public.occasions o ON o.id=ou.occasion
      WHERE o.unit=p_unit AND ou."user"=p_user),'[]'::jsonb)) INTO v_before;
  v_result:=public.delete_unit_user_internal_v1(p_user,p_unit);
  SELECT jsonb_build_object('unitUser',(SELECT to_jsonb(uu)
      FROM public.unit_users uu WHERE uu.unit=p_unit AND uu."user"=p_user),
    'occasionUsers',COALESCE((SELECT jsonb_agg(to_jsonb(ou) ORDER BY ou.occasion)
      FROM public.occasion_users ou JOIN public.occasions o ON o.id=ou.occasion
      WHERE o.unit=p_unit AND ou."user"=p_user),'[]'::jsonb)) INTO v_after;
  IF v_before IS NOT DISTINCT FROM v_after THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
      jsonb_build_object('userId',p_user)); END IF;
  INSERT INTO public.client_commits
    (unit,actor_id,actor_display,actor_kind,source,change_class)
  SELECT p_unit,v_actor,nullif(concat_ws(' ',ui.name,ui.surname),''),'user',
    'profile.unit_access.delete','profile' FROM public.user_info ui
    WHERE ui.id=v_actor RETURNING * INTO v_commit;
  INSERT INTO public.client_commit_items
    (commit_id,item_index,entity_type,entity_id,operation,safe_label,changed_fields)
  VALUES (v_commit.commit_id,0,'unit_user',p_user::text,'delete','Unit access',
    ARRAY['rights']);
  FOR v_occasion IN SELECT ou.occasion FROM public.occasion_users ou
    JOIN public.occasions o ON o.id=ou.occasion
    WHERE o.unit=p_unit AND ou."user"=p_user ORDER BY ou.occasion LOOP
    INSERT INTO public.client_aggregate_versions
      (aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES ('occasion_user','occasion',v_occasion,p_user::text,1)
    ON CONFLICT (aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE SET
      version=public.client_aggregate_versions.version+1,
      updated_at=clock_timestamp();
    INSERT INTO public.client_sync_private_scopes
      (component,occasion,user_id,source_revision)
    VALUES ('private_profile',v_occasion,p_user,1)
    ON CONFLICT (component,occasion,user_id) DO UPDATE SET
      source_revision=public.client_sync_private_scopes.source_revision+1,
      updated_at=now() RETURNING source_revision INTO v_revision;
    INSERT INTO public.client_commit_components
      (commit_id,component,scope_type,scope_id,user_id,resulting_revision)
    VALUES (v_commit.commit_id,'private_profile','occasion',v_occasion,
      p_user,v_revision);
  END LOOP;
  RETURN public.finish_client_mutation_v1(p_command_id,jsonb_build_object(
    'status','applied','code',200,'data',jsonb_build_object('userId',p_user),
    'mutation',jsonb_build_object('commandId',p_command_id,'receiptId',p_command_id,
      'commitId',v_commit.commit_id,'replayed',false,'occurredAt',v_commit.occurred_at),
    'sync',jsonb_build_object('replacements','[]'::jsonb)),v_commit.commit_id);
END; $$;


ALTER FUNCTION "public"."delete_unit_user_client_sync_v1"("p_user" "uuid", "p_unit" bigint, "p_command_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_unit_user_internal_v1"("usr" "uuid", "unit_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    DELETE FROM unit_users
    WHERE "user" = usr AND unit = unit_id;

    UPDATE occasion_users
    SET is_editor = false,
        is_manager = false,
        is_editor_view = false
    WHERE "user" = usr
      AND occasion IN (SELECT id FROM occasions WHERE unit = unit_id);

    RETURN jsonb_build_object('code', 200);
END;
$$;


ALTER FUNCTION "public"."delete_unit_user_internal_v1"("usr" "uuid", "unit_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_user_group_client_sync_v1"("p_occasion" bigint, "p_group_id" bigint, "p_command_id" "uuid", "p_expected_version" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_actor uuid:=auth.uid(); v_version bigint; v_begin jsonb; v_hash text;
  v_entity jsonb; v_users uuid[]; v_place bigint; v_private_place boolean;
  v_private_impacts jsonb; v_actor_replacements jsonb:='[]'::jsonb;
BEGIN
  IF v_actor IS NULL OR NOT public.get_is_editor_on_occasion(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,
    'groupId',p_group_id,'expectedVersion',p_expected_version)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'profile.group.delete',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  PERFORM 1 FROM public.user_group_info g WHERE g.id=p_group_id
    AND g.occasion=p_occasion FOR UPDATE;
  IF NOT FOUND THEN RETURN public.complete_client_mutation_outcome_v1(
    p_command_id,'unchanged',200,jsonb_build_object('version',0,'group',NULL)); END IF;
  SELECT public.get_user_group_command_data_v1(g.id),g.place,
    COALESCE(p.is_hidden AND p.type='group',false)
    INTO v_entity,v_place,v_private_place
  FROM public.user_group_info g LEFT JOIN public.places p ON p.id=g.place
  WHERE g.id=p_group_id;
  SELECT COALESCE(array_agg(ug."user" ORDER BY ug."user"),'{}'::uuid[])
    INTO v_users FROM public.user_groups ug WHERE ug."group"=p_group_id;
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES ('user_group','occasion',p_occasion,p_group_id::text,0) ON CONFLICT DO NOTHING;
  SELECT version INTO v_version FROM public.client_aggregate_versions
    WHERE aggregate_type='user_group' AND scope_type='occasion'
    AND scope_id=p_occasion AND aggregate_id=p_group_id::text FOR UPDATE;
  IF p_expected_version IS DISTINCT FROM v_version THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,
      jsonb_build_object('version',v_version,'group',v_entity)); END IF;
  DELETE FROM public.user_groups WHERE "group"=p_group_id;
  DELETE FROM public.user_group_info WHERE id=p_group_id;
  IF v_private_place THEN
    DELETE FROM public.places WHERE id=v_place;
    DELETE FROM public.client_aggregate_versions WHERE aggregate_type='place'
      AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=v_place::text;
  END IF;
  DELETE FROM public.client_aggregate_versions WHERE aggregate_type='user_group'
    AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=p_group_id::text;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('component','private_profile',
    'userId',id)),'[]'::jsonb) INTO v_private_impacts FROM unnest(v_users) id;
  IF v_actor=ANY(v_users) THEN v_actor_replacements:=jsonb_build_array(
    jsonb_build_object('component','private_profile','userId',v_actor,
      'payload',public.get_private_profile_payload_v1(p_occasion,v_actor))); END IF;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'profile.group.delete','profile',jsonb_build_array(jsonb_build_object(
      'entityType','user_group','entityId',p_group_id,'operation','delete',
      'safeLabel',left(v_entity->>'title',240),'changedFields',jsonb_build_array('aggregate'))),
    '{}',v_private_impacts,'[]',jsonb_build_object('version',v_version,'group',NULL),
    '{}','[]','user',NULL,v_actor_replacements);
END; $$;


ALTER FUNCTION "public"."delete_user_group_client_sync_v1"("p_occasion" bigint, "p_group_id" bigint, "p_command_id" "uuid", "p_expected_version" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."duplicate_form"("p_old_form_id" bigint) RETURNS bigint
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  new_form_id bigint;
  rec record;
  new_bp_id bigint;
BEGIN
  ------------------------------------------------------------------
  -- 1. Duplicate the main form record for the new occasion.
  --    - The link and key are regenerated to ensure they are unique.
  --    - The title is modified to indicate it's a copy.
  --    - Blueprint relationships are preserved if they exist in the original.
  ------------------------------------------------------------------
  SELECT * INTO rec
  FROM public.forms
  WHERE id = p_old_form_id;

  -- This assumes that if a blueprint is duplicated, the mapping is handled by the calling function.
  -- For a standalone duplication, the blueprint might be null or copied directly.
  -- In the context of duplicate_occasion, the blueprint ID is resolved outside.
  -- For simplicity here, we will assume blueprint is copied directly if not provided.
  -- However, the call from duplicate_occasion will handle this correctly.

  INSERT INTO public.forms
    (created_at, data, key, occasion, type, bank_account, deadline_duration_seconds, is_open, link, blueprint, header, header_off, updated_at, title)
  VALUES (
    now(),
    rec.data,
    uuid_generate_v4(),
    rec.occasion,
    rec.type,
    rec.bank_account,
    rec.deadline_duration_seconds,
    rec.is_open,
    rec.link || '-copy-' || substring(md5(random()::text) from 1 for 8), -- New unique link
    rec.blueprint,
    rec.header,
    rec.header_off,
    now(),
    rec.title || ' (Copy)'
  )
  RETURNING id INTO new_form_id;


  ------------------------------------------------------------------
  -- 2. Duplicate all associated form fields.
  --    - The 'form' foreign key is updated to point to the new_form_id.
  --    - The 'product_type' foreign key is copied directly, as product types
  --      are tied to the occasion, which is already correctly set.
  ------------------------------------------------------------------
  INSERT INTO public.form_fields
    (created_at, title, description, data, type, is_required, form, is_hidden, "order", product_type, is_ticket_field)
  SELECT
    now(),
    title,
    description,
    data,
    type,
    is_required,
    new_form_id,
    is_hidden,
    "order",
    product_type,
    is_ticket_field
  FROM public.form_fields
  WHERE form = p_old_form_id;

  RETURN new_form_id;
END;
$$;


ALTER FUNCTION "public"."duplicate_form"("p_old_form_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."duplicate_form_to_occasion"("source_form_id" bigint, "target_occasion_link" "text") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  RETURN (public.duplicate_form_to_occasion_client_sync_v1(source_form_id,
    target_occasion_link,extensions.gen_random_uuid())->'data'->>'formId')::bigint;
END; $$;


ALTER FUNCTION "public"."duplicate_form_to_occasion"("source_form_id" bigint, "target_occasion_link" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."duplicate_form_to_occasion_client_sync_v1"("p_source_form_id" bigint, "p_target_occasion_link" "text", "p_command_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_actor uuid:=auth.uid(); v_source_occasion bigint; v_source_unit bigint;
  v_target bigint; v_begin jsonb; v_hash text; v_form bigint;
BEGIN
  SELECT f.occasion,o.unit INTO v_source_occasion,v_source_unit
    FROM public.forms f JOIN public.occasions o ON o.id=f.occasion
    WHERE f.id=p_source_form_id;
  SELECT o.id INTO v_target FROM public.occasions o
    WHERE o.link=p_target_occasion_link;
  IF v_actor IS NULL OR v_source_occasion IS NULL OR v_target IS NULL
    OR NOT (public.get_is_editor_view_on_occasion(v_source_occasion)
      OR public.get_is_editor_view_on_unit(v_source_unit))
    OR NOT public.get_is_editor_on_occasion(v_target) THEN
    RAISE insufficient_privilege USING MESSAGE='form copy permission required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'sourceFormId',p_source_form_id,'targetOccasion',v_target)::text,'UTF8'),
    'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'inventory.form.duplicate',v_target,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  v_form:=public.duplicate_form_to_occasion_internal_v1(
    p_source_form_id,p_target_occasion_link);
  RETURN public.complete_private_inventory_mutation_v1(p_command_id,v_target,
    'inventory.form.duplicate',jsonb_build_array(jsonb_build_object(
      'entityType','form','entityId',v_form,'operation','insert',
      'safeLabel','Duplicated form','changedFields',jsonb_build_array(
        'configuration','fields','products'))),'{}'::uuid[],
    jsonb_build_object('formId',v_form));
END; $$;


ALTER FUNCTION "public"."duplicate_form_to_occasion_client_sync_v1"("p_source_form_id" bigint, "p_target_occasion_link" "text", "p_command_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."duplicate_form_to_occasion_internal_v1"("source_form_id" bigint, "target_occasion_link" "text") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    user_id UUID := auth.uid();
    target_occasion_id BIGINT;
    target_organization_id BIGINT;
    source_occasion_id BIGINT;
    source_unit_id BIGINT;
    has_source_permission BOOLEAN;
    has_target_permission BOOLEAN;
    new_form_id BIGINT;
    v_new_form_link TEXT;
    form_field_record RECORD;
    new_product_type_id BIGINT;
    product_record RECORD;
BEGIN
    -- Step 1: Resolve the target occasion ID and its organization ID from its link.
    SELECT id, organization INTO target_occasion_id, target_organization_id
    FROM public.occasions WHERE link = target_occasion_link;
    IF target_occasion_id IS NULL THEN
        RAISE EXCEPTION 'Target occasion not found for link: %', target_occasion_link;
    END IF;

    -- Step 2: Get the source occasion and unit IDs for permission checking.
    SELECT f.occasion, o.unit
    INTO source_occasion_id, source_unit_id
    FROM public.forms f
    JOIN public.occasions o ON f.occasion = o.id
    WHERE f.id = source_form_id;

    IF source_occasion_id IS NULL THEN
        RAISE EXCEPTION 'Source form not found.';
    END IF;

    -- Step 3: Check if the user has editor_view rights on the source occasion or its unit.
    SELECT EXISTS (
        SELECT 1 FROM public.occasion_users
        WHERE occasion = source_occasion_id AND "user" = user_id AND is_editor_view = TRUE
    ) OR EXISTS (
        SELECT 1 FROM public.unit_users
        WHERE unit = source_unit_id AND "user" = user_id AND is_editor_view = TRUE
    )
    INTO has_source_permission;

    IF NOT has_source_permission THEN
        RAISE EXCEPTION 'Insufficient permissions to view the source form.';
    END IF;

    -- Step 4: Check if the user has editor rights on the target occasion.
    SELECT EXISTS (
        SELECT 1 FROM public.occasion_users
        WHERE occasion = target_occasion_id AND "user" = user_id AND is_editor = TRUE
    )
    INTO has_target_permission;

    IF NOT has_target_permission THEN
        RAISE EXCEPTION 'Insufficient permissions to create a form in the target occasion.';
    END IF;

    -- Step 5: Generate a unique link for the new form within the same organization.
    -- Try to use the target occasion's link first. If it's taken within the same organization, append a random hash.
    IF EXISTS (
        SELECT 1
        FROM public.forms f
        JOIN public.occasions o ON f.occasion = o.id
        WHERE f.link = target_occasion_link AND o.organization = target_organization_id
    ) THEN
        v_new_form_link := target_occasion_link || '-' || substring(md5(random()::text) from 1 for 8);
    ELSE
        v_new_form_link := target_occasion_link;
    END IF;

    -- Step 6: Copy the main form record to the target occasion.
    INSERT INTO public.forms (title, data, occasion, type, bank_account, deadline_duration_seconds, is_open, link, blueprint, header, header_off)
    SELECT
        title || ' (Copy)',
        data,
        target_occasion_id,
        type,
        bank_account,
        deadline_duration_seconds,
        is_open,
        v_new_form_link, -- Use the generated unique link
        blueprint,
        header,
        header_off
    FROM public.forms
    WHERE id = source_form_id
    RETURNING id INTO new_form_id;

    -- Step 7: Loop through each field of the source form and perform a deep copy.
    FOR form_field_record IN
        SELECT * FROM public.form_fields WHERE form = source_form_id
    LOOP
        -- Check if the field is linked to a product type.
        IF form_field_record.product_type IS NOT NULL THEN
            -- A) If yes, perform a deep copy of the product type and its products.
            INSERT INTO eshop.product_types (title, description, type, data, occasion, maximum)
            SELECT title, description, type, data, target_occasion_id, maximum
            FROM eshop.product_types
            WHERE id = form_field_record.product_type
            RETURNING id INTO new_product_type_id;

            FOR product_record IN
                SELECT * FROM eshop.products WHERE product_type = form_field_record.product_type
            LOOP
                INSERT INTO eshop.products (title, description, price, data, product_type, occasion, is_hidden, currency_code, "order", maximum)
                VALUES (
                    product_record.title, product_record.description, product_record.price, product_record.data,
                    new_product_type_id, target_occasion_id, product_record.is_hidden, product_record.currency_code,
                    product_record.order, product_record.maximum
                );
            END LOOP;

            INSERT INTO public.form_fields (title, description, data, type, is_required, form, is_hidden, "order", product_type, is_ticket_field)
            VALUES (
                form_field_record.title, form_field_record.description, form_field_record.data, form_field_record.type,
                form_field_record.is_required, new_form_id, form_field_record.is_hidden, form_field_record.order,
                new_product_type_id, form_field_record.is_ticket_field
            );
        ELSE
            -- B) If not, perform a simple copy of the form field.
            INSERT INTO public.form_fields (title, description, data, type, is_required, form, is_hidden, "order", product_type, is_ticket_field)
            VALUES (
                form_field_record.title, form_field_record.description, form_field_record.data, form_field_record.type,
                form_field_record.is_required, new_form_id, form_field_record.is_hidden, form_field_record.order,
                NULL, form_field_record.is_ticket_field
            );
        END IF;
    END LOOP;

    -- Step 8: Return the ID of the newly created form.
    RETURN new_form_id;
END;
$$;


ALTER FUNCTION "public"."duplicate_form_to_occasion_internal_v1"("source_form_id" bigint, "target_occasion_link" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."duplicate_form_ws"("p_form_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    result jsonb;
    v_occasion_id bigint;
    v_unit_id bigint;
    new_form_id bigint;
BEGIN
    BEGIN
        -- Fetch occasion and unit details to check permissions
        SELECT f.occasion, o.unit
        INTO v_occasion_id, v_unit_id
        FROM public.forms f
        JOIN public.occasions o ON f.occasion = o.id
        WHERE f.id = p_form_id;

        IF NOT FOUND THEN
             RAISE EXCEPTION '%',
                JSONB_BUILD_OBJECT('code', 4040, 'message', 'Form not found')::TEXT;
        END IF;

        -- Perform the required permission checks
        IF NOT (
            (SELECT get_is_editor_on_unit(v_unit_id)) OR
            (SELECT get_is_editor_on_occasion(v_occasion_id))
        ) THEN
            RAISE EXCEPTION '%',
                JSONB_BUILD_OBJECT('code', 4030, 'message', 'Permission denied to duplicate this form.')::TEXT;
        END IF;

        -- Call the internal function to duplicate the form within the SAME occasion
        new_form_id := duplicate_form(p_form_id);

        -- Build the success response for the client
        result := JSONB_BUILD_OBJECT(
            'code', 201, -- 201 Created
            'message', 'Form duplicated successfully',
            'data', jsonb_build_object('new_form_id', new_form_id)
        );

    EXCEPTION WHEN OTHERS THEN
        -- Catch any exceptions and format them
        result := CASE
            WHEN left(SQLERRM, 1) = '{' THEN SQLERRM::JSONB
            ELSE JSONB_BUILD_OBJECT('code', 5000, 'message', SQLERRM)
        END;
    END;

    RETURN result;
END;
$$;


ALTER FUNCTION "public"."duplicate_form_ws"("p_form_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."duplicate_occasion"("oc" bigint) RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_response jsonb;
BEGIN
  v_response:=public.duplicate_occasion_client_sync_v1(
    oc,extensions.gen_random_uuid());
  RETURN (v_response->'data'->>'occasionId')::bigint;
END; $$;


ALTER FUNCTION "public"."duplicate_occasion"("oc" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."duplicate_occasion_client_sync_v1"("p_occasion" bigint, "p_command_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_actor uuid:=auth.uid(); v_unit bigint; v_title text; v_new bigint;
  v_begin jsonb; v_hash text; v_commit public.client_commits%ROWTYPE;
BEGIN
  SELECT o.unit,o.title INTO v_unit,v_title FROM public.occasions o
    WHERE o.id=p_occasion;
  IF v_actor IS NULL OR v_unit IS NULL OR NOT public.get_is_manager_on_unit(v_unit) THEN
    RAISE insufficient_privilege USING MESSAGE='unit manager required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',p_occasion)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_unit_client_mutation_v1(p_command_id,
    'occasion.duplicate',v_unit,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  v_new:=public.duplicate_occasion_internal_v1(p_occasion);
  INSERT INTO public.client_commits
    (unit,actor_id,actor_display,actor_kind,source,change_class)
  SELECT v_unit,v_actor,nullif(concat_ws(' ',ui.name,ui.surname),''),'user',
    'occasion.duplicate','configuration' FROM public.user_info ui WHERE ui.id=v_actor
  RETURNING * INTO v_commit;
  INSERT INTO public.client_commit_items
    (commit_id,item_index,entity_type,entity_id,operation,safe_label,changed_fields)
  VALUES (v_commit.commit_id,0,'occasion',v_new::text,'create',
    left(COALESCE(v_title,'')||' (Copy)',240),ARRAY['aggregate']);
  PERFORM public.fanout_unit_catalog_v1(v_commit.commit_id,v_unit);
  RETURN public.finish_client_mutation_v1(p_command_id,jsonb_build_object(
    'status','applied','code',200,'data',jsonb_build_object('occasionId',v_new),
    'mutation',jsonb_build_object('commandId',p_command_id,'receiptId',p_command_id,
      'commitId',v_commit.commit_id,'replayed',false,'occurredAt',v_commit.occurred_at),
    'sync',jsonb_build_object('replacements','[]'::jsonb)),v_commit.commit_id);
END; $$;


ALTER FUNCTION "public"."duplicate_occasion_client_sync_v1"("p_occasion" bigint, "p_command_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."duplicate_occasion_internal_v1"("oc" bigint) RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  new_occ         bigint;
  rec             record;
  new_info_id     bigint;
  v_new_id        bigint;
  new_place_id    bigint;
  new_event_id    bigint;
  new_bp_id       bigint;
  new_pt_id       bigint;
  new_product_id  bigint;
  new_form_id     bigint;
BEGIN
    PERFORM public.check_is_manager_on_unit((SELECT unit FROM public.occasions WHERE id = oc));

  INSERT INTO public.occasions
    (created_at, updated_at, data, is_hidden, is_open, is_promoted, start_time, end_time, link, title, organization, services, unit, features, occasion_hidden, description)
  SELECT now(), now(), data, is_hidden, is_open, is_promoted, start_time, end_time,
         link || '-copy-' || substring(md5(random()::text) from 1 for 8) AS link,
         title || ' (Copy)', organization, services, unit, features, occasion_hidden, description
  FROM public.occasions
  WHERE id = oc
  RETURNING id INTO new_occ;

  RAISE NOTICE 'New occasion id: %', new_occ;

  CREATE TEMP TABLE tmp_places (old_id bigint, new_id bigint) ON COMMIT DROP;
  CREATE TEMP TABLE tmp_events (old_id bigint, new_id bigint) ON COMMIT DROP;
  CREATE TEMP TABLE tmp_exclusive_groups (old_id bigint, new_id bigint) ON COMMIT DROP;
  CREATE TEMP TABLE tmp_blueprints (old_id bigint, new_id bigint) ON COMMIT DROP;
  CREATE TEMP TABLE tmp_product_types (old_id bigint, new_id bigint) ON COMMIT DROP;
  CREATE TEMP TABLE tmp_products (old_id bigint, new_id bigint) ON COMMIT DROP;
  CREATE TEMP TABLE tmp_spots (old_id bigint, new_id bigint) ON COMMIT DROP;
  CREATE TEMP TABLE tmp_forms (old_id bigint, new_id bigint) ON COMMIT DROP;
  CREATE TEMP TABLE tmp_information_hidden (old_id bigint, new_id bigint) ON COMMIT DROP;

  INSERT INTO public.email_templates (html, occasion, unit, subject, organization, code)
  SELECT html, new_occ, unit, subject, organization, code
  FROM public.email_templates
  WHERE occasion = oc;

  FOR rec IN
    SELECT id, data
    FROM public.information_hidden
    WHERE occasion = oc
  LOOP
    INSERT INTO public.information_hidden (created_at, data, occasion)
    VALUES (now(), rec.data, new_occ)
    RETURNING id INTO new_info_id;

    INSERT INTO tmp_information_hidden (old_id, new_id)
    VALUES (rec.id, new_info_id);
  END LOOP;

  INSERT INTO public.information
    (created_at, title, description, is_hidden, "order", updated_at, type, occasion, data, information_hidden, unit)
  SELECT now(), title, description, is_hidden, "order", now(), type, new_occ, data,
         CASE WHEN information_hidden IS NOT NULL
              THEN (SELECT tih.new_id FROM tmp_information_hidden AS tih WHERE tih.old_id = information_hidden)
              ELSE NULL END,
         unit
  FROM public.information
  WHERE occasion = oc;

  INSERT INTO public.role_info (title, occasion)
  SELECT title, new_occ
  FROM public.role_info
  WHERE occasion = oc;

  FOR rec IN
    SELECT id, title, description, type, created_at, coordinates, is_hidden, "order", icon, unit
    FROM public.places
    WHERE occasion = oc
  LOOP
    INSERT INTO public.places
      (title, description, type, created_at, coordinates, is_hidden, updated_at, occasion, "order", icon, unit)
    VALUES (rec.title, rec.description, rec.type, rec.created_at, rec.coordinates, rec.is_hidden, now(), new_occ, rec."order", rec.icon, rec.unit)
    RETURNING id INTO v_new_id;

    INSERT INTO tmp_places (old_id, new_id)
    VALUES (rec.id, v_new_id);
  END LOOP;

  FOR rec IN
    SELECT id, title
    FROM public.exclusive_groups
    WHERE occasion = oc
  LOOP
    INSERT INTO public.exclusive_groups (title, occasion)
    VALUES (rec.title, new_occ)
    RETURNING id INTO v_new_id;

    INSERT INTO tmp_exclusive_groups (old_id, new_id)
    VALUES (rec.id, v_new_id);
  END LOOP;

  FOR rec IN
    SELECT id, title, start_time, end_time, max_participants, description, place, split_for_men_women, is_group_event, is_hidden, type, data
    FROM public.events
    WHERE occasion = oc
  LOOP
    SELECT t.new_id INTO new_place_id
      FROM tmp_places AS t
      WHERE t.old_id = rec.place;

    INSERT INTO public.events
      (created_at, title, start_time, end_time, max_participants, description, place, split_for_men_women, is_group_event, updated_at, is_hidden, occasion, type, data)
    VALUES (now(), rec.title, rec.start_time, rec.end_time, rec.max_participants, rec.description,
            COALESCE(new_place_id, rec.place), rec.split_for_men_women, rec.is_group_event, now(), rec.is_hidden, new_occ, rec.type, rec.data)
    RETURNING id INTO v_new_id;

    INSERT INTO tmp_events (old_id, new_id)
    VALUES (rec.id, v_new_id);
  END LOOP;

  INSERT INTO public.event_groups (event_parent, event_child)
  SELECT
    (SELECT te.new_id FROM tmp_events AS te WHERE te.old_id = eg.event_parent),
    (SELECT te.new_id FROM tmp_events AS te WHERE te.old_id = eg.event_child)
  FROM public.event_groups eg
  WHERE eg.event_parent IN (SELECT old_id FROM tmp_events)
    AND eg.event_child IN (SELECT old_id FROM tmp_events);

  INSERT INTO public.event_roles (event, role)
  SELECT (SELECT te.new_id FROM tmp_events AS te WHERE te.old_id = er.event), er.role
  FROM public.event_roles er
  WHERE er.event IN (SELECT old_id FROM tmp_events);

  INSERT INTO public.exclusive_events (event, "group")
  SELECT
    (SELECT te.new_id FROM tmp_events AS te WHERE te.old_id = ee.event),
    (SELECT teg.new_id FROM tmp_exclusive_groups AS teg WHERE teg.old_id = ee."group")
  FROM public.exclusive_events ee
  WHERE ee.event IN (SELECT old_id FROM tmp_events)
    AND ee."group" IN (SELECT old_id FROM tmp_exclusive_groups);

  FOR rec IN
    SELECT id, data, title, organization, configuration, objects, groups, background_svg
    FROM eshop.blueprints
    WHERE occasion = oc
  LOOP
    INSERT INTO eshop.blueprints
      (created_at, data, title, organization, configuration, objects, groups, occasion, updated_at, background_svg)
    VALUES (now(), rec.data, rec.title, rec.organization, rec.configuration, rec.objects, rec.groups, new_occ, now(), rec.background_svg)
    RETURNING id INTO v_new_id;

    INSERT INTO tmp_blueprints (old_id, new_id)
    VALUES (rec.id, v_new_id);
  END LOOP;

  FOR rec IN
    SELECT id, title, description, type, data
    FROM eshop.product_types
    WHERE occasion = oc
  LOOP
    INSERT INTO eshop.product_types
      (created_at, updated_at, title, description, type, data, occasion)
    VALUES (now(), now(), rec.title, rec.description, rec.type, rec.data, new_occ)
    RETURNING id INTO v_new_id;

    INSERT INTO tmp_product_types (old_id, new_id)
    VALUES (rec.id, v_new_id);
  END LOOP;

  FOR rec IN
    SELECT id, title, description, price, data, product_type, is_hidden, currency_code, "order"
    FROM eshop.products
    WHERE occasion = oc
  LOOP
    SELECT t.new_id INTO new_pt_id
      FROM tmp_product_types AS t
      WHERE t.old_id = rec.product_type;

    INSERT INTO eshop.products
      (created_at, updated_at, title, description, price, data, product_type, occasion, is_hidden, currency_code, "order")
    VALUES (now(), now(), rec.title, rec.description, rec.price, rec.data,
            COALESCE(new_pt_id, rec.product_type), new_occ, rec.is_hidden, rec.currency_code, rec."order")
    RETURNING id INTO v_new_id;

    INSERT INTO tmp_products (old_id, new_id)
    VALUES (rec.id, v_new_id);
  END LOOP;

  FOR rec IN
    SELECT id, product, secret, secret_expiration_time, title, order_product_ticket, blueprint
    FROM eshop.spots
    WHERE occasion = oc
  LOOP
    SELECT t.new_id INTO new_product_id
      FROM tmp_products AS t
      WHERE t.old_id = rec.product;

    SELECT t.new_id INTO new_bp_id
      FROM tmp_blueprints AS t
      WHERE t.old_id = rec.blueprint;

    INSERT INTO eshop.spots
      (created_at, occasion, product, updated_at, secret, secret_expiration_time, title, order_product_ticket, blueprint)
    VALUES (now(), new_occ, COALESCE(new_product_id, rec.product), now(), null, null, rec.title, null, COALESCE(new_bp_id, rec.blueprint))
    RETURNING id INTO v_new_id;

    INSERT INTO tmp_spots (old_id, new_id)
    VALUES (rec.id, v_new_id);
  END LOOP;

  FOR rec IN
    SELECT tb.old_id AS old_bp, tb.new_id AS new_bp, b.objects
    FROM tmp_blueprints tb
    JOIN eshop.blueprints b ON b.id = tb.new_id
  LOOP
    IF rec.objects IS NOT NULL THEN
      UPDATE eshop.blueprints
      SET objects = (
        SELECT jsonb_agg(
          CASE
            WHEN obj->>'type' = 'spot' THEN
              obj || jsonb_build_object(
                'id',
                COALESCE(
                  (SELECT ts.new_id FROM tmp_spots ts WHERE ts.old_id = (obj->>'id')::bigint),
                  (obj->>'id')::int
                )
              )
            ELSE obj
          END
        )
        FROM jsonb_array_elements(rec.objects) AS obj
      )
      WHERE id = rec.new_bp;
    END IF;
  END LOOP;

  FOR rec IN
    SELECT id, data, key, type, bank_account, deadline_duration_seconds, is_open, link, blueprint, header, header_off, title
    FROM public.forms
    WHERE occasion = oc
  LOOP
    SELECT t.new_id INTO new_bp_id
      FROM tmp_blueprints AS t
      WHERE t.old_id = rec.blueprint;

    INSERT INTO public.forms
      (created_at, data, key, occasion, type, bank_account, deadline_duration_seconds, is_open, link, blueprint, header, header_off, updated_at, title)
    VALUES (now(), rec.data, uuid_generate_v4(), new_occ, rec.type, rec.bank_account, rec.deadline_duration_seconds, rec.is_open,
            replace(uuid_generate_v4()::text, '-', ''),
            COALESCE(new_bp_id, rec.blueprint), rec.header, rec.header_off, now(), rec.title)
    RETURNING id INTO v_new_id;

    INSERT INTO tmp_forms (old_id, new_id)
    VALUES (rec.id, v_new_id);
  END LOOP;

  INSERT INTO public.form_fields
    (created_at, title, description, data, type, is_required, form, is_hidden, "order", product_type, is_ticket_field)
  SELECT now(), title, description, data, type, is_required,
         (SELECT tf.new_id FROM tmp_forms AS tf WHERE tf.old_id = form),
         is_hidden, "order",
         CASE WHEN product_type IS NOT NULL
              THEN (SELECT tp.new_id FROM tmp_product_types AS tp WHERE tp.old_id = product_type)
              ELSE NULL END,
         is_ticket_field
  FROM public.form_fields
  WHERE form IN (SELECT old_id FROM tmp_forms);

  RETURN new_occ;
END;
$$;


ALTER FUNCTION "public"."duplicate_occasion_internal_v1"("oc" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_ticket_order_confirmation_v1"("p_command_id" "uuid", "p_occasion" bigint, "p_order_payload" "jsonb", "p_language" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_organization bigint; v_unit bigint;
BEGIN
  SELECT o.organization,o.unit INTO v_organization,v_unit
    FROM public.occasions o WHERE o.id=p_occasion;
  IF v_organization IS NULL OR p_command_id IS NULL OR p_order_payload IS NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid ticket order effect'; END IF;
  INSERT INTO public.queue_emails
    (target_time,code,data,organization,occasion,unit)
  VALUES (now(),'TICKET_ORDER_CONFIRMATION',jsonb_build_object(
    'command_id',p_command_id,'ticket_order',p_order_payload,
    'lang',COALESCE(NULLIF(p_language,''),'cs')),v_organization,p_occasion,v_unit)
  ON CONFLICT ((data->>'command_id'))
    WHERE code='TICKET_ORDER_CONFIRMATION' AND data ? 'command_id'
    DO NOTHING;
END; $$;


ALTER FUNCTION "public"."enqueue_ticket_order_confirmation_v1"("p_command_id" "uuid", "p_occasion" bigint, "p_order_payload" "jsonb", "p_language" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."eshop_fetch_resources"("p_occasion_id" integer) RETURNS "json"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  product_types json;
  products json;
BEGIN
  -- Fetch all product types
  SELECT json_agg(
           json_build_object(
             'id', pt.id,
             'type', pt.type
           )
         )
    INTO product_types
  FROM eshop.product_types pt;

  -- Fetch products for the given occasion
  SELECT json_agg(
           json_build_object(
             'id', p.id,
             'title', p.title,
             'title_short', p.title_short,
             'product_type', p.product_type,
             'data', p.data
           )
         )
    INTO products
  FROM eshop.products p
  WHERE p.occasion = p_occasion_id;

  RETURN json_build_object(
    'product_types', COALESCE(product_types, '[]'::json),
    'products', COALESCE(products, '[]'::json)
  );
END;
$$;


ALTER FUNCTION "public"."eshop_fetch_resources"("p_occasion_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."extract_history_product_ids"("history_data" "jsonb") RETURNS integer[]
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT COALESCE(
    -- Aggregate distinct product IDs into an array, sorting them for consistency
    ARRAY_AGG(DISTINCT (p->>'id')::int ORDER BY (p->>'id')::int),
    -- If aggregation results in NULL (i.e., no products found), return an empty integer array
    '{}'::int[]
  )
  FROM jsonb_array_elements(history_data->'tickets') AS t,
       jsonb_array_elements(t->'products') AS p;
$$;


ALTER FUNCTION "public"."extract_history_product_ids"("history_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."extract_history_products_with_price"("history_data" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT COALESCE(
    -- Step 2: Aggregate the distinct product objects into a single JSONB array,
    -- ordering them by the 'id' field cast to an integer.
    jsonb_agg(p.product_object ORDER BY (p.product_object->>'id')::int),

    -- If the aggregation is null (no products found), return an empty array.
    '[]'::jsonb
  )
  FROM (
    -- Step 1: Create a derived table (subquery) of distinct product objects.
    -- This subquery unnests the tickets and products, builds the desired
    -- {'id': ..., 'price': ...} object, and returns only the unique ones.
    SELECT DISTINCT
      jsonb_build_object('id', product->>'id', 'price', product->>'price') AS product_object
    FROM
      jsonb_array_elements(history_data->'tickets') AS ticket,
      jsonb_array_elements(ticket->'products') AS product
  ) AS p;
$$;


ALTER FUNCTION "public"."extract_history_products_with_price"("history_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."f_html_snippet"("p_html" "text", "p_limit" integer DEFAULT 160) RETURNS "text"
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    AS $_$
    WITH cleaned AS (
        SELECT btrim(
                 regexp_replace(
                   regexp_replace(
                     regexp_replace(coalesce(p_html, ''), '<[^>]*>', ' ', 'g'),
                     '<[^>]*$', '', 'g'
                   ),
                   '\s+', ' ', 'g'
                 )
               ) AS t
    )
    SELECT CASE
             WHEN length(t) <= p_limit THEN t
             ELSE btrim(regexp_replace(LEFT(t, p_limit), '\s\S*$', '')) || '…'
           END
    FROM cleaned;
$_$;


ALTER FUNCTION "public"."f_html_snippet"("p_html" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."f_unaccent"("t" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE STRICT PARALLEL SAFE
    SET "search_path" TO 'public', 'extensions'
    AS $$
  SELECT lower(extensions.unaccent('extensions.unaccent'::regdictionary, t));
$$;


ALTER FUNCTION "public"."f_unaccent"("t" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fanout_unit_catalog_v1"("p_commit_id" "uuid", "p_unit" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_occasion bigint; v_revision bigint;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.client_commits c
    WHERE c.commit_id=p_commit_id) THEN
    RAISE foreign_key_violation USING MESSAGE='unit fanout requires an audit commit';
  END IF;
  FOR v_occasion IN SELECT o.id FROM public.occasions o
    WHERE o.unit=p_unit AND NOT o.is_hidden ORDER BY o.id LOOP
    INSERT INTO public.client_sync_scopes
      (component,scope_type,scope_id,source_revision)
    VALUES ('unit_catalog','occasion',v_occasion,1)
    ON CONFLICT (component,scope_type,scope_id) DO UPDATE
      SET source_revision=public.client_sync_scopes.source_revision+1,
          updated_at=now()
    RETURNING source_revision INTO v_revision;
    INSERT INTO public.client_commit_components
      (commit_id,component,scope_type,scope_id,user_id,resulting_revision)
    VALUES (p_commit_id,'unit_catalog','occasion',v_occasion,NULL,v_revision);
    INSERT INTO public.client_projection_dirty_keys
      (component,scope_type,scope_id,entity_id,source_revision)
    VALUES ('unit_catalog','occasion',v_occasion,0,v_revision)
    ON CONFLICT (component,scope_type,scope_id,entity_id) DO UPDATE
      SET source_revision=EXCLUDED.source_revision,dirty_since=now(),
          claimed_at=NULL,claim_token=NULL;
  END LOOP;
END; $$;


ALTER FUNCTION "public"."fanout_unit_catalog_v1"("p_commit_id" "uuid", "p_unit" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finish_client_mutation_v1"("p_command_id" "uuid", "p_response" "jsonb", "p_commit_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_receipt public.client_mutation_receipts%ROWTYPE;
BEGIN
  -- Aggregate commands may carry one bounded private replacement (activities
  -- and inventory are the largest). The receipt must preserve the exact
  -- response for retry, so its bound must exceed the aggregate DTO bounds.
  IF p_response IS NULL OR octet_length(p_response::text) > 8388608 THEN
    RAISE program_limit_exceeded USING MESSAGE='mutation response exceeds receipt limit';
  END IF;
  SELECT * INTO STRICT v_receipt
  FROM public.client_mutation_receipts
  WHERE command_id=p_command_id
  FOR UPDATE;
  IF (v_receipt.actor_id IS NOT NULL
      AND v_receipt.actor_id IS DISTINCT FROM auth.uid())
    OR (v_receipt.actor_client_id IS NOT NULL AND auth.uid() IS NOT NULL) THEN
    RAISE insufficient_privilege USING MESSAGE='mutation receipt actor mismatch';
  END IF;
  IF v_receipt.status <> 'processing' THEN
    RAISE invalid_parameter_value USING MESSAGE='mutation receipt already completed';
  END IF;
  IF p_commit_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.client_commits c
    WHERE c.commit_id=p_commit_id
      AND c.occasion IS NOT DISTINCT FROM v_receipt.occasion
      AND c.unit IS NOT DISTINCT FROM v_receipt.unit
      AND c.organization IS NULL
      AND c.actor_id IS NOT DISTINCT FROM v_receipt.actor_id
  ) THEN
    RAISE foreign_key_violation USING MESSAGE='commit does not belong to mutation receipt';
  END IF;

  UPDATE public.client_mutation_receipts
  SET status='completed', response=p_response, commit_id=p_commit_id,
      completed_at=clock_timestamp()
  WHERE command_id=p_command_id;
  RETURN p_response;
END;
$$;


ALTER FUNCTION "public"."finish_client_mutation_v1"("p_command_id" "uuid", "p_response" "jsonb", "p_commit_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."game_get_correctly_guessed_checkpoints"("oc" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    user_group_data JSONB;
BEGIN
    -- Retrieve the `data` field for the user's first group where `type = 'game'` and matches the given occasion
    SELECT data
    INTO user_group_data
    FROM user_group_info ug
    JOIN user_groups ug_rel ON ug.id = ug_rel.group
    WHERE ug_rel.user = auth.uid()
      AND ug.type = 'game'
      AND ug.occasion = oc
    LIMIT 1;

    -- Extract each checkpoint as a JSON object with key "check_point" from the "game" array
    RETURN jsonb_build_object(
        'code', 200,
        'data', COALESCE(
            (SELECT jsonb_agg(jsonb_build_object('check_point', (game_entry->>'check_point')::INT))
             FROM jsonb_array_elements(user_group_data->'game') AS game_entry),
            '[]'::JSONB
        )
    );
END;
$$;


ALTER FUNCTION "public"."game_get_correctly_guessed_checkpoints"("oc" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."game_guess"("check_point_id" bigint, "guess" "text") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT public.game_guess_internal_v1(check_point_id,guess);
$$;


ALTER FUNCTION "public"."game_guess"("check_point_id" bigint, "guess" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."game_guess_client_sync_v1"("p_checkpoint" bigint, "p_guess" "text", "p_command_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_actor uuid:=auth.uid(); v_occasion bigint; v_group bigint;
  v_begin jsonb; v_hash text; v_result jsonb; v_before jsonb; v_after jsonb;
  v_version bigint; v_impacts jsonb; v_replacements jsonb;
  v_domain_code integer;
BEGIN
  SELECT ih.occasion INTO v_occasion FROM public.information i
    JOIN public.information_hidden ih ON ih.id=i.information_hidden
    WHERE i.id=p_checkpoint;
  IF v_actor IS NULL OR v_occasion IS NULL THEN
    RAISE insufficient_privilege USING MESSAGE='occasion participant required'; END IF;
  SELECT ug."group" INTO v_group FROM public.user_groups ug
    JOIN public.user_group_info g ON g.id=ug."group"
    WHERE ug."user"=v_actor AND g.occasion=v_occasion AND g.type='game'
    ORDER BY g.id LIMIT 1;
  IF v_group IS NULL THEN RAISE insufficient_privilege USING MESSAGE='game group required'; END IF;
  IF p_guess IS NULL OR length(p_guess)>2000 THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid game guess'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'checkpoint',p_checkpoint,'guess',p_guess)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'profile.game.guess',
    v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  SELECT g.data INTO v_before FROM public.user_group_info g WHERE g.id=v_group FOR UPDATE;
  v_result:=public.game_guess_internal_v1(p_checkpoint,p_guess);
  v_domain_code:=COALESCE((v_result->>'code')::integer,500);
  IF v_domain_code<>200 THEN RETURN public.complete_client_mutation_outcome_v1(
    p_command_id,'rejected',CASE WHEN v_domain_code BETWEEN 4030 AND 4039 THEN 403
      WHEN v_domain_code BETWEEN 4040 AND 4049 THEN 404 ELSE 400 END,
    jsonb_build_object('domainCode',v_domain_code,'message',v_result->>'message'));
  END IF;
  SELECT g.data INTO v_after FROM public.user_group_info g WHERE g.id=v_group;
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES ('user_group','occasion',v_occasion,v_group::text,0) ON CONFLICT DO NOTHING;
  SELECT version INTO v_version FROM public.client_aggregate_versions
    WHERE aggregate_type='user_group' AND scope_type='occasion'
      AND scope_id=v_occasion AND aggregate_id=v_group::text FOR UPDATE;
  IF v_before IS NOT DISTINCT FROM v_after THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
      jsonb_build_object('domainCode',200,'correct',true,'version',v_version)); END IF;
  UPDATE public.client_aggregate_versions SET version=version+1,
    updated_at=clock_timestamp() WHERE aggregate_type='user_group'
    AND scope_type='occasion' AND scope_id=v_occasion AND aggregate_id=v_group::text
    RETURNING version INTO v_version;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('component','private_profile',
    'userId',ug."user")),'[]'::jsonb) INTO v_impacts FROM public.user_groups ug
    WHERE ug."group"=v_group;
  v_replacements:=jsonb_build_array(jsonb_build_object(
    'component','private_profile','userId',v_actor,
    'payload',public.get_private_profile_payload_v1(v_occasion,v_actor)));
  RETURN public.complete_client_mutation_applied_v1(p_command_id,v_occasion,
    'profile.game.guess','profile',jsonb_build_array(jsonb_build_object(
      'entityType','user_group','entityId',v_group,'operation','update',
      'safeLabel','Game checkpoint','changedFields',jsonb_build_array('game'))),
    '{}',v_impacts,'[]',jsonb_build_object('domainCode',200,'correct',true,
      'version',v_version),'{}','[]','user',NULL,v_replacements);
END; $$;


ALTER FUNCTION "public"."game_guess_client_sync_v1"("p_checkpoint" bigint, "p_guess" "text", "p_command_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."game_guess_internal_v1"("check_point_id" bigint, "guess" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    hidden_value TEXT;
    correct_reference BIGINT;
    user_occasion BIGINT;
    user_in_group BOOLEAN;
    current_time TIMESTAMPTZ := NOW() AT TIME ZONE 'UTC';
    game_start TIMESTAMPTZ;
    game_end TIMESTAMPTZ;
    user_id UUID := auth.uid();  -- Retrieve the user ID from the authentication context
    existing_game_data JSONB;
BEGIN
    -- Step 1: Get the reference to `information_hidden` in `information` and check if it exists
    SELECT information_hidden::BIGINT INTO correct_reference
    FROM information
    WHERE id = check_point_id;

    IF correct_reference IS NULL THEN
        RETURN jsonb_build_object('code', 4041, 'message', 'Correct reference not found in information');
    END IF;

    -- Step 2: Retrieve the correct answer from `information_hidden.data` under the "correct" key and the occasion
    SELECT data->>'correct', occasion INTO hidden_value, user_occasion
    FROM information_hidden
    WHERE id = correct_reference;

    IF hidden_value IS NULL THEN
        RETURN jsonb_build_object('code', 4042, 'message', 'Hidden info not found or correct answer missing');
    END IF;

    -- Step 3: Retrieve game start and end times from the occasion data JSON, casting directly to TIMESTAMPTZ
    SELECT
        COALESCE((data->'game'->>'start')::TIMESTAMPTZ, NULL),
        COALESCE((data->'game'->>'end')::TIMESTAMPTZ, NULL)
    INTO game_start, game_end
    FROM occasions
    WHERE id = user_occasion;

    -- Step 4: Check if the current time is within the game time window
    IF game_start IS NOT NULL AND game_end IS NOT NULL THEN
        IF (CURRENT_DATE + current_time)::TIMESTAMPTZ < game_start OR (CURRENT_DATE + current_time)::TIMESTAMPTZ > game_end THEN
            RETURN jsonb_build_object('code', 4033, 'message', 'Guessing is only allowed within the game time window');
        END IF;
    END IF;

    -- Step 5: Check if the user is part of the occasion
    IF NOT EXISTS (
        SELECT 1
        FROM occasion_users
        WHERE "user" = user_id
          AND occasion = user_occasion
    ) THEN
        RETURN jsonb_build_object('code', 4031, 'message', 'User not in occasion');
    END IF;

    -- Step 6: Check if user is in a "game" type user group associated with the occasion
    user_in_group := EXISTS (
        SELECT 1
        FROM user_groups ug
        JOIN user_group_info ugi ON ug."group" = ugi.id
        WHERE ug."user" = user_id
          AND ugi.occasion = user_occasion
          AND ugi.type = 'game'
    );

    IF NOT user_in_group THEN
        RETURN jsonb_build_object('code', 4032, 'message', 'User not part of a game group');
    END IF;

    -- Step 7: Compare `guess` with `hidden_value` (ignoring diacritics, case, and trimming whitespace)
    IF unaccent(LOWER(TRIM(guess))) = unaccent(LOWER(TRIM(hidden_value))) THEN

        -- Step 8: Retrieve existing `game` array from `data` JSON and check if checkpoint already exists
        SELECT COALESCE(data->'game', '[]'::jsonb) INTO existing_game_data
        FROM user_group_info
        WHERE id = (
            SELECT "group"
            FROM user_groups
            WHERE "user" = user_id
              AND "group" IN (SELECT id FROM user_group_info WHERE occasion = user_occasion AND type = 'game')
            LIMIT 1
        );

        -- If `game` array does not exist, initialize it as an empty array
        IF existing_game_data IS NULL OR existing_game_data = 'null'::jsonb THEN
            existing_game_data := '[]'::jsonb;
        END IF;

        -- Append the new checkpoint if it does not already exist in the `game` array
        IF NOT EXISTS (
            SELECT 1 FROM jsonb_array_elements(existing_game_data) AS elem
            WHERE (elem->>'check_point')::INT = check_point_id
        ) THEN
            existing_game_data := existing_game_data || jsonb_build_array(
                jsonb_build_object('check_point', check_point_id, 'time', current_time)
            );

            -- Update the `data` JSON with the modified `game` array
            UPDATE user_group_info
            SET data = jsonb_set(COALESCE(data, '{}'::jsonb), '{game}', existing_game_data, true)
            WHERE id = (
                SELECT "group"
                FROM user_groups
                WHERE "user" = user_id
                  AND "group" IN (SELECT id FROM user_group_info WHERE occasion = user_occasion AND type = 'game')
                LIMIT 1
            );
        END IF;

        RETURN jsonb_build_object('code', 200, 'message', 'Correct answer');
    ELSE
        RETURN jsonb_build_object('code', 4001, 'message', 'Incorrect guess');
    END IF;
END;
$$;


ALTER FUNCTION "public"."game_guess_internal_v1"("check_point_id" bigint, "guess" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."game_update_settings"("oc" bigint, "new_start_time" timestamp with time zone, "new_end_time" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN RETURN public.game_update_settings_client_sync_v1(
  oc,new_start_time,new_end_time,extensions.gen_random_uuid())->'data'; END; $$;


ALTER FUNCTION "public"."game_update_settings"("oc" bigint, "new_start_time" timestamp with time zone, "new_end_time" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."game_update_settings_client_sync_v1"("p_occasion" bigint, "p_start" timestamp with time zone, "p_end" timestamp with time zone, "p_command_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_actor uuid:=auth.uid(); v_begin jsonb; v_hash text; v_result jsonb;
  v_before jsonb; v_after jsonb;
BEGIN
  IF v_actor IS NULL OR NOT public.get_is_editor_on_occasion(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',p_occasion,'start',p_start,'end',p_end)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'occasion.game.settings',p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  SELECT o.data INTO v_before FROM public.occasions o
    WHERE o.id=p_occasion FOR UPDATE;
  v_result:=public.game_update_settings_internal_v1(p_occasion,p_start,p_end);
  IF COALESCE((v_result->>'code')::integer,500)<>200 THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',
      400,v_result); END IF;
  SELECT o.data INTO v_after FROM public.occasions o WHERE o.id=p_occasion;
  IF v_before IS NOT DISTINCT FROM v_after THEN
    RETURN public.complete_client_mutation_outcome_v1(
      p_command_id,'unchanged',200,v_result); END IF;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'occasion.game.settings','configuration',jsonb_build_array(jsonb_build_object(
      'entityType','game_settings','entityId',p_occasion,'operation','update',
      'safeLabel','Game settings','changedFields',jsonb_build_array('data.game'))),
    ARRAY['occasion_config'],'[]','[]',v_result);
END; $$;


ALTER FUNCTION "public"."game_update_settings_client_sync_v1"("p_occasion" bigint, "p_start" timestamp with time zone, "p_end" timestamp with time zone, "p_command_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."game_update_settings_internal_v1"("oc" bigint, "new_start_time" timestamp with time zone, "new_end_time" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  existing_data JSONB;
  updated_game_data JSONB;
BEGIN
  -- Check if the user is an editor on the occasion
  IF (SELECT get_is_editor_on_occasion(oc)) <> TRUE THEN
    RETURN jsonb_build_object('code', 403, 'message', 'User is not authorized to edit this occasion');
  END IF;

  -- Retrieve existing data JSON if any
  SELECT data INTO existing_data FROM public.occasions WHERE id = oc;

  -- Create or update the "game" object with new start and end times, preserving other keys in "game"
  updated_game_data := COALESCE(existing_data->'game', '{}'::jsonb) || jsonb_build_object(
    'start', CASE WHEN new_start_time IS NOT NULL THEN to_jsonb(new_start_time) ELSE 'null'::jsonb END,
    'end', CASE WHEN new_end_time IS NOT NULL THEN to_jsonb(new_end_time) ELSE 'null'::jsonb END
  );

  -- Update the data JSON with the updated "game" data
  UPDATE public.occasions
  SET data = jsonb_set(
      COALESCE(data, '{}'::jsonb),                          -- Ensure data is an empty JSON if NULL
      ARRAY['game'],                                        -- Path to the "game" key
      updated_game_data,                                    -- Updated game data with merged start and end times
      true
    )
  WHERE id = oc;

  -- Return success response
  RETURN jsonb_build_object(
    'code', 200,
    'message', 'Game settings updated successfully'
  );
END;
$$;


ALTER FUNCTION "public"."game_update_settings_internal_v1"("oc" bigint, "new_start_time" timestamp with time zone, "new_end_time" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_payment_variable_symbol"("p_bank_account_id" bigint, "p_form_id" bigint) RETURNS bigint
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    -- Variables for form configuration
    v_form_data JSONB;
    v_vs_config JSONB;
    v_vs_type TEXT;
    v_starting_number BIGINT;
    v_max_symbol_for_form BIGINT;

    -- General variable for the symbol to be returned
    v_candidate_symbol BIGINT;

    -- Variables for the random generation fallback
    v_digit_count INT := 4;
    v_attempt_count INT := 0;
    v_max_attempts INT := 1;
    v_safety_counter INT := 0; -- Safety break for the sequential loop
BEGIN
    -- 1. Fetch the configuration data for the given form
    SELECT data INTO v_form_data FROM public.forms WHERE id = p_form_id;

    -- Raise an error if the form does not exist
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Form with ID % not found.', p_form_id;
    END IF;

    -- 2. Check for custom variable symbol configuration within the JSONB data
    -- We use COALESCE to default to 'random' if the setting is missing, making the function robust.
    v_vs_config := v_form_data -> 'variable_symbol';
    v_vs_type := COALESCE(v_vs_config ->> 'type', 'random');

    -- 3. Main logic: Choose between 'sequence' and 'random' generation
    IF v_vs_type = 'sequence' THEN
        ----------------------------------------------------
        -- LOGIC FOR SEQUENTIAL VARIABLE SYMBOL GENERATION --
        ----------------------------------------------------

        -- Get the defined starting number from the form's configuration
        v_starting_number := (v_vs_config ->> 'starting_number')::BIGINT;
        IF v_starting_number IS NULL THEN
            RAISE EXCEPTION 'Form with ID % is configured for sequential variable symbols, but "starting_number" is missing in its data.', p_form_id;
        END IF;

        -- Find the highest existing variable symbol used for this specific form.
        -- We must join through the orders table to link payments to a form.
        SELECT MAX(pi.variable_symbol)
        INTO v_max_symbol_for_form
        FROM eshop.payment_info pi
        JOIN eshop.orders o ON pi.id = o.payment_info
        WHERE o.form = p_form_id;

        -- Determine the first candidate for our new variable symbol.
        -- If no previous symbol exists for this form, use the starting number.
        -- Otherwise, take the highest existing symbol and add 1.
        -- The GREATEST function handles the edge case where the starting_number was increased after symbols were already generated.
        IF v_max_symbol_for_form IS NULL THEN
            v_candidate_symbol := v_starting_number;
        ELSE
            v_candidate_symbol := GREATEST(v_max_symbol_for_form + 1, v_starting_number);
        END IF;

        -- Loop to ensure the candidate symbol is unique for the target bank account.
        -- If the symbol is already taken, increment and check again.
        LOOP
            IF NOT EXISTS (
                SELECT 1
                FROM eshop.payment_info
                WHERE variable_symbol = v_candidate_symbol AND bank_account = p_bank_account_id
            ) THEN
                RETURN v_candidate_symbol; -- The symbol is unique, return it.
            END IF;

            -- The symbol was taken, so we increment and try the next one.
            v_candidate_symbol := v_candidate_symbol + 1;

            -- Add a safety break to prevent an infinite loop in unusual circumstances.
            v_safety_counter := v_safety_counter + 1;
            IF v_safety_counter > 1000 THEN
                RAISE EXCEPTION 'Could not find a unique sequential variable symbol for bank account % after 1000 attempts.', p_bank_account_id;
            END IF;
        END LOOP;

    ELSE
        ------------------------------------------------
        -- LOGIC FOR RANDOM VARIABLE SYMBOL GENERATION --
        ------------------------------------------------

        LOOP
            -- Generate a random number with the current digit count
            v_candidate_symbol := FLOOR(RANDOM() * (POWER(10, v_digit_count) - POWER(10, v_digit_count - 1))) + POWER(10, v_digit_count - 1);

            -- Ensure uniqueness within the bank_account
            IF NOT EXISTS (
                SELECT 1
                FROM eshop.payment_info
                WHERE variable_symbol = v_candidate_symbol AND bank_account = p_bank_account_id
            ) THEN
                RETURN v_candidate_symbol; -- Return the unique variable symbol
            END IF;

            -- Increment attempt count and adjust digit count after each failure
            v_attempt_count := v_attempt_count + 1;

            -- Extend digit count after reaching max attempts
            IF v_attempt_count >= v_max_attempts THEN
                v_digit_count := v_digit_count + 1;
                v_attempt_count := 0; -- Reset attempt count for the extended digit count
            END IF;

            -- Fail entirely if the system cannot generate a unique symbol after too many attempts
            IF v_digit_count > 10 THEN -- Arbitrary upper limit for digit count
                RAISE EXCEPTION 'Failed to generate a unique random variable symbol after too many attempts.';
            END IF;
        END LOOP;
    END IF;
END;
$$;


ALTER FUNCTION "public"."generate_payment_variable_symbol"("p_bank_account_id" bigint, "p_form_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_request_secret"("p_ttl_seconds" integer) RETURNS "text"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_secret text;
BEGIN
  -- Clean up expired secrets
  DELETE FROM public.request_secrets
  WHERE created_at < (now() - (interval '1 second' * ttl_seconds));

  -- Generate a new secret using a random UUID
  v_secret := gen_random_uuid()::text;

  INSERT INTO public.request_secrets(secret, ttl_seconds)
  VALUES (v_secret, p_ttl_seconds);

  RETURN v_secret;
END;
$$;


ALTER FUNCTION "public"."generate_request_secret"("p_ttl_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_schema_ddl"("p_schema" "text") RETURNS "text"
    LANGUAGE "sql" STABLE
    AS $$
WITH table_info AS (
  SELECT
    t.table_schema,
    t.table_name,
    CASE
      WHEN COALESCE(pg.tablespace, '') = '' THEN ' TABLESPACE pg_default'
      ELSE ' TABLESPACE ' || pg.tablespace
    END AS tablespace_clause
  FROM information_schema.tables t
  LEFT JOIN pg_catalog.pg_tables pg
    ON t.table_schema = pg.schemaname
   AND t.table_name = pg.tablename
  WHERE t.table_schema = p_schema
    AND t.table_type = 'BASE TABLE'
),
table_columns AS (
  SELECT
    c.table_schema,
    c.table_name,
    string_agg(
      '  ' || quote_ident(c.column_name) || ' ' ||
      (
        CASE
          -- Identity columns: type + identity clause
          WHEN c.is_identity = 'YES' THEN
            c.data_type ||
            CASE
              WHEN c.data_type IN ('character varying','character')
                   AND c.character_maximum_length IS NOT NULL
              THEN '(' || c.character_maximum_length || ')'
              WHEN c.data_type = 'numeric' AND c.numeric_precision IS NOT NULL
              THEN '(' || c.numeric_precision || ', ' || c.numeric_scale || ')'
              ELSE ''
            END ||
            ' generated ' || lower(c.identity_generation) || ' as identity'
          -- Serial columns (if not identity)
          WHEN c.data_type = 'integer' AND c.column_default LIKE 'nextval(%' THEN
            'serial'
          -- Numeric columns with precision/scale
          WHEN c.data_type = 'numeric' AND c.numeric_precision IS NOT NULL THEN
            'numeric(' || c.numeric_precision || ', ' || c.numeric_scale || ')'
          ELSE
            c.data_type ||
              CASE
                WHEN c.data_type IN ('character varying','character')
                     AND c.character_maximum_length IS NOT NULL
                THEN '(' || c.character_maximum_length || ')'
                ELSE ''
              END
        END
      ) ||
      ' ' || (CASE WHEN c.is_nullable = 'NO' THEN 'not null' ELSE 'null' END) ||
      CASE
         WHEN c.is_identity <> 'YES'
              AND NOT (c.data_type = 'integer' AND c.column_default LIKE 'nextval(%')
              AND c.column_default IS NOT NULL
         THEN ' default ' || c.column_default
         ELSE ''
      END,
      E',\n'
      ORDER BY c.ordinal_position
    ) AS columns_definition
  FROM information_schema.columns c
  WHERE c.table_schema = p_schema
  GROUP BY c.table_schema, c.table_name
),
constraints_pk AS (
  SELECT
    tc.table_schema,
    tc.table_name,
    '  constraint ' || quote_ident(tc.constraint_name) || ' primary key (' ||
      string_agg(quote_ident(kcu.column_name), ', ' ORDER BY kcu.ordinal_position) || ')' AS constraint_def
  FROM information_schema.table_constraints tc
  JOIN information_schema.key_column_usage kcu
    ON tc.constraint_name = kcu.constraint_name
   AND tc.table_schema = kcu.table_schema
  WHERE tc.constraint_type = 'PRIMARY KEY'
    AND tc.table_schema = p_schema
  GROUP BY tc.table_schema, tc.table_name, tc.constraint_name
),
constraints_fk AS (
  SELECT
    tc.table_schema,
    tc.table_name,
    '  constraint ' || quote_ident(tc.constraint_name) || ' foreign KEY (' ||
      string_agg(quote_ident(kcu.column_name), ', ' ORDER BY kcu.ordinal_position) || ') references ' ||
      (
        -- Invert the condition: if the referenced schema is different, qualify the name.
        CASE
          WHEN reftable_ns.nspname <> p_schema
          THEN quote_ident(reftable_ns.nspname) || '.' || quote_ident(reftable.relname)
          ELSE quote_ident(reftable.relname)
        END
      ) || ' (' ||
      (
        SELECT string_agg(quote_ident(att.attname), ', ' ORDER BY u.ordinality)
        FROM unnest(pgc.confkey) WITH ORDINALITY AS u(attnum, ordinality)
        JOIN pg_attribute att
          ON att.attrelid = pgc.confrelid AND att.attnum = u.attnum
      )
      || ')' ||
      CASE
         WHEN pgc.confdeltype = 'c' THEN ' on delete cascade'
         WHEN pgc.confdeltype = 'n' THEN ' on delete set null'
         WHEN pgc.confdeltype = 'd' THEN ' on delete set default'
         WHEN pgc.confdeltype = 'r' THEN ' on delete restrict'
         ELSE ''
      END AS constraint_def
  FROM information_schema.table_constraints tc
  JOIN information_schema.key_column_usage kcu
    ON tc.constraint_name = kcu.constraint_name
   AND tc.table_schema = kcu.table_schema
  JOIN pg_constraint pgc
    ON pgc.conname = tc.constraint_name
       AND pgc.conrelid = (
            SELECT oid FROM pg_class
            WHERE relname = tc.table_name
              AND relnamespace = (SELECT oid FROM pg_namespace WHERE nspname = tc.table_schema)
       )
  JOIN pg_class reftable ON reftable.oid = pgc.confrelid
  JOIN pg_namespace reftable_ns ON reftable_ns.oid = reftable.relnamespace
  WHERE tc.constraint_type = 'FOREIGN KEY'
    AND tc.table_schema = p_schema
  GROUP BY tc.table_schema, tc.table_name, tc.constraint_name,
           reftable_ns.nspname, reftable.relname, pgc.confdeltype, pgc.confkey, pgc.confrelid
),
all_constraints AS (
  SELECT
    table_schema,
    table_name,
    string_agg(constraint_def, E',\n') AS constraints_def
  FROM (
    SELECT * FROM constraints_pk
    UNION ALL
    SELECT * FROM constraints_fk
  ) sub
  GROUP BY table_schema, table_name
),
create_statements AS (
  SELECT
    'create table if not exists ' || quote_ident(t.table_schema) || '.' || quote_ident(t.table_name) || E' (\n' ||
    COALESCE(tc.columns_definition, '') ||
    CASE
      WHEN ac.constraints_def IS NOT NULL THEN E',\n' || ac.constraints_def
      ELSE ''
    END ||
    E'\n) ' ||
    COALESCE(t.tablespace_clause, '') ||
    ';' AS create_table_statement
  FROM table_info t
  LEFT JOIN table_columns tc
    ON t.table_schema = tc.table_schema AND t.table_name = tc.table_name
  LEFT JOIN all_constraints ac
    ON t.table_schema = ac.table_schema AND t.table_name = ac.table_name
)
SELECT string_agg(create_table_statement, E'\n\n') AS ddl_all
FROM create_statements;
$$;


ALTER FUNCTION "public"."generate_schema_ddl"("p_schema" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_schema_policies_ddl"("p_schema" "text") RETURNS "text"
    LANGUAGE "sql" STABLE
    AS $$
WITH policies AS (
  SELECT schemaname,
         tablename,
         policyname,
         permissive,
         cmd,
         roles,
         qual,
         with_check
  FROM pg_policies
  WHERE schemaname = p_schema
),
formatted_policies AS (
  SELECT
    (
      'DROP POLICY IF EXISTS ' || quote_ident(policyname) || ' ON ' ||
        quote_ident(schemaname) || '.' || quote_ident(tablename) || ';' || E'\n' ||
      'CREATE POLICY ' || quote_ident(policyname) || ' ON ' ||
        quote_ident(schemaname) || '.' || quote_ident(tablename) || E'\n' ||
      (CASE WHEN lower(permissive) = 'permissive'
            THEN 'AS PERMISSIVE '
            ELSE 'AS RESTRICTIVE ' END) ||
      'FOR ' || upper(cmd) || E'\n' ||
      (CASE
         WHEN roles IS NOT NULL AND array_length(roles,1) > 0
         THEN 'TO ' || (SELECT string_agg(quote_ident(r), ', ')
                      FROM unnest(roles) AS r) || E'\n'
         ELSE ''
       END) ||
      (CASE WHEN qual IS NOT NULL AND qual <> ''
            THEN 'USING (' || qual || ')' || E'\n'
            ELSE '' END) ||
      (CASE WHEN with_check IS NOT NULL AND with_check <> ''
            THEN 'WITH CHECK (' || with_check || ')' || E'\n'
            ELSE '' END)
    ) AS raw_policy_ddl
  FROM policies
)
SELECT string_agg(rtrim(raw_policy_ddl, E'\n') || ';', E'\n\n') AS ddl_all
FROM formatted_policies;
$$;


ALTER FUNCTION "public"."generate_schema_policies_ddl"("p_schema" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_schema_rls_enable_ddl"("p_schema" "text") RETURNS "text"
    LANGUAGE "sql" STABLE
    AS $$
WITH tables AS (
  SELECT n.nspname AS schemaname,
         c.relname AS tablename
  FROM pg_class c
  JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = p_schema
    AND c.relkind IN ('r', 'p')  -- regular and partitioned tables
)
SELECT string_agg(
         'ALTER TABLE ' || quote_ident(schemaname) || '.' || quote_ident(tablename) ||
         ' ENABLE ROW LEVEL SECURITY;', E'\n'
       ) AS ddl_all
FROM tables;
$$;


ALTER FUNCTION "public"."generate_schema_rls_enable_ddl"("p_schema" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_schema_triggers_ddl"("p_schema" "text") RETURNS "text"
    LANGUAGE "sql" STABLE
    AS $$
WITH aggregated_triggers AS (
  SELECT
    trigger_schema,
    trigger_name,
    event_object_schema,
    event_object_table,
    action_timing,
    action_orientation,
    string_agg(event_manipulation, ' or ') AS events,
    max(action_condition) AS action_condition,
    max(action_statement) AS action_statement
  FROM information_schema.triggers
  WHERE trigger_schema = p_schema
  GROUP BY trigger_schema, trigger_name, event_object_schema, event_object_table, action_timing, action_orientation
),
formatted_triggers AS (
  SELECT
    -- Drop statement
    'DROP TRIGGER IF EXISTS ' || quote_ident(trigger_name) || ' ON '
    || CASE
         WHEN event_object_schema = p_schema
           THEN quote_ident(event_object_table)
         ELSE quote_ident(event_object_schema) || '.' || quote_ident(event_object_table)
       END || ';' || E'\n'
    ||
    -- Create statement
    'CREATE TRIGGER ' || quote_ident(trigger_name) || E'\n'
    || upper(action_timing) || ' ' || lower(events) || ' ON '
    || CASE
         WHEN event_object_schema = p_schema
           THEN quote_ident(event_object_table)
         ELSE quote_ident(event_object_schema) || '.' || quote_ident(event_object_table)
       END
    || E'\nFOR EACH ' || lower(action_orientation) || E'\n'
    || CASE
         WHEN action_condition IS NOT NULL
           THEN 'WHEN (' || action_condition || ')' || E'\n'
         ELSE ''
       END
    || 'EXECUTE ' || action_statement || ';'
    AS trigger_ddl
  FROM aggregated_triggers
)
SELECT string_agg(trigger_ddl, E'\n\n') AS ddl_all
FROM formatted_triggers;
$$;


ALTER FUNCTION "public"."generate_schema_triggers_ddl"("p_schema" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_ticket_symbol"("organization_id" bigint, "occasion_id" bigint) RETURNS "text"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    visible_id TEXT;
    org_suffix TEXT;
    occasion_suffix TEXT;
    numeric_part TEXT := '123456789';
    alphabetic_part TEXT := 'ACEFGHIJKLMNPQRUVWXY';
    attempt_count INT := 0;
BEGIN
    -- Extract last two digits of organization_id and occasion_id
    org_suffix := LPAD((organization_id % 100)::TEXT, 2, '0');  -- Ensure 2 digits
    occasion_suffix := LPAD((occasion_id % 100)::TEXT, 2, '0'); -- Ensure 2 digits

    -- Replace '0' with 'X' in the suffixes
    org_suffix := REPLACE(org_suffix, '0', 'X');
    occasion_suffix := REPLACE(occasion_suffix, '0', 'X');

    LOOP
        -- Generate alternating numeric and alphabetic parts
        visible_id := org_suffix || occasion_suffix ||
                      SUBSTRING(numeric_part FROM FLOOR(RANDOM() * 9 + 1)::INT FOR 1) ||
                      SUBSTRING(alphabetic_part FROM FLOOR(RANDOM() * 20 + 1)::INT FOR 1) ||
                      SUBSTRING(numeric_part FROM FLOOR(RANDOM() * 9 + 1)::INT FOR 1) ||
                      SUBSTRING(alphabetic_part FROM FLOOR(RANDOM() * 20 + 1)::INT FOR 1) ||
                      SUBSTRING(numeric_part FROM FLOOR(RANDOM() * 9 + 1)::INT FOR 1) ||
                      SUBSTRING(alphabetic_part FROM FLOOR(RANDOM() * 20 + 1)::INT FOR 1);

        -- Ensure uniqueness in the database (within the occasion)
        IF NOT EXISTS (
            SELECT 1
            FROM eshop.tickets
            WHERE ticket_symbol = visible_id AND occasion = occasion_id
        ) THEN
            RETURN visible_id; -- Return the unique visible ID
        END IF;

        -- Increment attempt count and fail after a fixed number of attempts
        attempt_count := attempt_count + 1;
        IF attempt_count > 10 THEN
            RAISE EXCEPTION 'Failed to generate unique visible ID after 10 attempts';
        END IF;
    END LOOP;
END;
$$;


ALTER FUNCTION "public"."generate_ticket_symbol"("organization_id" bigint, "occasion_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_variable_symbol"("bank_account_id" bigint) RETURNS bigint
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    v_symbol BIGINT;
    digit_count INT := 4; -- Start with 4 digits
    attempt_count INT := 0;
    max_attempts INT := 1; -- Maximum allowed attempts per digit count
BEGIN
    LOOP
        -- Generate a random number with the current digit count
        v_symbol := FLOOR(RANDOM() * (POWER(10, digit_count) - POWER(10, digit_count - 1))) + POWER(10, digit_count - 1);

        -- Ensure uniqueness within the bank_account
        IF NOT EXISTS (
            SELECT 1
            FROM eshop.payment_info
            WHERE variable_symbol = v_symbol AND bank_account = bank_account_id
        ) THEN
            RETURN v_symbol; -- Return the unique variable symbol
        END IF;

        -- Increment attempt count and adjust digit count after each failure
        attempt_count := attempt_count + 1;

        -- Extend digit count after reaching max attempts
        IF attempt_count >= max_attempts THEN
            digit_count := digit_count + 1;
            attempt_count := 0; -- Reset attempt count for the extended digit count
        END IF;

        -- Fail entirely if the system cannot generate a unique symbol after too many attempts
        IF digit_count > 10 THEN -- Arbitrary upper limit for digit count
            RAISE EXCEPTION 'Failed to generate unique variable symbol after too many attempts.';
        END IF;
    END LOOP;
END;
$$;


ALTER FUNCTION "public"."generate_variable_symbol"("bank_account_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_account_deletion_storage_batch"("p_request_id" "uuid", "p_limit" integer DEFAULT 100) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE v_user uuid; v_result jsonb;
BEGIN
  PERFORM public.require_service_role();
  IF p_limit < 1 OR p_limit > 1000 THEN
    RAISE EXCEPTION 'account_deletion_invalid_storage_batch_limit' USING ERRCODE = '22023';
  END IF;
  SELECT user_id INTO v_user
  FROM public.account_deletion_requests
  WHERE id=p_request_id AND status IN ('deletion_pending','failed');
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'account_deletion_request_state_conflict' USING ERRCODE = '55000';
  END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'bucketId', item.bucket_id, 'name', item.name
  ) ORDER BY item.bucket_id,item.name),'[]'::jsonb)
  INTO v_result
  FROM (
    SELECT bucket_id,name FROM storage.objects
    WHERE owner_id=v_user::text
    ORDER BY bucket_id,name LIMIT p_limit
  ) item;
  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_account_deletion_storage_batch"("p_request_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_activities_for_edit"("p_occasion" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    eventsData              JSONB;
    placesData              JSONB;
    activitiesData          JSONB;
    assignmentPlaceLinksData JSONB;
    assignmentEventLinksData JSONB;
    aaData                  JSONB;
    usersData               JSONB;
BEGIN

   -- Authorization check
    IF (SELECT get_is_editor_view_on_occasion(p_occasion)) <> TRUE THEN
        RETURN jsonb_build_object('code', 403, 'message', 'User is not authorized to view this occasion''s edit data');
    END IF;

    -- (a) all events
    SELECT jsonb_agg(jsonb_build_object(
        'id', e.id, 'created_at', e.created_at, 'title', e.title, 'start_time', e.start_time,
        'end_time', e.end_time, 'max_participants', e.max_participants, 'description', e.description,
        'place', e.place, 'split_for_men_women', e.split_for_men_women, 'is_group_event', e.is_group_event,
        'updated_at', e.updated_at, 'is_hidden', e.is_hidden, 'occasion', e.occasion, 'type', e.type, 'data', e.data
    )) INTO eventsData
    FROM public.events e WHERE e.occasion = p_occasion;

    -- (b) all places for this occasion, sorted by places.order
    -- The jsonb_agg function will respect the order of the rows it aggregates.
    SELECT jsonb_agg(place_obj ORDER BY place_order ASC)
    INTO placesData
    FROM (
        SELECT jsonb_build_object(
            'id', p.id, 'title', p.title, 'description', p.description, 'type', p.type, 'created_at', p.created_at,
            'coordinates', p.coordinates, 'is_hidden', p.is_hidden, 'updated_at', p.updated_at, 'occasion', p.occasion,
            'order', p."order"
        ) AS place_obj,
        p."order" AS place_order
        FROM public.places p
        WHERE p.occasion = p_occasion
    ) AS ordered_places;


    -- (c) all activities
    SELECT jsonb_agg(jsonb_build_object(
        'id', a.id, 'created_at', a.created_at, 'updated_at', a.updated_at, 'title', a.title,
        'description', a.description, 'type', a.type, 'occasion', a.occasion, 'unit', a.unit,
        'is_hidden', a.is_hidden, 'order', a."order", 'data', a.data
    )) INTO activitiesData
    FROM public.activities a WHERE a.occasion = p_occasion;

    -- (d) activity_assignment_places links (now assignment_id <-> place_id)
    SELECT jsonb_agg(jsonb_build_object(
        'assignment_id', apl.assignment_id,
        'place_id',      apl.place_id
    )) INTO assignmentPlaceLinksData
    FROM public.activity_assignment_places apl
    JOIN public.activity_assignments aa ON apl.assignment_id = aa.id
    JOIN public.activities a ON aa.activity_id = a.id
    WHERE a.occasion = p_occasion;

    -- (e) activity_assignment_events links (now assignment_id <-> event_id)
    SELECT jsonb_agg(jsonb_build_object(
        'assignment_id', ael.assignment_id,
        'event_id',      ael.event_id
    )) INTO assignmentEventLinksData
    FROM public.activity_assignment_events ael
    JOIN public.activity_assignments aa ON ael.assignment_id = aa.id
    JOIN public.activities a ON aa.activity_id = a.id
    WHERE a.occasion = p_occasion;

    -- (f) activity_assignments
    SELECT jsonb_agg(jsonb_build_object(
        'id', aa.id, 'activity_id', aa.activity_id, 'user', aa."user", 'start_time', aa.start_time,
        'end_time', aa.end_time, 'title', aa.title, 'description', aa.description, 'data', aa.data
    )) INTO aaData
    FROM public.activity_assignments aa
    JOIN public.activities a ON aa.activity_id = a.id
    WHERE a.occasion = p_occasion;

    -- (g) users for this occasion who are volunteers
    SELECT jsonb_agg(jsonb_build_object(
        'id', ui.id, 'name', ui.name, 'surname', ui.surname, 'sex', ui.sex, 'email', ui.email_readonly
    )) INTO usersData
    FROM public.user_info ui
    JOIN public.occasion_users ou ON ui.id = ou."user"
    WHERE ou.occasion = p_occasion AND (ou.data->>'is_volunteer')::boolean = TRUE;

    -- (h) assemble
    RETURN jsonb_build_object(
      'code', 200,
      'message', 'Data for editing activities retrieved successfully.',
      'data', jsonb_build_object(
        'events',                  COALESCE(eventsData, '[]'::jsonb),
        'places',                  COALESCE(placesData, '[]'::jsonb),
        'activities',              COALESCE(activitiesData, '[]'::jsonb),
        'assignment_place_links',  COALESCE(assignmentPlaceLinksData, '[]'::jsonb),
        'assignment_event_links',  COALESCE(assignmentEventLinksData, '[]'::jsonb),
        'activity_assignments',    COALESCE(aaData, '[]'::jsonb),
        'user_info',               COALESCE(usersData, '[]'::jsonb)
      )
    );
END;
$$;


ALTER FUNCTION "public"."get_activities_for_edit"("p_occasion" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_activity_history_version"("p_history_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    AS $$
DECLARE
    v_occasion_id BIGINT;
    history_data JSONB;
BEGIN
    SELECT occasion_id INTO v_occasion_id FROM public.activity_history WHERE id = p_history_id;

    IF v_occasion_id IS NULL OR (SELECT get_is_editor_on_occasion(v_occasion_id)) <> TRUE THEN
        RETURN jsonb_build_object('code', 403, 'message', 'User is not authorized to view this history version');
    END IF;

    -- Select the single history record into a JSON object
    SELECT jsonb_build_object(
        'id', id,
        'created_at', created_at,
        'activities_data', activities_data,
        'parent_history_id', parent_history_id
    )
    INTO history_data
    FROM public.activity_history
    WHERE id = p_history_id;

    -- Return the object wrapped in a standard response
    RETURN jsonb_build_object(
        'code', 200,
        'message', 'History version retrieved.',
        'data', history_data
    );
END;
$$;


ALTER FUNCTION "public"."get_activity_history_version"("p_history_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_all_email_templates"("p_context" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  email_data jsonb;
  v_occ  bigint;
  v_unit bigint;
  v_org  bigint;

  v_effective_org bigint;
  is_app_supported boolean := false;
BEGIN
  -- 1. Extract context values from the JSON parameter
  v_occ  := CASE
              WHEN p_context ? 'occasion' AND (p_context->>'occasion') IS NOT NULL
              THEN (p_context->>'occasion')::bigint
              ELSE NULL
            END;
  v_unit := CASE
              WHEN p_context ? 'unit' AND (p_context->>'unit') IS NOT NULL
              THEN (p_context->>'unit')::bigint
              ELSE NULL
            END;
  v_org  := CASE
              WHEN p_context ? 'organization' AND (p_context->>'organization') IS NOT NULL
              THEN (p_context->>'organization')::bigint
              ELSE NULL
            END;

  -- 2. Determine the effective Organization ID to check settings
  -- Priority: Explicit Org -> Org from Occasion -> Org from Unit
  IF v_org IS NOT NULL THEN
    v_effective_org := v_org;
  ELSIF v_occ IS NOT NULL THEN
    SELECT organization INTO v_effective_org FROM public.occasions WHERE id = v_occ;
  ELSIF v_unit IS NOT NULL THEN
    SELECT organization INTO v_effective_org FROM public.units WHERE id = v_unit;
  END IF;

  -- 3. Check if App is Supported for the effective organization
  IF v_effective_org IS NOT NULL THEN
    SELECT COALESCE((data->>'IS_APP_SUPPORTED')::BOOLEAN, false)
    INTO is_app_supported
    FROM public.organizations
    WHERE id = v_effective_org;
  END IF;

  -- 4. If an occasion is provided, perform the permission check.
  IF v_occ IS NOT NULL THEN
    IF (SELECT get_is_editor_view_on_occasion(v_occ)) <> TRUE AND (SELECT get_is_editor_order_view_on_occasion(v_occ)) <> TRUE THEN
       RAISE EXCEPTION 'User is not editor view.';
    END IF;
  END IF;

  -- 5. Retrieve email templates
  SELECT jsonb_agg(result)
    INTO email_data
  FROM (
    SELECT DISTINCT ON (et.code)
           et.id,
           et.html,
           et.occasion,
           et.subject,
           et.organization,
           et.code,
           et.unit
    FROM public.email_templates et
    WHERE
      -- A. Filter based on context (Scope)
      (
           (v_occ IS NOT NULL AND et.occasion = v_occ)
        OR (v_unit IS NOT NULL AND et.unit = v_unit AND et.occasion IS NULL)
        OR (v_org IS NOT NULL  AND et.organization = v_org AND et.unit IS NULL AND et.occasion IS NULL)
        OR (et.organization IS NULL AND et.unit IS NULL AND et.occasion IS NULL)
      )
      -- B. Filter based on App Support (New Logic)
      AND (
        is_app_supported IS TRUE
        OR
        et.code NOT IN ('SIGN_IN_CODE', 'RESET_PASSWORD')
      )
    ORDER BY et.code,
             CASE
               WHEN (v_occ IS NOT NULL AND et.occasion = v_occ) THEN 1
               WHEN (v_unit IS NOT NULL AND et.unit = v_unit AND et.occasion IS NULL) THEN 2
               WHEN (v_org IS NOT NULL  AND et.organization = v_org AND et.unit IS NULL AND et.occasion IS NULL) THEN 3
               WHEN (et.organization IS NULL AND et.unit IS NULL AND et.occasion IS NULL) THEN 4
               ELSE 5
             END,
             et.id
  ) result;

  IF email_data IS NULL THEN
    email_data := '[]'::jsonb;
  END IF;

  RETURN email_data;
END;
$$;


ALTER FUNCTION "public"."get_all_email_templates"("p_context" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_all_email_templates_via_form_link"("form_link" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    occasion_id   bigint;
    v_unit        bigint;
    v_org         bigint;
    email_data    jsonb;
    context       jsonb;
    occasion_data jsonb;
    unit_data     jsonb;
    org_data      jsonb;
    final_result  jsonb;
BEGIN
    -- Retrieve the occasion ID from the forms table using the provided form link.
    SELECT f.occasion
      INTO occasion_id
      FROM public.forms f
      WHERE f.link = form_link;

    IF occasion_id IS NULL THEN
        RAISE EXCEPTION 'Form not found or no associated occasion.';
    END IF;

    -- Retrieve unit and organization IDs from the occasion.
    SELECT o.unit, o.organization
      INTO v_unit, v_org
      FROM public.occasions o
      WHERE o.id = occasion_id;

    -- Build a JSON context with the occasion, unit, and organization.
    context := jsonb_build_object(
                  'occasion', occasion_id,
                  'unit', v_unit,
                  'organization', v_org
               );

    -- Call the updated function with the context parameter to retrieve templates.
    email_data := public.get_all_email_templates(context);

    -- Retrieve occasion details (id and title).
    SELECT jsonb_build_object('id', o.id, 'title', o.title)
      INTO occasion_data
      FROM public.occasions o
      WHERE o.id = occasion_id;

    -- Retrieve unit details (id and title).
    SELECT jsonb_build_object('id', u.id, 'title', u.title)
      INTO unit_data
      FROM public.units u
      WHERE u.id = v_unit;

    -- Retrieve organization details (id and title).
    SELECT jsonb_build_object('id', org.id, 'title', org.title)
      INTO org_data
      FROM public.organizations org
      WHERE org.id = v_org;

    -- Build final result JSON object containing the separate objects.
    final_result := jsonb_build_object(
                      'occasion',     occasion_data,
                      'unit',         unit_data,
                      'organization', org_data,
                      'templates',    email_data
                    );

    RETURN final_result;
END;
$$;


ALTER FUNCTION "public"."get_all_email_templates_via_form_link"("form_link" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_all_email_templates_via_occasion_link"("occasion_link" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_occasion_id bigint;
BEGIN
    -- Retrieve the occasion ID
    SELECT id INTO v_occasion_id
    FROM public.occasions
    WHERE link = occasion_link;

    IF v_occasion_id IS NULL THEN
        RAISE EXCEPTION 'Occasion not found for link: %', occasion_link;
    END IF;

    -- Call Unified Function
    RETURN public.get_entity_email_templates('occasion', v_occasion_id);
END;
$$;


