CREATE OR REPLACE FUNCTION "public"."get_all_events_for_datagrid"("p_occasion_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
    result_jsonb jsonb;
BEGIN
    IF NOT public.get_is_editor_view_on_occasion(p_occasion_id) THEN
        RAISE EXCEPTION
            'Insufficient permissions. User requires editor view rights for this occasion.'
            USING ERRCODE = '42501';
    END IF;

    SELECT COALESCE(jsonb_agg(event_row.data), '[]'::jsonb)
    INTO result_jsonb
    FROM (
        SELECT jsonb_build_object(
            'id', e.id,
            'aggregate_version', COALESCE(av.version, 0),
            'is_hidden', e.is_hidden,
            'title', e.title,
            'start_time', e.start_time,
            'end_time', e.end_time,
            'max_participants', e.max_participants,
            'split_for_men_women', e.split_for_men_women,
            'is_group_event', e.is_group_event,
            'type', e.type,
            'data', e.data,
            'places', CASE
                WHEN p.id IS NULL THEN NULL::jsonb
                ELSE jsonb_build_object('id', p.id, 'title', p.title)
            END,
            'event_groups', (
                SELECT COALESCE(
                    jsonb_agg(jsonb_build_object('event_parent', eg.event_parent)),
                    '[]'::jsonb
                )
                FROM public.event_groups eg
                WHERE eg.event_child = e.id
            ),
            'event_roles', (
                SELECT COALESCE(
                    jsonb_agg(jsonb_build_object('role', er.role)),
                    '[]'::jsonb
                )
                FROM public.event_roles er
                WHERE er.event = e.id
            ),
            'event_users_saved', (
                SELECT jsonb_agg(jsonb_build_object('count', totals.count))
                FROM (
                    SELECT count(*) AS count
                    FROM public.event_users_saved eus
                    WHERE eus.event = e.id
                ) totals
            ),
            'event_users', (
                SELECT jsonb_agg(jsonb_build_object('count', totals.count))
                FROM (
                    SELECT count(*) AS count
                    FROM public.event_users eu
                    WHERE eu.event = e.id
                ) totals
            )
        ) AS data
        FROM public.events e
        LEFT JOIN public.places p ON p.id = e.place
        LEFT JOIN public.client_aggregate_versions av
          ON av.aggregate_type = 'event'
         AND av.scope_type = 'occasion'
         AND av.scope_id = p_occasion_id
         AND av.aggregate_id = e.id::text
        WHERE e.occasion = p_occasion_id
        ORDER BY e.start_time ASC
    ) AS event_row;

    RETURN result_jsonb;
END;
$$;


ALTER FUNCTION "public"."get_all_events_for_datagrid"("p_occasion_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_all_form_fields"("form_link" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_form_id BIGINT;
    v_occasion_id BIGINT;
    formFieldsData JSONB;
BEGIN
    -- Retrieve form ID and occasion ID
    SELECT id, occasion INTO v_form_id, v_occasion_id
    FROM public.forms
    WHERE link = form_link;

    -- Check if form exists
    IF v_form_id IS NULL THEN
        RAISE EXCEPTION 'Form not found.';
    END IF;

    -- Check permissions
    IF NOT public.get_is_editor_order_view_on_occasion(v_occasion_id) THEN
        RAISE EXCEPTION 'Access Denied';
    END IF;

    -- Fetch form fields
    SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
            'id', ff.id,
            'created_at', ff.created_at,
            'title', ff.title,
            'description', ff.description,
            'data', ff.data,
            'type', ff.type,
            'is_required', ff.is_required,
            'form', ff.form,
            'is_hidden', ff.is_hidden,
            'order', ff."order",
            'product_type', ff.product_type,
            'is_ticket_field', ff.is_ticket_field
        ) ORDER BY COALESCE(ff."order", 0)
    ), '[]'::jsonb)
    INTO formFieldsData
    FROM public.form_fields ff
    WHERE ff.form = v_form_id
      AND ff.is_ticket_field = false
      AND ff.type <> 'ticket';

    RETURN formFieldsData;
END;
$$;


ALTER FUNCTION "public"."get_all_form_fields"("form_link" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_all_forms"("occasion_link" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_occasion_id BIGINT;
    forms_data JSONB;
BEGIN
    -- Step 1: Resolve the occasion ID from the provided link.
    SELECT id
    INTO v_occasion_id
    FROM public.occasions
    WHERE link = occasion_link;

    -- Step 2: If no occasion is found, return a 404 error.
    IF v_occasion_id IS NULL THEN
        RETURN jsonb_build_object(
            'code', 404,
            'message', 'Occasion not found'
        );
    END IF;

    -- Step 3: Verify if the user has editor rights for this occasion.
    -- This assumes a function `get_is_editor_on_occasion` exists.
    IF NOT get_is_editor_view_on_occasion(v_occasion_id) THEN
        RETURN jsonb_build_object(
            'code', 403,
            'message', 'User is not authorized to view forms for this occasion.'
        );
    END IF;

    -- Step 4: Aggregate forms for the occasion into a JSONB array.
    -- The subquery for 'response_count' is now corrected to count responses from the 'eshop.orders' table.
    SELECT jsonb_agg(
        jsonb_build_object(
            'id', f.id,
            'created_at', f.created_at,
            'title', f.title,
            'data', f.data,
            'key', f.key,
            'occasion', f.occasion,
            'type', f.type,
            'is_open', f.is_open,
            'link', f.link,
            'blueprint', f.blueprint,
            'updated_at', f.updated_at,
            'response_count', (
                SELECT COUNT(*)
                FROM eshop.orders o
                WHERE (o.data->>'form')::uuid = f.key -- Correctly join forms.key with the UUID in orders.data
            )
        ) ORDER BY f.created_at
    )
    INTO forms_data
    FROM public.forms f
    WHERE f.occasion = v_occasion_id;

    -- Step 5: If no forms were found, return an empty array.
    IF forms_data IS NULL THEN
        forms_data := '[]'::jsonb;
    END IF;

    -- Step 6: Return the aggregated JSON response with a 200 code.
    RETURN jsonb_build_object(
        'code', 200,
        'data', forms_data
    );
END;
$$;


ALTER FUNCTION "public"."get_all_forms"("occasion_link" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_all_forms_with_fields"("occasion_link" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_occasion_id BIGINT;
    forms_data JSONB;
BEGIN
    -- Step 1: Resolve the occasion ID from the provided link.
    -- Find the ID of the occasion using its unique link.
    SELECT id
    INTO v_occasion_id
    FROM public.occasions
    WHERE link = occasion_link;

    -- Step 2: If no occasion is found, return a 404 'Not Found' error.
    -- This handles cases where the occasion_link does not exist.
    IF v_occasion_id IS NULL THEN
        RETURN jsonb_build_object(
            'code', 404,
            'message', 'Occasion not found'
        );
    END IF;

    -- Step 3: Verify if the user has editor rights for this occasion.
    -- This assumes a function `get_is_editor_view_on_occasion` exists to check permissions.
    IF NOT get_is_editor_view_on_occasion(v_occasion_id) THEN
        RETURN jsonb_build_object(
            'code', 403,
            'message', 'User is not authorized to view forms for this occasion.'
        );
    END IF;

    -- Step 4: Aggregate forms and their associated fields for the occasion into a JSONB array.
    -- For each form, a subquery aggregates its related form_fields.
    SELECT jsonb_agg(
        jsonb_build_object(
            'id', f.id,
            'title', f.title,
            'data', f.data,
            'key', f.key,
            'occasion', f.occasion,
            'type', f.type,
            'is_open', f.is_open,
            'link', f.link,
            'blueprint', f.blueprint,
            'response_count', (
                -- Subquery to count the number of responses (orders) for each form.
                SELECT COUNT(*)
                FROM eshop.orders o
                WHERE (o.data->>'form')::uuid = f.key
            ),
            'fields', (
                -- Subquery to aggregate all form_fields associated with the current form.
                SELECT jsonb_agg(
                    jsonb_build_object(
                        'id', ff.id,
                        'type', ff.type,
                        'is_ticket_field', ff.is_ticket_field
                    ) ORDER BY COALESCE(ff."order", 0)
                )
                FROM public.form_fields ff
                WHERE ff.form = f.id
            )
        ) ORDER BY f.created_at
    )
    INTO forms_data
    FROM public.forms f
    WHERE f.occasion = v_occasion_id;

    -- Step 5: If no forms were found for the occasion, return an empty JSON array.
    IF forms_data IS NULL THEN
        forms_data := '[]'::jsonb;
    END IF;

    -- Step 6: Return the aggregated JSON response with a 200 'OK' status code.
    RETURN jsonb_build_object(
        'code', 200,
        'data', forms_data
    );
END;
$$;


ALTER FUNCTION "public"."get_all_forms_with_fields"("occasion_link" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_all_occasions"("unit_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  occasion_data jsonb;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.units WHERE id = unit_id) THEN
    RETURN jsonb_build_object(
      'code', 404,
      'message', 'Unit not found'
    );
  END IF;

  SELECT jsonb_agg(
    jsonb_build_object(
      'id', o.id,
      'title', o.title,
      'created_at', o.created_at,
      'updated_at', o.updated_at,
      'data', o.data,
      'description', o.description,
      'is_hidden', o.is_hidden,
      'is_open', o.is_open,
      'start_time', o.start_time,
      'end_time', o.end_time,
      'link', o.link,
      'organization', o.organization,
      'services', o.services,
      'unit', o.unit,
      'features', o.features,
      'form', (
         SELECT row_to_json(f)
         FROM public.forms f
         WHERE f.occasion = o.id
         ORDER BY f.id
         LIMIT 1
      )
    )
  )
  INTO occasion_data
  FROM public.occasions o
  WHERE o.unit = unit_id
    AND o.is_hidden = false;

  IF occasion_data IS NULL THEN
    occasion_data := '[]'::jsonb;
  END IF;

  RETURN jsonb_build_object(
    'code', 200,
    'data', occasion_data
  );
END;
$$;


ALTER FUNCTION "public"."get_all_occasions"("unit_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_all_occasions_for_edit"("unit_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  occasion_data jsonb;
BEGIN
  -- Step 1: Verify that the unit exists
  IF NOT EXISTS (SELECT 1 FROM public.units WHERE id = unit_id) THEN
    RETURN jsonb_build_object(
      'code', 404,
      'message', 'Unit not found'
    );
  END IF;

  -- Step 2: Check if the caller is a manager or editor of the unit
  IF NOT EXISTS (
      SELECT 1 FROM public.unit_users
      WHERE "user" = auth.uid()
        AND unit = unit_id
        AND (is_manager = true OR is_editor = true OR is_editor_view = true)
  ) THEN
    RETURN jsonb_build_object('code', 403);
  END IF;

  -- Step 3: Aggregate occasions for the unit including the first form for each occasion.
  SELECT jsonb_agg(
    jsonb_build_object(
      'id', o.id,
      'title', o.title,
      'created_at', o.created_at,
      'updated_at', o.updated_at,
      'data', o.data,
      'description', o.description,
      'is_hidden', o.is_hidden,
      'is_open', o.is_open,
      'start_time', o.start_time,
      'end_time', o.end_time,
      'link', o.link,
      'organization', o.organization,
      'services', o.services,
      'unit', o.unit,
      'features', o.features,
      'form', (
         SELECT jsonb_build_object(
           'id', f.id,
           'created_at', f.created_at,
           'data', f.data,
           'key', f.key,
           'occasion', f.occasion,
           'type', f.type,
           'is_open', f.is_open,
           'link', f.link,
           'blueprint', f.blueprint,
           'header', f.header,
           'header_off', f.header_off,
           'updated_at', f.updated_at
         )
         FROM public.forms f
         WHERE f.occasion = o.id
         ORDER BY f.id
         LIMIT 1
      )
    )
    ORDER BY o.start_time DESC
  )
  INTO occasion_data
  FROM public.occasions o
  WHERE o.unit = unit_id;

  -- Step 4: If no occasions were found, return an empty array.
  IF occasion_data IS NULL THEN
    occasion_data := '[]'::jsonb;
  END IF;

  -- Step 5: Return the aggregated JSON response with a 200 code.
  RETURN jsonb_build_object(
    'code', 200,
    'data', occasion_data
  );
END;
$$;


ALTER FUNCTION "public"."get_all_occasions_for_edit"("unit_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_all_occasions_for_edit_v182"("unit_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  occasion_data jsonb;
BEGIN
  -- Step 1: Verify that the unit exists. If not, raise a 'not found' exception.
  IF NOT EXISTS (SELECT 1 FROM public.units WHERE id = unit_id) THEN
    RAISE EXCEPTION 'Unit not found' USING ERRCODE = 'PGRST001';
  END IF;

  -- Step 2: Check if the caller has sufficient permissions. If not, raise an 'insufficient privilege' exception.
  IF NOT EXISTS (
      SELECT 1 FROM public.unit_users
      WHERE "user" = auth.uid()
        AND unit = unit_id
        AND (is_manager = true OR is_editor = true OR is_editor_view = true)
  ) THEN
    RAISE EXCEPTION 'Insufficient permissions for this unit' USING ERRCODE = '42501';
  END IF;

  -- Step 3: Aggregate occasions for the unit, including forms, order stats, and user data.
  SELECT jsonb_agg(
    jsonb_build_object(
      'id', o.id,
      'title', o.title,
      'created_at', o.created_at,
      'updated_at', o.updated_at,
      'data', o.data,
      'is_hidden', o.is_hidden,
      'is_open', o.is_open,
      'start_time', o.start_time,
      'end_time', o.end_time,
      'link', o.link,
      'organization', o.organization,
      'services', o.services,
      'unit', o.unit,
      'features', o.features,
      'stats', jsonb_build_object(
          'total', COALESCE(order_stats.total, 0),
          'storno', COALESCE(order_stats.storno, 0),
          'paid_or_sent', COALESCE(order_stats.paid_or_sent, 0),
          'ordered', COALESCE(order_stats.ordered, 0),
          'used', COALESCE(order_stats.used, 0),
          'users', COALESCE(user_stats.user_count, 0)
      ),
      'form', (
         -- This subquery fetches the first associated form for the occasion.
         SELECT jsonb_build_object(
           'id', f.id,
           'created_at', f.created_at,
           'data', f.data,
           'key', f.key,
           'occasion', f.occasion,
           'type', f.type,
           'is_open', f.is_open,
           'link', f.link,
           'blueprint', f.blueprint,
           'header', f.header,
           'header_off', f.header_off,
           'updated_at', f.updated_at
         )
         FROM public.forms f
         WHERE f.occasion = o.id
         ORDER BY f.id
         LIMIT 1
      )
    )
    ORDER BY o.start_time DESC
  )
  INTO occasion_data
  FROM public.occasions o
  LEFT JOIN (
      -- This subquery calculates all required order counts in a single pass over the orders table.
      SELECT
          occasion,
          COUNT(*) AS total,
          COUNT(*) FILTER (WHERE state = 'storno') AS storno,
          COUNT(*) FILTER (WHERE state IN ('paid', 'sent')) AS paid_or_sent,
          COUNT(*) FILTER (WHERE state = 'ordered') AS ordered,
          COUNT(*) FILTER (WHERE state = 'used') AS used
      FROM eshop.orders
      WHERE occasion IS NOT NULL
      GROUP BY occasion
  ) AS order_stats ON o.id = order_stats.occasion
  LEFT JOIN (
      -- New: This subquery aggregates occasion users and provides their count.
      SELECT
          occasion,
          COUNT(*) as user_count
      FROM public.occasion_users
      GROUP BY occasion
  ) AS user_stats ON o.id = user_stats.occasion
  WHERE o.unit = unit_id;

  -- Step 4: If no occasions were found, return an empty JSON array.
  IF occasion_data IS NULL THEN
    occasion_data := '[]'::jsonb;
  END IF;

  -- Step 5: Return the aggregated JSON data directly.
  RETURN occasion_data;
END;
$$;


ALTER FUNCTION "public"."get_all_occasions_for_edit_v182"("unit_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_all_occasions_for_edit_v212"("unit_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  occasion_data jsonb;
  org_id bigint;
BEGIN
  -- Step 1: Verify that the unit exists and retrieve its Organization ID.
  SELECT organization INTO org_id
  FROM public.units
  WHERE id = unit_id;

  -- If org_id is null, the unit does not exist.
  IF org_id IS NULL THEN
    RAISE EXCEPTION 'Unit not found' USING ERRCODE = 'PGRST001';
  END IF;

  -- Step 2: Check permissions
  IF NOT EXISTS (
      SELECT 1 FROM public.unit_users
      WHERE "user" = auth.uid()
        AND unit = unit_id
        AND (is_manager = true OR is_editor = true OR is_editor_view = true)
  ) AND NOT EXISTS (
      SELECT 1 FROM public.occasion_users ou
      JOIN public.occasions o ON o.id = ou.occasion
      WHERE o.unit = unit_id
        AND ou."user" = auth.uid()
        AND (ou.is_manager IS TRUE OR ou.is_editor IS TRUE OR ou.is_editor_view IS TRUE OR ou.is_editor_order IS TRUE OR ou.is_editor_order_view IS TRUE)
  ) THEN
    RAISE EXCEPTION 'Insufficient permissions for this unit' USING ERRCODE = '42501';
  END IF;

  -- Step 3: Aggregate occasions
  SELECT jsonb_agg(
    jsonb_build_object(
      'id', o.id,
      'title', o.title,
      'created_at', o.created_at,
      'updated_at', o.updated_at,
      'data', o.data #- '{heavy_field}', -- OPTIMIZATION: Remove heavy_field
      'is_hidden', o.is_hidden,
      'is_open', o.is_open,
      'start_time', o.start_time,
      'end_time', o.end_time,
      'link', o.link,
      'organization', o.organization,
      'services', o.services,
      'unit', o.unit,
      'features', (
          SELECT jsonb_agg(
              elem #- '{heavy_config}' -- OPTIMIZATION: Remove heavy_config from features
          )
          FROM jsonb_array_elements(o.features) elem
      ),
      'stats', jsonb_build_object(
          'total', COALESCE(ticket_stats.total, 0),
          'storno', COALESCE(ticket_stats.storno, 0),
          'paid_or_sent', COALESCE(ticket_stats.paid_or_sent, 0),
          'ordered', COALESCE(ticket_stats.ordered, 0),
          'used', COALESCE(ticket_stats.used, 0),
          'users', COALESCE(user_stats.user_count, 0)
      ),
      'form', (
         -- This subquery fetches the first associated form for the occasion.
         SELECT jsonb_build_object(
           'id', f.id,
           'created_at', f.created_at,
           'data', f.data,
           'key', f.key,
           'occasion', f.occasion,
           'type', f.type,
           'is_open', f.is_open,
           'link', f.link,
           'blueprint', NULL, -- OPTIMIZATION: Remove blueprint
           'header', NULL, -- OPTIMIZATION: Remove header
           'header_off', f.header_off,
           'updated_at', f.updated_at
         )
         FROM public.forms f
         WHERE f.occasion = o.id
         ORDER BY f.id
         LIMIT 1
      )
    )
    ORDER BY o.start_time DESC
  )
  INTO occasion_data
  FROM public.occasions o

  -- Ticket Stats
  LEFT JOIN (
      SELECT
          occasion,
          COUNT(*) AS total,
          COUNT(*) FILTER (WHERE state = 'storno') AS storno,
          COUNT(*) FILTER (WHERE state IN ('paid', 'sent')) AS paid_or_sent,
          COUNT(*) FILTER (WHERE state = 'ordered') AS ordered,
          COUNT(*) FILTER (WHERE state = 'used') AS used
      FROM eshop.tickets
      GROUP BY occasion
  ) AS ticket_stats ON o.id = ticket_stats.occasion

  -- User Stats
  LEFT JOIN (
      SELECT
          ou.occasion,
          COUNT(*) as user_count
      FROM public.occasion_users ou
      LEFT JOIN public.organization_users org_u
          ON ou."user" = org_u."user"
          AND org_u.organization = org_id
      WHERE (org_u.is_hidden IS NOT TRUE)
      GROUP BY ou.occasion
  ) AS user_stats ON o.id = user_stats.occasion

  WHERE o.unit = unit_id
  AND (
      EXISTS (
          SELECT 1 FROM public.unit_users
          WHERE "user" = auth.uid()
            AND unit = unit_id
            AND (is_manager = true OR is_editor = true OR is_editor_view = true)
      )
      OR
      EXISTS (
          SELECT 1 FROM public.occasion_users ou
          WHERE ou.occasion = o.id
            AND ou."user" = auth.uid()
            AND (ou.is_manager IS TRUE OR ou.is_editor IS TRUE OR ou.is_editor_view IS TRUE OR ou.is_editor_order IS TRUE OR ou.is_editor_order_view IS TRUE)
      )
  );

  IF occasion_data IS NULL THEN
    occasion_data := '[]'::jsonb;
  END IF;

  RETURN occasion_data;
END;
$$;


