CREATE OR REPLACE FUNCTION "public"."get_all_tickets_for_scan"("scan_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    occasion_id_val bigint;
    result jsonb;
BEGIN
    SELECT o.id
    INTO occasion_id_val
    FROM public.occasions o
    JOIN public.occasions_hidden oh ON o.occasion_hidden = oh.id
    WHERE oh.secret = scan_code
    LIMIT 1;

    IF occasion_id_val IS NULL THEN
         RAISE EXCEPTION 'Invalid scan code';
    END IF;

    SELECT jsonb_agg(
        jsonb_build_object(
            'id', t.id,
            'ticket_symbol', t.ticket_symbol,
            'state', t.state,
            'related_order', jsonb_build_object(
                 'data', t.data
            )
        )
    )
    INTO result
    FROM (
        SELECT DISTINCT ON (t.id) t.id, t.ticket_symbol, t.state, o.data
        FROM eshop.tickets t
        JOIN eshop.order_product_ticket opt ON t.id = opt.ticket
        JOIN eshop.orders o ON opt."order" = o.id
        WHERE o.occasion = occasion_id_val
          AND t.state != 'storno'
        ORDER BY t.id
    ) t;

    RETURN COALESCE(result, '[]'::jsonb);
END;
$$;


ALTER FUNCTION "public"."get_all_tickets_for_scan"("scan_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_all_user_basics_for_scan"("scan_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  oid bigint;
  org_id bigint;
  user_basics jsonb;
BEGIN
  -----------------------------------------------------
  -- 1. Validate Code & Get Occasion AND Organization ID
  -----------------------------------------------------
  SELECT o.id, o.organization INTO oid, org_id
  FROM public.occasions o
  JOIN public.occasions_hidden oh ON o.occasion_hidden = oh.id
  WHERE oh.secret = scan_code
  LIMIT 1;

  -- Security Check: If ID is null, the code is invalid
  IF oid IS NULL THEN
      RAISE EXCEPTION 'Invalid scan code';
  END IF;

  -----------------------------------------------------
  -- 2. Retrieve User Data for this Occasion
  -----------------------------------------------------
  SELECT jsonb_agg(
    jsonb_build_object(
      'id', ui.id,
      'name', ui.name,
      'surname', ui.surname,
      'sex', ui.sex,
      'email_readonly', ui.email_readonly,
      'companion_parent', (
        SELECT jsonb_build_object(
          'id', parent_ui.id,
          'name', parent_ui.name,
          'surname', parent_ui.surname,
          'sex', parent_ui.sex,
          'email_readonly', parent_ui.email_readonly
        )
        FROM public.user_info parent_ui
        WHERE parent_ui.id = uc."user"
      )
    )
  ) INTO user_basics
  FROM public.user_info ui
  LEFT JOIN public.user_companions uc ON ui.id = uc.companion AND uc.occasion=oid
  JOIN public.occasion_users uo ON ui.id = uo."user"

  -- This keeps the user in the list even if they have no record in organization_users
  LEFT JOIN public.organization_users ou ON ui.id = ou."user" AND ou.organization = org_id

  WHERE uo.occasion = oid

  -- "IS NOT TRUE" covers two cases:
  -- 1. is_hidden is FALSE
  -- 2. is_hidden is NULL (record doesn't exist)
  AND (ou.is_hidden IS NOT TRUE);

  -----------------------------------------------------
  -- 3. Handle Empty Results & Return
  -----------------------------------------------------
  IF user_basics IS NULL THEN
    user_basics := '[]'::jsonb;
  END IF;

  RETURN user_basics;
END;
$$;


ALTER FUNCTION "public"."get_all_user_basics_for_scan"("scan_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_all_user_basics_from_occasion"("oc" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  org_id bigint;
  user_basics jsonb;
BEGIN
  -----------------------------------------------------
  -- 1. Permission Check
  -----------------------------------------------------
  -- Check if the user is a manager, editor, or approver for the occasion
  IF (SELECT get_is_manager_on_occasion(oc) OR get_is_editor_on_occasion(oc) OR get_is_approver_on_occasion(oc)) <> TRUE THEN
      RETURN jsonb_build_object('code', 403);
  END IF;

  -----------------------------------------------------
  -- 2. Get Organization ID
  -----------------------------------------------------
  -- We need the org_id to check the specific organization_users table
  SELECT organization INTO org_id
  FROM public.occasions
  WHERE id = oc;

  -----------------------------------------------------
  -- 3. Aggregate User Data
  -----------------------------------------------------
  SELECT jsonb_agg(
    jsonb_build_object(
      'id', ui.id,
      'name', ui.name,
      'surname', ui.surname,
      'sex', ui.sex,
      'email_readonly', ui.email_readonly,
      'companion_parent', (
        SELECT jsonb_build_object(
          'id', parent_ui.id,
          'name', parent_ui.name,
          'surname', parent_ui.surname,
          'sex', parent_ui.sex,
          'email_readonly', parent_ui.email_readonly
        )
        FROM public.user_info parent_ui
        WHERE parent_ui.id = uc."user"
      )
    )
  ) INTO user_basics
  FROM public.user_info ui
  LEFT JOIN public.user_companions uc ON ui.id = uc.companion AND uc.occasion=oc
  JOIN public.occasion_users uo ON ui.id = uo."user"

  -- LEFT JOIN to check visibility settings
  LEFT JOIN public.organization_users ou ON ui.id = ou."user" AND ou.organization = org_id

  WHERE uo.occasion = oc

  -- FILTER: Exclude only if explicitly hidden
  -- (NULL or FALSE means visible)
  AND (ou.is_hidden IS NOT TRUE);

  -----------------------------------------------------
  -- 4. Handle Empty Results & Return
  -----------------------------------------------------
  -- If no users are found, return an empty array
  IF user_basics IS NULL THEN
    user_basics := '[]'::jsonb;
  END IF;

  RETURN jsonb_build_object(
    'code', 200,
    'data', user_basics
  );
END;
$$;


ALTER FUNCTION "public"."get_all_user_basics_from_occasion"("oc" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_all_user_basics_from_occasion_unit"("p_unit_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  user_basics jsonb;
  org_id bigint;
BEGIN
  -- Step 1: Retrieve the organization for the given unit
  SELECT organization INTO org_id
  FROM public.units
  WHERE id = p_unit_id;

  -- If the unit does not exist, return a 404 error
  IF org_id IS NULL THEN
    RAISE EXCEPTION 'Unit not found' USING ERRCODE = 'P0002'; -- no_data_found
  END IF;

  -- Step 2: Check if the caller is a manager of the unit
  IF (SELECT get_is_manager_on_unit(p_unit_id)) <> TRUE THEN
    RAISE EXCEPTION 'Access denied' USING ERRCODE = '42501'; -- insufficient_privilege
  END IF;

  -- Step 3: Aggregate user information and roles for sorting
  WITH relevant_occasions AS (
    -- Occasions under the same unit
    SELECT id AS occasion_id FROM public.occasions WHERE unit = p_unit_id
    UNION
    -- Occasions where the current user has privileged rights
    SELECT occasion AS occasion_id
    FROM public.occasion_users
    WHERE "user" = auth.uid()
      AND (is_manager = true OR is_editor = true OR is_approver = true)
  ),
  raw_user_roles AS (
    -- Roles from occasion_users in relevant occasions
    SELECT
      uo."user",
      uo.is_manager,
      uo.is_editor,
      uo.is_editor_order,
      uo.is_editor_view,
      uo.is_editor_order_view,
      uo.is_approver
    FROM public.occasion_users uo
    WHERE uo.occasion IN (SELECT occasion_id FROM relevant_occasions)

    UNION ALL

    -- Roles from unit_users (mapping available columns)
    SELECT
      uu."user",
      uu.is_manager,
      uu.is_editor,
      false AS is_editor_order,       -- Not in unit_users
      uu.is_editor_view,
      false AS is_editor_order_view,  -- Not in unit_users
      false AS is_approver            -- Not in unit_users
    FROM public.unit_users uu
    WHERE uu.unit = p_unit_id
  ),
  aggregated_user_roles AS (
    -- Consolidate roles per user (taking true if any occurrence is true)
    SELECT
      "user",
      bool_or(is_manager) AS is_manager,
      bool_or(is_editor) AS is_editor,
      bool_or(is_editor_order) AS is_editor_order,
      bool_or(is_editor_view) AS is_editor_view,
      bool_or(is_editor_order_view) AS is_editor_order_view,
      bool_or(is_approver) AS is_approver
    FROM raw_user_roles
    GROUP BY "user"
  )
  SELECT jsonb_agg(
    jsonb_build_object(
      'id', ui.id,
      'name', ui.name,
      'surname', ui.surname,
      'sex', ui.sex,
      'email_readonly', ui.email_readonly,
      'companion_parent', (
        SELECT jsonb_build_object(
          'id', parent_ui.id,
          'name', parent_ui.name,
          'surname', parent_ui.surname,
          'sex', parent_ui.sex,
          'email_readonly', parent_ui.email_readonly
        )
        FROM public.user_info parent_ui
        WHERE parent_ui.id = uc."user"
      )
    ) ORDER BY
      aur.is_manager DESC,
      aur.is_editor DESC,
      aur.is_editor_order DESC,
      aur.is_editor_view DESC,
      aur.is_editor_order_view DESC,
      aur.is_approver DESC,
      ui.surname ASC NULLS LAST,
      ui.name ASC NULLS LAST
  ) INTO user_basics
  FROM public.user_info ui
  JOIN aggregated_user_roles aur ON ui.id = aur."user"
  LEFT JOIN public.user_companions uc ON ui.id = uc.companion AND uc.occasion IN (SELECT id FROM public.occasions WHERE unit=p_unit_id)
  LEFT JOIN public.organization_users ou ON ui.id = ou."user" AND ou.organization = org_id
  WHERE (ou.is_hidden IS NOT TRUE);

  -- Step 4: Handle cases with no users found
  IF user_basics IS NULL THEN
    user_basics := '[]'::jsonb;
  END IF;

  -- Step 5: Return the aggregated JSON response
  RETURN user_basics;
END;
$$;


ALTER FUNCTION "public"."get_all_user_basics_from_occasion_unit"("p_unit_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_all_user_group_info"("p_occasion_id" bigint, "p_type" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    groups_json jsonb;
    game_defs_json jsonb;
    result_data jsonb;
BEGIN
    -- Authorization Check:
    -- The user must have editor view permissions for the requested occasion.
    -- This function call is the security gate for this entire operation.
    IF NOT get_is_editor_view_on_occasion(p_occasion_id) THEN
        RETURN jsonb_build_object('code', 403, 'message', 'Not authorized to view user groups for this occasion');
    END IF;

    -- If authorized, proceed to fetch the data.
    SELECT
        COALESCE(jsonb_agg(
            jsonb_build_object(
                'id', ugi.id,
                'title', ugi.title,
                'description', ugi.description,
                'type', ugi.type,
                'data', ugi.data,
                'leader', ugi.leader,
                'place', ugi.place,
                'user_info', ( -- Nested leader object
                    SELECT jsonb_build_object('id', ui_leader.id, 'name', ui_leader.name, 'surname', ui_leader.surname)
                    FROM public.user_info ui_leader
                    WHERE ui_leader.id = ugi.leader
                ),
                'places', ( -- Nested place object
                    SELECT jsonb_strip_nulls(jsonb_build_object(
                        'id', p.id,
                        'title', p.title,
                        'description', p.description,
                        'type', p.type,
                        'created_at', p.created_at,
                        'coordinates', p.coordinates,
                        'is_hidden', p.is_hidden,
                        'updated_at', p.updated_at,
                        'occasion', p.occasion,
                        'order', p."order",
                        'icon', p.icon,
                        'unit', p.unit
                    ))
                    FROM public.places p
                    WHERE p.id = ugi.place
                ),
                'user_groups', ( -- Nested array of participants
                    SELECT COALESCE(jsonb_agg(
                        jsonb_build_object(
                            'user_info', jsonb_build_object('id', p_ui.id, 'name', p_ui.name, 'surname', p_ui.surname)
                        )
                    ), '[]'::jsonb)
                    FROM public.user_groups ug
                    JOIN public.user_info p_ui ON ug."user" = p_ui.id
                    WHERE ug."group" = ugi.id
                )
            )
        ), '[]'::jsonb)
    INTO groups_json
    FROM public.user_group_info ugi
    WHERE ugi.occasion = p_occasion_id
      AND (p_type IS NULL AND ugi.type IS NULL OR ugi.type = p_type);

    -- If the requested type is 'game', also fetch the game definitions (checkpoints).
    IF p_type = 'game' THEN
        SELECT jsonb_object_agg(info.id, info.title)
        INTO game_defs_json
        FROM public.information info
        WHERE info.type = 'game' AND info.occasion = p_occasion_id;
    END IF;

    -- Combine the results into a single data object.
    result_data := jsonb_build_object(
        'groups', groups_json,
        'game_definitions', game_defs_json
    );

    -- Return the data in a structured response on success.
    RETURN jsonb_build_object('code', 200, 'data', result_data);

EXCEPTION WHEN OTHERS THEN
    -- Catch any unexpected errors during execution.
    RETURN jsonb_build_object('code', 500, 'message', SQLERRM);
END;
$$;


ALTER FUNCTION "public"."get_all_user_group_info"("p_occasion_id" bigint, "p_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_all_user_groups"("p_occasion_id" bigint, "p_type" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  groups_json jsonb;
  game_defs_json jsonb;
  places_json jsonb;
BEGIN
  IF NOT get_is_editor_view_on_occasion(p_occasion_id) THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED';
  END IF;

  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', ugi.id,
      'title', ugi.title,
      'description', ugi.description,
      'type', ugi.type,
      'data', ugi.data,
      'place', ugi.place,
      'places', (
        SELECT row_to_json(p)::jsonb
        FROM public.places p
        WHERE p.id = ugi.place
      ),
      'user_groups', (
        SELECT COALESCE(jsonb_agg(
          jsonb_build_object(
            'is_admin', ug.is_admin,
            'user_info', jsonb_build_object(
              'id', p_ui.id,
              'name', p_ui.name,
              'surname', p_ui.surname
            )
          )
        ), '[]'::jsonb)
        FROM public.user_groups ug
        JOIN public.user_info p_ui ON ug."user" = p_ui.id
        WHERE ug."group" = ugi.id
      )
    )
  ), '[]'::jsonb)
  INTO groups_json
  FROM public.user_group_info ugi
  WHERE ugi.occasion = p_occasion_id
    AND (p_type IS NULL AND ugi.type IS NULL OR ugi.type = p_type);

  IF p_type = 'game' THEN
    SELECT jsonb_object_agg(info.id, info.title)
    INTO game_defs_json
    FROM public.information info
    WHERE info.type = 'game' AND info.occasion = p_occasion_id;
  END IF;

  SELECT COALESCE(
    jsonb_agg(to_jsonb(p) ORDER BY p."order" NULLS LAST, p.title),
    '[]'::jsonb
  )
  INTO places_json
  FROM public.places p
  WHERE p.occasion = p_occasion_id
    AND NOT p.is_hidden
    AND p.coordinates->'latLng'->>'lat' IS NOT NULL
    AND p.coordinates->'latLng'->>'lng' IS NOT NULL;

  RETURN jsonb_build_object(
    'groups', groups_json,
    'game_definitions', game_defs_json,
    'places', places_json
  );
END;
$$;


ALTER FUNCTION "public"."get_all_user_groups"("p_occasion_id" bigint, "p_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_all_users_from_unit"("unit_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  user_basics jsonb;
  org_id bigint;
BEGIN
  -- Step 1: Get the Organization ID for this Unit
  -- This also serves as a check to see if the unit exists
  SELECT organization INTO org_id
  FROM public.units
  WHERE id = unit_id;

  -- If org_id is null, the unit likely doesn't exist
  -- (Assuming all units belong to an organization)
  IF org_id IS NULL THEN
    RETURN jsonb_build_object('code', 404, 'message', 'Unit not found');
  END IF;

  -- Step 2: Permission Check
  IF NOT EXISTS (
      SELECT 1 FROM public.unit_users
      WHERE "user" = auth.uid()
        AND unit = unit_id
        AND (is_manager = true OR is_editor = true OR is_editor_view = true)
  ) THEN
    RETURN jsonb_build_object('code', 403);
  END IF;

  -- Step 3: Retrieve Users with Hidden Filter
  SELECT jsonb_agg(user_info)
  INTO user_basics
  FROM (
    SELECT jsonb_build_object(
      'user', ui.id,
      'name', ui.name,
      'surname', ui.surname,
      'sex', ui.sex,
      'email_readonly', ui.email_readonly,
      'unit', uu.unit,
      'is_manager', uu.is_manager,
      'is_editor', uu.is_editor,
      'is_editor_view', uu.is_editor_view,
      'data', uu.data
    ) AS user_info
    FROM public.unit_users uu
    JOIN public.user_info ui ON uu."user" = ui.id

    -- Left Join to check organization-wide visibility settings
    LEFT JOIN public.organization_users ou ON ui.id = ou."user" AND ou.organization = org_id

    WHERE uu.unit = unit_id

    -- Filter out hidden users
    -- (ou.is_hidden IS NOT TRUE) includes FALSE (visible) and NULL (no record found, so visible)
    AND (ou.is_hidden IS NOT TRUE)

    ORDER BY uu.created_at DESC
  ) t;

  -- Step 4: Handle Empty Results
  IF user_basics IS NULL THEN
    user_basics := '[]'::jsonb;
  END IF;

  RETURN jsonb_build_object('code', 200, 'data', user_basics);
END;
$$;


ALTER FUNCTION "public"."get_all_users_from_unit"("unit_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_all_viewable_forms_for_copying"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    forms_data JSONB;
    user_id UUID := auth.uid();
BEGIN
    -- Step 1: Aggregate forms into a JSONB array based on the user's combined permissions.
    -- The user can see forms from occasions where they are a direct editor,
    -- or from any occasion within a unit where they are a unit editor.
    SELECT jsonb_agg(
        jsonb_build_object(
            'id', f.id,
            'created_at', f.created_at,
            'title', f.title,
            'data', f.data,
            'key', f.key,
            'occasion', jsonb_build_object(
                'id', o.id,
                'title', o.title,
                'link', o.link,
                'start_time', o.start_time,
                'end_time', o.end_time
            ),
            'type', f.type,
            'is_open', f.is_open,
            'link', f.link,
            'blueprint', f.blueprint,
            'updated_at', f.updated_at,
            'stats', jsonb_build_object(
                'total', COALESCE(order_stats.total, 0),
                'storno', COALESCE(order_stats.storno, 0),
                'paid_or_sent', COALESCE(order_stats.paid_or_sent, 0),
                'ordered', COALESCE(order_stats.ordered, 0)
            )
        ) ORDER BY o.start_time DESC, f.created_at DESC
    )
    INTO forms_data
    FROM public.forms f
    JOIN public.occasions o ON f.occasion = o.id
    LEFT JOIN (
        -- Subquery to calculate order statistics for each form.
        SELECT
            (data->>'form')::uuid AS form_key,
            COUNT(*) AS total,
            COUNT(*) FILTER (WHERE state = 'storno') AS storno,
            COUNT(*) FILTER (WHERE state IN ('paid', 'sent')) AS paid_or_sent,
            COUNT(*) FILTER (WHERE state = 'ordered') AS ordered
        FROM eshop.orders
        WHERE data->>'form' IS NOT NULL
        GROUP BY form_key
    ) AS order_stats ON f.key = order_stats.form_key
    WHERE f.occasion IN (
        -- Subquery to get all occasion IDs the user has editor view access to.
        -- This includes direct occasion permissions.
        SELECT ou.occasion
        FROM public.occasion_users ou
        WHERE ou.user = user_id AND ou.is_editor_view = TRUE

        UNION

        -- And permissions inherited from unit-level roles.
        SELECT o_unit.id
        FROM public.occasions o_unit
        JOIN public.unit_users uu ON o_unit.unit = uu.unit
        WHERE uu.user = user_id AND uu.is_editor_view = TRUE
    );

    -- Step 2: If no forms are found, return an empty JSON array.
    IF forms_data IS NULL THEN
        forms_data := '[]'::jsonb;
    END IF;

    -- Step 3: Return the aggregated data.
    RETURN forms_data;
END;
$$;


ALTER FUNCTION "public"."get_all_viewable_forms_for_copying"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_app_config"("data_in" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    org_id bigint := (data_in->>'organization')::bigint;
    link_txt text := data_in->>'link';
    platform_info jsonb := data_in->'platform';
    platform_name text := platform_info->>'platform';
    occasionId bigint;
    is_open_bool BOOLEAN;
    occasion_user occasion_users%rowtype;
    is_admin_bool BOOLEAN;
    occasion_link text;
    version_recommended text;
BEGIN
    -- Log the request details in log_app_config table
    INSERT INTO public.log_app_config (organization, platform)
    VALUES (org_id, platform_info);

    -- Map "pwa" to "web" for platform consistency
    IF platform_name = 'pwa' THEN
        platform_name := 'web';
    END IF;

    -- If no link is provided, get the default occasion from the organization
    IF link_txt IS NULL OR link_txt = '' THEN
        SELECT data->>'DEFAULT_OCCASION' INTO occasionId
        FROM organizations
        WHERE id = org_id;

        -- If no default occasion is set, get the first open and non-hidden occasion within the organization
        IF occasionId IS NULL THEN
            SELECT id, link INTO occasionId, occasion_link
            FROM occasions
            WHERE is_open = true
              AND is_hidden = false
              AND organization = org_id
            LIMIT 1;

            -- If no open occasion is found, return a 404 response
            IF occasionId IS NULL THEN
                RETURN json_build_object('code', 404, 'message', 'No open occasion found for the organization');
            END IF;
        ELSE
            -- Get the link for the default occasion
            SELECT link INTO occasion_link
            FROM occasions
            WHERE id = occasionId AND organization = org_id;
        END IF;
    ELSE
        -- Get the occasion ID and link for the provided link within the specified organization
        SELECT id, link INTO occasionId, occasion_link
        FROM occasions
        WHERE link = link_txt
          AND is_hidden = false
          AND organization = org_id;

        -- If the occasion ID is not found, return a 404 response
        IF occasionId IS NULL THEN
            RETURN json_build_object('code', 404, 'message', 'Occasion not found');
        END IF;
    END IF;

    -- Retrieve version_recommended for the specific platform, or leave as NULL if not found
    SELECT (SELECT item->>'prompt'
            FROM jsonb_array_elements(data->'PLATFORMS') AS item
            WHERE item->>'platform' = platform_name) INTO version_recommended
    FROM organizations
    WHERE id = org_id;

    -- Get the is_open status for the occasion
    SELECT is_open INTO is_open_bool
    FROM occasions
    WHERE id = occasionId;

    -- Get the occasion user record if it exists
    SELECT * INTO occasion_user
    FROM occasion_users
    WHERE occasion = occasionId
      AND "user" = auth.uid();

    -- Check if the current user is an admin on the occasion
    is_admin_bool := get_is_admin_on_occasion(occasionId);

    -- If the occasion is not open, enforce access restrictions
    IF is_open_bool = FALSE THEN
        IF auth.uid() IS NULL OR (occasion_user IS NULL AND NOT is_admin_bool) THEN
            RETURN json_build_object('code', 403, 'message', 'Access forbidden', 'link', occasion_link, 'version_recommended', version_recommended);
        END IF;
    END IF;

    -- If the occasion user record is not found, the user is authenticated, and the occasion is open
    IF occasion_user IS NULL AND auth.uid() IS NOT NULL THEN
        -- Add the user to the occasion
        PERFORM add_user_to_occasion(occasionId, auth.uid());

        -- Fetch the updated occasion user record
        SELECT * INTO occasion_user
        FROM occasion_users
        WHERE occasion = occasionId
          AND "user" = auth.uid();
    END IF;

    -- Return final response with all data and status code 200 at the end
    RETURN json_build_object(
        'code', 200,
        'is_admin', is_admin_bool,
        'occasion_user', COALESCE(row_to_json(occasion_user)::jsonb, NULL),
        'link', occasion_link,
        'occasion', occasionId,
        'version_recommended', version_recommended
    );
END;
$$;


ALTER FUNCTION "public"."get_app_config"("data_in" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_app_config_v182"("data_in" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    org_id bigint := (data_in->>'organization')::bigint;
    link_txt text := data_in->>'link';
    form_link text := data_in->>'form_link';
    unit_id bigint := (data_in->>'unit_id')::bigint;
    platform_info jsonb := data_in->'platform';
    platform_name text := platform_info->>'platform';
    occasionId bigint;
    default_unit bigint;
    is_open_bool BOOLEAN;
    occasion_user occasion_users%rowtype;
    unit_user unit_users%rowtype;
    is_admin_bool BOOLEAN;
    occasion_link text;
    version_recommended text;
    version_link text;
    occasion_unit bigint;
    bank_account_ids bigint[];
    occasion_json jsonb;
    unit_json jsonb;
    user_info_json jsonb;
    org_json jsonb;
    user_groups_json jsonb;
    is_editor_view_on_occasion_bool BOOLEAN;
    user_occasions_json jsonb;
    current_user_id UUID := auth.uid();
BEGIN
    -- Log the request details in log_app_config table
    INSERT INTO public.log_app_config (organization, platform)
    VALUES (org_id, platform_info);

    -- Map "pwa" to "web" for platform consistency
    IF platform_name = 'pwa' THEN
        platform_name := 'web';
    END IF;

    -- If form_link is provided, fetch the occasion from forms
    IF form_link IS NOT NULL AND form_link <> '' THEN
        SELECT forms.occasion, occasions.link
          INTO occasionId, occasion_link
        FROM forms
        JOIN occasions ON forms.occasion = occasions.id
        WHERE forms.link = form_link
          AND occasions.organization = org_id;

        -- If no occasion is found, return a 404 response
        IF occasionId IS NULL THEN
            RETURN json_build_object(
                'code', 404,
                'message', 'No occasion found for the provided form link'
            );
        END IF;

    -- If no form_link but link_txt is provided
    ELSIF link_txt IS NOT NULL AND link_txt <> '' THEN
        SELECT id, link
          INTO occasionId, occasion_link
        FROM occasions
        WHERE link = link_txt
          AND organization = org_id;

        IF occasionId IS NULL THEN
            RETURN json_build_object(
                'code', 404,
                'message', 'Occasion not found'
            );
        END IF;

    -- New: If a unit_id is provided directly (and no links), prioritize it and do not load an occasion.
    ELSIF unit_id IS NOT NULL THEN
        occasionId := NULL; -- Ensure no occasion is loaded, even if a default is set for the org.
        default_unit := unit_id; -- Use the provided unit_id as the context.

        -- Fetch unit details from the provided unit_id
        SELECT json_build_object('id', u.id, 'title', u.title)
            INTO unit_json
        FROM units u
        WHERE u.id = default_unit;

        -- Fetch the user's relationship with this unit
        SELECT *
            INTO unit_user
        FROM unit_users
        WHERE unit = default_unit
            AND "user" = current_user_id;

    ELSE
        -- No link or specific unit_id provided: first try to get the representative or default occasion
        SELECT COALESCE(
                 (data->>'REPRESENTATIVE_OCCASION')::bigint,
                 (data->>'DEFAULT_OCCASION')::bigint
               )
          INTO occasionId
        FROM organizations
        WHERE id = org_id;

        IF occasionId IS NULL THEN
            -- No default occasion; try to get the default unit instead
            SELECT (data->>'DEFAULT_UNIT')::bigint
              INTO default_unit
            FROM organizations
            WHERE id = org_id;

            IF default_unit IS NOT NULL THEN
                -- Default unit exists so we leave occasion unset
                occasionId := NULL;
                -- Fetch unit details from the default unit
                SELECT json_build_object('id', u.id, 'title', u.title)
                  INTO unit_json
                FROM units u
                WHERE u.id = default_unit;

                SELECT *
                  INTO unit_user
                FROM unit_users
                WHERE unit = default_unit
                  AND "user" = current_user_id;
            ELSE
                -- Neither default occasion nor default unit exists; search for first open, non-hidden occasion
                SELECT id, link
                  INTO occasionId, occasion_link
                FROM occasions
                WHERE is_open = true
                  AND organization = org_id
                LIMIT 1;

                IF occasionId IS NULL THEN
                    RETURN json_build_object(
                        'code', 404,
                        'message', 'No open occasion found for the organization'
                    );
                END IF;
            END IF;
        ELSE
            -- Default occasion exists; fetch its link
            SELECT link
              INTO occasion_link
            FROM occasions
            WHERE id = occasionId AND organization = org_id;
        END IF;
    END IF;

    -- Retrieve version_recommended and version_link for the specific platform, or leave as NULL if not found
    SELECT
        item->>'prompt',
        item->>'link'
    INTO
        version_recommended,
        version_link
    FROM
        public.organizations,
        jsonb_array_elements(data->'PLATFORMS') AS item
    WHERE
        id = org_id AND item->>'platform' = platform_name
    LIMIT 1;

    IF occasionId IS NOT NULL THEN
        -- Process occasion-related queries only if an occasion was determined

        -- Get the is_open status for the occasion
        SELECT is_open
          INTO is_open_bool
        FROM occasions
        WHERE id = occasionId;

        -- Get the occasion user record if it exists
        SELECT *
          INTO occasion_user
        FROM occasion_users
        WHERE occasion = occasionId
          AND "user" = current_user_id;

        -- Retrieve the unit ID from the occasion
        SELECT unit
          INTO occasion_unit
        FROM occasions
        WHERE id = occasionId;

        -- Get the unit user record if it exists
        SELECT *
          INTO unit_user
        FROM unit_users
        WHERE unit = occasion_unit
          AND "user" = current_user_id;

        -- Check if the current user is an admin on the occasion
        is_admin_bool := get_is_admin_on_occasion(occasionId);

        -- Check if the current user has editor_view permissions on the occasion
        is_editor_view_on_occasion_bool := get_is_editor_view_on_occasion(occasionId);

        -- If the occasion is not open, enforce access restrictions
        IF is_open_bool = FALSE THEN
            IF is_editor_view_on_occasion_bool <> TRUE
               AND (SELECT get_is_editor_order_view_on_occasion(occasionId)) <> TRUE
               AND (SELECT get_is_editor_on_unit(occasion_unit)) <> TRUE THEN
                RETURN json_build_object(
                    'code', 403,
                    'message', 'Access forbidden',
                    'link', occasion_link,
                    'version_recommended', version_recommended,
                    'version_link', version_link,
                    'unit_user', COALESCE(row_to_json(unit_user)::jsonb, NULL)
                );
            END IF;
        END IF;

        -- If the occasion user record is not found and the user is authenticated, add the user to the occasion
        IF occasion_user IS NULL AND current_user_id IS NOT NULL THEN
            PERFORM add_user_to_occasion(occasionId, current_user_id);

            SELECT *
              INTO occasion_user
            FROM occasion_users
            WHERE occasion = occasionId
              AND "user" = current_user_id;
        END IF;
    ELSE
        -- If no occasion is set (because a default or specific unit was used), use the unit as the context
        occasion_unit := default_unit;
        -- Here we assume no occasion means no occasion-based admin check
        is_admin_bool := false;
    END IF;

    -- Retrieve unit_user again in case the user was added and now belongs to the unit
    IF unit_user IS NULL AND occasion_unit IS NOT NULL AND current_user_id IS NOT NULL THEN
        SELECT *
          INTO unit_user
        FROM unit_users
        WHERE unit = occasion_unit
          AND "user" = current_user_id;
    END IF;

    -- Fetch list of bank account IDs where the user is an admin
    SELECT array_agg(bank_account)
      INTO bank_account_ids
    FROM eshop.bank_account_users
    WHERE "user" = current_user_id
      AND is_admin = true;

    -- Fetch full occasion details as a JSON object if an occasion is set
    IF occasionId IS NOT NULL THEN
        SELECT row_to_json(o)
          INTO occasion_json
        FROM occasions o
        WHERE o.id = occasionId;
    ELSE
        occasion_json := '{}'::jsonb;
    END IF;

    -- Fetch full unit details as a JSON object
    IF occasion_unit IS NOT NULL THEN
        SELECT json_build_object('id', u.id, 'title', u.title)
          INTO unit_json
        FROM units u
        WHERE u.id = occasion_unit;
    ELSE
        unit_json := '{}'::jsonb;
    END IF;

    -- Fetch occasions for the user based on the specified logic
    IF occasion_unit IS NOT NULL AND current_user_id IS NOT NULL THEN
        IF is_editor_view_on_occasion_bool THEN
            -- If user is an editor, get all occasions for the unit
            SELECT json_agg(json_build_object('id', o.id, 'title', o.title, 'link', o.link, 'start_time', o.start_time, 'end_time', o.end_time))
            INTO user_occasions_json
            FROM public.occasions o
            WHERE o.unit = occasion_unit;
        ELSE
            -- Otherwise, get only occasions the user is explicitly on for that unit
            SELECT json_agg(json_build_object('id', o.id, 'title', o.title, 'link', o.link, 'start_time', o.start_time, 'end_time', o.end_time))
            INTO user_occasions_json
            FROM public.occasions o
            JOIN public.occasion_users ou ON ou.occasion = o.id
            WHERE ou."user" = current_user_id
            AND o.unit = occasion_unit;
        END IF;
    END IF;

    -- Fetch user information along with associated units and occasions
    SELECT row_to_json(ui)::jsonb || jsonb_build_object(
            'units',
            (
                SELECT json_agg(jsonb_build_object('id', u.id, 'title', u.title))
                FROM public.units u
                JOIN public.unit_users uu ON uu.unit = u.id
                WHERE uu."user" = ui.id AND uu.is_editor_view = TRUE
            ),
            'occasions', user_occasions_json
          )
      INTO user_info_json
    FROM public.user_info ui
    WHERE ui.id = current_user_id;

    -- Fetch limited organization info
    SELECT json_build_object(
        'title', title,
        'APP_NAME', data->>'APP_NAME',
        'PLATFORMS', data->'PLATFORMS',
        'IS_REGISTRATION_ENABLED', data->'IS_REGISTRATION_ENABLED'
    ) INTO org_json
    FROM public.organizations
    WHERE id = org_id;

    -- Fetch the user's groups for the specific occasion
    IF occasionId IS NOT NULL THEN
        user_groups_json := public.get_user_groups(occasionId);
    END IF;

    RETURN json_build_object(
        'code', 200,
        'is_admin', is_admin_bool,
        'occasion_user', COALESCE(row_to_json(occasion_user)::jsonb, NULL),
        'unit_user', COALESCE(row_to_json(unit_user)::jsonb, NULL),
        'occasion', COALESCE(occasion_json, '{}'::jsonb),
        'unit', COALESCE(unit_json, '{}'::jsonb),
        'version_recommended', version_recommended,
        'version_link', version_link,
        'bank_accounts_admin', COALESCE(bank_account_ids, '{}'),
        'user_info', COALESCE(user_info_json, '{}'::jsonb),
        'organization', COALESCE(org_json::jsonb, '{}'::jsonb),
        'groups', COALESCE(user_groups_json, '{}'::jsonb)
    );
END;
$$;


