CREATE OR REPLACE FUNCTION "public"."get_bank_account_secret"("p_bank_account_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_bank_secret bigint;
  v_secret_rec RECORD;
BEGIN
  -- Fetch the secret associated with the bank account
  SELECT secret
    INTO v_bank_secret
    FROM eshop.bank_accounts
   WHERE id = p_bank_account_id;

  IF v_bank_secret IS NULL THEN
    RAISE EXCEPTION 'Bank account not found or missing secret for id %', p_bank_account_id;
  END IF;

  -- Fetch the secret details from the secrets table
  SELECT secret, expiry_date
    INTO v_secret_rec
    FROM eshop.secrets
   WHERE id = v_bank_secret;

  IF NOT FOUND OR v_secret_rec.secret IS NULL THEN
    RAISE EXCEPTION 'Secret not found or expired for bank account %', p_bank_account_id;
  END IF;

  RETURN to_jsonb(v_secret_rec);
END;
$$;


ALTER FUNCTION "public"."get_bank_account_secret"("p_bank_account_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_bank_account_users"("p_bank_account_id" bigint) RETURNS TABLE("user_id" "uuid", "email" "text", "name" "text", "surname" "text", "is_admin" boolean, "is_support" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        u.id,
        u.email_readonly,
        u.name,
        u.surname,
        bau.is_admin,
        bau.is_support
    FROM eshop.bank_account_users bau
    JOIN public.user_info u ON bau."user" = u.id
    WHERE bau.bank_account = p_bank_account_id;
END;
$$;


ALTER FUNCTION "public"."get_bank_account_users"("p_bank_account_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_bank_account_users"("p_bank_account_id" bigint, "p_unit_id" bigint DEFAULT NULL::bigint) RETURNS TABLE("user_id" "uuid", "email" "text", "name" "text", "surname" "text", "is_admin" boolean, "is_support" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_org_id bigint;
BEGIN
    -- If unit context is provided, find the organization
    IF p_unit_id IS NOT NULL THEN
        SELECT organization INTO v_org_id FROM public.units WHERE id = p_unit_id;
    END IF;

    RETURN QUERY
    SELECT
        u.id,
        u.email_readonly,
        u.name,
        u.surname,
        bau.is_admin,
        bau.is_support
    FROM eshop.bank_account_users bau
    JOIN public.user_info u ON bau."user" = u.id
    LEFT JOIN public.organization_users ou ON u.id = ou."user" AND (v_org_id IS NULL OR ou.organization = v_org_id)
    WHERE bau.bank_account = p_bank_account_id
      AND (v_org_id IS NULL OR ou.is_hidden IS NOT TRUE);
END;
$$;


ALTER FUNCTION "public"."get_bank_account_users"("p_bank_account_id" bigint, "p_unit_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_bank_accounts_for_unit_management"("p_unit_id" bigint) RETURNS TABLE("id" bigint, "account_number" "text", "title" "text", "type" "text", "is_admin" boolean, "token_masked" "text", "token_expiry_date" timestamp with time zone, "supported_currencies" "text"[], "pairing_code" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        ba.id,
        ba.account_number,
        ba.title,
        ba.type,
        EXISTS (
            SELECT 1
            FROM eshop.bank_account_users bau
            WHERE bau.bank_account = ba.id
            AND bau."user" = auth.uid()
            AND bau.is_admin = true
        ) as is_admin,
        CASE
            WHEN s.secret IS NOT NULL THEN
                '************' || right(s.secret, 4)
            ELSE NULL
        END as token_masked,
        s.expiry_date as token_expiry_date,
        ba.supported_currencies,
        ba.pairing_code
    FROM eshop.bank_accounts ba
    JOIN eshop.unit_bank_accounts uba ON ba.id = uba.bank_account
    LEFT JOIN eshop.secrets s ON ba.secret = s.id
    WHERE uba.unit = p_unit_id
    AND ba.type != 'CASH';  -- ADDED: Exclude Cash Accounts
END;
$$;


ALTER FUNCTION "public"."get_bank_accounts_for_unit_management"("p_unit_id" bigint) OWNER TO "postgres";


