CREATE OR REPLACE FUNCTION "public"."get_cleaning_reports"("oc" bigint, "p_include_resolved" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_data jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object('code', 401, 'message', 'Sign in is required');
  END IF;

  IF NOT public.get_is_cleaning_crew_on_occasion(oc) THEN
    RETURN jsonb_build_object('code', 403, 'message', 'Cleaning crew access required');
  END IF;

  SELECT COALESCE(jsonb_agg(row_to_json(t) ORDER BY t.created_at DESC), '[]'::jsonb)
  INTO v_data
  FROM (
    SELECT
      r.id,
      r.place,
      p.title AS place_title,
      r.problem_type,
      r.note,
      r.data,
      r.created_at,
      r.created_by,
      TRIM(BOTH ' ' FROM COALESCE(ui.name, '') || ' ' || COALESCE(ui.surname, '')) AS created_by_name,
      COALESCE(ou.is_cleaning_blocked, false) AS created_by_blocked,
      r.resolved_at,
      r.resolved_by
    FROM public.cleaning_reports r
    JOIN public.places p ON p.id = r.place
    LEFT JOIN public.user_info ui ON ui.id = r.created_by
    LEFT JOIN public.occasion_users ou ON ou."user" = r.created_by AND ou.occasion = r.occasion
    WHERE r.occasion = oc
      AND (p_include_resolved OR r.resolved_at IS NULL)
  ) t;

  RETURN jsonb_build_object('code', 200, 'data', v_data);
END;
$$;


ALTER FUNCTION "public"."get_cleaning_reports"("oc" bigint, "p_include_resolved" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_cleaning_status"("oc" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_data jsonb;
  v_blocked boolean;
  v_muted boolean;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object('code', 401, 'message', 'Sign in is required');
  END IF;

  SELECT
    COALESCE(bool_or(is_cleaning_blocked), false),
    COALESCE(bool_or((data->>'cleaning_notifications_off')::boolean), false)
  INTO v_blocked, v_muted
  FROM public.occasion_users
  WHERE occasion = oc AND "user" = auth.uid();

  SELECT COALESCE(jsonb_agg(t ORDER BY t.title), '[]'::jsonb)
  INTO v_data
  FROM (
    SELECT
      p.id AS place,
      p.title AS title,
      -- Severity ranking — keep in sync with the CleaningStatus enum order in
      -- cleaning_status.dart (green < paper < hygiene < contamination).
      CASE COALESCE(MAX(
        CASE r.problem_type
          WHEN 'contamination' THEN 3
          WHEN 'hygiene'       THEN 2
          WHEN 'paper'         THEN 1
          ELSE 0
        END), 0)
        WHEN 3 THEN 'contamination'
        WHEN 2 THEN 'hygiene'
        WHEN 1 THEN 'paper'
        ELSE 'green'
      END AS status,
      MAX(r.created_at) AS last_reported_at
    FROM public.places p
    LEFT JOIN public.cleaning_reports r
      ON r.place = p.id AND r.resolved_at IS NULL
    WHERE p.occasion = oc
      AND p.type = 'toilet'
    GROUP BY p.id, p.title
  ) t;

  RETURN jsonb_build_object(
    'code', 200,
    'data', v_data,
    'is_blocked', v_blocked,
    'notifications_muted', v_muted
  );
END;
$$;


ALTER FUNCTION "public"."get_cleaning_status"("oc" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_client_commit_v1"("p_commit_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT CASE WHEN c.commit_id IS NULL THEN jsonb_build_object('code',404)
    WHEN NOT (
      (c.occasion IS NOT NULL AND (
        public.get_is_manager_on_occasion(c.occasion)
        OR public.get_is_admin_on_occasion(c.occasion)))
      OR (c.unit IS NOT NULL AND public.get_is_manager_on_unit(c.unit))
      OR (c.organization IS NOT NULL
        AND public.get_is_admin_on_organization(c.organization))
    ) THEN jsonb_build_object('code',403)
    ELSE jsonb_build_object('code',200,'data',jsonb_build_object(
      'commitId',c.commit_id,'occurredAt',c.occurred_at,
      'actorDisplay',c.actor_display,'actorKind',c.actor_kind,
      'source',c.source,'changeClass',c.change_class,'reason',c.reason,
      'items',(SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'entityType',i.entity_type,'entityId',i.entity_id,
        'operation',i.operation,'safeLabel',i.safe_label,
        'changedFields',i.changed_fields) ORDER BY i.item_index),'[]')
        FROM public.client_commit_items i WHERE i.commit_id=c.commit_id),
      'components',(SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'component',cc.component,'scopeType',cc.scope_type,
        'scopeId',cc.scope_id,'revision',cc.resulting_revision,
        'publishedRevision',p.published_revision,
        'publicationStatus',CASE
          WHEN p.published_revision>=cc.resulting_revision
            THEN 'published' ELSE 'pending' END)
        ORDER BY cc.component),'[]')
        FROM public.client_commit_components cc
        LEFT JOIN LATERAL (
          SELECT max(cp.published_revision) published_revision
          FROM public.client_sync_publications cp
          WHERE cp.component=cc.component
            AND cp.scope_type=cc.scope_type
            AND cp.scope_id=cc.scope_id
        ) p ON true
        WHERE cc.commit_id=c.commit_id))) END
  FROM (SELECT * FROM public.client_commits WHERE commit_id=p_commit_id) c
  RIGHT JOIN (SELECT 1) seed ON true;
$$;


ALTER FUNCTION "public"."get_client_commit_v1"("p_commit_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_client_commits_v1"("p_occasion" bigint, "p_before_time" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_before_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 50, "p_filters" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  WITH scope AS (
    SELECT o.unit, o.organization,
      public.get_is_manager_on_occasion(p_occasion)
        OR public.get_is_admin_on_occasion(p_occasion) AS can_occasion,
      CASE WHEN o.unit IS NULL THEN false
        ELSE public.get_is_manager_on_unit(o.unit) END AS can_unit,
      CASE WHEN o.organization IS NULL THEN false
        ELSE public.get_is_admin_on_organization(o.organization) END AS can_organization
    FROM public.occasions o
    WHERE o.id = p_occasion
  )
  SELECT CASE
    WHEN NOT EXISTS (
      SELECT 1 FROM scope s
      WHERE s.can_occasion OR s.can_unit OR s.can_organization
    ) THEN jsonb_build_object('code',403)
    ELSE jsonb_build_object('code',200,'data',COALESCE((
      SELECT jsonb_agg(row_data ORDER BY occurred_at DESC, commit_id DESC)
      FROM (
        SELECT c.occurred_at,c.commit_id,jsonb_build_object(
          'commitId',c.commit_id,'occurredAt',c.occurred_at,
          'actorDisplay',c.actor_display,'actorKind',c.actor_kind,
          'source',c.source,'changeClass',c.change_class,
          'itemCount',(SELECT count(*) FROM public.client_commit_items ci
            WHERE ci.commit_id=c.commit_id),
          'components',(SELECT COALESCE(jsonb_agg(jsonb_build_object(
            'component',cc.component,'revision',cc.resulting_revision,
            'publishedRevision',pub.published_revision,
            'publicationStatus',CASE
              WHEN pub.published_revision>=cc.resulting_revision
                THEN 'published' ELSE 'pending' END)),'[]')
            FROM public.client_commit_components cc
            LEFT JOIN LATERAL (
              SELECT max(cp.published_revision) published_revision
              FROM public.client_sync_publications cp
              WHERE cp.component=cc.component
                AND cp.scope_type=cc.scope_type
                AND cp.scope_id=cc.scope_id
            ) pub ON true
            WHERE cc.commit_id=c.commit_id)
        ) row_data
        FROM public.client_commits c
        CROSS JOIN scope s
        WHERE (
          (s.can_occasion AND c.occasion=p_occasion)
          OR (s.can_unit AND c.unit=s.unit)
          OR (s.can_organization AND c.organization=s.organization)
        )
          AND (p_before_time IS NULL OR
            (c.occurred_at,c.commit_id)<(p_before_time,p_before_id))
          AND (NOT p_filters ? 'source' OR c.source=p_filters->>'source')
          AND (NOT p_filters ? 'changeClass'
            OR c.change_class=p_filters->>'changeClass')
          AND (NOT p_filters ? 'actorKind'
            OR c.actor_kind=p_filters->>'actorKind')
          AND (NOT p_filters ? 'actor'
            OR COALESCE(c.actor_display,'') ILIKE
              '%'||(p_filters->>'actor')||'%')
          AND (NOT p_filters ? 'from'
            OR c.occurred_at >= (p_filters->>'from')::timestamptz)
          AND (NOT p_filters ? 'to'
            OR c.occurred_at < (p_filters->>'to')::timestamptz)
          AND (NOT p_filters ? 'component' OR EXISTS(
            SELECT 1 FROM public.client_commit_components fc
            WHERE fc.commit_id=c.commit_id
              AND fc.component=p_filters->>'component'))
        ORDER BY c.occurred_at DESC,c.commit_id DESC
        LIMIT LEAST(GREATEST(p_limit,1),501)
      ) page
    ), '[]'))
  END
  FROM (SELECT 1) singleton;
$$;


ALTER FUNCTION "public"."get_client_commits_v1"("p_occasion" bigint, "p_before_time" timestamp with time zone, "p_before_id" "uuid", "p_limit" integer, "p_filters" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_client_sync_publication_state_v1"("p_scope_type" "text", "p_scope_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_scope text; v_head public.client_sync_public_heads%ROWTYPE; v_components jsonb;
BEGIN
  PERFORM public.require_client_sync_service_role_v1();
  IF p_scope_type <> 'occasion' THEN RAISE EXCEPTION 'unsupported scope type'; END IF;
  SELECT o.organization::text||'/'||o.id::text INTO v_scope
  FROM public.occasions o WHERE o.id=p_scope_id AND NOT o.is_hidden;
  IF v_scope IS NULL THEN RAISE EXCEPTION 'scope is not publicly publishable'; END IF;
  SELECT * INTO v_head FROM public.client_sync_public_heads
    WHERE scope_type=p_scope_type AND scope_id=p_scope_id;
  WITH required(component) AS (VALUES ('occasion_config'),('program_catalog'),
    ('map_catalog'),('content_catalog'),('unit_catalog')),
  latest AS (
    SELECT DISTINCT ON (p.component) p.* FROM public.client_sync_publications p
    JOIN required r ON r.component=p.component
    WHERE p.scope_type=p_scope_type AND p.scope_id=p_scope_id
    ORDER BY p.component,p.published_revision DESC
  ) SELECT COALESCE(jsonb_object_agg(component,jsonb_build_object(
      'revision',published_revision,'mediaType',media_type,'url',artifact_url,
      'sha256',sha256,'bytes',byte_size)),'{}') INTO v_components FROM latest;
  RETURN jsonb_build_object('scope',v_scope,'components',v_components,
    'catalog',v_head.head_json->'catalog','live',v_head.head_json->'live',
    'headEtag',v_head.head_etag);
END; $$;


ALTER FUNCTION "public"."get_client_sync_publication_state_v1"("p_scope_type" "text", "p_scope_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_companion_feature_policy_v1"("p_occasion" bigint) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
  SELECT jsonb_build_object(
    'is_enabled',COALESCE((feature->>'is_enabled')::boolean,false),
    'allow_user_create',COALESCE((feature->>'allow_user_create')::boolean,true),
    'allow_admin_assign',COALESCE((feature->>'allow_admin_assign')::boolean,false),
    'max_companions',GREATEST(COALESCE((feature->>'max_companions')::integer,1),1))
  FROM public.occasions o
  LEFT JOIN LATERAL (
    SELECT item AS feature FROM jsonb_array_elements(COALESCE(o.features,'[]')) item
    WHERE item->>'code'='companions' LIMIT 1
  ) configured ON true
  WHERE o.id=p_occasion;
$$;


ALTER FUNCTION "public"."get_companion_feature_policy_v1"("p_occasion" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_counseling_availability"("p_occasion" bigint, "p_topic" bigint, "p_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_to" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
    v_uid        UUID := auth.uid();
    v_counselors JSONB;
BEGIN
    -- Feature gate.
    IF NOT public.get_is_counseling_enabled_on_occasion(p_occasion) THEN
        RETURN jsonb_build_object('code', 404);
    END IF;

    -- The chosen topic must belong to the occasion and be visible.
    -- NOTE (decision R3): the topic is only a filter — it is never stored.
    IF NOT EXISTS (
        SELECT 1 FROM public.speaker_topics t
        WHERE t.id = p_topic AND t.occasion = p_occasion AND t.is_hidden = FALSE
    ) THEN
        RETURN jsonb_build_object('code', 404);
    END IF;

    SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
            'id',       s.id,
            'title',    s.title,
            'subtitle', s.subtitle,
            'image',    s.image,
            'slots', COALESCE((
                SELECT jsonb_agg(jsonb_build_object(
                    'id',               e.id,
                    'start_time',       e.start_time,
                    'end_time',         e.end_time,
                    'place',            e.place,
                    'place_title',      (SELECT pl.title FROM public.places pl WHERE pl.id = e.place),
                    'max_participants', e.max_participants,
                    'occupied',         (SELECT count(*) FROM public.event_users eu WHERE eu.event = e.id),
                    'isSignedIn',       (v_uid IS NOT NULL AND EXISTS (
                                            SELECT 1 FROM public.event_users eu2
                                            WHERE eu2.event = e.id AND eu2."user" = v_uid))
                ) ORDER BY e.start_time)
                FROM public.event_speakers es
                JOIN public.events e ON e.id = es.event
                WHERE es.speaker = s.id
                  AND e.occasion = p_occasion
                  AND (e.data->>'is_counseling_slot')::boolean IS TRUE
                  AND e.end_time > (CURRENT_TIMESTAMP AT TIME ZONE 'UTC')
                  AND (p_from IS NULL OR e.start_time >= p_from)
                  AND (p_to   IS NULL OR e.start_time <  p_to)
            ), '[]'::jsonb)
        ) ORDER BY s."order", s.title
    ), '[]'::jsonb)
    INTO v_counselors
    FROM public.speakers s
    JOIN public.speaker_topic_links stl ON stl.speaker = s.id AND stl.topic = p_topic
    WHERE s.occasion = p_occasion AND s.is_hidden = FALSE
      -- Only counselors who actually have a slot in the window.
      AND EXISTS (
          SELECT 1
          FROM public.event_speakers es
          JOIN public.events e ON e.id = es.event
          WHERE es.speaker = s.id
            AND e.occasion = p_occasion
            AND (e.data->>'is_counseling_slot')::boolean IS TRUE
            AND e.end_time > (CURRENT_TIMESTAMP AT TIME ZONE 'UTC')
            AND (p_from IS NULL OR e.start_time >= p_from)
            AND (p_to   IS NULL OR e.start_time <  p_to)
      );

    RETURN jsonb_build_object(
        'code', 200,
        'data', jsonb_build_object('counselors', v_counselors)
    );
END;
$$;


ALTER FUNCTION "public"."get_counseling_availability"("p_occasion" bigint, "p_topic" bigint, "p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_counseling_topics_overview"("p_occasion" bigint, "p_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_to" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
    v_topics JSONB;
BEGIN
    IF NOT public.get_is_counseling_enabled_on_occasion(p_occasion) THEN
        RETURN jsonb_build_object('code', 404);
    END IF;

    SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
            'id',                 t.id,
            'title',              t.title,
            'order',              t."order",
            'total_future_slots', COALESCE(fs.total, 0),
            'free_future_slots',  COALESCE(fs.free, 0)
        ) ORDER BY t."order", t.title
    ), '[]'::jsonb)
    INTO v_topics
    FROM public.speaker_topics t
    LEFT JOIN LATERAL (
        SELECT
            count(*) AS total,
            count(*) FILTER (
                WHERE e.max_participants IS NULL
                   OR (SELECT count(*) FROM public.event_users eu WHERE eu.event = e.id) < e.max_participants
            ) AS free
        FROM public.events e
        WHERE e.occasion = p_occasion
          AND (e.data->>'is_counseling_slot')::boolean IS TRUE
          AND e.end_time > (CURRENT_TIMESTAMP AT TIME ZONE 'UTC')
          AND (p_from IS NULL OR e.start_time >= p_from)
          AND (p_to   IS NULL OR e.start_time <  p_to)
          AND EXISTS (
              SELECT 1
              FROM public.event_speakers es
              JOIN public.speakers s ON s.id = es.speaker
              JOIN public.speaker_topic_links stl ON stl.speaker = s.id
              WHERE es.event = e.id
                AND s.occasion = p_occasion
                AND s.is_hidden = FALSE
                AND stl.topic = t.id
          )
    ) fs ON TRUE
    WHERE t.occasion = p_occasion
      AND t.is_hidden = FALSE;

    RETURN jsonb_build_object(
        'code', 200,
        'data', jsonb_build_object('topics', v_topics)
    );
END;
$$;


ALTER FUNCTION "public"."get_counseling_topics_overview"("p_occasion" bigint, "p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_current_organization_data"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    AS $$
DECLARE
    organization_id bigint;
    org_data jsonb;
    organization_user record;
BEGIN
    -- Retrieve the organization ID associated with the current authenticated user
    SELECT organization INTO organization_id
    FROM organization_users
    WHERE "user" = auth.uid()
      AND is_admin = true
    LIMIT 1;

    -- If the user is not associated with any organization as an admin, return a 403 code
    IF organization_id IS NULL THEN
        RETURN jsonb_build_object('code', 403);
    END IF;

    -- Retrieve the organization data as jsonb
    SELECT jsonb_build_object(
        'id', id,
        'title', title,
        'data', data,
        'phone_prefixes', phone_prefixes -- Added phone_prefixes
    ) INTO org_data
    FROM organizations
    WHERE id = organization_id;

    -- Return the organization data with a 200 code
    RETURN jsonb_build_object('code', 200, 'data', org_data);
END;
$$;


ALTER FUNCTION "public"."get_current_organization_data"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_current_quote"("unit_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    unit_rec RECORD;
    unit_features jsonb;
    quotes_feature jsonb;
    feature_idx int;
    feature jsonb;
    feature_found BOOLEAN := FALSE;
    curr_quote_id bigint;
    curr_quote_date text;  -- stored as 'YYYY-MM-DD'
    curr_quote_rec RECORD;
    next_quote_rec RECORD;
    updated_features jsonb;
    v_current_date text := to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD');
BEGIN
    -- Lock the unit row to prevent concurrent updates
    SELECT *
    INTO unit_rec
    FROM public.units
    WHERE id = unit_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('code', 404, 'message', 'Unit not found');
    END IF;

    unit_features := unit_rec.features;
    IF unit_features IS NULL THEN
        RETURN jsonb_build_object('code', 404, 'message', 'No features configured for this unit');
    END IF;

    -- Find the enabled "quotes" feature in the JSON array
    FOR feature_idx IN 0 .. jsonb_array_length(unit_features) - 1 LOOP
        feature := unit_features -> feature_idx;
        IF (feature ->> 'code') = 'quotes'
           AND (feature ->> 'is_enabled') = 'true' THEN
            quotes_feature := feature;
            feature_found := TRUE;
            EXIT;
        END IF;
    END LOOP;

    IF NOT feature_found THEN
        RETURN jsonb_build_object('code', 404, 'message', 'Quotes feature is not enabled for this unit');
    END IF;

    -- Retrieve stored quote_id and quote_date from the feature
    curr_quote_id := NULL;
    IF quotes_feature ? 'quote_id' THEN
        curr_quote_id := (quotes_feature ->> 'quote_id')::bigint;
    END IF;

    curr_quote_date := NULL;
    IF quotes_feature ? 'quote_date' THEN
        curr_quote_date := quotes_feature ->> 'quote_date';
    END IF;

    -- If a stored quote exists and its date equals today's UTC date, try to fetch it
    IF curr_quote_id IS NOT NULL AND curr_quote_date = v_current_date THEN
        SELECT *
        INTO curr_quote_rec
        FROM public.information
        WHERE id = curr_quote_id
          AND type = 'quote'
          AND occasion IS NULL
          AND unit = unit_id
          AND is_hidden = false
        LIMIT 1;

        IF FOUND THEN
            RETURN jsonb_build_object('code', 200, 'data', row_to_json(curr_quote_rec));
        END IF;
    END IF;

    -- No valid quote for today; select a new random quote.
    SELECT *
    INTO next_quote_rec
    FROM public.information
    WHERE type = 'quote'
      AND occasion IS NULL
      AND unit = unit_id
      AND is_hidden = false
    ORDER BY random()
    LIMIT 1;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('code', 404, 'message', 'No quotes found for this unit');
    END IF;

    -- Update the feature with the new quote id and today's UTC date
    updated_features := unit_features;
    FOR feature_idx IN 0 .. jsonb_array_length(unit_features) - 1 LOOP
        feature := unit_features -> feature_idx;
        IF (feature ->> 'code') = 'quotes'
           AND (feature ->> 'is_enabled') = 'true' THEN
            updated_features := jsonb_set(
                updated_features,
                ARRAY[feature_idx::text],
                (feature || jsonb_build_object(
                    'quote_id', next_quote_rec.id,
                    'quote_date', v_current_date
                ))
            );
            EXIT;
        END IF;
    END LOOP;

    UPDATE public.units
    SET features = updated_features
    WHERE id = unit_id;

    RETURN jsonb_build_object('code', 200, 'data', row_to_json(next_quote_rec));
END;
$$;


ALTER FUNCTION "public"."get_current_quote"("unit_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_due_queue_emails"() RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_result JSONB;
  -- Reminder grace period: TICKET_ORDER_REMINDER entries with target_time older
  -- than this are treated as stale and dropped during validation. Prevents email
  -- bursts after extended cron downtime (e.g. send-email auth failure backlog).
  c_reminder_grace_period CONSTANT INTERVAL := INTERVAL '7 days';
BEGIN
  -- This function uses Common Table Expressions (CTEs) to first identify all due emails,
  -- then validate them, delete the ones that are no longer valid, and finally return
  -- the ones that are valid and ready to be sent.

  WITH due_emails AS (
    -- 1. Get all emails that have reached their target_time.
    SELECT *
    FROM public.queue_emails
    WHERE target_time <= NOW()
  ),
  validated_emails AS (
    -- 2. For each due email, check if it's still valid.
    SELECT
      de.id,
      CASE
        -- For ticket reminders, re-check the original conditions plus feature flags and the form-specific setting.
        WHEN de.code = 'TICKET_ORDER_REMINDER' THEN
          CASE
            -- Grace period: drop reminder entries whose target_time is older than
            -- c_reminder_grace_period (declared above). Without this, months-old
            -- backlog entries would fire all at once for events that already ended.
            WHEN de.target_time < NOW() - c_reminder_grace_period THEN FALSE
            -- Deposit reminder (has is_deposit_reminder flag)
            WHEN (de.data->>'is_deposit_reminder')::boolean IS TRUE THEN
              (
                o_dr.state = 'paid'
                AND pi_dr.deposit_amount IS NOT NULL
                AND pi_dr.paid < pi_dr.amount
                AND (deposit_feature.feature->>'is_enabled')::boolean IS TRUE
                AND (deposit_feature.feature->>'deposit_deadline') IS DISTINCT FROM 'on_site'
                AND (form_settings_dr.feature->>'is_enabled')::boolean IS TRUE
                AND (form_settings_dr.feature->>'reminder_is_enabled')::boolean IS TRUE
                AND (f_dr.id IS NULL OR COALESCE((f_dr.data->>'is_reminder_enabled')::boolean, TRUE) IS TRUE)
              )
            -- Regular payment reminder
            ELSE
              (
                o.state = 'ordered'
                AND pi.deadline IS NOT NULL
                AND COALESCE((pi.data->>'current_version_reminded')::boolean, false) IS FALSE
                AND (form_settings.feature->>'is_enabled')::boolean IS TRUE
                AND (form_settings.feature->>'reminder_is_enabled')::boolean IS TRUE
                AND (f.id IS NULL OR COALESCE((f.data->>'is_reminder_enabled')::boolean, false) IS TRUE)
              )
          END
        -- Paid emails are immediate sends, just validate order exists.
        WHEN de.code = 'TICKET_ORDER_PAYMENT_DONE' THEN
          TRUE
        -- All other email types are considered valid by default.
        ELSE
          TRUE
      END AS is_valid
    FROM due_emails de
    -- JOINs for regular TICKET_ORDER_REMINDER validation
    LEFT JOIN eshop.orders o ON de.code = 'TICKET_ORDER_REMINDER' AND (de.data->>'is_deposit_reminder')::boolean IS NOT TRUE AND o.id = (de.data->>'order_id')::bigint
    LEFT JOIN eshop.payment_info pi ON de.code = 'TICKET_ORDER_REMINDER' AND (de.data->>'is_deposit_reminder')::boolean IS NOT TRUE AND pi.id = o.payment_info
    LEFT JOIN public.occasions occ ON de.code = 'TICKET_ORDER_REMINDER' AND (de.data->>'is_deposit_reminder')::boolean IS NOT TRUE AND occ.id = o.occasion
    LEFT JOIN LATERAL (
        SELECT elem AS feature
        FROM jsonb_array_elements(occ.features) elem
        WHERE elem->>'code' = 'form'
    ) form_settings ON TRUE
    LEFT JOIN public.forms f ON de.code = 'TICKET_ORDER_REMINDER' AND (de.data->>'is_deposit_reminder')::boolean IS NOT TRUE AND f.id = o.form
    -- JOINs for deposit reminder validation (TICKET_ORDER_REMINDER with is_deposit_reminder flag)
    LEFT JOIN eshop.orders o_dr ON de.code = 'TICKET_ORDER_REMINDER' AND (de.data->>'is_deposit_reminder')::boolean IS TRUE AND o_dr.id = (de.data->>'order_id')::bigint
    LEFT JOIN eshop.payment_info pi_dr ON de.code = 'TICKET_ORDER_REMINDER' AND (de.data->>'is_deposit_reminder')::boolean IS TRUE AND pi_dr.id = o_dr.payment_info
    LEFT JOIN public.occasions occ_dr ON de.code = 'TICKET_ORDER_REMINDER' AND (de.data->>'is_deposit_reminder')::boolean IS TRUE AND occ_dr.id = o_dr.occasion
    LEFT JOIN LATERAL (
        SELECT elem AS feature
        FROM jsonb_array_elements(occ_dr.features) elem
        WHERE elem->>'code' = 'deposit'
    ) deposit_feature ON de.code = 'TICKET_ORDER_REMINDER' AND (de.data->>'is_deposit_reminder')::boolean IS TRUE
    LEFT JOIN LATERAL (
        SELECT elem AS feature
        FROM jsonb_array_elements(occ_dr.features) elem
        WHERE elem->>'code' = 'form'
    ) form_settings_dr ON de.code = 'TICKET_ORDER_REMINDER' AND (de.data->>'is_deposit_reminder')::boolean IS TRUE
    LEFT JOIN public.forms f_dr ON de.code = 'TICKET_ORDER_REMINDER' AND (de.data->>'is_deposit_reminder')::boolean IS TRUE AND f_dr.id = o_dr.form
  ),
  deleted_emails AS (
    -- 3. Delete all emails that failed the validation check.
    --    The RETURNING clause gets the IDs of the deleted rows.
    DELETE FROM public.queue_emails
    WHERE id IN (SELECT id FROM validated_emails WHERE is_valid IS NOT TRUE)
    RETURNING id
  )
  -- 4. Select from the original set of due emails, but exclude the ones that were
  --    just deleted. Aggregate the final valid list into a JSONB array.
  SELECT jsonb_agg(de ORDER BY de.target_time ASC)
  INTO v_result
  FROM due_emails de
  WHERE de.id NOT IN (SELECT id FROM deleted_emails);

  RETURN v_result;

END;
$$;


ALTER FUNCTION "public"."get_due_queue_emails"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_email_template_and_wrapper"("p_code" "text", "p_context" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  result jsonb;
  email_template jsonb;
  email_wrapper jsonb;
  v_occ bigint;
  v_unit bigint;
  v_org bigint;
BEGIN
  -- Extract context values. The ->> operator handles missing keys by returning SQL NULL.
  v_occ := (p_context->>'occasion')::bigint;
  v_unit := (p_context->>'unit')::bigint;
  v_org  := (p_context->>'organization')::bigint;

  -- Retrieve the most specific email template.
  WITH candidates AS (
    SELECT
      et.id,
      et.html,
      et.occasion,
      et.subject,
      et.organization,
      et.code,
      et.unit
    FROM public.email_templates et
    WHERE et.code = p_code
      -- This pattern finds all potential matches. A template is a valid candidate if,
      -- for each parameter, its value either matches the context or is NULL (generic fallback).
      -- If a context variable (e.g. v_unit) is NULL, it acts as a wildcard for that parameter.
      AND (v_occ IS NULL OR et.occasion IS NOT DISTINCT FROM v_occ OR et.occasion IS NULL)
      AND (v_unit IS NULL OR et.unit IS NOT DISTINCT FROM v_unit OR et.unit IS NULL)
      AND (v_org IS NULL OR et.organization IS NOT DISTINCT FROM v_org OR et.organization IS NULL)
  )
  SELECT to_jsonb(t)
  INTO email_template
  FROM (
    SELECT * FROM candidates
    ORDER BY
      -- Ranks candidates by specificity. A direct match (value 0) is better than a generic fallback (value 1).
      -- `IS NOT DISTINCT FROM` is used for NULL-safe equality comparison.
      CASE WHEN occasion IS NOT DISTINCT FROM v_occ THEN 0 ELSE 1 END,
      CASE WHEN unit IS NOT DISTINCT FROM v_unit THEN 0 ELSE 1 END,
      CASE WHEN organization IS NOT DISTINCT FROM v_org THEN 0 ELSE 1 END,
      id -- Stable tie-breaker
    LIMIT 1
  ) t;

  -- Retrieve the most specific email wrapper using the same logic.
  SELECT to_jsonb(t)
  INTO email_wrapper
  FROM (
    SELECT
      ew.id,
      ew.title,
      ew.organization,
      ew.unit,
      ew.html,
      ew.created_at
    FROM public.email_wrappers ew
    WHERE (v_occ IS NULL OR ew.occasion IS NOT DISTINCT FROM v_occ OR ew.occasion IS NULL)
      AND (v_unit IS NULL OR ew.unit IS NOT DISTINCT FROM v_unit OR ew.unit IS NULL)
      AND (v_org IS NULL OR ew.organization IS NOT DISTINCT FROM v_org OR ew.organization IS NULL)
    ORDER BY
         CASE WHEN ew.occasion IS NOT DISTINCT FROM v_occ THEN 0 ELSE 1 END,
         CASE WHEN ew.unit IS NOT DISTINCT FROM v_unit THEN 0 ELSE 1 END,
         CASE WHEN ew.organization IS NOT DISTINCT FROM v_org THEN 0 ELSE 1 END,
         ew.id
    LIMIT 1
  ) t;

  -- Build the final result object, ensuring JSON nulls are used for missing records.
  result := jsonb_build_object(
              'template', COALESCE(email_template, 'null'::jsonb),
              'wrapper',  COALESCE(email_wrapper, 'null'::jsonb)
            );
  RETURN result;
END;
$$;


ALTER FUNCTION "public"."get_email_template_and_wrapper"("p_code" "text", "p_context" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_entity_email_templates"("p_entity_type" "text", "p_entity_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_occasion_id bigint;
    v_unit_id     bigint;
    v_org_id      bigint;

    context       jsonb;
    email_data    jsonb;

    occasion_data jsonb;
    unit_data     jsonb;
    org_data      jsonb;

    final_result  jsonb;
BEGIN
    -- 1. Resolve Hierarchy based on Entity Type
    IF p_entity_type = 'occasion' THEN
        v_occasion_id := p_entity_id;

        -- Get Unit & Org from Occasion
        SELECT unit, organization INTO v_unit_id, v_org_id
        FROM public.occasions WHERE id = v_occasion_id;

        IF v_unit_id IS NULL THEN
            RAISE EXCEPTION 'Occasion not found: %', p_entity_id;
        END IF;

    ELSIF p_entity_type = 'unit' THEN
        v_unit_id := p_entity_id;
        v_occasion_id := NULL;

        -- Get Org from Unit
        SELECT organization INTO v_org_id
        FROM public.units WHERE id = v_unit_id;

        IF v_org_id IS NULL THEN
            RAISE EXCEPTION 'Unit not found: %', p_entity_id;
        END IF;
    ELSE
        RAISE EXCEPTION 'Invalid entity type: %', p_entity_type;
    END IF;

    -- 2. Build Context for Template Retrieval
    context := jsonb_build_object(
        'occasion', v_occasion_id,
        'unit', v_unit_id,
        'organization', v_org_id
    );

    -- 3. Retrieve Templates (using core logic)
    email_data := public.get_all_email_templates(context);

    -- 4. Retrieve Entity Details for Response

    -- Organization
    SELECT jsonb_build_object('id', id, 'title', title, 'data', data)
    INTO org_data
    FROM public.organizations WHERE id = v_org_id;

    -- Unit
    SELECT jsonb_build_object('id', id, 'title', title, 'data', COALESCE(data, '{}'::jsonb), 'email', data->>'reply_to')
    INTO unit_data
    FROM public.units WHERE id = v_unit_id;

    -- Occasion (if applicable)
    IF v_occasion_id IS NOT NULL THEN
        SELECT jsonb_build_object('id', id, 'title', title, 'data', COALESCE(data, '{}'::jsonb), 'email', data->>'reply_to')
        INTO occasion_data
        FROM public.occasions WHERE id = v_occasion_id;
    ELSE
        occasion_data := NULL;
    END IF;

    -- 5. Build Final Result
    final_result := jsonb_build_object(
        'occasion',     occasion_data,
        'unit',         unit_data,
        'organization', org_data,
        'templates',    email_data
    );

    RETURN final_result;
END;
$$;


ALTER FUNCTION "public"."get_entity_email_templates"("p_entity_type" "text", "p_entity_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_event_command_data_v1"("p_event_id" bigint) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT jsonb_build_object(
    'id',e.id,'title',e.title,'startTime',e.start_time,'endTime',e.end_time,
    'maxParticipants',e.max_participants,'description',e.description,
    'placeId',e.place,'splitForMenWomen',e.split_for_men_women,
    'isGroupEvent',e.is_group_event,'isHidden',e.is_hidden,'type',e.type,
    'data',e.data,'order',e."order",
    'parentEventIds',COALESCE((SELECT jsonb_agg(g.event_parent ORDER BY g.event_parent)
      FROM public.event_groups g WHERE g.event_child=e.id),'[]'::jsonb),
    'eventRoleIds',COALESCE((SELECT jsonb_agg(r.role ORDER BY r.role)
      FROM public.event_roles r WHERE r.event=e.id),'[]'::jsonb))
  FROM public.events e WHERE e.id=p_event_id;
$$;


ALTER FUNCTION "public"."get_event_command_data_v1"("p_event_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_event_editor_v1"("p_occasion" bigint, "p_event" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_event jsonb; v_version bigint;
BEGIN
  IF NOT public.get_is_editor_view_on_occasion(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor view required';
  END IF;
  SELECT public.get_event_command_data_v1(e.id)||jsonb_build_object(
      'childEventIds',COALESCE((SELECT jsonb_agg(g.event_child ORDER BY g.event_child)
        FROM public.event_groups g WHERE g.event_parent=e.id),'[]'::jsonb)
    ),COALESCE(v.version,0)
    INTO v_event,v_version FROM public.events e
    LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='event'
      AND v.scope_type='occasion' AND v.scope_id=p_occasion
      AND v.aggregate_id=e.id::text
    WHERE e.id=p_event AND e.occasion=p_occasion;
  IF v_event IS NULL THEN RETURN jsonb_build_object('code',404,'data',NULL); END IF;
  RETURN jsonb_build_object('code',200,'data',jsonb_build_object(
    'version',v_version,'event',v_event));
END; $$;


ALTER FUNCTION "public"."get_event_editor_v1"("p_occasion" bigint, "p_event" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_event_feedback"("p_event" bigint, "p_client_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
    v_event public.events%ROWTYPE;
    v_user UUID := auth.uid();
    v_feedback public.event_feedback%ROWTYPE;
BEGIN
    SELECT *
    INTO v_event
    FROM public.events
    WHERE id = p_event
      AND is_hidden = false;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('code', 404, 'message', 'Event not found');
    END IF;

    IF NOT public.get_is_event_allowed(p_event) THEN
        RETURN jsonb_build_object('code', 403, 'message', 'Event is not available');
    END IF;

    IF NOT public.get_is_event_feedback_enabled_on_occasion(v_event.occasion) THEN
        RETURN jsonb_build_object('code', 404, 'message', 'Feedback feature is not enabled for this occasion');
    END IF;

    IF v_user IS NOT NULL THEN
        SELECT *
        INTO v_feedback
        FROM public.event_feedback
        WHERE event = p_event
          AND "user" = v_user
        LIMIT 1;
    ELSIF p_client_id IS NOT NULL THEN
        SELECT *
        INTO v_feedback
        FROM public.event_feedback
        WHERE event = p_event
          AND "user" IS NULL
          AND client_id = p_client_id
        LIMIT 1;
    ELSE
        RETURN jsonb_build_object('code', 200, 'data', NULL);
    END IF;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('code', 200, 'data', NULL);
    END IF;

    RETURN jsonb_build_object(
        'code', 200,
        'data', jsonb_build_object(
            'id', v_feedback.id,
            'event', v_feedback.event,
            'rating', v_feedback.rating,
            'note', v_feedback.note,
            'created_at', v_feedback.created_at,
            'updated_at', v_feedback.updated_at
        )
    );
END;
$$;


ALTER FUNCTION "public"."get_event_feedback"("p_event" bigint, "p_client_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_event_feedback_command_data_v1"("p_feedback" bigint) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT jsonb_build_object('id',f.id,'event',f.event,'rating',f.rating,
    'note',f.note,'created_at',f.created_at,'updated_at',f.updated_at)
  FROM public.event_feedback f WHERE f.id=p_feedback;
$$;


ALTER FUNCTION "public"."get_event_feedback_command_data_v1"("p_feedback" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_event_feedback_export_for_edit"("p_occasion" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
    v_items JSONB;
BEGIN
    IF NOT public.get_is_editor_view_on_occasion(p_occasion) THEN
        RETURN jsonb_build_object('code', 403, 'message', 'Insufficient permissions');
    END IF;

    IF NOT public.get_is_event_feedback_enabled_on_occasion(p_occasion) THEN
        RETURN jsonb_build_object('code', 404, 'message', 'Feedback feature is not enabled for this occasion');
    END IF;

    SELECT COALESCE(
        jsonb_agg(
            jsonb_build_object(
                'event_id', e.id,
                'event_title', e.title,
                'event_start_time', e.start_time,
                'event_end_time', e.end_time,
                'feedback_id', f.id,
                'created_at', f.created_at,
                'updated_at', f.updated_at,
                'rating', f.rating,
                'note', f.note,
                'user_name', NULLIF(btrim(CONCAT_WS(' ', ui.name, ui.surname)), ''),
                'is_anonymous', f."user" IS NULL
            )
            ORDER BY e.start_time ASC, e.title ASC, f.updated_at DESC
        ),
        '[]'::jsonb
    )
    INTO v_items
    FROM public.event_feedback f
    JOIN public.events e ON e.id = f.event
    LEFT JOIN public.user_info ui ON ui.id = f."user"
    WHERE f.occasion = p_occasion;

    RETURN jsonb_build_object('code', 200, 'data', v_items);
END;
$$;


ALTER FUNCTION "public"."get_event_feedback_export_for_edit"("p_occasion" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_event_feedback_for_edit"("p_event" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
    v_occasion BIGINT;
    v_summary JSONB;
    v_items JSONB;
BEGIN
    SELECT occasion
    INTO v_occasion
    FROM public.events
    WHERE id = p_event;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('code', 404, 'message', 'Event not found');
    END IF;

    IF NOT public.get_is_editor_view_on_occasion(v_occasion) THEN
        RETURN jsonb_build_object('code', 403, 'message', 'Insufficient permissions');
    END IF;

    IF NOT public.get_is_event_feedback_enabled_on_occasion(v_occasion) THEN
        RETURN jsonb_build_object('code', 404, 'message', 'Feedback feature is not enabled for this occasion');
    END IF;

    SELECT jsonb_build_object(
        'total', COUNT(*),
        'happy', COUNT(*) FILTER (WHERE rating = 'happy'),
        'neutral', COUNT(*) FILTER (WHERE rating = 'neutral'),
        'sad', COUNT(*) FILTER (WHERE rating = 'sad')
    )
    INTO v_summary
    FROM public.event_feedback
    WHERE event = p_event;

    SELECT COALESCE(
        jsonb_agg(
            jsonb_build_object(
                'id', f.id,
                'created_at', f.created_at,
                'updated_at', f.updated_at,
                'rating', f.rating,
                'note', f.note,
                'user_name', NULLIF(btrim(CONCAT_WS(' ', ui.name, ui.surname)), ''),
                'is_anonymous', f."user" IS NULL
            )
            ORDER BY f.updated_at DESC
        ),
        '[]'::jsonb
    )
    INTO v_items
    FROM public.event_feedback f
    LEFT JOIN public.user_info ui ON ui.id = f."user"
    WHERE f.event = p_event;

    RETURN jsonb_build_object(
        'code', 200,
        'data', jsonb_build_object(
            'summary', v_summary,
            'items', v_items
        )
    );
END;
$$;


ALTER FUNCTION "public"."get_event_feedback_for_edit"("p_event" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_event_participants_for_edit"("p_event" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_occasion bigint;
  v_participants jsonb;
BEGIN
  SELECT e.occasion
  INTO v_occasion
  FROM public.events e
  WHERE e.id = p_event;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('code', 404, 'message', 'Event not found');
  END IF;

  IF NOT (
    public.get_is_editor_view_on_occasion(v_occasion)
    OR public.get_is_editor_on_occasion(v_occasion)
    OR public.get_is_admin_on_occasion(v_occasion)
  ) THEN
    RETURN jsonb_build_object('code', 403, 'message', 'Insufficient permissions');
  END IF;

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'id', ui.id,
        'name', ui.name,
        'surname', ui.surname
      )
      ORDER BY ui.surname, ui.name, ui.id
    ),
    '[]'::jsonb
  )
  INTO v_participants
  FROM public.event_users eu
  JOIN public.user_info ui ON ui.id = eu."user"
  WHERE eu.event = p_event;

  RETURN jsonb_build_object('code', 200, 'data', v_participants);
END;
$$;


ALTER FUNCTION "public"."get_event_participants_for_edit"("p_event" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_events"("p_occasion" bigint, "p_include_description" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    current_user_id        UUID;
    eventsData             JSONB;
    placesData             JSONB;
    eventGroupsData        JSONB;
    eventRolesData         JSONB;
    eventUsersData         JSONB;
    eventUsersSavedData    JSONB;
BEGIN
    -- grab current_user_id user after entering PL/pgSQL execution
    current_user_id := auth.uid();

    -- (a) all non-hidden events, with per-user flags and conditional fields
    SELECT jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
        'id',                   e.id,
        'title',                e.title,
        'start_time',           e.start_time,
        'end_time',             e.end_time,
        'max_participants',     e.max_participants,
        'updated_at',           e.updated_at,
        'description',          CASE WHEN p_include_description THEN e.description ELSE NULL END,
        'type',                 e.type,
        'data',                 (SELECT COALESCE(jsonb_object_agg(key, value), '{}'::jsonb)
                                   FROM jsonb_each(e.data)
                                  WHERE value <> 'false'::jsonb),
        'place',                e.place,
        'split_for_men_women',  NULLIF(e.split_for_men_women, FALSE),
        'is_group_event',       NULLIF(e.is_group_event, FALSE),
        'isSignedIn',           NULLIF((current_user_id IS NOT NULL
                                   AND EXISTS (
                                     SELECT 1
                                       FROM public.event_users eu
                                      WHERE eu.event = e.id
                                        AND eu."user" = current_user_id
                                   )
                                ), FALSE),
        'isEventInMyProgram',   NULLIF((current_user_id IS NOT NULL
                                   AND EXISTS (
                                     SELECT 1
                                       FROM public.event_users_saved eus
                                      WHERE eus.event = e.id
                                        AND eus."user" = current_user_id
                                   )
                                ), FALSE)
    )))
    INTO eventsData
    FROM public.events e
    WHERE e.occasion   = p_occasion
      AND e.is_hidden = FALSE;

    -- (b) places for this occasion (unchanged)
    SELECT jsonb_agg(jsonb_build_object(
        'id',           p.id,
        'order',        p."order",
        'title',        p.title
    ))
    INTO placesData
    FROM public.places p
    WHERE p.occasion = p_occasion;

    -- (c) event_groups only for non-hidden events (unchanged)
    SELECT jsonb_agg(jsonb_build_object(
        'event_parent', eg.event_parent,
        'event_child',  eg.event_child
    ))
    INTO eventGroupsData
    FROM public.event_groups eg
    JOIN public.events e1 ON eg.event_parent = e1.id
    JOIN public.events e2 ON eg.event_child  = e2.id
    WHERE e1.occasion   = p_occasion AND e1.is_hidden = FALSE
      AND e2.occasion   = p_occasion AND e2.is_hidden = FALSE;

    -- (d) event_roles only on non-hidden events (unchanged)
    SELECT jsonb_agg(jsonb_build_object(
        'event', er.event,
        'role',  er.role
    ))
    INTO eventRolesData
    FROM public.event_roles er
    JOIN public.events e ON er.event = e.id
    WHERE e.occasion   = p_occasion
      AND e.is_hidden = FALSE;

    -- (e) signed-in counts for non-hidden events (unchanged)
    WITH user_counts AS (
      SELECT eu.event AS event, COUNT(*) AS cnt
      FROM public.event_users eu
      JOIN public.events e ON eu.event = e.id
      WHERE e.occasion   = p_occasion
        AND e.is_hidden = FALSE
      GROUP BY eu.event
    )
    SELECT jsonb_agg(jsonb_build_object(
      'event', uc.event,
      'count', uc.cnt
    ))
    INTO eventUsersData
    FROM user_counts uc;

    -- (f) saved-for-later counts for non-hidden events (unchanged)
    WITH saved_counts AS (
      SELECT eus.event AS event, COUNT(*) AS cnt
      FROM public.event_users_saved eus
      JOIN public.events e ON eus.event = e.id
      WHERE e.occasion   = p_occasion
        AND e.is_hidden = FALSE
      GROUP BY eus.event
    )
    SELECT jsonb_agg(jsonb_build_object(
      'event', sc.event,
      'count', sc.cnt
    ))
    INTO eventUsersSavedData
    FROM saved_counts sc;

    -- (g) final assembly (unchanged)
    RETURN jsonb_build_object(
      'code', 200,
      'data', jsonb_build_object(
        'events',            COALESCE(eventsData,          '[]'::jsonb),
        'places',            COALESCE(placesData,          '[]'::jsonb),
        'event_groups',      COALESCE(eventGroupsData,     '[]'::jsonb),
        'event_roles',       COALESCE(eventRolesData,      '[]'::jsonb),
        'event_users',       COALESCE(eventUsersData,      '[]'::jsonb),
        'event_users_saved', COALESCE(eventUsersSavedData, '[]'::jsonb)
      )
    );
END;
$$;


