CREATE OR REPLACE FUNCTION "public"."get_fetchable_bank_accounts_with_t_count"() RETURNS TABLE("bank_account_id" bigint, "bank_secret" "text", "account_type" "text", "transaction_count_last_90_days" integer)
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    ba.id,
    s.secret,
    ba.type,
    -- This subquery counts transactions for each fetchable bank account
    -- over the last 90 days.
    (SELECT COUNT(*)::INT
     FROM eshop.transactions t
     WHERE t.bank_account_id = ba.id
       -- The number of days has been hardcoded to 90.
       AND t."date" >= NOW() - MAKE_INTERVAL(days := 90)
    ) AS transaction_count_last_90_days
  FROM eshop.bank_accounts ba
  JOIN eshop.secrets s ON ba.secret = s.id
  WHERE ba.is_fetch_enabled = TRUE
    -- Check if last_fetch_time is either null or the waiting period has elapsed
    AND (ba.last_fetch_time IS NULL
         OR NOW() - ba.last_fetch_time >= (COALESCE(ba.min_fetch_wait_seconds, 0) || ' seconds')::INTERVAL)
    -- Ensure that the secret has not expired (if an expiry is set)
    AND (s.expiry_date IS NULL OR s.expiry_date > NOW());
END;
$$;


ALTER FUNCTION "public"."get_fetchable_bank_accounts_with_t_count"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_form"("form_key" "uuid") RETURNS "json"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    allData JSON;
    generated_secret UUID := gen_random_uuid();
BEGIN
    -- Check if the form is open
    IF NOT EXISTS (
        SELECT 1
        FROM public.forms
        WHERE key = form_key AND is_open = true
    ) THEN
        -- Return an error if the form is not open
        RETURN jsonb_build_object(
            'code', 400,
            'message', 'Form is not open.'
        );
    END IF;

    -- Build the query to fetch data if the form is open
    SELECT jsonb_build_object(
        'code', 200,
        'data', jsonb_build_object(
            'id', f.id,
            'key', f.key,
            'created_at', f.created_at,
            'data', f.data,
            'type', f.type,
            'header', f.header,
            'footer', f.footer,
            'occasion', f.occasion,
            'blueprint', f.blueprint,
            'deadline_duration_seconds', f.deadline_duration_seconds,
            'account_number', ba.account_number,
            'secret', generated_secret
        )
    )
    INTO allData
    FROM public.forms f
    LEFT JOIN eshop.bank_accounts ba ON f.bank_account = ba.id
    WHERE f.key = form_key;

    -- Return the result
    RETURN allData;
END;
$$;


ALTER FUNCTION "public"."get_form"("form_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_form_by_link"("form_link" "text") RETURNS "json"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
    allData JSON;
    generated_secret UUID := gen_random_uuid();
    form_exists BOOLEAN;
    is_editor_view BOOLEAN := false;
    occ_id BIGINT;
BEGIN
    -- Check if the form exists
    SELECT EXISTS (
        SELECT 1
        FROM public.forms
        WHERE link = form_link
    ) INTO form_exists;

    IF NOT form_exists THEN
        RETURN jsonb_build_object(
            'code', 404,
            'message', 'Form does not exist.'
        );
    END IF;

    SELECT occasion INTO occ_id FROM public.forms WHERE link = form_link;
    is_editor_view := public.get_is_editor_order_view_on_occasion(occ_id);


    IF NOT is_editor_view AND NOT EXISTS (
        SELECT 1
        FROM public.forms
        WHERE link = form_link AND is_open = true
    ) THEN
        -- If the form is closed, retrieve only the 'header_off' message
        SELECT jsonb_build_object(
            'code', 400,
            'data', jsonb_build_object(
                'header_off', f.header_off,
                'is_open', f.is_open
            )
        )
        INTO allData
        FROM public.forms f
        WHERE f.link = form_link;

        RETURN allData;
    END IF;

    -- If the form is open, retrieve the full form data including dynamic product availability
    SELECT jsonb_build_object(
        'code', 200,
        'data', jsonb_build_object(
            'id', f.id,
            'key', f.key,
            'created_at', f.created_at,
            'data', f.data,
            'type', f.type,
            'title', f.title,
            'is_open', f.is_open,
            'header', f.header,
            'header_off', f.header_off,
            'occasion', jsonb_build_object(
                'id', o.id,
                'features', o.features,
                'start_time', o.start_time
            ),
            'blueprint', f.blueprint,
            'deadline_duration_seconds', f.deadline_duration_seconds,
            'account_number', ba.account_number,
            'secret', generated_secret,
            'fields', (
                SELECT jsonb_agg(
                    jsonb_build_object(
                        'id', ff.id,
                        'title', ff.title,
                        'description', ff.description,
                        'data', ff.data,
                        'type', ff.type,
                        'is_required', ff.is_required,
                        'is_hidden', ff.is_hidden,
                        'is_ticket_field', ff.is_ticket_field,
                        'order', ff."order",
                        'product_type_data', (
                            CASE
                                WHEN ff.product_type IS NOT NULL THEN
                                    jsonb_build_object(
                                        'id', pt.id,
                                        'title', pt.title,
                                        'description', pt.description,
                                        'type', pt.type,
                                        'data', pt.data,
                                        'occasion', pt.occasion,
                                        'products', (
                                            SELECT jsonb_agg(
                                                jsonb_build_object(
                                                    'id', p.id,
                                                    'title', p.title,
                                                    'description', p.description,
                                                    'price', p.price,
                                                    'currency_code', p.currency_code,
                                                    'data', p.data,
                                                    'order', p."order",
                                                    'ordered_count', (
                                                        SELECT count(*)
                                                        FROM eshop.order_product_ticket opt
                                                        WHERE opt.product = p.id
                                                    ),
                                                    'maximum', p.maximum,
                                                    'is_dynamically_available', is_product_dynamically_available(p.id)
                                                ) ORDER BY COALESCE(p."order", 0)
                                            )
                                            FROM eshop.products p
                                            WHERE p.product_type = pt.id
                                              AND NOT p.is_hidden
                                        )
                                    )
                                ELSE NULL
                            END
                        )
                    ) ORDER BY COALESCE(ff."order", 0)
                )
                FROM public.form_fields ff
                LEFT JOIN eshop.product_types pt ON ff.product_type = pt.id
                WHERE ff.form = f.id AND ff.is_hidden = false
            )
        )
    )
    INTO allData
    FROM public.forms f
    LEFT JOIN eshop.bank_accounts ba ON f.bank_account = ba.id
    LEFT JOIN public.occasions o ON f.occasion = o.id
    WHERE f.link = form_link;

    RETURN allData;
END;
$$;


ALTER FUNCTION "public"."get_form_by_link"("form_link" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_form_fields"("p_form_link" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    form_id INT;
    fieldsData JSONB;
    productTypesData JSONB;
BEGIN
    -- Retrieve the form ID from the form link.
    SELECT id
    INTO form_id
    FROM public.forms
    WHERE link = p_form_link;

    -- Validate that the form exists.
    IF form_id IS NULL THEN
        RETURN jsonb_build_object('code', 404, 'message', 'Form not found');
    END IF;

    -- Retrieve the form fields associated with the form.
    -- (Filtering out ticket fields by checking a Boolean column and a specific type value)
    SELECT jsonb_agg(
         jsonb_build_object(
            'id', ff.id,
            'created_at', ff.created_at,
            'title', ff.title,
            'description', ff.description,
            'data', ff.data,
            'type', ff.type,
            'is_required', ff.is_required,
            'form', ff.form,
            'is_hidden', ff.is_hidden,
            'order', ff.order,
            'product_type', ff.product_type,
            'is_ticket_field', ff.is_ticket_field
         )
    )
    INTO fieldsData
    FROM public.form_fields ff
    WHERE ff.form = form_id
      AND ff.is_ticket_field = FALSE
      AND ff.type <> 'ticket';  -- Adjust this filter as needed.

    -- Retrieve product types for those fields.
    SELECT jsonb_agg(
         jsonb_build_object(
            'id', pt.id,
            'name', pt.name,
            'description', pt.description
         )
    )
    INTO productTypesData
    FROM public.product_types pt
    WHERE pt.id IN (
        SELECT DISTINCT ff.product_type
        FROM public.form_fields ff
        WHERE ff.form = form_id
    );

    -- Return combined data as JSON.
    RETURN jsonb_build_object(
        'code', 200,
        'data', jsonb_build_object(
            'fields', COALESCE(fieldsData, '[]'::jsonb),
            'product_types', COALESCE(productTypesData, '[]'::jsonb)
        )
    );
END;
$$;


ALTER FUNCTION "public"."get_form_fields"("p_form_link" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_form_for_edit"("form_link" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_form_id BIGINT;
    v_occasion_id BIGINT;
    v_unit_id BIGINT;
    v_organization_id BIGINT;
    v_phone_prefixes TEXT[];
    formData JSONB;
    formFieldsData JSONB;
    productTypesData JSONB;
    productsData JSONB;
    availableBankAccountsData JSONB;
    canDelete BOOLEAN;
BEGIN
    SELECT
        f.id,
        f.occasion,
        o.unit,
        o.organization
    INTO
        v_form_id,
        v_occasion_id,
        v_unit_id,
        v_organization_id
    FROM public.forms f
    JOIN public.occasions o ON f.occasion = o.id
    WHERE f.link = form_link;

    IF v_form_id IS NULL THEN
        RETURN jsonb_build_object('code', 404, 'message', 'Form not found for the provided link.');
    END IF;

    PERFORM check_is_editor_order_view_via_form_link(form_link);

    -- Calculate can_delete
    SELECT NOT EXISTS (
        SELECT 1 FROM eshop.orders WHERE form = v_form_id
    ) INTO canDelete;

    -- Fetch organization phone prefixes
    SELECT phone_prefixes INTO v_phone_prefixes
    FROM public.organizations
    WHERE id = v_organization_id;

    SELECT jsonb_build_object(
        'id', f.id,
        'key', f.key,
        'is_open', f.is_open,
        'created_at', f.created_at,
        'data', f.data || jsonb_build_object('phone_prefixes', v_phone_prefixes), -- Inject phone_prefixes into data
        'type', f.type,
        'title', f.title,
        'header', f.header,
        'header_off', f.header_off,
        'occasion', f.occasion,
        'blueprint', f.blueprint,
        'link', f.link,
        'bank_account', f.bank_account,
        'deadline_duration_seconds', f.deadline_duration_seconds,
        'can_delete', canDelete
    )
    INTO formData
    FROM public.forms f
    WHERE f.id = v_form_id;

    SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
            'id', ff.id,
            'form', ff.form,
            'title', ff.title,
            'description', ff.description,
            'data', ff.data,
            'type', ff.type,
            'is_required', ff.is_required,
            'is_hidden', ff.is_hidden,
            'is_ticket_field', ff.is_ticket_field,
            'order', ff."order",
            'product_type', ff.product_type
        ) ORDER BY COALESCE(ff."order", 0)
    ), '[]'::jsonb)
    INTO formFieldsData
    FROM public.form_fields ff
    WHERE ff.form = v_form_id;

    SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
            'id', pt.id,
            'title', pt.title,
            'description', pt.description,
            'type', pt.type,
            'data', pt.data,
            'occasion', pt.occasion
        ) ORDER BY pt.title
    ), '[]'::jsonb)
    INTO productTypesData
    FROM eshop.product_types pt
    WHERE pt.occasion = v_occasion_id;

    SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
            'id', p.id,
            'occasion', p.occasion,
            'title', p.title,
            'description', p.description,
            'price', p.price,
            'currency_code', p.currency_code,
            'is_hidden', p.is_hidden,
            'order', p."order",
            'product_type', p.product_type,
            'ordered_count', (
                SELECT count(*)
                FROM eshop.order_product_ticket opt
                JOIN eshop.orders o ON opt."order" = o.id
                WHERE opt.product = p.id AND o.state <> 'storno'
            ),
            'maximum', p.maximum,
            'data', p.data
        ) ORDER BY COALESCE(p."order", 0)
    ), '[]'::jsonb)
    INTO productsData
    FROM eshop.products p
    WHERE p.product_type IN (SELECT id FROM eshop.product_types WHERE occasion = v_occasion_id);

    SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
            'id', ba.id,
            'account_number', ba.account_number,
            'account_number_human_readable', ba.account_number_human_readable,
            'title', ba.title,
            'supported_currencies', ba.supported_currencies,
            'type', ba.type
        ) ORDER BY uba.priority ASC, ba.id ASC
    ), '[]'::jsonb)
    INTO availableBankAccountsData
    FROM eshop.unit_bank_accounts uba
    JOIN eshop.bank_accounts ba ON uba.bank_account = ba.id
    WHERE uba.unit = v_unit_id
      AND (ba.type IS DISTINCT FROM 'CASH');

    RETURN jsonb_build_object(
        'code', 200,
        'data', jsonb_build_object(
            'form', formData,
            'form_fields', formFieldsData,
            'product_types', productTypesData,
            'products', productsData,
            'available_bank_accounts', availableBankAccountsData
        )
    );
END;
$$;


ALTER FUNCTION "public"."get_form_for_edit"("form_link" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_form_from_link"("form_link" "text") RETURNS "json"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    allData JSON;
    generated_secret UUID := gen_random_uuid();
    form_exists BOOLEAN;
BEGIN
    -- Check if the form exists
    SELECT EXISTS (
        SELECT 1
        FROM public.forms
        WHERE link = form_link
    ) INTO form_exists;

    IF NOT form_exists THEN
        RETURN jsonb_build_object(
            'code', 404,
            'message', 'Form does not exist.'
        );
    END IF;

    -- Check if the form is open
    IF NOT EXISTS (
        SELECT 1
        FROM public.forms
        WHERE link = form_link AND is_open = true
    ) THEN
        -- Retrieve only the header_off when the form is not open
        SELECT jsonb_build_object(
            'code', 400,
            'data', jsonb_build_object(
                'header_off', f.header_off
            )
        )
        INTO allData
        FROM public.forms f
        WHERE f.link = form_link;

        RETURN allData;
    END IF;

    -- Retrieve full form data when the form is open
    SELECT jsonb_build_object(
        'code', 200,
        'data', jsonb_build_object(
            'id', f.id,
            'key', f.key,
            'created_at', f.created_at,
            'data', f.data,
            'type', f.type,
            'title', f.title,
            'header', f.header,
            'header_off', f.header_off,
            'occasion', f.occasion,
            'blueprint', f.blueprint,
            'deadline_duration_seconds', f.deadline_duration_seconds,
            'account_number', ba.account_number,
            'secret', generated_secret,
            'fields', (
                SELECT jsonb_agg(
                    jsonb_build_object(
                        'id', ff.id,
                        'title', ff.title,
                        'description', ff.description,
                        'data', ff.data,
                        'type', ff.type,
                        'is_required', ff.is_required,
                        'is_hidden', ff.is_hidden,
                        'is_ticket_field', ff.is_ticket_field,
                        'order', ff."order",
                        'product_type_data', (
                            CASE
                                WHEN ff.product_type IS NOT NULL THEN
                                    jsonb_build_object(
                                        'id', pt.id,
                                        'title', pt.title,
                                        'description', pt.description,
                                        'type', pt.type,
                                        'data', pt.data,
                                        'occasion', pt.occasion,
                                        'products', (
                                            SELECT jsonb_agg(
                                                jsonb_build_object(
                                                    'id', p.id,
                                                    'title', p.title,
                                                    'description', p.description,
                                                    'price', p.price,
                                                    'currency_code', p.currency_code,
                                                    'order', p."order",
                                                    'ordered_count', (
                                                        SELECT count(*)
                                                        FROM eshop.order_product_ticket opt
                                                        WHERE opt.product = p.id
                                                    ),
                                                    'maximum', p.maximum
                                                ) ORDER BY COALESCE(p."order", 0)
                                            )
                                            FROM eshop.products p
                                            WHERE p.product_type = pt.id
                                              AND NOT p.is_hidden
                                        )
                                    )
                                ELSE NULL
                            END
                        )
                    ) ORDER BY COALESCE(ff."order", 0)
                )
                FROM public.form_fields ff
                LEFT JOIN eshop.product_types pt ON ff.product_type = pt.id
                WHERE ff.form = f.id AND ff.is_hidden = false
            )
        )
    )
    INTO allData
    FROM public.forms f
    LEFT JOIN eshop.bank_accounts ba ON f.bank_account = ba.id
    WHERE f.link = form_link;

    RETURN allData;
END;
$$;


ALTER FUNCTION "public"."get_form_from_link"("form_link" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_form_from_link_for_edit"("form_link" "text") RETURNS "json"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    allData JSON;
BEGIN

    PERFORM check_is_editor_order_view_via_form_link(form_link);

    SELECT jsonb_build_object(
        'code', 200,
        'data', jsonb_build_object(
            'id', f.id,
            'key', f.key,
            'is_open', f.is_open,
            'created_at', f.created_at,
            'data', f.data,
            'type', f.type,
            'header', f.header,
            'header_off', f.header_off,
            'occasion', f.occasion,
            'blueprint', f.blueprint,
            'link', f.link,
            -- Return full bank_account details as JSON instead of just the id:
            'bank_account', jsonb_build_object(
                                'account_number', ba.account_number,
                                'account_number_human_readable', ba.account_number_human_readable,
                                'title', ba.title,
                                'supported_currencies', ba.supported_currencies
                            ),
            'deadline_duration_seconds', f.deadline_duration_seconds,
            -- Optionally, if you want to keep the account_number separately, you can leave it:
            'account_number', ba.account_number,
            'available_bank_accounts', (
                SELECT jsonb_agg(
                    jsonb_build_object(
                        'account_number', ba_inner.account_number,
                        'account_number_human_readable', ba_inner.account_number_human_readable,
                        'title', ba_inner.title,
                        'supported_currencies', ba_inner.supported_currencies
                    )
                )
                FROM eshop.unit_bank_accounts uba
                JOIN eshop.bank_accounts ba_inner ON uba.bank_account = ba_inner.id
                WHERE uba.unit = (
                    SELECT o.unit
                    FROM public.occasions o
                    WHERE o.id = f.occasion
                )
            ),
            'fields', (
                SELECT jsonb_agg(
                    jsonb_build_object(
                        'id', ff.id,
                        'title', ff.title,
                        'description', ff.description,
                        'data', ff.data,
                        'type', ff.type,
                        'is_required', ff.is_required,
                        'is_hidden', ff.is_hidden,
                        'is_ticket_field', ff.is_ticket_field,
                        'order', ff."order",
                        'product_type_data', (
                            CASE
                                WHEN ff.product_type IS NOT NULL THEN
                                    jsonb_build_object(
                                        'id', pt.id,
                                        'title', pt.title,
                                        'description', pt.description,
                                        'type', pt.type,
                                        'data', pt.data,
                                        'occasion', pt.occasion,
                                        'products', (
                                            SELECT jsonb_agg(
                                                jsonb_build_object(
                                                    'id', p.id,
                                                    'occasion', p.occasion,
                                                    'title', p.title,
                                                    'description', p.description,
                                                    'price', p.price,
                                                    'currency_code', p.currency_code,
                                                    'is_hidden', p.is_hidden,
                                                    'order', p."order",
                                                    'ordered_count', (
                                                        SELECT count(*)
                                                        FROM eshop.order_product_ticket opt
                                                        WHERE opt.product = p.id
                                                    ),
                                                    'maximum', p.maximum
                                                ) ORDER BY COALESCE(p."order", 0)
                                            )
                                            FROM eshop.products p
                                            WHERE p.product_type = pt.id
                                        )
                                    )
                                ELSE NULL
                            END
                        )
                    ) ORDER BY COALESCE(ff."order", 0)
                )
                FROM public.form_fields ff
                LEFT JOIN eshop.product_types pt ON ff.product_type = pt.id
                WHERE ff.form = f.id
            )
        )
    )
    INTO allData
    FROM public.forms f
    LEFT JOIN eshop.bank_accounts ba ON f.bank_account = ba.id
    WHERE f.link = form_link;

    RETURN allData;
END;
$$;


ALTER FUNCTION "public"."get_form_from_link_for_edit"("form_link" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_forms_by_link"("occasion_link" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_occasion_id BIGINT;
    forms_data JSONB;
BEGIN
    -- Step 1: Resolve the occasion ID from the provided link.
    SELECT id
    INTO v_occasion_id
    FROM public.occasions
    WHERE link = occasion_link;

    -- Step 2: If no occasion is found, throw a 'no_data_found' exception.
    IF v_occasion_id IS NULL THEN
        RAISE EXCEPTION 'Occasion not found for link: %', occasion_link USING ERRCODE = 'PGRST001'; -- Custom error for PostgREST
    END IF;

    -- Step 3: Verify if the user has editor rights for this occasion.
    -- If not, throw an 'insufficient_privilege' exception.
    IF NOT (get_is_editor_view_on_occasion(v_occasion_id) OR get_is_editor_order_view_on_occasion(v_occasion_id)) THEN
        RAISE EXCEPTION 'User is not authorized to view forms for this occasion.' USING ERRCODE = '42501'; -- insufficient_privilege
    END IF;

    -- Step 4: Aggregate forms for the occasion into a JSONB array.
    -- The order statistics are nested within a 'stats' JSON object.
    SELECT jsonb_agg(
        jsonb_build_object(
            'id', f.id,
            'created_at', f.created_at,
            'title', f.title,
            'data', f.data,
            'key', f.key,
            'occasion', f.occasion,
            'type', f.type,
            'is_open', f.is_open,
            'link', f.link,
            'blueprint', f.blueprint,
            'updated_at', f.updated_at,
            'stats', jsonb_build_object(
                'total', COALESCE(order_stats.total, 0),
                'storno', COALESCE(order_stats.storno, 0),
                'paid_or_sent', COALESCE(order_stats.paid_or_sent, 0),
                'ordered', COALESCE(order_stats.ordered, 0)
            )
        ) ORDER BY f.created_at
    )
    INTO forms_data
    FROM public.forms f
    LEFT JOIN (
        -- This subquery calculates all required counts in a single pass over the orders table.
        SELECT
            (data->>'form')::uuid AS form_key,
            COUNT(*) AS total,
            COUNT(*) FILTER (WHERE state = 'storno') AS storno,
            COUNT(*) FILTER (WHERE state IN ('paid', 'sent')) AS paid_or_sent,
            COUNT(*) FILTER (WHERE state = 'ordered') AS ordered
        FROM eshop.orders
        WHERE data->>'form' IS NOT NULL -- Ensure the key exists before casting
        GROUP BY form_key
    ) AS order_stats ON f.key = order_stats.form_key
    WHERE f.occasion = v_occasion_id;

    -- Step 5: If no forms were found, ensure an empty JSON array is returned.
    IF forms_data IS NULL THEN
        forms_data := '[]'::jsonb;
    END IF;

    -- Step 6: Return the data directly.
    RETURN forms_data;
END;
$$;


ALTER FUNCTION "public"."get_forms_by_link"("occasion_link" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_inclusion_type_groups_by_link"("p_occasion_link" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_occasion_id bigint;
    v_occasion_data jsonb;
    v_groups_data jsonb;
    result jsonb;
BEGIN
    -- Find the occasion ID from the provided link.
    SELECT id INTO v_occasion_id FROM public.occasions WHERE link = p_occasion_link;
    IF v_occasion_id IS NULL THEN
        RAISE EXCEPTION 'Occasion with link % not found.', p_occasion_link;
    END IF;

    -- Permission check to ensure the user can view data for this occasion.
    IF NOT get_is_editor_order_view_on_occasion(v_occasion_id) THEN
        RAISE EXCEPTION 'User is not authorized to view this occasion.';
    END IF;

    -- Get the occasion details.
    SELECT to_jsonb(o) INTO v_occasion_data FROM public.occasions o WHERE id = v_occasion_id;

    -- Aggregate all groups for the occasion, and for each group, aggregate its inclusion types.
    SELECT COALESCE(jsonb_agg(groups_with_types), '[]'::jsonb)
    INTO v_groups_data
    FROM (
        SELECT
            jsonb_build_object(
                'id', g.id,
                'created_at', g.created_at,
                'updated_at', g.updated_at,
                'title', g.title,
                'type', g.type,
                'occasion', g.occasion,
                'inclusion_types', (
                    SELECT COALESCE(jsonb_agg(
                        jsonb_build_object(
                            'id', t.id,
                            'created_at', t.created_at,
                            'updated_at', t.updated_at,
                            'title', t.title,
                            'inclusion_type_group', t.inclusion_type_group,
                            'data', t.data
                        ) ORDER BY t.created_at
                    ), '[]'::jsonb)
                    FROM public.inclusion_types t
                    WHERE t.inclusion_type_group = g.id
                )
            ) AS groups_with_types
        FROM public.inclusion_type_groups g
        WHERE g.occasion = v_occasion_id
        ORDER BY g.created_at
    ) AS subquery;

    -- Construct the final bundle.
    result := jsonb_build_object(
        'occasion', v_occasion_data,
        'groups', v_groups_data
    );

    RETURN result;
EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object('code', 500, 'message', SQLERRM);
END;
$$;


ALTER FUNCTION "public"."get_inclusion_type_groups_by_link"("p_occasion_link" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_information_command_data_v1"("p_information_id" bigint) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT to_jsonb(i)||jsonb_build_object('information_hidden',CASE
    WHEN ih.id IS NULL THEN NULL ELSE jsonb_build_object('id',ih.id,'data',ih.data) END)
  FROM public.information i LEFT JOIN public.information_hidden ih
    ON ih.id=i.information_hidden WHERE i.id=p_information_id;
$$;


ALTER FUNCTION "public"."get_information_command_data_v1"("p_information_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_information_editor_bundle_v1"("p_occasion" bigint, "p_type" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_information jsonb;
BEGIN
  IF NOT public.get_is_editor_view_on_occasion(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor view required';
  END IF;
  SELECT COALESCE(jsonb_agg(public.get_information_command_data_v1(i.id)||
    jsonb_build_object('aggregate_version',COALESCE(v.version,0))
    ORDER BY i."order" NULLS LAST,i.id),'[]'::jsonb) INTO v_information
  FROM public.information i LEFT JOIN public.client_aggregate_versions v
    ON v.aggregate_type='information' AND v.scope_type='occasion'
    AND v.scope_id=p_occasion AND v.aggregate_id=i.id::text
  WHERE i.occasion=p_occasion AND (CASE WHEN p_type IS NULL
    THEN NULLIF(i.type,'') IS NULL ELSE i.type=p_type END);
  RETURN jsonb_build_object('code',200,'information',v_information);
END; $$;


ALTER FUNCTION "public"."get_information_editor_bundle_v1"("p_occasion" bigint, "p_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_inventory_pool_bundle"("p_inventory_pool_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_occasion_id bigint;
    v_pool_data jsonb;
    v_occasion_data jsonb;
    v_resources_data jsonb;
    v_contexts_data jsonb;
    v_places_data jsonb;
    v_products_data jsonb;
    v_product_inventory_contexts_data jsonb; -- New variable for the join table data
    result jsonb;
BEGIN
    -- Get occasion for permission check from the inventory pool
    SELECT occasion INTO v_occasion_id
    FROM public.inventory_pools
    WHERE id = p_inventory_pool_id;

    IF v_occasion_id IS NULL THEN
        RAISE EXCEPTION 'Inventory Pool not found.';
    END IF;

    -- Permission check
    IF NOT get_is_editor_order_view_on_occasion(v_occasion_id) THEN
        RAISE EXCEPTION 'User is not authorized to view this occasion.';
    END IF;

    -- Get the main inventory pool details
    SELECT to_jsonb(ip) INTO v_pool_data FROM public.inventory_pools ip WHERE ip.id = p_inventory_pool_id;

    -- Get the full occasion details
    SELECT to_jsonb(o) INTO v_occasion_data
    FROM public.occasions o
    WHERE o.id = v_occasion_id;

    -- Aggregate all resources for the pool, and for each resource, aggregate its slots.
    SELECT COALESCE(jsonb_agg(resources_with_slots), '[]'::jsonb)
    INTO v_resources_data
    FROM (
        SELECT
            jsonb_build_object(
                'id', r.id,
                'created_at', r.created_at,
                'updated_at', r.updated_at,
                'title', r.title,
                'description', r.description,
                'capacity', r.capacity,
                'booking_rules', r.booking_rules,
                'inventory_pool', r.inventory_pool,
                'place', r.place,
                'occasion', r.occasion,
                'unit', r.unit,
                'data', r.data,
                'slots', (
                    SELECT COALESCE(jsonb_agg(
                        jsonb_build_object(
                            'id', rs.id,
                            'resource', rs.resource,
                            'title', rs.title,
                            'data', rs.data
                        ) ORDER BY rs.id
                    ), '[]'::jsonb)
                    FROM public.resource_slots rs
                    WHERE rs.resource = r.id
                )
            ) AS resources_with_slots
        FROM public.resources r
        WHERE r.inventory_pool = p_inventory_pool_id
        ORDER BY r.title
    ) AS subquery;

    -- Aggregate all inventory contexts for the pool, sorted by the 'order' field
    SELECT COALESCE(jsonb_agg(to_jsonb(ic) ORDER BY ic.order), '[]'::jsonb)
    INTO v_contexts_data
    FROM public.inventory_contexts ic
    WHERE ic.inventory_pool = p_inventory_pool_id;

    -- Aggregate all places for the occasion
    SELECT COALESCE(jsonb_agg(to_jsonb(p) ORDER BY p.order), '[]'::jsonb)
    INTO v_places_data
    FROM public.places p
    WHERE p.occasion = v_occasion_id;

    -- MODIFICATION START
    -- Aggregate products that are linked to the inventory contexts of this specific pool.
    SELECT COALESCE(jsonb_agg(to_jsonb(pr)), '[]'::jsonb)
    INTO v_products_data
    FROM (
        SELECT DISTINCT pr.*
        FROM eshop.products pr
        JOIN eshop.product_inventory_contexts pic ON pr.id = pic.product
        JOIN public.inventory_contexts ic ON pic.inventory_context = ic.id
        WHERE ic.inventory_pool = p_inventory_pool_id
    ) pr;

    -- Aggregate the product <-> inventory_context join table entries for this pool's contexts.
    SELECT COALESCE(jsonb_agg(to_jsonb(pic)), '[]'::jsonb)
    INTO v_product_inventory_contexts_data
    FROM eshop.product_inventory_contexts pic
    JOIN public.inventory_contexts ic ON pic.inventory_context = ic.id
    WHERE ic.inventory_pool = p_inventory_pool_id;

    -- Construct the final bundle object, now including context-specific products and the join table data.
    result := jsonb_build_object(
        'pool', v_pool_data,
        'occasion', v_occasion_data,
        'resources', v_resources_data,
        'contexts', v_contexts_data,
        'places', v_places_data,
        'products', v_products_data,
        'product_inventory_contexts', v_product_inventory_contexts_data
    );
    -- MODIFICATION END

    RETURN result;
EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object('code', 500, 'message', SQLERRM);
END;
$$;


ALTER FUNCTION "public"."get_inventory_pool_bundle"("p_inventory_pool_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_inventory_pools_by_occasion_link"("p_occasion_link" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_occasion_id bigint;
    v_occasion_data jsonb;
    v_pools_data jsonb;
    v_inventory_contexts_data jsonb;
    v_spots_data jsonb;
    result jsonb;
BEGIN
    -- Find the occasion ID from the provided link.
    SELECT id INTO v_occasion_id FROM public.occasions WHERE link = p_occasion_link;
    IF v_occasion_id IS NULL THEN
        RAISE EXCEPTION 'Occasion with link % not found.', p_occasion_link;
    END IF;

    -- Permission check to ensure the user can view data for this occasion.
    IF NOT get_is_editor_order_view_on_occasion(v_occasion_id) THEN
        RAISE EXCEPTION 'User is not authorized to view this occasion.';
    END IF;

    -- Get the full occasion object
    SELECT to_jsonb(o) INTO v_occasion_data FROM public.occasions o WHERE id = v_occasion_id;

    -- Aggregate all inventory pools for the occasion, sorted by creation date.
    SELECT COALESCE(jsonb_agg(to_jsonb(ip) ORDER BY ip.created_at), '[]'::jsonb)
    INTO v_pools_data
    FROM public.inventory_pools ip
    WHERE ip.occasion = v_occasion_id;

    -- Aggregate all inventory_contexts for all pools of the occasion, sorted by the 'order' column.
    SELECT COALESCE(jsonb_agg(to_jsonb(ic) ORDER BY ic.order), '[]'::jsonb)
    INTO v_inventory_contexts_data
    FROM public.inventory_contexts ic
    WHERE ic.inventory_pool IN (SELECT id FROM public.inventory_pools WHERE occasion = v_occasion_id);

    -- Aggregate all spots that belong to any context within the occasion's pools
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'secret', s.secret,
        'secret_expiration_time', s.secret_expiration_time,
        'order_product_ticket', s.order_product_ticket,
        'inventory_context', s.inventory_context,
        'resource', s.resource,
        'state', s.state
    ) ORDER BY s.id), '[]'::jsonb)
    INTO v_spots_data
    FROM eshop.spots s
    WHERE s.inventory_context IN (
        SELECT id FROM public.inventory_contexts WHERE inventory_pool IN (
            SELECT id FROM public.inventory_pools WHERE occasion = v_occasion_id
        )
    );

    -- Construct the final bundle object with the new data
    result := jsonb_build_object(
        'occasion', v_occasion_data,
        'pools', v_pools_data,
        'inventory_contexts', v_inventory_contexts_data,
        'spots', v_spots_data
    );

    RETURN result;
EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object('code', 500, 'message', SQLERRM);
END;
$$;


ALTER FUNCTION "public"."get_inventory_pools_by_occasion_link"("p_occasion_link" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_is_admin_on_occasion"("oc" bigint) RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
    is_admin_var boolean;
    organization_id bigint;
BEGIN
    -- Retrieve the organization ID associated with the given occasion
    SELECT organization INTO organization_id
    FROM occasions
    WHERE id = oc;

    -- Check if the current authenticated user is an admin in the organization
    SELECT is_admin INTO is_admin_var
    FROM organization_users
    WHERE organization = organization_id
      AND "user" = auth.uid();

    -- Return true if the user is an admin, otherwise false
    RETURN COALESCE(is_admin_var, false);
END;
$$;


