CREATE OR REPLACE FUNCTION "public"."get_private_profile_payload_v1"("p_occasion" bigint, "p_user" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
  SELECT jsonb_build_object(
    'user',(SELECT jsonb_build_object('id',u.id,'email',u.email_readonly,
      'name',u.name,'surname',u.surname,'sex',u.sex,'phone',u.phone,
      'birthDate',u.birth_date,'data',u.data) FROM public.user_info u
      WHERE u.id=p_user),
    'occasion',(SELECT jsonb_build_object('role',ou.role,'services',ou.services,
      'data',ou.data,'isCleaningBlocked',ou.is_cleaning_blocked,
      'isCleaningCrew',ou.is_cleaning_crew) FROM public.occasion_users ou
      WHERE ou.occasion=p_occasion AND ou."user"=p_user),
    'companions',COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'id',ui.id,'name',ui.name,'surname',COALESCE(ui.surname,''),
      'group_title',COALESCE(groups.titles,''),'origin',uc.origin,
      'can_owner_delete',uc.origin='self_created',
      'services',COALESCE(companion_membership.services,'{}'::jsonb),
      'event_ids',COALESCE((SELECT jsonb_agg(eu.event ORDER BY eu.event)
        FROM public.event_users eu JOIN public.events e ON e.id=eu.event
        WHERE eu."user"=ui.id AND e.occasion=p_occasion),'[]'::jsonb))
      ORDER BY ui.name,ui.surname,ui.id)
      FROM public.user_companions uc
      JOIN public.user_info ui ON ui.id=uc.companion
      JOIN public.occasion_users companion_membership
        ON companion_membership.occasion=uc.occasion
       AND companion_membership."user"=uc.companion
      LEFT JOIN LATERAL (SELECT string_agg(ugi.title,', ' ORDER BY ugi.title) titles
        FROM public.user_groups ug JOIN public.user_group_info ugi ON ugi.id=ug."group"
        WHERE ug."user"=uc.companion AND ugi.occasion=p_occasion
          AND ugi.type IS NULL) groups ON true
      WHERE uc.occasion=p_occasion AND uc."user"=p_user),'[]'::jsonb),
    'groups',COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'id',g.id,'title',g.title,'description',g.description,'type',g.type,
      'data',g.data,'place',g.place,'isAdmin',mine.is_admin,
      'participants',COALESCE((SELECT jsonb_agg(jsonb_build_object(
        'userId',members."user",'isAdmin',members.is_admin,
        'name',ui.name,'surname',ui.surname) ORDER BY members."user")
        FROM public.user_groups members JOIN public.user_info ui
          ON ui.id=members."user" WHERE members."group"=g.id),'[]'::jsonb),
      'placeData',(SELECT to_jsonb(p) FROM public.places p WHERE p.id=g.place))
      ORDER BY g.id) FROM public.user_groups mine JOIN public.user_group_info g
        ON g.id=mine."group" WHERE mine."user"=p_user
        AND g.occasion=p_occasion),'[]'::jsonb));
$$;


ALTER FUNCTION "public"."get_private_profile_payload_v1"("p_occasion" bigint, "p_user" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_products_and_types"("p_occasion_id" bigint) RETURNS "json"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  product_types json;
  products json;
BEGIN
  -- Fetch product types filtered by occasion.
  SELECT json_agg(
           json_build_object(
             'id', pt.id,
             'type', pt.type
           )
         )
    INTO product_types
  FROM eshop.product_types pt
  WHERE pt.occasion = p_occasion_id;

  -- Fetch products whose product_type is in the filtered product types.
  SELECT json_agg(
           json_build_object(
             'id', p.id,
             'title', p.title,
             'short_title', p.data->>'short_title',
             'product_type', p.product_type,
             'data', p.data
           )
         )
    INTO products
  FROM eshop.products p
  WHERE p.product_type IN (
    SELECT pt.id
    FROM eshop.product_types pt
    WHERE pt.occasion = p_occasion_id
  );

  RETURN json_build_object(
    'product_types', COALESCE(product_types, '[]'::json),
    'products', COALESCE(products, '[]'::json)
  );
END;
$$;


ALTER FUNCTION "public"."get_products_and_types"("p_occasion_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_products_and_types_for_edit"("occasion_link" "text") RETURNS "json"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  product_types json;
  products json;
  inventory_pools_data json;
  inventory_contexts_data json;
  product_inventory_contexts_data json;
  forms_data json;
  occ_id bigint;
BEGIN
  -- Resolve occasion_id from the provided occasion_link
  SELECT id
    INTO occ_id
  FROM public.occasions
  WHERE link = occasion_link;

  -- If the occasion link is invalid, raise an exception.
  IF occ_id IS NULL THEN
    RAISE EXCEPTION 'Occasion not found for link: %', occasion_link;
  END IF;

  -- Verify if the current user is an editor for the order's occasion
  IF NOT get_is_editor_order_view_on_occasion(occ_id) THEN
      RETURN jsonb_build_object('code', 403, 'message', 'User is not authorized to view this.');
  END IF;

  SELECT json_agg(
           json_build_object(
             'id', pt.id,
             'type', pt.type,
             'title', pt.title
           )
         )
    INTO product_types
  FROM eshop.product_types pt
  WHERE pt.occasion = occ_id;

  -- Fetch all products for the given occasion, including form IDs
  SELECT json_agg(
           json_build_object(
             'id', p.id,
             'title', p.title,
             'description', p.description,
             'short_title', p.data->>'short_title',
             'product_type', p.product_type,
             'data', p.data,
             'price', p.price,
             'currency_code', p.currency_code,
             'is_hidden', p.is_hidden,
             'order', p."order",
             'maximum', p.maximum,
             'form_ids', (
               SELECT COALESCE(json_agg(DISTINCT ff.form), '[]'::json)
               FROM public.form_fields ff
               WHERE ff.product_type = p.product_type
             ),
             'ordered_count', (
               SELECT count(*)
               FROM eshop.order_product_ticket opt
               WHERE opt.product = p.id
             ),
             'paid_count', (
               SELECT count(*)
               FROM eshop.order_product_ticket opt
               JOIN eshop.orders o ON o.id = opt.order
               WHERE opt.product = p.id
                 AND o.state = 'paid'
             ),
             'sent_count', (
               SELECT count(*)
               FROM eshop.order_product_ticket opt
               JOIN eshop.orders o ON o.id = opt.order
               WHERE opt.product = p.id
                 AND o.state = 'sent'
             )
           )
         )
    INTO products
  FROM eshop.products p
  WHERE p.product_type IN (
    SELECT pt.id
    FROM eshop.product_types pt
    WHERE pt.occasion = occ_id
  );

  -- Fetch all inventory pools for the occasion
  SELECT json_agg(ip.*)
  INTO inventory_pools_data
  FROM public.inventory_pools ip
  WHERE ip.occasion = occ_id;

  -- Fetch all inventory contexts for the occasion
  SELECT json_agg(ic.*)
  INTO inventory_contexts_data
  FROM public.inventory_contexts ic
  JOIN public.inventory_pools ip ON ic.inventory_pool = ip.id
  WHERE ip.occasion = occ_id;

  -- Fetch all links between products and inventory contexts for the occasion
  SELECT json_agg(pic.*)
  INTO product_inventory_contexts_data
  FROM eshop.product_inventory_contexts pic
  JOIN eshop.products p ON pic.product = p.id
  JOIN eshop.product_types pt ON p.product_type = pt.id
  WHERE pt.occasion = occ_id;

  -- Fetch only the id, title, and link for each form associated with the occasion
  SELECT json_agg(
           json_build_object(
             'id', f.id,
             'title', f.title,
             'link', f.link
           )
         )
    INTO forms_data
  FROM public.forms f
  WHERE f.occasion = occ_id;

  RETURN json_build_object(
    'product_types', COALESCE(product_types, '[]'::json),
    'products', COALESCE(products, '[]'::json),
    'inventory_pools', COALESCE(inventory_pools_data, '[]'::json),
    'inventory_contexts', COALESCE(inventory_contexts_data, '[]'::json),
    'product_inventory_contexts', COALESCE(product_inventory_contexts_data, '[]'::json),
    'forms', COALESCE(forms_data, '[]'::json)
  );
END;
$$;


ALTER FUNCTION "public"."get_products_and_types_for_edit"("occasion_link" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_products_and_types_for_occasion"("form_link" "text") RETURNS "json"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  product_types json;
  products json;
  occ_id bigint;
BEGIN
  PERFORM check_is_editor_order_view_via_form_link(form_link);

  SELECT f.occasion
    INTO occ_id
  FROM public.forms f
  WHERE f.link = form_link;

  SELECT json_agg(
           json_build_object(
             'id', pt.id,
             'type', pt.type,
             'title', pt.title
           )
         )
    INTO product_types
  FROM eshop.product_types pt
  WHERE pt.occasion = occ_id;

  SELECT json_agg(
           json_build_object(
             'id', p.id,
             'title', p.title,
             'description', p.description,
             'title_short', p.title_short,
             'product_type', p.product_type,
             'data', p.data,
             'price', p.price,
             'currency_code', p.currency_code,
             'is_hidden', p.is_hidden,
             'order', p."order",
             'maximum', p.maximum,
             'ordered_count', (
               SELECT count(*)
               FROM eshop.order_product_ticket opt
               WHERE opt.product = p.id
             ),
             'paid_count', (
               SELECT count(*)
               FROM eshop.order_product_ticket opt
               JOIN eshop.orders o ON o.id = opt.order
               WHERE opt.product = p.id
                 AND o.state = 'paid'
             ),
             'sent_count', (
               SELECT count(*)
               FROM eshop.order_product_ticket opt
               JOIN eshop.orders o ON o.id = opt.order
               WHERE opt.product = p.id
                 AND o.state = 'sent'
             )
           )
         )
    INTO products
  FROM eshop.products p
  WHERE p.product_type IN (
    SELECT pt.id
    FROM eshop.product_types pt
    WHERE pt.occasion = occ_id
  );

  RETURN json_build_object(
    'product_types', COALESCE(product_types, '[]'::json),
    'products', COALESCE(products, '[]'::json)
  );
END;
$$;


ALTER FUNCTION "public"."get_products_and_types_for_occasion"("form_link" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_products_and_types_from_occasion"("form_link" "text") RETURNS "json"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  product_types json;
  products json;
  occ_id bigint;
BEGIN
  PERFORM check_is_editor_order_view_via_form_link(form_link);

  SELECT f.occasion
    INTO occ_id
  FROM public.forms f
  WHERE f.link = form_link;

  SELECT json_agg(
           json_build_object(
             'id', pt.id,
             'type', pt.type
           )
         )
    INTO product_types
  FROM eshop.product_types pt
  WHERE pt.occasion = occ_id;

  SELECT json_agg(
           json_build_object(
             'id', p.id,
             'title', p.title,
             'title_short', p.title_short,
             'product_type', p.product_type,
             'data', p.data,
             'price', p.price,
             'currency_code', p.currency_code,
             'is_hidden', p.is_hidden,
             'order', p."order",
             'maximum', p.maximum,
             'ordered_count', (
               SELECT count(*)
               FROM eshop.order_product_ticket opt
               WHERE opt.product = p.id
             ),
             'paid_count', (
               SELECT count(*)
               FROM eshop.order_product_ticket opt
               JOIN eshop.orders o ON o.id = opt.order
               WHERE opt.product = p.id
                 AND o.state = 'paid'
             ),
             'sent_count', (
               SELECT count(*)
               FROM eshop.order_product_ticket opt
               JOIN eshop.orders o ON o.id = opt.order
               WHERE opt.product = p.id
                 AND o.state = 'sent'
             )
           )
         )
    INTO products
  FROM eshop.products p
  WHERE p.product_type IN (
    SELECT pt.id
    FROM eshop.product_types pt
    WHERE pt.occasion = occ_id
  );

  RETURN json_build_object(
    'product_types', COALESCE(product_types, '[]'::json),
    'products', COALESCE(products, '[]'::json)
  );
END;
$$;


ALTER FUNCTION "public"."get_products_and_types_from_occasion"("form_link" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_products_for_ticket"("ticket_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_occasion_id bigint;
  v_order_json jsonb;
  v_payment_info_json jsonb;
  v_ticket jsonb;
  v_latest_sent_at timestamptz;
  v_is_newer_available boolean := FALSE;
  v_order_id bigint;
  latest_history_data jsonb;
  reference_history_data jsonb;
BEGIN
  -- Find the order containing the ticket and LEFT JOIN its associated payment_info.
  SELECT
    o.id,
    o.occasion,
    to_jsonb(o),
    to_jsonb(pi)
  INTO
    v_order_id,
    v_occasion_id,
    v_order_json,
    v_payment_info_json
  FROM eshop.orders AS o
  LEFT JOIN eshop.payment_info AS pi ON o.payment_info = pi.id
  WHERE EXISTS (
    SELECT 1
    FROM   jsonb_array_elements(o.data->'tickets') AS t
    WHERE  (t->>'id')::bigint = ticket_id
  );

  -- Check if the order was found.
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'code',    404,
      'message', 'Ticket not found'
    );
  END IF;

  -- Permission check.
  IF NOT get_is_editor_order_view_on_occasion(v_occasion_id) THEN
    RETURN jsonb_build_object(
      'code',    403,
      'message', 'Not authorized to view this ticket'
    );
  END IF;

  -- Extract the full JSON object for the specified ticket from the order's data.
  SELECT t
  INTO   v_ticket
  FROM   jsonb_array_elements(v_order_json->'data'->'tickets') AS t
  WHERE  (t->>'id')::bigint = ticket_id;

  -- Get the data of the latest history entry
  SELECT data INTO latest_history_data
  FROM eshop.orders_history
  WHERE "order" = v_order_id
  ORDER BY created_at DESC LIMIT 1;

  -- Get the data and timestamp of the latest SENT history entry
  SELECT
    jsonb_build_object(
        'data', oh.data,
        'state', oh.state,
        'price', oh.price,
        'currency_code', oh.currency_code
    ),
    oh.created_at
  INTO reference_history_data, v_latest_sent_at
  FROM eshop.orders_history AS oh
  WHERE oh.order = v_order_id AND (oh.data->>'is_sent_to_customer')::boolean IS TRUE
  ORDER BY oh.created_at DESC LIMIT 1;

  -- If no sent record was found, get the oldest record as the reference
  IF NOT FOUND THEN
      SELECT jsonb_build_object(
        'data', oh.data,
        'state', oh.state,
        'price', oh.price,
        'currency_code', oh.currency_code
      )
      INTO reference_history_data
      FROM eshop.orders_history AS oh
      WHERE oh.order = v_order_id
      ORDER BY oh.created_at ASC LIMIT 1;
  END IF;

  -- Compare product IDs and prices between the latest and reference history entries
  IF latest_history_data IS NOT NULL AND reference_history_data IS NOT NULL THEN
      v_is_newer_available :=
          -- Use the new function to compare product sets including prices.
          -- This will return true if either the products or their prices have changed.
          extract_history_products_with_price(latest_history_data) <> extract_history_products_with_price(reference_history_data->'data');
  END IF;


  -- Build the simplified and comprehensive JSONB response object.
  RETURN jsonb_build_object(
    'code', 200,
    'data', jsonb_build_object(
      'ticket', v_ticket,
      'order', v_order_json,
      'payment_info', v_payment_info_json,
      'order_history', jsonb_build_object(
          'latest_sent_at', v_latest_sent_at,
          'is_newer_version_available', v_is_newer_available
      ),
      'reference_order_data', reference_history_data
    )
  );
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object(
    'code',    500,
    'message', SQLERRM
  );
END;
$$;


ALTER FUNCTION "public"."get_products_for_ticket"("ticket_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_products_for_ticket_all_available"("ticket_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_occasion_id bigint;
  v_available   jsonb;
BEGIN
  -- find the ticket’s occasion
  SELECT occasion
  INTO   v_occasion_id
  FROM   eshop.tickets
  WHERE  id = ticket_id;

  IF NOT FOUND OR v_occasion_id IS NULL THEN
    RETURN jsonb_build_object(
      'code',    404,
      'message', 'Ticket not found'
    );
  END IF;

  IF NOT get_is_editor_order_view_on_occasion(v_occasion_id) THEN
    RETURN jsonb_build_object(
      'code',    403,
      'message', 'Not authorized'
    );
  END IF;

  -- aggregate all products for that occasion
  SELECT jsonb_agg(
           jsonb_build_object(
             'id',            p.id,
             'title',         p.title,
             'price',         p.price,
             'currency_code', p.currency_code,
             'type_title',    pt.title
           )
         )
  INTO   v_available
  FROM   eshop.products p
  LEFT JOIN eshop.product_types pt
    ON pt.id = p.product_type
  WHERE  p.occasion = v_occasion_id;

  RETURN jsonb_build_object(
    'code', 200,
    'data', COALESCE(v_available, '[]'::jsonb)
  );
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object(
    'code',    500,
    'message', SQLERRM
  );
END;
$$;


ALTER FUNCTION "public"."get_products_for_ticket_all_available"("ticket_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_public_client_sync_component_v1"("p_component" "text", "p_scope_type" "text", "p_scope_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_revision bigint; v_payload jsonb; v_organization bigint; v_generated_at timestamptz;
BEGIN
  IF NOT public.is_service_role()
     AND NOT public.get_is_editor_on_occasion(p_scope_id) THEN
    RAISE insufficient_privilege USING MESSAGE='publisher or occasion editor required';
  END IF;
  IF p_scope_type <> 'occasion' OR NOT EXISTS (
    SELECT 1 FROM public.occasions WHERE id=p_scope_id AND NOT is_hidden
  ) THEN RAISE EXCEPTION 'scope is not publicly publishable'; END IF;
  SELECT source_revision,updated_at INTO v_revision,v_generated_at FROM public.client_sync_scopes
    WHERE component=p_component AND scope_type=p_scope_type AND scope_id=p_scope_id;
  v_revision := COALESCE(v_revision,0);

  CASE p_component
    WHEN 'occasion_config' THEN
      SELECT jsonb_build_object('id',o.id,'title',o.title,'startTime',o.start_time,
        'endTime',o.end_time,'isOpen',o.is_open,'features',o.features,'data',o.data,
        'services',o.services,'unitId',o.unit) INTO v_payload
      FROM public.occasions o WHERE o.id=p_scope_id AND NOT o.is_hidden;
    WHEN 'program_catalog' THEN
      SELECT jsonb_build_object(
        'events',COALESCE(jsonb_agg(DISTINCT jsonb_build_object('id',e.id,'title',e.title,
          'startTime',e.start_time,'endTime',e.end_time,'maxParticipants',e.max_participants,
          'description',e.description,'placeId',e.place,'type',e.type,'data',e.data,
          'order',e."order",'isGroupEvent',e.is_group_event,'splitForMenWomen',e.split_for_men_women)) FILTER (WHERE e.id IS NOT NULL),'[]'),
        'eventGroups',(SELECT COALESCE(jsonb_agg(jsonb_build_object('parentId',eg.event_parent,'childId',eg.event_child) ORDER BY eg.event_parent,eg.event_child),'[]') FROM public.event_groups eg JOIN public.events ep ON ep.id=eg.event_parent JOIN public.events ec ON ec.id=eg.event_child WHERE ep.occasion=p_scope_id AND ec.occasion=p_scope_id AND NOT ep.is_hidden AND NOT ec.is_hidden),
        'eventRoles',(SELECT COALESCE(jsonb_agg(jsonb_build_object('eventId',er.event,'roleId',er.role) ORDER BY er.event,er.role),'[]') FROM public.event_roles er JOIN public.events e2 ON e2.id=er.event WHERE e2.occasion=p_scope_id AND NOT e2.is_hidden),
        'eventSpeakers',(SELECT COALESCE(jsonb_agg(jsonb_build_object('eventId',es.event,'speakerId',es.speaker) ORDER BY es.event,es.speaker),'[]') FROM public.event_speakers es JOIN public.events e3 ON e3.id=es.event JOIN public.speakers sp ON sp.id=es.speaker WHERE e3.occasion=p_scope_id AND NOT e3.is_hidden AND NOT sp.is_hidden)
      ) INTO v_payload FROM public.events e WHERE e.occasion=p_scope_id AND NOT e.is_hidden;
    WHEN 'map_catalog' THEN
      SELECT o.organization INTO v_organization FROM public.occasions o WHERE o.id=p_scope_id;
      WITH visible_places AS (
        SELECT p.*,COALESCE(v.version,0) aggregate_version FROM public.places p
        LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='place'
          AND v.scope_type='occasion' AND v.scope_id=p_scope_id
          AND v.aggregate_id=p.id::text
        WHERE p.occasion=p_scope_id AND NOT p.is_hidden
      ), visible_types AS (
        SELECT pt.*,COALESCE(v.version,0) aggregate_version FROM public.place_types pt
        LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='place_type'
          AND v.scope_type='occasion' AND v.scope_id=p_scope_id
          AND v.aggregate_id=pt.id::text
        WHERE pt.occasion=p_scope_id AND NOT pt.is_hidden
      ), visible_paths AS (
        SELECT pg.*,COALESCE(v.version,0) aggregate_version FROM public.path_groups pg
        LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='path'
          AND v.scope_type='occasion' AND v.scope_id=p_scope_id
          AND v.aggregate_id=pg.id::text
        WHERE pg.occasion=p_scope_id AND NOT pg.is_hidden
      ), icon_ids AS (
        SELECT icon FROM visible_places WHERE icon IS NOT NULL UNION
        SELECT icon FROM visible_types WHERE icon IS NOT NULL UNION
        SELECT icon FROM visible_paths WHERE icon IS NOT NULL
      ), missing AS (
        SELECT i.icon FROM icon_ids i LEFT JOIN public.icons x ON x.id=i.icon AND x.organization=v_organization
        WHERE x.id IS NULL
      )
      SELECT CASE WHEN EXISTS(SELECT 1 FROM missing) THEN NULL ELSE jsonb_build_object(
        'places',(SELECT COALESCE(jsonb_agg(jsonb_build_object('id',p.id,'title',p.title,'description',p.description,'type',p.type,'coordinates',p.coordinates,'order',p."order",'icon',p.icon,'aggregateVersion',p.aggregate_version) ORDER BY p."order",p.id),'[]') FROM visible_places p),
        'placeTypes',(SELECT COALESCE(jsonb_agg(jsonb_build_object('id',pt.id,'code',pt.code,'title',pt.title,'icon',pt.icon,'order',pt."order",'isDefault',pt.is_default,'aggregateVersion',pt.aggregate_version) ORDER BY pt."order",pt.id),'[]') FROM visible_types pt),
        'paths',(SELECT COALESCE(jsonb_agg(jsonb_build_object('id',pg.id,'title',pg.title,'pathData',pg.path_data,'data',pg.data,'icon',pg.icon,'order',pg."order",'aggregateVersion',pg.aggregate_version) ORDER BY pg."order",pg.id),'[]') FROM visible_paths pg),
        'icons',(SELECT COALESCE(jsonb_agg(jsonb_build_object('id',i.id,'link',i.link,'svg',i.data) ORDER BY i.id),'[]') FROM public.icons i JOIN icon_ids refs ON refs.icon=i.id)
      ) END INTO v_payload;
      IF v_payload IS NULL THEN RAISE EXCEPTION 'map_catalog has a dangling or foreign icon reference'; END IF;
    WHEN 'content_catalog' THEN
      SELECT jsonb_build_object(
        'information',(SELECT COALESCE(jsonb_agg(jsonb_build_object('id',i.id,'title',i.title,'description',i.description,'order',i."order",'type',i.type,'data',i.data,'aggregateVersion',COALESCE(v.version,0)) ORDER BY i."order",i.id),'[]') FROM public.information i LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='information' AND v.scope_type='occasion' AND v.scope_id=p_scope_id AND v.aggregate_id=i.id::text WHERE i.occasion=p_scope_id AND NOT i.is_hidden),
        'news',(SELECT COALESCE(jsonb_agg(jsonb_build_object('id',n.id,'message',n.message,'createdAt',n.created_at,'updatedAt',n.updated_at,'aggregateVersion',COALESCE(v.version,0)) ORDER BY n.created_at,n.id),'[]') FROM public.news n LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='news' AND v.scope_type='occasion' AND v.scope_id=p_scope_id AND v.aggregate_id=n.id::text WHERE n.occasion=p_scope_id),
        'speakers',(SELECT COALESCE(jsonb_agg(jsonb_build_object('id',s.id,'title',s.title,'subtitle',s.subtitle,'description',s.description,'image',s.image,'order',s."order",'data',s.data,'aggregateVersion',COALESCE(v.version,0)) ORDER BY s."order",s.id),'[]') FROM public.speakers s LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='speaker' AND v.scope_type='occasion' AND v.scope_id=p_scope_id AND v.aggregate_id=s.id::text WHERE s.occasion=p_scope_id AND NOT s.is_hidden),
        'topics',(SELECT COALESCE(jsonb_agg(jsonb_build_object('id',t.id,'title',t.title,'order',t."order",'aggregateVersion',COALESCE(v.version,0)) ORDER BY t."order",t.id),'[]') FROM public.speaker_topics t LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='speaker_topic' AND v.scope_type='occasion' AND v.scope_id=p_scope_id AND v.aggregate_id=t.id::text WHERE t.occasion=p_scope_id AND NOT t.is_hidden),
        'topicLinks',(SELECT COALESCE(jsonb_agg(jsonb_build_object('speakerId',l.speaker,'topicId',l.topic) ORDER BY l.speaker,l.topic),'[]') FROM public.speaker_topic_links l JOIN public.speakers s ON s.id=l.speaker JOIN public.speaker_topics t ON t.id=l.topic WHERE s.occasion=p_scope_id AND t.occasion=p_scope_id AND NOT s.is_hidden AND NOT t.is_hidden)
      ) INTO v_payload;
    WHEN 'unit_catalog' THEN
      SELECT jsonb_build_object('unit',jsonb_build_object('id',u.id,'title',u.title,'data',u.data,'features',u.features),
        'occasions',COALESCE(jsonb_agg(jsonb_build_object('id',o.id,'title',o.title,'link',o.link,'startTime',o.start_time,'endTime',o.end_time,'description',o.description,'isOpen',o.is_open,'isPromoted',o.is_promoted) ORDER BY o.start_time,o.id) FILTER (WHERE o.id IS NOT NULL),'[]')) INTO v_payload
      FROM public.occasions current_o JOIN public.units u ON u.id=current_o.unit
      LEFT JOIN public.occasions o ON o.unit=u.id AND NOT o.is_hidden
      WHERE current_o.id=p_scope_id GROUP BY u.id;
    WHEN 'live_public' THEN
      SELECT jsonb_build_object(
        'events',(SELECT COALESCE(jsonb_agg(jsonb_build_object('eventId',s.event,'participantCount',s.participant_count,'savedCount',s.saved_count,'remainingCapacity',s.remaining_capacity) ORDER BY s.event),'[]') FROM public.event_public_state s JOIN public.events e ON e.id=s.event WHERE s.occasion=p_scope_id AND NOT e.is_hidden),
        'cleaning',(SELECT COALESCE(jsonb_agg(jsonb_build_object('placeId',s.place,'status',s.status,'openReportCount',s.open_report_count) ORDER BY s.place),'[]') FROM public.cleaning_public_state s WHERE s.occasion=p_scope_id),
        'newsViews',public.get_news_view_counts_v1(p_scope_id)
      ) INTO v_payload;
    ELSE RAISE EXCEPTION 'unsupported public component %',p_component;
  END CASE;
  RETURN jsonb_build_object('protocol',1,'schema',1,'component',p_component,
    'scope',((SELECT organization FROM public.occasions WHERE id=p_scope_id))::text||'/'||p_scope_id::text,
    'revision',v_revision,'generatedAt',COALESCE(v_generated_at,'epoch'::timestamptz),'payload',v_payload);
END; $$;


ALTER FUNCTION "public"."get_public_client_sync_component_v1"("p_component" "text", "p_scope_type" "text", "p_scope_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_public_occasions"("p_organization_id" bigint, "p_unit_id" bigint DEFAULT NULL::bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  result_data jsonb;
  occasions_data jsonb;
BEGIN
  -- 1. First, check if the provided organization exists.
  IF NOT EXISTS (SELECT 1 FROM public.organizations WHERE id = p_organization_id) THEN
    RAISE EXCEPTION 'organization_not_found: Organization with id % does not exist.', p_organization_id
      USING ERRCODE = 'P0002'; -- P0002 = no_data_found
  END IF;

  -- 2. Handle the case where unit_id IS NULL.
  -- Fetch all occasions for the given organization.
  IF p_unit_id IS NULL THEN

    -- Query all non-hidden, open, and promoted occasions for the specified organization
    SELECT COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'id', o.id,
          'title', o.title,
          'created_at', o.created_at,
          'updated_at', o.updated_at,
          'data', o.data,
          'description', o.description,
          'is_hidden', o.is_hidden,
          'is_open', o.is_open,
          'start_time', o.start_time,
          'end_time', o.end_time,
          'link', o.link,
          'organization', o.organization,
          'services', o.services,
          'unit', o.unit,
          'features', o.features,
          'form', (
             SELECT jsonb_build_object(
                'id', f.id,
                'created_at', f.created_at,
                'data', f.data,
                'occasion', f.occasion,
                'type', f.type,
                'is_open', f.is_open,
                'link', f.link,
                'blueprint', f.blueprint,
                'header', f.header,
                'header_off', f.header_off,
                'updated_at', f.updated_at
             )
             FROM public.forms f
             WHERE f.occasion = o.id
             -- Sort by is_open DESC (True first), then by ID
             ORDER BY f.is_open DESC, f.id
             LIMIT 1
          )
        )
        ORDER BY o.start_time DESC
      ),
      '[]'::jsonb
    )
    INTO occasions_data
    FROM public.occasions o
    WHERE o.organization = p_organization_id
      AND o.is_hidden = false
      AND o.is_promoted = true;

    -- Build a "virtual" unit object to hold these occasions,
    -- matching the structure of the "ELSE" block.
    result_data := jsonb_build_object(
      'id', NULL,
      'created_at', NULL,
      'title', 'All Occasions', -- Placeholder title
      'organization', p_organization_id,
      'data', NULL,
      'features', NULL,
      'occasions', occasions_data
    );

  -- 3. Handle the case where unit_id IS NOT NULL.
  -- Fetch data for that specific unit.
  ELSE
    -- Check if the unit exists AND belongs to the specified organization
    IF NOT EXISTS (
      SELECT 1
      FROM public.units
      WHERE id = p_unit_id
        AND organization = p_organization_id
    ) THEN
      RAISE EXCEPTION 'unit_not_found: Unit with id % in organization % does not exist.', p_unit_id, p_organization_id
        USING ERRCODE = 'P0002'; -- P0002 = no_data_found
    END IF;

    -- If check passes, run the original query.
    SELECT jsonb_build_object(
      'id', u.id,
      'created_at', u.created_at,
      'title', u.title,
      'organization', u.organization,
      'data', u.data,
      'features', u.features,
      'occasions', (
         SELECT COALESCE(
           jsonb_agg(
             jsonb_build_object(
               'id', o.id,
               'title', o.title,
               'created_at', o.created_at,
               'updated_at', o.updated_at,
               'data', o.data,
               'description', o.description,
               'is_hidden', o.is_hidden,
               'is_open', o.is_open,
               'start_time', o.start_time,
               'end_time', o.end_time,
               'link', o.link,
               'organization', o.organization,
               'services', o.services,
               'unit', o.unit,
               'features', o.features,
               'form', (
                  SELECT jsonb_build_object(
                     'id', f.id,
                     'created_at', f.created_at,
                     'data', f.data,
                     'occasion', f.occasion,
                     'type', f.type,
                     'is_open', f.is_open,
                     'link', f.link,
                     'blueprint', f.blueprint,
                     'header', f.header,
                     'header_off', f.header_off,
                     'updated_at', f.updated_at
                  )
                  FROM public.forms f
                  WHERE f.occasion = o.id
                  -- Sort by is_open DESC (True first), then by ID
                  ORDER BY f.is_open DESC, f.id
                  LIMIT 1
               )
             )
             ORDER BY o.start_time DESC
           ),
           '[]'::jsonb
         )
         FROM public.occasions o
         WHERE o.unit = u.id
           AND o.is_hidden = false
      )
    )
    INTO result_data
    FROM public.units u
    WHERE u.id = p_unit_id;
  END IF;

  -- 4. Return the resulting JSON object directly.
  RETURN result_data;
END;
$$;


ALTER FUNCTION "public"."get_public_occasions"("p_organization_id" bigint, "p_unit_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_reply_to_email_for_order"("p_order_id" bigint) RETURNS "text"
    LANGUAGE "sql" STABLE
    AS $$
    -- by joining its occasion and extracting the email from the occasion's 'data'.
    -- If occasion's reply_to is null, it falls back to the unit's reply_to.
    SELECT
        COALESCE(occ.data->>'reply_to', u.data->>'reply_to')
    FROM
        eshop.orders AS ord
    JOIN
        public.occasions AS occ ON ord.occasion = occ.id
    LEFT JOIN
        public.units AS u ON occ.unit = u.id
    WHERE
        ord.id = p_order_id;
$$;


ALTER FUNCTION "public"."get_reply_to_email_for_order"("p_order_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_report_for_occasion"("occasion_id" bigint) RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
    total_spots             INT;
    booked_spots            INT;
    free_spots              INT;
    total_tickets_ordered   INT;
    total_tickets_paid      INT;
    total_tickets_sent      INT;
    total_tickets_used      INT;
    total_tickets_canceled  INT;
    total_orders            INT;
    ordered_orders          INT;
    paid_orders             INT;
    sent_orders             INT;
    canceled_orders         INT;

    -- For per-currency revenue
    rec_rev     RECORD;
    currency_count INT;
    single_cc    TEXT;
    total_revenue     NUMERIC;
    paid_revenue      NUMERIC;
    paid_cash         NUMERIC; -- NEW
    paid_bank         NUMERIC; -- NEW
    returned_revenue  NUMERIC;
    result_revenue    NUMERIC;
    remaining_balance NUMERIC;
    deposit_paid      NUMERIC;
    remaining_paid    NUMERIC;
    has_deposits      BOOLEAN;
    revenue_section   TEXT;

    -- Variables for product type counts
    rec_product_type     RECORD;
    current_product_type TEXT := '';
    product_type_section TEXT := E'===========\nPočet zaplacených produktů podle typu:\n';
BEGIN
    -- 1) Spots ... (Unchanged)
    SELECT
        COUNT(*),
        COUNT(*) FILTER (WHERE order_product_ticket IS NOT NULL),
        COUNT(*) FILTER (WHERE order_product_ticket IS NULL)
    INTO
        total_spots, booked_spots, free_spots
    FROM eshop.spots
    WHERE occasion = occasion_id;

    -- 2) Tickets ... (Unchanged)
    SELECT
        COUNT(DISTINCT t.id) FILTER (WHERE t.state = 'ordered'),
        COUNT(DISTINCT t.id) FILTER (WHERE t.state = 'paid'),
        COUNT(DISTINCT t.id) FILTER (WHERE t.state = 'sent'),
        COUNT(DISTINCT t.id) FILTER (WHERE t.state = 'used'),
        COUNT(DISTINCT t.id) FILTER (WHERE t.state = 'storno')
    INTO
        total_tickets_ordered,
        total_tickets_paid,
        total_tickets_sent,
        total_tickets_used,
        total_tickets_canceled
    FROM eshop.tickets t
    JOIN eshop.order_product_ticket opt ON t.id = opt.ticket
    WHERE t.occasion = occasion_id;

    -- 3) Orders ... (Unchanged)
    SELECT
        COUNT(*),
        COUNT(*) FILTER (WHERE state = 'ordered'),
        COUNT(*) FILTER (WHERE state = 'paid'),
        COUNT(*) FILTER (WHERE state = 'sent'),
        COUNT(*) FILTER (WHERE state = 'storno')
    INTO
        total_orders, ordered_orders, paid_orders, sent_orders, canceled_orders
    FROM eshop.orders
    WHERE occasion = occasion_id;

    -- 4) Count distinct currencies
    SELECT
        COUNT(DISTINCT o.currency_code)
    INTO
        currency_count
    FROM eshop.orders o
    WHERE o.occasion = occasion_id;

    IF currency_count = 1 THEN
        -- Single currency: compute sums directly
        SELECT
            o.currency_code,
            COALESCE(SUM(o.price),   0),
            COALESCE(SUM(pi.paid),   0),
            COALESCE(SUM(pi.returned),0),
            -- Manual (Cash)
            COALESCE(SUM(
                (SELECT COALESCE(SUM(t.amount), 0)
                 FROM eshop.transactions t
                 WHERE t.payment_info = pi.id AND t.transaction_type = 'manual')
            ), 0),
            -- Bank (Others = Total Paid - Manual? Or explicit sum?)
            -- Using explicit sum ensures we track what is actually IN transactions.
            -- However, pi.paid might technically differ if there were manual DB edits.
            -- User wants distinction. Let's calculate Bank as Paid - Cash to ensure they sum up to Paid?
            -- No, "Normal transaction and cash transaction".
            -- If we trust pi.paid is the master total, then Bank = pi.paid - Cash.
            -- BUT, let's sum transactions for 'bank' explicitly to see if they match?
            -- Actually, to be safe and consistent with the total 'Paid' line:
            --   Total Paid = X
            --     Cash: Y
            --     Bank: Z
            -- If Y+Z != X, it might be confusing.
            -- Safest approach:
            --   Cash = Sum(Manual Transactions)
            --   Bank = PaymentInfo.Paid - Cash (Treat 'Paid' as the source of truth for total, and Cash as the specific component).
            -- This handles cases where transactions might be missing but balance was set.
            -- ... Actually, if transactions are the ONLY way to pay, then Sum(Trans) == Paid.
            -- Let's go with: Bank = Paid - Cash.
            COALESCE(SUM(pi.paid), 0) -
            COALESCE(SUM(
                (SELECT COALESCE(SUM(t.amount), 0)
                 FROM eshop.transactions t
                 WHERE t.payment_info = pi.id AND t.transaction_type = 'manual')
            ), 0),
            -- Deposit revenue: MIN(paid, deposit_amount) for deposit orders
            COALESCE(SUM(
                CASE
                    WHEN pi.deposit_amount IS NOT NULL
                    THEN LEAST(COALESCE(pi.paid, 0), pi.deposit_amount)
                    ELSE 0
                END
            ), 0),
            -- Remaining revenue (paid beyond deposit): MAX(0, paid - deposit_amount) for deposit orders
            COALESCE(SUM(
                CASE
                    WHEN pi.deposit_amount IS NOT NULL AND COALESCE(pi.paid, 0) > pi.deposit_amount
                    THEN COALESCE(pi.paid, 0) - pi.deposit_amount
                    ELSE 0
                END
            ), 0),
            -- Has any deposit orders
            BOOL_OR(pi.deposit_amount IS NOT NULL)
        INTO
            single_cc,
            total_revenue,
            paid_revenue,
            returned_revenue,
            paid_cash,
            paid_bank,
            deposit_paid,
            remaining_paid,
            has_deposits
        FROM eshop.orders o
        LEFT JOIN eshop.payment_info pi ON pi.id = o.payment_info
        WHERE o.occasion = occasion_id
        GROUP BY o.currency_code;

        result_revenue    := paid_revenue - returned_revenue;
        remaining_balance := total_revenue - (paid_revenue - returned_revenue);

        revenue_section := E'===========\nPřehled tržeb:\n' ||
            E'    • Suma všech objednávek: '   || to_char(total_revenue,     'FM99999990.00') || ' ' || single_cc || E'\n' ||
            E'    • Suma přijatých částek: '  || to_char(paid_revenue,      'FM99999990.00') || ' ' || single_cc || E'\n' ||
            E'         - Banka: '             || to_char(paid_bank,         'FM99999990.00') || ' ' || single_cc || E'\n' ||
            E'         - Hotovost: '          || to_char(paid_cash,         'FM99999990.00') || ' ' || single_cc || E'\n' ||
            E'    • Suma vrácených částek: '  || to_char(returned_revenue,  'FM99999990.00') || ' ' || single_cc || E'\n' ||
            E'    • Výsledná částka: '         || to_char(result_revenue,    'FM99999990.00') || ' ' || single_cc || E'\n' ||
            E'    • Zbývající částka: '       || to_char(remaining_balance,'FM99999990.00') || ' ' || single_cc || E'\n';

        IF has_deposits THEN
            revenue_section := revenue_section ||
                E'    • Zálohy (deposits): '    || to_char(deposit_paid,    'FM99999990.00') || ' ' || single_cc || E'\n' ||
                E'    • Doplatky (remaining): ' || to_char(remaining_paid,  'FM99999990.00') || ' ' || single_cc || E'\n';
        END IF;
    ELSE
        -- Multiple currencies: loop per currency
        revenue_section := E'===========\nPřehled tržeb podle měny:\n';
        FOR rec_rev IN
            SELECT
                o.currency_code,
                COALESCE(SUM(o.price),   0) AS total_revenue,
                COALESCE(SUM(pi.paid),   0) AS paid_revenue,
                COALESCE(SUM(pi.returned),0) AS returned_revenue,
                -- Cash
                COALESCE(SUM(
                    (SELECT COALESCE(SUM(t.amount), 0)
                     FROM eshop.transactions t
                     WHERE t.payment_info = pi.id AND t.transaction_type = 'manual')
                ), 0) AS paid_cash,
                -- Deposit revenue
                COALESCE(SUM(
                    CASE
                        WHEN pi.deposit_amount IS NOT NULL
                        THEN LEAST(COALESCE(pi.paid, 0), pi.deposit_amount)
                        ELSE 0
                    END
                ), 0) AS deposit_paid,
                -- Remaining revenue (paid beyond deposit)
                COALESCE(SUM(
                    CASE
                        WHEN pi.deposit_amount IS NOT NULL AND COALESCE(pi.paid, 0) > pi.deposit_amount
                        THEN COALESCE(pi.paid, 0) - pi.deposit_amount
                        ELSE 0
                    END
                ), 0) AS remaining_paid
            FROM eshop.orders o
            LEFT JOIN eshop.payment_info pi ON pi.id = o.payment_info
            WHERE o.occasion = occasion_id
            GROUP BY o.currency_code
            ORDER BY o.currency_code
        LOOP
            result_revenue    := rec_rev.paid_revenue - rec_rev.returned_revenue;
            remaining_balance := rec_rev.total_revenue - rec_rev.paid_revenue;
            paid_bank         := rec_rev.paid_revenue - rec_rev.paid_cash;

            revenue_section := revenue_section ||
                E' - ' || rec_rev.currency_code || E':\n' ||
                E'    • Suma všech objednávek: '   || to_char(rec_rev.total_revenue,    'FM99999990.00') || ' ' || rec_rev.currency_code || E'\n' ||
                E'    • Suma přijatých částek: '  || to_char(rec_rev.paid_revenue,     'FM99999990.00') || ' ' || rec_rev.currency_code || E'\n' ||
                E'         - Banka: '             || to_char(paid_bank,                'FM99999990.00') || ' ' || rec_rev.currency_code || E'\n' ||
                E'         - Hotovost: '          || to_char(rec_rev.paid_cash,        'FM99999990.00') || ' ' || rec_rev.currency_code || E'\n' ||
                E'    • Suma vrácených částek: '  || to_char(rec_rev.returned_revenue, 'FM99999990.00') || ' ' || rec_rev.currency_code || E'\n' ||
                E'    • Výsledná částka: '         || to_char(result_revenue,           'FM99999990.00') || ' ' || rec_rev.currency_code || E'\n' ||
                E'    • Zbývající částka: '       || to_char(remaining_balance,       'FM99999990.00') || ' ' || rec_rev.currency_code || E'\n';

            IF rec_rev.deposit_paid > 0 OR rec_rev.remaining_paid > 0 THEN
                revenue_section := revenue_section ||
                    E'    • Zálohy (deposits): '    || to_char(rec_rev.deposit_paid,    'FM99999990.00') || ' ' || rec_rev.currency_code || E'\n' ||
                    E'    • Doplatky (remaining): ' || to_char(rec_rev.remaining_paid,  'FM99999990.00') || ' ' || rec_rev.currency_code || E'\n';
            END IF;
        END LOOP;
    END IF;

    -- 5) Products by type ... (Unchanged)
    FOR rec_product_type IN
        SELECT
            pt.title   AS product_type,
            p.title    AS product_title,
            COUNT(opt.product) AS ordered_count
        FROM eshop.order_product_ticket opt
        JOIN eshop.products p          ON opt.product      = p.id
        JOIN eshop.product_types pt    ON p.product_type   = pt.id
        JOIN eshop.orders o            ON o.id             = opt."order"
        WHERE p.occasion = occasion_id
          AND o.state NOT IN ('storno','ordered')
        GROUP BY pt.title, p.title
        ORDER BY pt.title, p.title
    LOOP
        IF rec_product_type.product_type <> current_product_type THEN
            current_product_type := rec_product_type.product_type;
            product_type_section := product_type_section || E' - ' || current_product_type || E':\n';
        END IF;
        product_type_section := product_type_section ||
            E'    • ' || rec_product_type.product_title || E': ' || rec_product_type.ordered_count || E'\n';
    END LOOP;
    IF product_type_section = E'===========\nPočet zaplacených produktů podle typu:\n' THEN
        product_type_section := product_type_section || E' - Žádné zaplacené produkty.\n';
    END IF;

    -- 6) Assemble final report ... (Unchanged)
    RETURN
        E'===========\n' ||
        E'Počet míst celkem: '     || to_char(total_spots,              'FM9999') || E'\n' ||
        E'Počet volných: '          || to_char(free_spots,               'FM9999') || E'\n' ||
        E'Počet obsazených: '       || to_char(booked_spots,             'FM9999') || E'\n' ||
        E'Počet objednaných: '      || to_char(total_tickets_ordered,    'FM9999') || E'\n' ||
        E'Počet zaplacených: '      || to_char(total_tickets_paid,       'FM9999') || E'\n' ||
        E'Počet odeslaných: '       || to_char(total_tickets_sent,       'FM9999') || E'\n' ||
        E'Počet využitých: '        || to_char(total_tickets_used,       'FM9999') || E'\n' ||
        E'Počet storno: '           || to_char(total_tickets_canceled,   'FM9999') || E'\n' ||
        E'===========\n' ||
        E'Počet objednávek celkem: '|| to_char(total_orders,             'FM9999') || E'\n' ||
        E'Objednáno: '              || to_char(ordered_orders,           'FM9999') || E'\n' ||
        E'Zaplaceno: '              || to_char(paid_orders,              'FM9999') || E'\n' ||
        E'Odesláno: '               || to_char(sent_orders,              'FM9999') || E'\n' ||
        E'Storno: '                 || to_char(canceled_orders,          'FM9999') || E'\n' ||
        product_type_section ||
        revenue_section ||
        E'===========';
EXCEPTION
    WHEN OTHERS THEN
        RETURN E'An unexpected error occurred: ' || SQLERRM;
END;
$$;


ALTER FUNCTION "public"."get_report_for_occasion"("occasion_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_report_for_occasion_with_security"("form_link" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    occasion_id bigint;
    report_data text; -- Variable to hold the result of the original report function
BEGIN
    -- Retrieve the occasion associated with the form link
    SELECT occasion
    INTO occasion_id
    FROM public.forms
    WHERE link = form_link;

    -- Check if the order exists and has an associated occasion
    IF occasion_id IS NULL THEN
        RAISE EXCEPTION 'Order not found or no associated occasion.';
    END IF;

    -- Verify if the user is an editor on the occasion
    IF NOT get_is_editor_view_on_occasion(occasion_id) THEN
        RAISE EXCEPTION 'User is not authorized to edit this occasion.';
    END IF;

    -- Call the original function to get the report data
    report_data := get_report_for_occasion(occasion_id);

    -- Return the result as a jsonb object with the data and code 200
    RETURN jsonb_build_object(
        'code', 200,
        'data', report_data
    );
EXCEPTION WHEN OTHERS THEN
    -- Handle any exceptions
    RETURN jsonb_build_object(
        'code', 500,
        'message', SQLERRM,
        'detail', coalesce(SQLERRM, 'An unexpected error occurred')
    );
END;
$$;


ALTER FUNCTION "public"."get_report_for_occasion_with_security"("form_link" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_report_for_occasion_ws"("form_link" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
