    );
END;
$$;


ALTER FUNCTION "public"."get_report_for_occasion_ws"("form_link" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_report_ws"("occasion_link" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    occasion_id bigint;
    report_data text;
BEGIN
    SELECT id
    INTO occasion_id
    FROM public.occasions
    WHERE link = occasion_link;

    IF occasion_id IS NULL THEN
        RAISE EXCEPTION 'Occasion not found for link: %', occasion_link;
    END IF;

    IF NOT get_is_editor_order_view_on_occasion(occasion_id) THEN
        RAISE EXCEPTION 'User is not authorized to view this report.';
    END IF;

    report_data := get_report_for_occasion(occasion_id);

    RETURN jsonb_build_object(
        'code', 200,
        'data', report_data
    );
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object(
        'code', 500,
        'message', SQLERRM,
        'detail', coalesce(SQLERRM, 'An unexpected error occurred')
    );
END;
$$;


ALTER FUNCTION "public"."get_report_ws"("occasion_link" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_reservations"("p_occasion_link" "text", "p_form_link" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_occasion_id BIGINT;
    v_form_key UUID;
    spotsData JSONB;
    productsData JSONB;
    productTypesData JSONB;
    ticketsData JSONB;
    ordersData JSONB;
    orderProductTicketsData JSONB;
    paymentInfoData JSONB;
    formsData JSONB;
BEGIN
    -- 1. Input Validation: Ensure at least one link is provided.
    IF p_occasion_link IS NULL AND p_form_link IS NULL THEN
        RETURN jsonb_build_object('code', 400, 'message', 'Either occasion_link or form_link must be provided');
    END IF;

    -- 2. Determine occasion_id based on the provided link.
    -- occasion_link has priority.
    IF p_occasion_link IS NOT NULL THEN
        SELECT id
        INTO v_occasion_id
        FROM public.occasions
        WHERE link = p_occasion_link;
    ELSE -- If occasion_link is NULL, use form_link
        SELECT occasion, key
        INTO v_occasion_id, v_form_key
        FROM public.forms
        WHERE link = p_form_link;
    END IF;

    -- 3. Check if a valid occasion was found.
    IF v_occasion_id IS NULL THEN
        RETURN jsonb_build_object('code', 404, 'message', 'The provided link is invalid or not linked to any occasion');
    END IF;

    -- 4. Authorization check.
    IF (SELECT get_is_editor_order_view_on_occasion(v_occasion_id)) <> TRUE THEN
        RETURN jsonb_build_object('code', 403, 'message', 'User is not authorized to access this occasion');
    END IF;

    -- Fetch spots where order_product_ticket is not NULL
    SELECT jsonb_agg(jsonb_build_object(
        'id', s.id,
        'title', s.title,
        'product', s.product,
        'order_product_ticket', s.order_product_ticket,
        'state', CASE
            WHEN s.order_product_ticket IS NOT NULL THEN 'ordered'
            WHEN s.secret IS NOT NULL AND s.secret_expiration_time > now() THEN 'selected'
            ELSE 'available'
        END
    ))
    INTO spotsData
    FROM eshop.spots s
    WHERE s.occasion = v_occasion_id
      AND s.order_product_ticket IS NOT NULL;

    -- Fetch all products linked to the occasion
    SELECT jsonb_agg(jsonb_build_object(
        'id', p.id,
        'title', p.title,
        'price', p.price,
        'currency_code', p.currency_code,
        'type', pt.type,
        'description', pt.description
    ))
    INTO productsData
    FROM eshop.products p
    JOIN eshop.product_types pt ON pt.id = p.product_type
    WHERE pt.occasion = v_occasion_id;

    -- Fetch product types for the occasion
    SELECT jsonb_agg(jsonb_build_object(
        'id', pt.id,
        'type', pt.type,
        'title', pt.title,
        'description', pt.description
    ))
    INTO productTypesData
    FROM eshop.product_types pt
    WHERE pt.occasion = v_occasion_id;

    -- Fetch tickets linked to the occasion
    SELECT jsonb_agg(jsonb_build_object(
        'id', t.id,
        'created_at', t.created_at,
        'ticket_symbol', t.ticket_symbol,
        'state', t.state,
        'note', t.note,
        'note_hidden', t.note_hidden
    ))
    INTO ticketsData
    FROM eshop.tickets t
    WHERE t.occasion = v_occasion_id;

    -- Fetch forms linked to the occasion
    SELECT jsonb_agg(jsonb_build_object(
        'id', f.id,
        'created_at', f.created_at,
        'data', f.data,
        'key', f.key,
        'occasion', f.occasion,
        'type', f.type,
        'deadline_duration_seconds', f.deadline_duration_seconds,
        'is_open', f.is_open,
        'link', f.link,
        'blueprint', f.blueprint,
        'title', f.title,
        'header', f.header,
        'header_off', f.header_off,
        'updated_at', f.updated_at
    ))
    INTO formsData
    FROM public.forms f
    WHERE f.occasion = v_occasion_id;

    -- Fetch orders - this is the conditional part.
    -- If v_form_key is not NULL, it means we are filtering by form.
    IF v_form_key IS NOT NULL THEN
        SELECT jsonb_agg(jsonb_build_object(
            'id', o.id,
            'created_at', o.created_at,
            'updated_at', o.updated_at,
            'price', o.price,
            'state', o.state,
            'currency_code', o.currency_code,
            'data', o.data,
            'payment_info', o.payment_info,
            'note_hidden', o.note_hidden
        ))
        INTO ordersData
        FROM eshop.orders o
        WHERE o.occasion = v_occasion_id
          AND o.data->>'form' = v_form_key::TEXT; -- Filter by the form's key
    ELSE
        -- Original query if not filtering by form
        SELECT jsonb_agg(jsonb_build_object(
            'id', o.id,
            'created_at', o.created_at,
            'updated_at', o.updated_at,
            'price', o.price,
            'state', o.state,
            'currency_code', o.currency_code,
            'data', o.data,
            'payment_info', o.payment_info,
            'note_hidden', o.note_hidden
        ))
        INTO ordersData
        FROM eshop.orders o
        WHERE o.occasion = v_occasion_id;
    END IF;

    -- Extract order IDs from the (potentially filtered) ordersData JSONB
    WITH order_ids AS (
        SELECT (order_obj->>'id')::BIGINT AS id
        FROM jsonb_array_elements(COALESCE(ordersData, '[]'::jsonb)) order_obj
    )
    -- Fetch relevant order-product-ticket data based on extracted order IDs
    SELECT jsonb_agg(jsonb_build_object(
        'id', opt.id,
        'order', opt."order",
        'product', opt.product,
        'ticket', opt.ticket,
        'created_at', opt.created_at
    ))
    INTO orderProductTicketsData
    FROM eshop.order_product_ticket opt
    WHERE opt."order" IN (SELECT id FROM order_ids);

    -- Fetch payment information linked to the orders
    SELECT jsonb_agg(jsonb_build_object(
        'id', pi.id,
        'created_at', pi.created_at,
        'bank_account', pi.bank_account,
        'variable_symbol', pi.variable_symbol,
        'amount', pi.amount,
        'paid', pi.paid,
        'returned', pi.returned,
        'deadline', pi.deadline,
        'currency_code', pi.currency_code,
        'data', pi.data
    ))
    INTO paymentInfoData
    FROM eshop.payment_info pi
    WHERE pi.id IN (
        SELECT DISTINCT (order_obj->>'payment_info')::BIGINT
        FROM jsonb_array_elements(COALESCE(ordersData, '[]'::jsonb)) order_obj
        WHERE order_obj->>'payment_info' IS NOT NULL
    );

    -- Return combined data
    RETURN jsonb_build_object(
        'code', 200,
        'data', jsonb_build_object(
            'spots', COALESCE(spotsData, '[]'::jsonb),
            'products', COALESCE(productsData, '[]'::jsonb),
            'product_types', COALESCE(productTypesData, '[]'::jsonb),
            'tickets', COALESCE(ticketsData, '[]'::jsonb),
            'orders', COALESCE(ordersData, '[]'::jsonb),
            'order_product_ticket', COALESCE(orderProductTicketsData, '[]'::jsonb),
            'payment_info', COALESCE(paymentInfoData, '[]'::jsonb),
            'forms', COALESCE(formsData, '[]'::jsonb)
        )
    );
END;
$$;


ALTER FUNCTION "public"."get_reservations"("p_occasion_link" "text", "p_form_link" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."resources" (
    "id" bigint NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "title" "text" NOT NULL,
    "description" "text",
    "capacity" integer DEFAULT 1 NOT NULL,
    "booking_rules" "jsonb",
    "inventory_pool" bigint NOT NULL,
    "place" bigint,
    "occasion" bigint,
    "unit" bigint,
    "data" "jsonb"
);


ALTER TABLE "public"."resources" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_resources_for_inventory_pool"("p_inventory_pool_id" bigint) RETURNS SETOF "public"."resources"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_occasion_id BIGINT;
BEGIN
  -- First, find the occasion associated with the requested inventory pool.
  -- This is crucial for the permission check.
  SELECT p.occasion
  INTO v_occasion_id
  FROM public.inventory_pools p
  WHERE p.id = p_inventory_pool_id;

  -- If the pool doesn't exist, we can't proceed.
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Inventory Pool with ID % not found.', p_inventory_pool_id;
  END IF;

  -- If the pool isn't linked to an occasion, deny access as we cannot check permissions.
  IF v_occasion_id IS NULL THEN
    RAISE EXCEPTION 'The parent Inventory Pool with ID % is not linked to an occasion.', p_inventory_pool_id;
  END IF;

  -- Perform the security check to ensure the calling user has editor rights on the occasion.
  -- This prevents users from one occasion from viewing data from another.
  PERFORM public.check_is_editor_order_view_on_occasion(v_occasion_id);

  -- If the permission check is successful, return all resources
  -- that belong to the specified inventory pool.
  RETURN QUERY
  SELECT *
  FROM public.resources
  WHERE inventory_pool = p_inventory_pool_id
  ORDER BY id;
END;
$$;


ALTER FUNCTION "public"."get_resources_for_inventory_pool"("p_inventory_pool_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_resources_for_inventory_pool_v1"("p_inventory_pool_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_occasion bigint; v_result jsonb;
BEGIN
  SELECT ip.occasion INTO v_occasion FROM public.inventory_pools ip
    WHERE ip.id=p_inventory_pool_id;
  IF v_occasion IS NULL THEN RAISE invalid_parameter_value USING MESSAGE='inventory pool not found'; END IF;
  PERFORM public.check_is_editor_order_view_on_occasion(v_occasion);
  SELECT COALESCE(jsonb_agg(to_jsonb(r)||jsonb_build_object(
    'aggregate_version',COALESCE(v.version,0)) ORDER BY r.id),'[]'::jsonb)
    INTO v_result FROM public.resources r
    LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='resource'
      AND v.scope_type='occasion' AND v.scope_id=v_occasion
      AND v.aggregate_id=r.id::text
    WHERE r.inventory_pool=p_inventory_pool_id;
  RETURN v_result;
END; $$;


ALTER FUNCTION "public"."get_resources_for_inventory_pool_v1"("p_inventory_pool_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_scan_code"("occasion_link" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    occasion_id BIGINT;
    current_scan_code TEXT;
BEGIN
    -- 1. Retrieve occasion_id using occasion_link
    SELECT id
    INTO occasion_id
    FROM public.occasions
    WHERE link = occasion_link;

    -- 2. Check if occasion_link is valid
    IF occasion_id IS NULL THEN
        RETURN jsonb_build_object(
            'code', 404,
            'message', 'Occasion link does not exist.'
        );
    END IF;

    -- 3. Verify if the user is an editor on the occasion
    IF NOT get_is_editor_order_view_on_occasion(occasion_id) THEN
        RETURN jsonb_build_object(
            'code', 403,
            'message', 'User is not authorized to view scan code for this occasion.'
        );
    END IF;

    -- 4. Retrieve the scan_code from the occasions_hidden table via the foreign key
    SELECT oh.secret
    INTO current_scan_code
    FROM public.occasions_hidden oh
    JOIN public.occasions o ON o.occasion_hidden = oh.id
    WHERE o.id = occasion_id
    LIMIT 1;

    -- 4.a. Handle case where scan_code is not found
    IF current_scan_code IS NULL THEN
        RETURN jsonb_build_object(
            'code', 404,
            'message', 'Scan code not found for the specified occasion.'
        );
    END IF;

    -- 5. Return the scan_code
    RETURN jsonb_build_object(
        'code', 200,
        'message', 'Scan code retrieved successfully.',
        'scan_code', current_scan_code
    );

EXCEPTION
    WHEN OTHERS THEN
        -- Handle any unexpected exceptions
        RETURN jsonb_build_object(
            'code', 500,
            'message', 'An unexpected error occurred.',
            'detail', SQLERRM
        );
END;
$$;


ALTER FUNCTION "public"."get_scan_code"("occasion_link" "text") OWNER TO "postgres";


