CREATE OR REPLACE FUNCTION "public"."get_unit"("unit_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  unit_data jsonb;
BEGIN
  -- Check if the unit exists
  IF NOT EXISTS (SELECT 1 FROM public.units WHERE id = unit_id) THEN
    RETURN jsonb_build_object(
      'code', 404,
      'message', 'Unit not found'
    );
  END IF;

  SELECT jsonb_build_object(
    'id', u.id,
    'created_at', u.created_at,
    'title', u.title,
    'organization', u.organization,
    'data', u.data,
    'features', u.features,
    'occasions', (
       SELECT COALESCE(
         jsonb_agg(
           jsonb_build_object(
             'id', o.id,
             'title', o.title,
             'created_at', o.created_at,
             'updated_at', o.updated_at,
             'data', o.data,
             'description', o.description,
             'is_hidden', o.is_hidden,
             'is_open', o.is_open,
             'start_time', o.start_time,
             'end_time', o.end_time,
             'link', o.link,
             'organization', o.organization,
             'services', o.services,
             'unit', o.unit,
             'features', o.features,
             'form', (
                SELECT jsonb_build_object(
                   'id', f.id,
                   'created_at', f.created_at,
                   'data', f.data,
                   'occasion', f.occasion,
                   'type', f.type,
                   'is_open', f.is_open,
                   'link', f.link,
                   'blueprint', f.blueprint,
                   'header', f.header,
                   'header_off', f.header_off,
                   'updated_at', f.updated_at
                )
                FROM public.forms f
                WHERE f.occasion = o.id
                ORDER BY f.id
                LIMIT 1
             )
           )
           ORDER BY o.start_time DESC
         ),
         '[]'::jsonb
       )
       FROM public.occasions o
       WHERE o.unit = u.id
         AND o.is_hidden = false
    )
  )
  INTO unit_data
  FROM public.units u
  WHERE u.id = unit_id;

  RETURN jsonb_build_object(
    'code', 200,
    'data', unit_data
  );
END;
$$;


ALTER FUNCTION "public"."get_unit"("unit_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_unit_edit_data"("p_unit_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    v_unit_data jsonb;
    v_occasions_data jsonb;
BEGIN
    -- 1. Call get_unit_for_edit to get the unit details
    SELECT get_unit_for_edit(p_unit_id) INTO v_unit_data;

    -- Check if get_unit_for_edit returned an error (code != 200)
    IF (v_unit_data->>'code')::INT <> 200 THEN
          RAISE EXCEPTION 'get_unit_for_edit failed: %', v_unit_data->>'message';
    END IF;

    -- 2. Call get_all_occasions_for_edit_v212 to get the occasions
    -- Note: get_all_occasions_for_edit_v212 returns the array directly, not wrapped in code/data
    SELECT get_all_occasions_for_edit_v212(p_unit_id) INTO v_occasions_data;

    -- 3. Merge the results.
    -- v_unit_data has structure {code: 200, data: {...}}
    -- We want to return structure that includes both.
    -- Let's return { unit: ..., occasions: ... }

    RETURN jsonb_build_object(
        'unit', (v_unit_data->'data'),
        'occasions', v_occasions_data
    );
END;
$$;


ALTER FUNCTION "public"."get_unit_edit_data"("p_unit_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_unit_edit_data_v1"("p_unit" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_result jsonb; v_version bigint;
BEGIN
  IF auth.uid() IS NULL OR NOT public.get_is_manager_on_unit(p_unit) THEN
    RAISE insufficient_privilege USING MESSAGE='unit manager required'; END IF;
  v_result:=public.get_unit_edit_data(p_unit);
  SELECT COALESCE(v.version,0) INTO v_version
    FROM (SELECT 1) seed LEFT JOIN public.client_aggregate_versions v
      ON v.aggregate_type='unit' AND v.scope_type='unit'
      AND v.scope_id=p_unit AND v.aggregate_id=p_unit::text;
  RETURN jsonb_set(v_result,'{unit}',(v_result->'unit')||
    jsonb_build_object('aggregate_version',v_version));
END; $$;


ALTER FUNCTION "public"."get_unit_edit_data_v1"("p_unit" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_unit_for_edit"("unit_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    AS $$
DECLARE
    unit_data jsonb;
BEGIN
    -- Check if the current user is authorized (editor or manager) for the provided unit
    IF NOT EXISTS (
        SELECT 1
        FROM unit_users
        WHERE "user" = auth.uid()
          AND unit = unit_id
          AND (is_editor = true OR is_manager = true OR is_editor_view = true)
    ) AND NOT EXISTS (
        SELECT 1
        FROM occasions o
        JOIN occasion_users ou ON ou.occasion = o.id
        WHERE o.unit = unit_id
          AND ou."user" = auth.uid()
          AND (
              ou.is_manager IS TRUE
              OR ou.is_editor IS TRUE
              OR ou.is_editor_view IS TRUE
              OR ou.is_editor_order IS TRUE
              OR ou.is_editor_order_view IS TRUE
          )
    ) THEN
        RETURN jsonb_build_object('code', 403);
    END IF;

    -- Retrieve the unit data as jsonb
    SELECT jsonb_build_object(
        'id', id,
        'title', title,
        'data', data,
        'features', features,
        'organization', organization
    ) INTO unit_data
    FROM units
    WHERE id = unit_id;

    -- Return the unit data with a 200 code
    RETURN jsonb_build_object('code', 200, 'data', unit_data);
END;
$$;


