CREATE OR REPLACE FUNCTION "public"."get_user_group_info"("p_group_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_occasion_id bigint;
    v_is_member boolean;
    v_is_editor_view boolean;
    result_json jsonb;
BEGIN
    -- First, find the occasion for the requested group to check permissions against it.
    SELECT occasion INTO v_occasion_id FROM public.user_group_info WHERE id = p_group_id;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('code', 404, 'message', 'User group not found');
    END IF;

    -- Authorization Check:
    -- 1. Check if the current user is a member of the group.
    SELECT EXISTS (
        SELECT 1 FROM public.user_groups WHERE "group" = p_group_id AND "user" = auth.uid()
    ) INTO v_is_member;

    -- 2. Check if the current user has editor view permissions on the occasion.
    v_is_editor_view := get_is_editor_view_on_occasion(v_occasion_id);

    -- If the user is neither a member nor has editor view permissions, deny access.
    IF NOT v_is_member AND NOT v_is_editor_view THEN
        RETURN jsonb_build_object('code', 403, 'message', 'Not authorized to view this user group');
    END IF;

    -- If authorized, proceed to fetch the data.
    SELECT
        jsonb_build_object(
            'id', ugi.id,
            'title', ugi.title,
            'description', ugi.description,
            'type', ugi.type,
            'data', ugi.data,
            'leader', ugi.leader,
            'place', ugi.place,
            'user_info', (SELECT jsonb_build_object('id', ui_leader.id, 'name', ui_leader.name, 'surname', ui_leader.surname) FROM public.user_info ui_leader WHERE ui_leader.id = ugi.leader),
            'places', (SELECT jsonb_build_object('id', p.id, 'title', p.title, 'description', p.description, 'type', p.type, 'created_at', p.created_at, 'coordinates', p.coordinates, 'is_hidden', p.is_hidden, 'updated_at', p.updated_at, 'occasion', p.occasion, 'order', p."order", 'icon', p.icon, 'unit', p.unit) FROM public.places p WHERE p.id = ugi.place),
            'user_groups', (SELECT COALESCE(jsonb_agg(jsonb_build_object('user_info', jsonb_build_object('id', p_ui.id, 'name', p_ui.name, 'surname', p_ui.surname))), '[]'::jsonb) FROM public.user_groups ug JOIN public.user_info p_ui ON ug."user" = p_ui.id WHERE ug."group" = ugi.id)
        )
    INTO result_json
    FROM public.user_group_info ugi
    WHERE ugi.id = p_group_id;

    -- Return the data in a structured response on success.
    RETURN jsonb_build_object('code', 200, 'data', result_json);

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('code', 500, 'message', SQLERRM);
END;
$$;


ALTER FUNCTION "public"."get_user_group_info"("p_group_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_user_group_info_with_users"("p_group_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_occasion_id bigint;
    v_is_member boolean;
    v_is_editor_view boolean;
    v_current_user_is_admin boolean;
    result_json jsonb;
BEGIN
    -- Check if the group exists and get its occasion for permission checks.
    SELECT occasion INTO v_occasion_id FROM public.user_group_info WHERE id = p_group_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'USER_GROUP_NOT_FOUND';
    END IF;

    -- Authorization Check: User must be a member or have editor view permissions on the occasion.
    SELECT EXISTS (SELECT 1 FROM public.user_groups WHERE "group" = p_group_id AND "user" = auth.uid()) INTO v_is_member;
    v_is_editor_view := get_is_editor_view_on_occasion(v_occasion_id);

    IF NOT v_is_member AND NOT v_is_editor_view THEN
        RAISE EXCEPTION 'NOT_AUTHORIZED';
    END IF;

    -- Get the current user's admin status for this specific group.
    SELECT is_admin INTO v_current_user_is_admin FROM public.user_groups WHERE "group" = p_group_id AND "user" = auth.uid();

    -- If authorized, build the final JSON object.
    SELECT
        jsonb_build_object(
            'id', ugi.id,
            'title', ugi.title,
            'description', ugi.description,
            'type', ugi.type,
            'data', ugi.data,
            'place', ugi.place, -- This is placeId
            'is_admin', COALESCE(v_current_user_is_admin, false),
            'places', (SELECT row_to_json(p)::jsonb FROM public.places p WHERE p.id = ugi.place),
            'user_groups', (
                SELECT COALESCE(jsonb_agg(
                    jsonb_build_object(
                        'is_admin', ug.is_admin,
                        'user_info', row_to_json(p_ui)::jsonb
                    )
                ), '[]'::jsonb)
                FROM public.user_groups ug
                JOIN public.user_info p_ui ON ug."user" = p_ui.id
                WHERE ug."group" = ugi.id
            )
        )
    INTO result_json
    FROM public.user_group_info ugi
    WHERE ugi.id = p_group_id;

    RETURN result_json;
END;
$$;


ALTER FUNCTION "public"."get_user_group_info_with_users"("p_group_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_user_groups"("p_occasion_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    -- Retrieve the user ID from the authentication context
    current_user_id UUID := auth.uid();
BEGIN
    -- This function retrieves all groups a user is a member of for a specific occasion,
    -- including their admin status for each group.
    -- It joins the user_groups table (which defines membership and roles)
    -- with the user_group_info table (which contains group details)
    -- and filters the results by the provided occasion ID.
    -- The result is aggregated into a single JSONB object (dictionary) where keys are group IDs.

    RETURN (
        SELECT
            -- COALESCE ensures that if the user is not in any groups for this occasion,
            -- an empty JSON object '{}' is returned instead of NULL.
            COALESCE(
                jsonb_object_agg(
                    ugi.id, -- The group ID is used as the key.
                    -- jsonb_build_object constructs a JSON object for each group.
                    jsonb_build_object(
                        'id', ugi.id,
                        'title', ugi.title,
                        'type', ugi.type,
                        'place', ugi.place,
                        'description', ugi.description,
                        'occasion', ugi.occasion,
                        'data', ugi.data,
                        'is_admin', ug.is_admin
                    )
                ),
                '{}'::JSONB
            )
        FROM
            -- ug is the membership link table
            public.user_groups ug
        JOIN
            -- ugi contains the actual information about the group
            public.user_group_info ugi ON ug."group" = ugi.id
        WHERE
            -- Filter to get groups for the currently authenticated user
            ug."user" = current_user_id
            -- AND filter by the specific occasion ID passed to the function
            AND ugi.occasion = p_occasion_id
    );
END;
$$;


ALTER FUNCTION "public"."get_user_groups"("p_occasion_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_user_groups_by_occasion"("occasion_id_in" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    -- Retrieve the user ID from the authentication context
    current_user_id UUID := auth.uid();
BEGIN
    -- This function retrieves all groups a user is a member of for a specific occasion,
    -- including their admin status for each group.
    -- It joins the user_groups table (which defines membership and roles)
    -- with the user_group_info table (which contains group details)
    -- and filters the results by the provided occasion ID.
    -- The result is aggregated into a single JSONB array.

    RETURN (
        SELECT
            -- COALESCE ensures that if the user is not in any groups for this occasion,
            -- an empty JSON array '[]' is returned instead of NULL.
            COALESCE(
                jsonb_agg(
                    -- jsonb_build_object constructs a JSON object for each group.
                    jsonb_build_object(
                        'id', ugi.id,
                        'title', ugi.title,
                        'type', ugi.type,
                        'place', ugi.place,
                        'description', ugi.description,
                        'occasion', ugi.occasion,
                        'data', ugi.data,
                        'is_admin', ug.is_admin
                    )
                ),
                '[]'::JSONB
            )
        FROM
            -- ug is the membership link table
            public.user_groups ug
        JOIN
            -- ugi contains the actual information about the group
            public.user_group_info ugi ON ug."group" = ugi.id
        WHERE
            -- Filter to get groups for the currently authenticated user
            ug."user" = current_user_id
            -- AND filter by the specific occasion ID passed to the function
            AND ugi.occasion = occasion_id_in
    );
END;
$$;


ALTER FUNCTION "public"."get_user_groups_by_occasion"("occasion_id_in" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_user_groups_editor_bundle_v1"("p_occasion" bigint, "p_type" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_groups jsonb; v_places jsonb; v_game_definitions jsonb;
BEGIN
  IF NOT public.get_is_editor_view_on_occasion(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor view required';
  END IF;
  SELECT COALESCE(jsonb_agg(public.get_user_group_command_data_v1(g.id)||
    jsonb_build_object('aggregate_version',COALESCE(v.version,0))
    ORDER BY g.title,g.id),'[]'::jsonb) INTO v_groups
  FROM public.user_group_info g LEFT JOIN public.client_aggregate_versions v
    ON v.aggregate_type='user_group' AND v.scope_type='occasion'
    AND v.scope_id=p_occasion AND v.aggregate_id=g.id::text
  WHERE g.occasion=p_occasion AND (p_type IS NULL AND g.type IS NULL OR g.type=p_type);
  SELECT COALESCE(jsonb_agg(to_jsonb(p)||jsonb_build_object(
    'aggregate_version',COALESCE(v.version,0)) ORDER BY p."order" NULLS LAST,p.title),
    '[]'::jsonb) INTO v_places FROM public.places p
  LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='place'
    AND v.scope_type='occasion' AND v.scope_id=p_occasion
    AND v.aggregate_id=p.id::text
  WHERE p.occasion=p_occasion AND NOT p.is_hidden
    AND p.coordinates->'latLng'->>'lat' IS NOT NULL
    AND p.coordinates->'latLng'->>'lng' IS NOT NULL;
  IF p_type='game' THEN
    SELECT jsonb_object_agg(i.id,i.title) INTO v_game_definitions
    FROM public.information i WHERE i.occasion=p_occasion AND i.type='game';
  END IF;
  RETURN jsonb_build_object('groups',v_groups,'places',v_places,
    'game_definitions',v_game_definitions);
END; $$;


