CREATE OR REPLACE FUNCTION "public"."get_user_info_for_users"("user_ids" "uuid"[], "oc" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  companions jsonb;
BEGIN
  -- Check if the user is a manager, editor, or approver for the occasion
  IF (SELECT get_is_manager_on_occasion(oc) OR get_is_editor_on_occasion(oc) OR get_is_approver_on_occasion(oc)) <> TRUE THEN
      RETURN jsonb_build_object('code', 403);
  END IF;

  -- Aggregate the user information as JSON
  SELECT jsonb_agg(
    jsonb_build_object(
      'id', ui.id,
      'created_at', ui.created_at,
      'updated_at', ui.updated_at,
      'email_readonly', ui.email_readonly,
      'name', ui.name,
      'surname', ui.surname,
      'sex', ui.sex,
      'phone', ui.phone,
      'data', ui.data,
      'birth_date', ui.birth_date,
      'companion_parent', (
        SELECT jsonb_build_object(
          'id', parent_ui.id,
          'created_at', parent_ui.created_at,
          'updated_at', parent_ui.updated_at,
          'email_readonly', parent_ui.email_readonly,
          'name', parent_ui.name,
          'surname', parent_ui.surname,
          'sex', parent_ui.sex,
          'phone', parent_ui.phone,
          'data', parent_ui.data,
          'birth_date', parent_ui.birth_date
        )
        FROM public.user_info parent_ui
        WHERE parent_ui.id = uc."user"
      )
    )
  ) INTO companions
  FROM public.user_info ui
  LEFT JOIN public.user_companions uc ON ui.id = uc.companion AND uc.occasion=oc
  WHERE ui.id = ANY(user_ids);

  -- If no companions are found, return an empty array
  IF companions IS NULL THEN
    companions := '[]'::jsonb;
  END IF;

  RETURN jsonb_build_object(
    'code', 200,
    'data', companions
  );
END;
$$;


ALTER FUNCTION "public"."get_user_info_for_users"("user_ids" "uuid"[], "oc" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_user_inventory"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_user_id UUID;
    v_result JSONB;
BEGIN
    -- 1. Get the current user's ID.
    v_user_id := auth.uid();
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'User not authenticated. Cannot retrieve inventory.';
    END IF;

    -- 2. Create a definitive list of the user's tickets and associated products.
    -- This is the absolute source of truth for which products the user owns.
    WITH user_ticket_products AS (
        SELECT
            opt.id AS order_product_ticket_id,
            opt.product AS product_id
        FROM public.occasion_users ou
        JOIN eshop.order_product_ticket opt ON ou.ticket = opt.ticket
        WHERE ou."user" = v_user_id
          AND ou.ticket IS NOT NULL
          AND opt.product IS NOT NULL
    ),

    -- 3. Find the user's assigned spots and their context ONLY for the tickets identified above.
    user_assigned_inventory AS (
        SELECT
            s.id AS id, -- Renamed to 'id' to match the provided CTE
            s.title AS title, -- Renamed to 'title'
            s.state AS state, -- Renamed to 'state'
            s.resource_slot AS resource_slot, -- Renamed to 'resource_slot'
            s.resource AS resource, -- Renamed to 'resource'
            s.inventory_context AS inventory_context, -- Renamed to 'inventory_context'
            ic.inventory_pool AS inventory_pool, -- Renamed to 'inventory_pool'
            utp.product_id
        FROM eshop.spots s
        JOIN user_ticket_products utp ON s.order_product_ticket = utp.order_product_ticket_id
        JOIN public.inventory_contexts ic ON s.inventory_context = ic.id
    ),

    -- 4. Fetch the full data for each entity, strictly filtering by the IDs gathered above.

    -- MODIFIED: Fetches products STRICTLY from the user's tickets.
    products_json AS (
        SELECT
            jsonb_object_agg(p.id, jsonb_build_object(
                'id', p.id, 'title', p.title, 'description', p.description, 'price', p.price, 'data', p.data,
                'product_type', p.product_type, 'occasion', p.occasion, 'is_hidden', p.is_hidden,
                'currency_code', p.currency_code, 'order', p."order",
                'maximum', p.maximum, 'is_dynamically_available', is_product_dynamically_available(p.id)
            )) AS data
        FROM eshop.products p
        WHERE p.id IN (SELECT DISTINCT product_id FROM user_ticket_products)
    ),

    -- MODIFIED: Fetches PIC records using a precise (context, product) match from the user's assigned spots.
    -- This is the most minimal possible query for this data.
    product_inventory_contexts_json AS (
        SELECT jsonb_object_agg(pic.id, to_jsonb(pic)) AS data
        FROM eshop.product_inventory_contexts pic
        WHERE (pic.inventory_context, pic.product) IN (
            SELECT DISTINCT inventory_context, product_id FROM user_assigned_inventory -- Updated column name
        )
    ),

    -- Build the JSON for contexts, ensuring the 'spots' array is correctly populated.
    contexts_json AS (
        SELECT
            jsonb_object_agg(ic.id, jsonb_build_object(
                'id', ic.id, 'order', ic."order", 'block_date', ic.block_date, 'title', ic.title,
                'data', ic.data, 'inventory_pool', ic.inventory_pool,
                'spots', (
                    SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY t.id), '[]'::jsonb) -- Updated column name
                    FROM (
                        SELECT uai.id, uai.title, uai.state, uai.resource_slot, uai.resource, uai.product_id -- Updated column names
                        FROM user_assigned_inventory uai
                        WHERE uai.inventory_context = ic.id -- Updated column name
                    ) t
                )
            )) AS data
        FROM public.inventory_contexts ic
        WHERE ic.id IN (SELECT DISTINCT inventory_context FROM user_assigned_inventory) -- Updated column name
    ),

    -- Pools, Places, and Resources are filtered based on the derived inventory.
    pools_json AS (
        SELECT jsonb_object_agg(p.id, jsonb_strip_nulls(jsonb_build_object(
            'id', p.id, 'data', p.data, 'title', p.title, 'description', p.description,
            'type', p.type, 'sellable_capacity', p.sellable_capacity, 'occasion', p.occasion
        ))) AS data
        FROM public.inventory_pools p
        WHERE p.id IN (SELECT DISTINCT inventory_pool FROM user_assigned_inventory) -- Updated column name
    ),
    places_json AS (
        SELECT jsonb_object_agg(pl.id, to_jsonb(pl)) AS data
        FROM public.places pl
        JOIN (
            SELECT DISTINCT (ip.data->>'place_id')::bigint AS id
            FROM public.inventory_pools ip
            WHERE ip.id IN (SELECT DISTINCT inventory_pool FROM user_assigned_inventory) -- Updated column name
              AND ip.data ? 'place_id' AND ip.data->>'place_id' IS NOT NULL
        ) AS place_ids ON pl.id = place_ids.id
    ),
    resources_json AS (
        SELECT jsonb_object_agg(r.id, to_jsonb(r)) AS data
        FROM public.resources r
        WHERE r.id IN (SELECT DISTINCT resource FROM user_assigned_inventory WHERE resource IS NOT NULL) -- Updated column name
    )

    -- 5. Assemble the final, minimal JSON object.
    SELECT jsonb_build_object(
        'inventory_contexts', COALESCE((SELECT data FROM contexts_json), '{}'::jsonb),
        'inventory_pools', COALESCE((SELECT data FROM pools_json), '{}'::jsonb),
        'resources', COALESCE((SELECT data FROM resources_json), '{}'::jsonb),
        'products', COALESCE((SELECT data FROM products_json), '{}'::jsonb),
        'product_inventory_contexts', COALESCE((SELECT data FROM product_inventory_contexts_json), '{}'::jsonb),
        'places', COALESCE((SELECT data FROM places_json), '{}'::jsonb)
    )
    INTO v_result;

    -- 6. Return the final object.
    RETURN v_result;

END;
$$;


ALTER FUNCTION "public"."get_user_inventory"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_user_inventory_for_occasion_v1"("p_occasion" bigint) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  WITH user_ticket_products AS (
    SELECT opt.id order_product_ticket_id,opt.product product_id
    FROM public.occasion_users ou
    JOIN eshop.order_product_ticket opt ON opt.ticket=ou.ticket
    WHERE ou."user"=auth.uid() AND ou.occasion=p_occasion
      AND ou.ticket IS NOT NULL AND opt.product IS NOT NULL
  ), assigned AS (
    SELECT s.id,s.title,s.state,s.resource_slot,s.resource,s.inventory_context,
      ic.inventory_pool,utp.product_id
    FROM eshop.spots s
    JOIN user_ticket_products utp
      ON utp.order_product_ticket_id=s.order_product_ticket
    JOIN public.inventory_contexts ic ON ic.id=s.inventory_context
    JOIN public.inventory_pools ip ON ip.id=ic.inventory_pool
    WHERE ip.occasion=p_occasion
  )
  SELECT jsonb_build_object(
    'inventory_contexts',COALESCE((SELECT jsonb_object_agg(ic.id,
      jsonb_build_object('id',ic.id,'order',ic."order",'block_date',ic.block_date,
        'title',ic.title,'data',ic.data,'inventory_pool',ic.inventory_pool,
        'spots',(SELECT COALESCE(jsonb_agg(jsonb_build_object('id',a.id,
          'title',a.title,'state',a.state,'resource_slot',a.resource_slot,
          'resource',a.resource,'product_id',a.product_id) ORDER BY a.id),'[]')
          FROM assigned a WHERE a.inventory_context=ic.id)))
      FROM public.inventory_contexts ic
      WHERE ic.id IN (SELECT DISTINCT a.inventory_context FROM assigned a)),'{}'),
    'inventory_pools',COALESCE((SELECT jsonb_object_agg(ip.id,
      jsonb_strip_nulls(jsonb_build_object('id',ip.id,'data',ip.data,
        'title',ip.title,'description',ip.description,'type',ip.type,
        'sellable_capacity',ip.sellable_capacity,'occasion',ip.occasion)))
      FROM public.inventory_pools ip
      WHERE ip.occasion=p_occasion AND ip.id IN (
        SELECT DISTINCT a.inventory_pool FROM assigned a)),'{}'),
    'resources',COALESCE((SELECT jsonb_object_agg(r.id,to_jsonb(r))
      FROM public.resources r WHERE r.occasion=p_occasion AND r.id IN (
        SELECT DISTINCT a.resource FROM assigned a WHERE a.resource IS NOT NULL)),'{}'),
    'products',COALESCE((SELECT jsonb_object_agg(p.id,jsonb_build_object(
      'id',p.id,'title',p.title,'description',p.description,'price',p.price,
      'data',p.data,'product_type',p.product_type,'occasion',p.occasion,
      'is_hidden',p.is_hidden,'currency_code',p.currency_code,'order',p."order",
      'maximum',p.maximum,'is_dynamically_available',
        public.is_product_dynamically_available(p.id)))
      FROM eshop.products p WHERE p.id IN (
        SELECT DISTINCT a.product_id FROM assigned a)),'{}'),
    'product_inventory_contexts',COALESCE((SELECT jsonb_object_agg(pic.id,to_jsonb(pic))
      FROM eshop.product_inventory_contexts pic
      WHERE (pic.inventory_context,pic.product) IN (
        SELECT DISTINCT a.inventory_context,a.product_id FROM assigned a)),'{}'),
    'places',COALESCE((SELECT jsonb_object_agg(pl.id,to_jsonb(pl))
      FROM public.places pl WHERE pl.occasion=p_occasion AND pl.id IN (
        SELECT DISTINCT (ip.data->>'place_id')::bigint
        FROM public.inventory_pools ip
        WHERE ip.id IN (SELECT DISTINCT a.inventory_pool FROM assigned a)
          AND ip.data ? 'place_id' AND ip.data->>'place_id' IS NOT NULL)),'{}'));
$$;


ALTER FUNCTION "public"."get_user_inventory_for_occasion_v1"("p_occasion" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_user_profile_data_patch"("p_data" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO 'public', 'extensions'
    AS $$
  SELECT COALESCE(jsonb_object_agg(entry.key, entry.value), '{}'::jsonb)
  FROM jsonb_each(
    CASE WHEN jsonb_typeof(p_data) = 'object' THEN p_data ELSE '{}'::jsonb END
  ) AS entry
  WHERE entry.key = ANY (ARRAY[
    'name', 'surname', 'sex', 'phone', 'birthDate'
  ]::text[]);
$$;


ALTER FUNCTION "public"."get_user_profile_data_patch"("p_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_users_from_occasion_with_orders"("oc" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  users_data jsonb;
  tickets_data jsonb;
  order_product_tickets_data jsonb;
  orders_data jsonb;
  forms_data jsonb;
  form_fields_data jsonb;
  org_id bigint; -- Variable to store Organization ID
BEGIN
  -- 0. Retrieve Organization ID
  -- We need this to check the organization_users table
  SELECT organization INTO org_id
  FROM public.occasions
  WHERE id = oc;

  -- Security check: If the user lacks permission, raise an exception.
  IF (SELECT get_is_editor_view_on_occasion(oc)) <> TRUE THEN
      RAISE EXCEPTION 'User is not authorized to access this occasion' USING ERRCODE = '42501';
  END IF;

  -- 1. Fetch users as a JSON object, keyed by user ID.
  SELECT jsonb_object_agg(ui.id,
    jsonb_strip_nulls(jsonb_build_object(
      'id', ui.id,
      'name', ui.name,
      'surname', ui.surname,
      'sex', ui.sex,
      'email_readonly', ui.email_readonly,
      'phone', ui.phone,
      'birth_date', ui.birth_date,
      'data', ui.data,
      'ticket_id', ou.ticket,
      'companions', (
        SELECT COALESCE(jsonb_agg(
          jsonb_build_object(
            'id', comp_ui.id,
            'name', comp_ui.name,
            'surname', comp_ui.surname
          )
        ), '[]'::jsonb)
        FROM public.user_companions uc
        JOIN public.user_info comp_ui ON uc.companion = comp_ui.id
        WHERE uc."user" = ui.id AND uc.occasion=oc
      )
    ))
  ) INTO users_data
  FROM public.occasion_users ou
  JOIN public.user_info ui ON ou."user" = ui.id

  -- Join to check visibility
  LEFT JOIN public.organization_users org_u ON ui.id = org_u."user" AND org_u.organization = org_id

  WHERE ou.occasion = oc
  -- Filter hidden users
  AND (org_u.is_hidden IS NOT TRUE);

  -- 2. Use CTEs to gather the unique IDs of all related items, preventing duplicates.
  WITH relevant_tickets AS (
      -- Get unique ticket IDs directly linked to users on the occasion
      -- We MUST apply the same hidden filter here, otherwise we might fetch tickets for hidden users
      SELECT DISTINCT ou.ticket AS id
      FROM public.occasion_users ou
      LEFT JOIN public.organization_users org_u ON ou."user" = org_u."user" AND org_u.organization = org_id
      WHERE ou.occasion = oc
        AND ou.ticket IS NOT NULL
        AND (org_u.is_hidden IS NOT TRUE)
  ),
  relevant_orders AS (
      -- From those tickets, get unique order IDs via the join table
      -- (This automatically excludes orders from hidden users because relevant_tickets is filtered)
      SELECT DISTINCT "order" AS id
      FROM eshop.order_product_ticket
      WHERE ticket IN (SELECT id FROM relevant_tickets)
  ),
  relevant_forms AS (
      -- From those orders, get unique form IDs
      SELECT DISTINCT f.id
      FROM public.forms f
      JOIN eshop.orders o ON f.occasion = o.occasion AND f.key::text = o.data->>'form'
      WHERE o.id IN (SELECT id FROM relevant_orders)
  )
  -- 3. Fetch the data as dictionaries, using the de-duplicated ID sets from the CTEs.
  SELECT
    (SELECT jsonb_object_agg(t.id, to_jsonb(t)) FROM eshop.tickets t WHERE t.id IN (SELECT id FROM relevant_tickets)),
    (SELECT jsonb_object_agg(o.id, to_jsonb(o)) FROM eshop.orders o WHERE o.id IN (SELECT id FROM relevant_orders)),
    (SELECT jsonb_object_agg(opt.id, to_jsonb(opt)) FROM eshop.order_product_ticket opt WHERE opt.order IN (SELECT id FROM relevant_orders)),
    (SELECT jsonb_object_agg(f.id, to_jsonb(f)) FROM public.forms f WHERE f.id IN (SELECT id FROM relevant_forms)),
    (SELECT jsonb_object_agg(ff.id, to_jsonb(ff)) FROM public.form_fields ff WHERE ff.form IN (SELECT id FROM relevant_forms))
  INTO
    tickets_data,
    orders_data,
    order_product_tickets_data,
    forms_data,
    form_fields_data;

  -- 4. Return the data object directly.
  RETURN jsonb_build_object(
      'users', COALESCE(users_data, '{}'::jsonb),
      'tickets', COALESCE(tickets_data, '{}'::jsonb),
      'order_product_ticket', COALESCE(order_product_tickets_data, '{}'::jsonb),
      'orders', COALESCE(orders_data, '{}'::jsonb),
      'forms', COALESCE(forms_data, '{}'::jsonb),
      'form_fields', COALESCE(form_fields_data, '{}'::jsonb)
  );
END;
$$;


ALTER FUNCTION "public"."get_users_from_occasion_with_orders"("oc" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."groups_get_user_groups"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    user_id UUID := auth.uid();  -- Retrieve the user ID from the authentication context
    user_groups JSONB := '[]'::JSONB;  -- Initialize an empty JSON array
BEGIN
    -- Step 1: Query groups where the user is the leader in `user_group_info`
    user_groups := (
        SELECT COALESCE(jsonb_agg(
            jsonb_build_object(
                'id', ug.id,
                'title', ug.title,
                'type', ug.type,
                'leader', ug.leader,
                'place', ug.place,
                'description', ug.description,
                'occasion', ug.occasion,
                'data', ug.data
            )
        ), '[]'::JSONB)
        FROM user_group_info ug
        WHERE ug.leader = user_id
    );

    -- Step 2: Query groups where the user is a member in `user_groups` but not the leader
    user_groups := user_groups || (
        SELECT COALESCE(jsonb_agg(
            jsonb_build_object(
                'id', ug_info.id,
                'title', ug_info.title,
                'type', ug_info.type,
                'leader', ug_info.leader,
                'place', ug_info.place,
                'description', ug_info.description,
                'occasion', ug_info.occasion,
                'data', ug_info.data
            )
        ), '[]'::JSONB)
        FROM user_groups ug
        JOIN user_group_info ug_info ON ug."group" = ug_info.id
        WHERE ug.user = user_id AND ug_info.leader IS DISTINCT FROM user_id
    );

    -- Return code 200 with the combined array of user groups
    RETURN jsonb_build_object('code', 200, 'data', user_groups);
END;
$$;


ALTER FUNCTION "public"."groups_get_user_groups"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."impact_companion_owners_v1"("p_occasion" bigint, "p_companions" "uuid"[], "p_source" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE v_impacts jsonb;
BEGIN
  SELECT COALESCE(jsonb_agg(jsonb_build_object('component','private_profile',
    'userId',owners."user") ORDER BY owners."user"),'[]'::jsonb)
  INTO v_impacts
  FROM (SELECT DISTINCT uc."user" FROM public.user_companions uc
    WHERE uc.occasion=p_occasion AND uc.companion=ANY(p_companions)) owners;
  IF jsonb_array_length(v_impacts)>0 THEN
    PERFORM public.record_client_sync_commit_v1(p_occasion,p_source,'profile',
      '[]','{}',v_impacts,'[]','user',NULL);
  END IF;
END $$;


ALTER FUNCTION "public"."impact_companion_owners_v1"("p_occasion" bigint, "p_companions" "uuid"[], "p_source" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."impact_private_profile_users_v1"("p_occasion" bigint, "p_users" "uuid"[], "p_source" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE v_impacts jsonb;
BEGIN
  SELECT COALESCE(jsonb_agg(jsonb_build_object('component','private_profile',
    'userId',impacted.id) ORDER BY impacted.id),'[]'::jsonb)
  INTO v_impacts
  FROM (SELECT DISTINCT id FROM unnest(COALESCE(p_users,'{}'::uuid[])) id) impacted
  JOIN public.occasion_users ou
    ON ou.occasion=p_occasion AND ou."user"=impacted.id;
  IF jsonb_array_length(v_impacts)>0 THEN
    PERFORM public.record_client_sync_commit_v1(p_occasion,p_source,'profile',
      '[]','{}',v_impacts,'[]','user',NULL);
  END IF;
END $$;


