CREATE OR REPLACE FUNCTION "public"."insert_manual_transaction"("p_amount" double precision, "p_currency" "text", "p_unit_id" integer, "p_variable_symbol" "text", "p_date" "text", "p_note" "text" DEFAULT NULL::"text", "p_payment_info_id" integer DEFAULT NULL::integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'eshop', 'extensions'
    AS $$
DECLARE
    v_account_id int;
    v_date timestamp with time zone;
    v_new_transaction_id bigint;
    v_payment_info_id bigint;
BEGIN
    PERFORM public.check_is_manager_on_unit(p_unit_id);
    v_date := p_date::timestamp with time zone;

    SELECT ba.id INTO v_account_id
    FROM eshop.bank_accounts ba
    JOIN eshop.unit_bank_accounts uba ON ba.id = uba.bank_account
    WHERE uba.unit = p_unit_id
      AND ba.type = 'CASH'
      AND p_currency = ANY(ba.supported_currencies);

    IF v_account_id IS NULL THEN
        INSERT INTO eshop.bank_accounts (
            title, type, supported_currencies, account_number, account_number_human_readable
        ) VALUES (
            'Cash Account (' || p_currency || ')', 'CASH', ARRAY[p_currency], '', ''
        )
        RETURNING id INTO v_account_id;

        INSERT INTO eshop.unit_bank_accounts (unit, bank_account, priority)
        VALUES (p_unit_id, v_account_id, 0);
    END IF;

    INSERT INTO eshop.transactions (
        bank_account_id,
        transaction_id,
        amount,
        currency,
        date,
        vs,
        message_for_recipient,
        transaction_type,
        created_by
    ) VALUES (
        v_account_id,
        ('-1' || (extract(epoch from now()) * 1000)::bigint::text)::bigint,
        p_amount,
        p_currency,
        v_date,
        p_variable_symbol,
        p_note,
        'manual',
        auth.uid()
    )
    RETURNING id INTO v_new_transaction_id;

    IF p_payment_info_id IS NOT NULL THEN
         v_payment_info_id := p_payment_info_id;
    ELSIF p_variable_symbol IS NOT NULL AND p_variable_symbol != '' THEN
        BEGIN
            SELECT id INTO v_payment_info_id
            FROM eshop.payment_info
            WHERE variable_symbol = p_variable_symbol::bigint
            LIMIT 1;
        EXCEPTION WHEN OTHERS THEN
             v_payment_info_id := NULL;
        END;
    END IF;

    IF v_payment_info_id IS NOT NULL THEN
            PERFORM public.add_transaction_to_payment_info(v_new_transaction_id, v_payment_info_id);
    END IF;
END;
$$;


ALTER FUNCTION "public"."insert_manual_transaction"("p_amount" double precision, "p_currency" "text", "p_unit_id" integer, "p_variable_symbol" "text", "p_date" "text", "p_note" "text", "p_payment_info_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."insert_transactions"("transactions" "jsonb", "bank_account_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
  DECLARE
      transaction JSONB;
      parsed_date TIMESTAMPTZ;
      inserted_count INT := 0;
      skipped_count INT := 0;
      payment_info_data eshop.payment_info%ROWTYPE;
      new_transaction_id BIGINT;
      v_symbol_text TEXT;
  BEGIN
      -- Loop through each transaction provided in the JSONB array
      FOR transaction IN SELECT * FROM jsonb_array_elements(transactions) LOOP
          -- Reset variables for each loop iteration to prevent using old data
          new_transaction_id := NULL;
          payment_info_data := NULL;

          -- Attempt to parse the transaction date
          BEGIN
              parsed_date := (transaction->'column0'->>'value')::TIMESTAMPTZ;
          EXCEPTION WHEN OTHERS THEN
              RAISE NOTICE 'Invalid date format, skipping transaction: %', transaction->'column0'->>'value';
              skipped_count := skipped_count + 1;
              CONTINUE;
          END;

          -- Check if the transaction already exists in the database to prevent duplicates
          IF EXISTS (
              SELECT 1
              FROM eshop.transactions
              WHERE transaction_id = (transaction->'column22'->>'value')::BIGINT
          ) THEN
              skipped_count := skipped_count + 1;
              CONTINUE;
          END IF;

          -- If the transaction is new, insert it into the database
          INSERT INTO eshop.transactions (
              transaction_id, date, amount, currency, counter_account, bank_code,
              bank_name, ks, vs, ss, user_identification, transaction_type,
              performed_by, comment, command_id, bank_account_id, message_for_recipient, counter_account_name
          ) VALUES (
              (transaction->'column22'->>'value')::BIGINT, -- ID pohybu
              parsed_date, -- Parsed Datum
              (transaction->'column1'->>'value')::NUMERIC, -- Objem
              transaction->'column14'->>'value', -- Měna
              transaction->'column2'->>'value', -- Protiúčet
              transaction->'column3'->>'value', -- Kód banky
              transaction->'column12'->>'value', -- Název banky
              NULLIF(transaction->'column4'->>'value', ''), -- KS
              NULLIF(transaction->'column5'->>'value', ''), -- VS
              NULLIF(transaction->'column6'->>'value', ''), -- SS
              transaction->'column7'->>'value', -- Uživatelská identifikace
              transaction->'column8'->>'value', -- Typ
              transaction->'column9'->>'value', -- Provedl
              transaction->'column25'->>'value', -- Komentář
              (transaction->'column17'->>'value')::BIGINT, -- ID pokynu
              bank_account_id, -- Bank Account ID from the function parameter
              transaction->'column16'->>'value', -- Zpráva pro příjemce
              transaction->'column10'->>'value'  -- Název protiúčtu
          )
          RETURNING id INTO new_transaction_id;
          inserted_count := inserted_count + 1;

          -- Get the variable symbol from the transaction data
          v_symbol_text := transaction->'column5'->>'value';

          -- Only try to find payment_info if a variable symbol is present
          IF v_symbol_text IS NOT NULL AND v_symbol_text != '' THEN
              -- Look for a payment_info using the variable symbol (vs) AND the bank_account_id.
              -- This ensures we only match payments for the specific bank account.
              SELECT * INTO payment_info_data
              FROM eshop.payment_info
              WHERE variable_symbol = v_symbol_text::BIGINT
                AND eshop.payment_info.bank_account = insert_transactions.bank_account_id
              LIMIT 1;

              -- If a matching payment_info is found, associate it with the new transaction
              IF FOUND THEN
                  BEGIN
                      -- Call the function to handle the association
                      PERFORM public.add_transaction_to_payment_info(
                          new_transaction_id,      -- The newly created transactions.id
                          payment_info_data.id     -- The found payment_info_id
                      );
                  EXCEPTION WHEN OTHERS THEN
                      RAISE NOTICE 'Error associating transaction_id % with payment_info: %', new_transaction_id, SQLERRM;
                      -- Continue to the next transaction even if this part fails
                  END;
              END IF;
          END IF;
      END LOOP;

      -- Return a summary of the operation
      RETURN jsonb_build_object(
          'inserted', inserted_count,
          'skipped', skipped_count
      );
  END;
  $$;


ALTER FUNCTION "public"."insert_transactions"("transactions" "jsonb", "bank_account_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."inspect_account_deletion_token"("p_token_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $_$
DECLARE v_request public.account_deletion_requests%ROWTYPE;
BEGIN
  IF p_token_hash !~ '^[0-9a-f]{64}$' THEN RETURN jsonb_build_object('status', 'invalid'); END IF;
  SELECT * INTO v_request FROM public.account_deletion_requests
  WHERE token_hash = p_token_hash OR used_token_hash = p_token_hash
  LIMIT 1;
  IF v_request.id IS NULL THEN RETURN jsonb_build_object('status', 'invalid'); END IF;
  IF v_request.status = 'completed' THEN RETURN jsonb_build_object('status', 'already_completed'); END IF;
  IF v_request.status <> 'email_sent' THEN RETURN jsonb_build_object('status', 'invalid'); END IF;
  IF v_request.expires_at <= clock_timestamp() THEN RETURN jsonb_build_object('status', 'expired'); END IF;
  RETURN jsonb_build_object('status', 'valid', 'expiresAt', v_request.expires_at);
END;
$_$;


ALTER FUNCTION "public"."inspect_account_deletion_token"("p_token_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."internal_storno_tickets_221"("ticket_ids_to_storno" bigint[]) RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    opt_ids BIGINT[];
BEGIN
    IF ticket_ids_to_storno IS NULL OR array_length(ticket_ids_to_storno, 1) = 0 THEN
        RETURN; -- Nothing to do
    END IF;

    -- 1. Get all related order_product_ticket IDs
    SELECT ARRAY_AGG(opt.id) INTO opt_ids
    FROM eshop.order_product_ticket opt
    WHERE opt.ticket = ANY(ticket_ids_to_storno);

    -- 2. (NEW) Delete any occasion_users linked to these tickets.
    -- We delete directly because the parent function already
    -- verified the user has 'editor' permissions.
    DELETE FROM public.occasion_users
    WHERE ticket = ANY(ticket_ids_to_storno);

    -- 3. Update the tickets themselves to 'storno'
    UPDATE eshop.tickets
    SET state = 'storno', updated_at = NOW()
    WHERE id = ANY(ticket_ids_to_storno);

    -- 4. Nullify the relevant spots
    IF opt_ids IS NOT NULL THEN
        UPDATE eshop.spots
        SET order_product_ticket = NULL,
            secret = NULL,
            secret_expiration_time = NULL,
            updated_at = NOW(),
            resource = NULL,
            state = NULL
        WHERE order_product_ticket = ANY(opt_ids);
    END IF;

    -- 5. Nullify the product link on the order_product_ticket records
    UPDATE eshop.order_product_ticket
    SET product = NULL
    WHERE ticket = ANY(ticket_ids_to_storno);

END;
$$;


ALTER FUNCTION "public"."internal_storno_tickets_221"("ticket_ids_to_storno" bigint[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."is_claims_admin"() RETURNS boolean
    LANGUAGE "plpgsql"
    AS $$
  BEGIN
    IF session_user = 'authenticator' THEN
      --------------------------------------------
      -- To disallow any authenticated app users
      -- from editing claims, delete the following
      -- block of code and replace it with:
      -- RETURN FALSE;
      --------------------------------------------
      IF extract(epoch from now()) > coalesce((current_setting('request.jwt.claims', true)::jsonb)->>'exp', '0')::numeric THEN
        return false; -- jwt expired
      END IF;
      If current_setting('request.jwt.claims', true)::jsonb->>'role' = 'service_role' THEN
        RETURN true; -- service role users have admin rights
      END IF;
      IF coalesce((current_setting('request.jwt.claims', true)::jsonb)->'app_metadata'->'is_admin', 'false')::bool THEN
        return true; -- user has is_claims_admin set to true
      ELSE
        return false; -- user does NOT have is_claims_admin set to true
      END IF;
      --------------------------------------------
      -- End of block
      --------------------------------------------
    ELSE -- not a user session, probably being called from a trigger or something
      return true;
    END IF;
  END;
$$;


ALTER FUNCTION "public"."is_claims_admin"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."is_product_dynamically_available"("p_product_id" bigint) RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    AS $$
DECLARE
    context_record RECORD;
    occupied_spots BIGINT;
    total_spots BIGINT;
BEGIN
    -- If a product is not linked to any inventory contexts,
    -- it is considered available by default.
    IF NOT EXISTS (SELECT 1 FROM eshop.product_inventory_contexts WHERE product = p_product_id) THEN
        RETURN TRUE;
    END IF;

    -- Iterate through each inventory context required by the product.
    FOR context_record IN
        SELECT
            pic.inventory_context,
            pic.quantity,
            ip.sellable_capacity
        FROM eshop.product_inventory_contexts pic
        JOIN public.inventory_contexts ic ON pic.inventory_context = ic.id
        JOIN public.inventory_pools ip ON ic.inventory_pool = ip.id
        WHERE pic.product = p_product_id
    LOOP
        -- Calculate the total number of physical spots available for the context.
        SELECT count(*)
        INTO total_spots
        FROM eshop.spots
        WHERE inventory_context = context_record.inventory_context;

        -- Calculate the number of spots that are currently occupied.
        -- A spot is considered occupied if it's assigned to an order (opt is not null)
        -- or if it has been temporarily reserved via a secret.
        SELECT count(*)
        INTO occupied_spots
        FROM eshop.spots
        WHERE inventory_context = context_record.inventory_context
          AND (order_product_ticket IS NOT NULL OR (secret IS NOT NULL AND secret_expiration_time > now()));

        -- Check 1: Ensure purchasing does not exceed the total physical spots.
        IF (occupied_spots + context_record.quantity) > total_spots THEN
            RETURN FALSE;
        END IF;

        -- Check 2: If a commercial sellable capacity is set on the pool,
        -- ensure purchasing does not exceed this limit.
        IF context_record.sellable_capacity IS NOT NULL AND (occupied_spots + context_record.quantity) > context_record.sellable_capacity THEN
            RETURN FALSE;
        END IF;
    END LOOP;

    -- If all checks for all contexts pass, the product is available for purchase.
    RETURN TRUE;
END;
$$;


ALTER FUNCTION "public"."is_product_dynamically_available"("p_product_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."is_service_role"() RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
DECLARE v_role text:=NULLIF(current_setting('request.jwt.claim.role',true),'');
  v_claims text;
BEGIN
  IF session_user='postgres' THEN RETURN true; END IF;
  IF v_role IS NULL THEN
    v_claims:=NULLIF(current_setting('request.jwt.claims',true),'');
    IF v_claims IS NOT NULL THEN
      BEGIN v_role:=v_claims::jsonb->>'role';
      EXCEPTION WHEN OTHERS THEN RETURN false; END;
    END IF;
  END IF;
  RETURN COALESCE(v_role='service_role',false);
END; $$;


