    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT public.set_cleaning_reporter_blocked_internal_v1(
    p_occasion,p_user,p_blocked);
$$;


ALTER FUNCTION "public"."set_cleaning_reporter_blocked"("p_occasion" bigint, "p_user" "uuid", "p_blocked" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_cleaning_reporter_blocked_client_sync_v1"("p_occasion" bigint, "p_user" "uuid", "p_blocked" boolean, "p_command_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_actor uuid:=auth.uid(); v_begin jsonb; v_hash text; v_result jsonb;
  v_current boolean; v_impacts jsonb; v_replacements jsonb:='[]'::jsonb;
BEGIN
  IF v_actor IS NULL THEN RAISE insufficient_privilege USING MESSAGE='sign in required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',p_occasion,'userId',p_user,'blocked',p_blocked)::text,'UTF8'),
    'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'cleaning.reporter.set',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  SELECT ou.is_cleaning_blocked INTO v_current FROM public.occasion_users ou
    WHERE ou.occasion=p_occasion AND ou."user"=p_user FOR UPDATE;
  v_result:=public.set_cleaning_reporter_blocked_internal_v1(
    p_occasion,p_user,p_blocked);
  IF COALESCE((v_result->>'code')::integer,500)<>200 THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',
      COALESCE((v_result->>'code')::integer,400),COALESCE(v_result->'data','{}')||
      jsonb_build_object('message',v_result->>'message')); END IF;
  IF v_current IS NOT DISTINCT FROM p_blocked THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
      v_result->'data'); END IF;
  v_impacts:=jsonb_build_array(jsonb_build_object(
    'component','private_profile','userId',p_user));
  IF p_user=v_actor THEN v_replacements:=jsonb_build_array(jsonb_build_object(
    'component','private_profile','userId',v_actor,
    'payload',public.get_private_profile_payload_v1(p_occasion,v_actor))); END IF;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'cleaning.reporter.set','profile',jsonb_build_array(jsonb_build_object(
      'entityType','occasion_user','entityId',p_user,'operation','update',
      'safeLabel','Cleaning reporter','changedFields',jsonb_build_array('blocked'))),
    '{}',v_impacts,'[]',v_result->'data','{}','[]','user',NULL,v_replacements);
END; $$;


ALTER FUNCTION "public"."set_cleaning_reporter_blocked_client_sync_v1"("p_occasion" bigint, "p_user" "uuid", "p_blocked" boolean, "p_command_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_cleaning_reporter_blocked_internal_v1"("p_occasion" bigint, "p_user" "uuid", "p_blocked" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_found boolean;
BEGIN
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('code', 401, 'message', 'Sign in is required');
  END IF;

  IF p_user IS NULL THEN
    RETURN jsonb_build_object('code', 400, 'message', 'Target user is required');
  END IF;

  -- Blocking needs crew rights; unblocking needs the higher editor right.
  IF p_blocked THEN
    IF NOT public.get_is_cleaning_crew_on_occasion(p_occasion) THEN
      RETURN jsonb_build_object('code', 403, 'message', 'Cleaning crew access required');
    END IF;
  ELSE
    IF NOT public.get_is_editor_on_occasion(p_occasion) THEN
      RETURN jsonb_build_object('code', 403, 'message', 'Editor access required to unblock');
    END IF;
  END IF;

  IF p_blocked THEN
    UPDATE public.occasion_users
    SET is_cleaning_blocked = true,
        data = COALESCE(data, '{}'::jsonb) || jsonb_build_object(
          'cleaning_blocked_by', v_caller::text,
          'cleaning_blocked_at', to_char(now(), 'YYYY-MM-DD"T"HH24:MI:SSOF'))
    WHERE occasion = p_occasion AND "user" = p_user
    RETURNING true INTO v_found;
  ELSE
    UPDATE public.occasion_users
    SET is_cleaning_blocked = false,
        data = COALESCE(data, '{}'::jsonb) - 'cleaning_blocked_by' - 'cleaning_blocked_at'
    WHERE occasion = p_occasion AND "user" = p_user
    RETURNING true INTO v_found;
  END IF;

  IF NOT COALESCE(v_found, false) THEN
    RETURN jsonb_build_object('code', 404, 'message', 'Participant not found on this occasion');
  END IF;

  RETURN jsonb_build_object(
    'code', 200,
    'data', jsonb_build_object('blocked', p_blocked)
  );
END;
$$;


ALTER FUNCTION "public"."set_cleaning_reporter_blocked_internal_v1"("p_occasion" bigint, "p_user" "uuid", "p_blocked" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_event_attendance_client_sync_v1"("p_event_id" bigint, "p_participant_id" "uuid", "p_action" "text", "p_command_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor uuid:=auth.uid(); v_occasion bigint; v_event public.events%ROWTYPE;
  v_begin jsonb; v_hash text; v_response jsonb; v_commit jsonb;
  v_private_revision bigint; v_live_revision bigint; v_private_payload jsonb;
  v_live_payload jsonb; v_code integer; v_registration_start timestamptz;
  v_feature jsonb; v_limit integer; v_count bigint; v_group bigint;
  v_is_male boolean; v_changed boolean:=false; v_status text;
  v_needs_occasion_join boolean:=false; v_profile_revision bigint;
  v_profile_payload jsonb; v_private_impacts jsonb; v_items jsonb;
  v_is_publishable boolean; v_companion_owner uuid;
BEGIN
  IF p_action NOT IN ('sign_in','sign_out') OR p_participant_id IS NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid attendance command';
  END IF;
  SELECT e.occasion,NOT o.is_hidden INTO v_occasion,v_is_publishable
  FROM public.events e JOIN public.occasions o ON o.id=e.occasion
  WHERE e.id=p_event_id;
  IF v_actor IS NULL OR v_occasion IS NULL OR NOT (
    v_actor=p_participant_id OR EXISTS (SELECT 1 FROM public.user_companions c
      WHERE c.occasion=v_occasion AND c."user"=v_actor AND c.companion=p_participant_id AND COALESCE((public.get_companion_feature_policy_v1(v_occasion)->>'is_enabled')::boolean,false))
    OR public.get_is_editor_on_occasion(v_occasion)) THEN
    RAISE insufficient_privilege USING MESSAGE='participant attendance permission required';
  END IF;
  SELECT c."user" INTO v_companion_owner FROM public.user_companions c
    JOIN public.occasion_users ou ON ou."user"=c."user" AND ou.occasion=v_occasion
    WHERE c.occasion=v_occasion AND c.companion=p_participant_id ORDER BY c."user" LIMIT 1;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('eventId',p_event_id,
    'participantId',p_participant_id,'action',p_action)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'event.attendance.'||p_action,
    v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(
    'attendance-user:'||p_participant_id::text||':'||v_occasion::text,0));
  FOR v_group IN SELECT ee."group" FROM public.exclusive_events ee
      WHERE ee.event=p_event_id ORDER BY ee."group" LOOP
    PERFORM pg_advisory_xact_lock(hashtextextended(
      'attendance-group:'||v_group::text,0));
  END LOOP;
  SELECT * INTO STRICT v_event FROM public.events e WHERE e.id=p_event_id
    AND e.occasion=v_occasion FOR UPDATE;

  IF p_action='sign_out' THEN
    IF NOT EXISTS (SELECT 1 FROM public.event_users eu
      WHERE eu.event=p_event_id AND eu."user"=p_participant_id) THEN
      v_status:='unchanged'; v_code:=404;
    ELSIF clock_timestamp() > v_event.end_time THEN
      v_status:='rejected'; v_code:=201;
    ELSE
      DELETE FROM public.event_users WHERE event=p_event_id AND "user"=p_participant_id;
      v_changed:=true; v_code:=200;
    END IF;
  ELSE
    IF NOT EXISTS (SELECT 1 FROM public.occasion_users ou
      WHERE ou.occasion=v_occasion AND ou."user"=p_participant_id) THEN
      IF v_actor=p_participant_id AND EXISTS (SELECT 1 FROM public.occasions o
        WHERE o.id=v_occasion AND o.is_open) THEN
        v_needs_occasion_join:=true;
      END IF;
      IF NOT v_needs_occasion_join THEN
        v_status:='rejected'; v_code:=403;
      END IF;
    END IF;
    IF v_code IS NULL AND EXISTS (SELECT 1 FROM public.event_users eu
      WHERE eu.event=p_event_id AND eu."user"=p_participant_id) THEN
      v_status:='unchanged'; v_code:=103;
    END IF;
    IF v_code IS NULL AND clock_timestamp() > v_event.end_time THEN
      v_status:='rejected'; v_code:=100;
    END IF;

    IF v_code IS NULL AND COALESCE((v_event.data->>'is_counseling_slot')::boolean,false) THEN
      SELECT f INTO v_feature FROM public.occasions o,
        LATERAL jsonb_array_elements(o.features) f
      WHERE o.id=v_occasion AND f->>'code'='counseling' LIMIT 1;
      IF v_feature IS NULL OR COALESCE((v_feature->>'is_enabled')::boolean,false)=false THEN
        v_status:='rejected'; v_code:=108;
      ELSE
        v_registration_start:=(v_feature->>'registration_start_time')::timestamptz;
        IF v_registration_start IS NOT NULL AND clock_timestamp()<v_registration_start THEN
          v_status:='rejected'; v_code:=104;
        END IF;
        v_limit:=COALESCE((v_feature->>'max_active_bookings')::integer,1);
        IF v_code IS NULL AND v_limit>0 THEN
          SELECT count(*) INTO v_count FROM public.event_users eu
          JOIN public.events e ON e.id=eu.event
          WHERE eu."user"=p_participant_id AND e.occasion=v_occasion
            AND COALESCE((e.data->>'is_counseling_slot')::boolean,false)
            AND e.end_time>clock_timestamp();
          IF v_count>=v_limit THEN v_status:='rejected'; v_code:=109; END IF;
        END IF;
      END IF;
    ELSIF v_code IS NULL THEN
      SELECT f INTO v_feature FROM public.occasions o,
        LATERAL jsonb_array_elements(o.features) f
      WHERE o.id=v_occasion AND f->>'code'='workshops' LIMIT 1;
      IF v_feature IS NOT NULL THEN
        IF COALESCE((v_feature->>'is_enabled')::boolean,false)=false THEN
          v_status:='rejected'; v_code:=108;
        ELSE
          v_registration_start:=(v_feature->>'start_time')::timestamptz;
          IF v_registration_start IS NOT NULL AND clock_timestamp()<v_registration_start THEN
            v_status:='rejected'; v_code:=104;
          END IF;
        END IF;
      END IF;
    END IF;

    IF v_code IS NULL AND EXISTS (
      SELECT 1 FROM public.exclusive_events target
      JOIN public.exclusive_events occupied ON occupied."group"=target."group"
      JOIN public.event_users eu ON eu.event=occupied.event
      WHERE target.event=p_event_id AND eu."user"=p_participant_id) THEN
      v_status:='rejected'; v_code:=102;
    END IF;
    IF v_code IS NULL AND EXISTS (
      SELECT 1 FROM public.event_users eu JOIN public.events e ON e.id=eu.event
      WHERE eu."user"=p_participant_id AND e.id<>p_event_id
        AND e.start_time<v_event.end_time AND e.end_time>v_event.start_time) THEN
      v_status:='rejected'; v_code:=107;
    END IF;
    IF v_code IS NULL AND COALESCE(v_event.max_participants,0)>0 THEN
      SELECT count(*) INTO v_count FROM public.event_users eu WHERE eu.event=p_event_id;
      IF v_event.split_for_men_women THEN
        SELECT COALESCE(u.sex='male',false) INTO v_is_male
          FROM public.user_info u WHERE u.id=p_participant_id;
        SELECT count(*) INTO v_count FROM public.event_users eu
          JOIN public.user_info u ON u.id=eu."user" WHERE eu.event=p_event_id
            AND (u.sex='male')=v_is_male;
        IF v_count>=v_event.max_participants/2 THEN
          v_status:='rejected'; v_code:=CASE WHEN v_is_male THEN 105 ELSE 106 END;
        END IF;
      ELSIF v_count>=v_event.max_participants THEN
        v_status:='rejected'; v_code:=101;
      END IF;
    END IF;
    IF v_code IS NULL THEN
      IF v_needs_occasion_join THEN
        PERFORM public.add_user_to_occasion_internal_v1(v_occasion,p_participant_id);
        IF NOT EXISTS (SELECT 1 FROM public.occasion_users ou
          WHERE ou.occasion=v_occasion AND ou."user"=p_participant_id) THEN
          RAISE EXCEPTION 'occasion membership handler did not create membership';
        END IF;
      END IF;
      INSERT INTO public.event_users(event,"user") VALUES(p_event_id,p_participant_id);
      v_changed:=true; v_code:=200;
    END IF;
  END IF;

  IF NOT v_changed THEN
    v_response:=jsonb_build_object('status',v_status,'code',v_code,
      'data',jsonb_build_object('eventId',p_event_id,'participantId',p_participant_id,
        'isSignedIn',EXISTS(SELECT 1 FROM public.event_users eu
          WHERE eu.event=p_event_id AND eu."user"=p_participant_id),
        'eventsRegistrationStart',v_registration_start),
      'mutation',jsonb_build_object('commandId',p_command_id,'receiptId',p_command_id,
        'commitId',NULL,'replayed',false,'occurredAt',clock_timestamp()),
      'sync',jsonb_build_object('replacements','[]'::jsonb));
    RETURN public.finish_client_mutation_v1(p_command_id,v_response,NULL);
  END IF;

  v_items:=jsonb_build_array(jsonb_build_object(
      'entityType','event_attendance','entityId',p_event_id||':'||p_participant_id::text,
      'operation','update','safeLabel','Event attendance',
      'changedFields',jsonb_build_array('is_signed_in')));
  v_private_impacts:=jsonb_build_array(jsonb_build_object(
    'component','private_program','userId',p_participant_id));
  IF v_companion_owner IS NOT NULL THEN
    v_private_impacts:=v_private_impacts||jsonb_build_array(jsonb_build_object(
      'component','private_profile','userId',v_companion_owner));
  END IF;
  IF v_needs_occasion_join THEN
    v_items:=v_items||jsonb_build_array(jsonb_build_object(
      'entityType','occasion_membership','entityId',p_participant_id,
      'operation','insert','safeLabel','Occasion membership',
      'changedFields',jsonb_build_array('occasion')));
    v_private_impacts:=v_private_impacts||jsonb_build_array(jsonb_build_object(
      'component','private_profile','userId',p_participant_id));
  END IF;
  v_commit:=public.record_client_sync_commit_v1(v_occasion,
    'event.attendance.'||p_action,'attendance',v_items,
    CASE WHEN v_is_publishable THEN ARRAY['live_public'] ELSE '{}'::text[] END,
    v_private_impacts,CASE WHEN v_is_publishable THEN jsonb_build_array(
      jsonb_build_object('component','live_public','entityId',p_event_id))
      ELSE '[]'::jsonb END,'user',NULL);
  SELECT source_revision INTO v_private_revision FROM public.client_sync_private_scopes
    WHERE component='private_program' AND occasion=v_occasion AND user_id=p_participant_id;
  IF v_needs_occasion_join OR v_companion_owner IS NOT NULL THEN
    SELECT source_revision INTO STRICT v_profile_revision
    FROM public.client_sync_private_scopes
    WHERE component='private_profile' AND occasion=v_occasion
      AND user_id=COALESCE(v_companion_owner,p_participant_id);
    v_profile_payload:=public.get_private_profile_payload_v1(
      v_occasion,COALESCE(v_companion_owner,p_participant_id));
  END IF;
  SELECT jsonb_build_object(
    'signedIn',COALESCE(jsonb_agg(eu.event ORDER BY eu.event),'[]'::jsonb),
    'saved',(SELECT COALESCE(jsonb_agg(es.event ORDER BY es.event),'[]'::jsonb)
      FROM public.event_users_saved es JOIN public.events e ON e.id=es.event
      WHERE es."user"=p_participant_id AND e.occasion=v_occasion))
    INTO v_private_payload FROM public.event_users eu JOIN public.events e ON e.id=eu.event
    WHERE eu."user"=p_participant_id AND e.occasion=v_occasion;
  IF v_is_publishable THEN
    SELECT source_revision INTO v_live_revision FROM public.client_sync_scopes
      WHERE component='live_public' AND scope_type='occasion' AND scope_id=v_occasion;
    INSERT INTO public.event_public_state
      (occasion,event,participant_count,saved_count,remaining_capacity,revision,projected_at)
    SELECT v_occasion,v_event.id,count(DISTINCT eu."user"),count(DISTINCT es."user"),
      CASE WHEN v_event.max_participants IS NULL THEN NULL
        ELSE GREATEST(v_event.max_participants-count(DISTINCT eu."user"),0) END,
      v_live_revision,clock_timestamp()
    FROM (SELECT 1) seed LEFT JOIN public.event_users eu ON eu.event=v_event.id
    LEFT JOIN public.event_users_saved es ON es.event=v_event.id
    ON CONFLICT (occasion,event) DO UPDATE SET
      participant_count=EXCLUDED.participant_count,saved_count=EXCLUDED.saved_count,
      remaining_capacity=EXCLUDED.remaining_capacity,revision=EXCLUDED.revision,
      projected_at=EXCLUDED.projected_at;
    SELECT jsonb_build_object(
      'events',COALESCE(jsonb_agg(jsonb_build_object('eventId',s.event,
        'participantCount',s.participant_count,'savedCount',s.saved_count,
        'remainingCapacity',s.remaining_capacity) ORDER BY s.event),'[]'::jsonb),
      'cleaning',(SELECT COALESCE(jsonb_agg(jsonb_build_object('placeId',c.place,
        'status',c.status,'openReportCount',c.open_report_count) ORDER BY c.place),'[]'::jsonb)
        FROM public.cleaning_public_state c WHERE c.occasion=v_occasion))
      INTO v_live_payload FROM public.event_public_state s JOIN public.events e ON e.id=s.event
      WHERE s.occasion=v_occasion AND NOT e.is_hidden;
  END IF;
  v_response:=jsonb_build_object('status','applied','code',200,
    'data',jsonb_build_object('eventId',p_event_id,'participantId',p_participant_id,
      'isSignedIn',p_action='sign_in'),
    'mutation',jsonb_build_object('commandId',p_command_id,'receiptId',p_command_id,
      'commitId',v_commit->>'commitId','replayed',false,'occurredAt',v_commit->>'occurredAt'),
    'sync',jsonb_build_object('replacements',
      CASE WHEN v_is_publishable THEN jsonb_build_array(jsonb_build_object(
        'component','live_public','revision',v_live_revision,
        'payload',v_live_payload)) ELSE '[]'::jsonb END ||
      CASE WHEN v_actor=p_participant_id THEN jsonb_build_array(jsonb_build_object(
        'component','private_program','revision',v_private_revision,
        'payload',v_private_payload)) ELSE '[]'::jsonb END ||
        CASE WHEN v_needs_occasion_join OR v_companion_owner=v_actor
          THEN jsonb_build_array(jsonb_build_object(
          'component','private_profile','revision',v_profile_revision,
          'payload',v_profile_payload)) ELSE '[]'::jsonb END));
  RETURN public.finish_client_mutation_v1(p_command_id,v_response,
    (v_commit->>'commitId')::uuid);
END; $$;


ALTER FUNCTION "public"."set_event_attendance_client_sync_v1"("p_event_id" bigint, "p_participant_id" "uuid", "p_action" "text", "p_command_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_event_speakers"("p_event" bigint, "p_speakers" bigint[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
    v_occasion BIGINT;
    v_speakers BIGINT[] := COALESCE(p_speakers, ARRAY[]::BIGINT[]);
BEGIN
    SELECT occasion INTO v_occasion
    FROM public.events
    WHERE id = p_event;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('code', 404);
    END IF;

    IF NOT public.get_is_editor_on_occasion(v_occasion) THEN
        RETURN jsonb_build_object('code', 403);
    END IF;

    -- Every supplied speaker must belong to the event's occasion.
    IF EXISTS (
        SELECT 1
        FROM unnest(v_speakers) AS sid
        LEFT JOIN public.speakers s ON s.id = sid AND s.occasion = v_occasion
        WHERE s.id IS NULL
    ) THEN
        RETURN jsonb_build_object('code', 400);
    END IF;

    -- Replace the set: drop links no longer present, add the missing ones.
    DELETE FROM public.event_speakers
    WHERE event = p_event
      AND speaker <> ALL (v_speakers);

    INSERT INTO public.event_speakers (event, speaker)
    SELECT p_event, sid
    FROM unnest(v_speakers) AS sid
    ON CONFLICT (event, speaker) DO NOTHING;

    RETURN jsonb_build_object('code', 200);
END;
$$;


ALTER FUNCTION "public"."set_event_speakers"("p_event" bigint, "p_speakers" bigint[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_last_fetch_time"("p_bank_account_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  UPDATE eshop.bank_accounts
  SET last_fetch_time = now() AT TIME ZONE 'UTC'
  WHERE id = p_bank_account_id;
END;
$$;


ALTER FUNCTION "public"."set_last_fetch_time"("p_bank_account_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_payment_deadline"("p_payment_info_id" bigint, "p_new_deadline" timestamp with time zone) RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  order_details RECORD;
  v_interval INTERVAL;
  v_form_settings JSONB;
  reminder_interval_seconds BIGINT;
BEGIN
  -- This function now handles the entire process of rescheduling a payment deadline.

  -- 1. Find the order and related details (occasion, organization, unit, features)
  --    associated with the given payment_info ID.
  SELECT o.id, o.occasion, occ.organization, occ.unit, occ.features
  INTO order_details
  FROM eshop.orders o
  JOIN public.occasions occ ON o.occasion = occ.id
  WHERE o.payment_info = p_payment_info_id;

  -- If no corresponding order is found, exit the function.
  IF NOT FOUND THEN
    RETURN;
  END IF;

  -- 2. Delete any pre-existing 'TICKET_ORDER_REMINDER' for this specific order
  --    to prevent sending multiple or outdated reminders.
  DELETE FROM public.queue_emails
  WHERE code = 'TICKET_ORDER_REMINDER' AND (data->>'order_id')::bigint = order_details.id;

  -- 3. Update the payment_info record with the new deadline and reset the
  --    'current_version_reminded' flag to false. This makes the order
  --    eligible for a new reminder.
  UPDATE eshop.payment_info
  SET
    deadline = p_new_deadline,
    data = COALESCE(data, '{}'::jsonb) || '{"current_version_reminded": false}'::jsonb
  WHERE
    id = p_payment_info_id;

  -- 4. Check occasion features to see if reminders are enabled and get the timing.
  IF order_details.features IS NOT NULL THEN
    -- Find the 'form' object within the features JSON array.
    SELECT elem INTO v_form_settings
    FROM jsonb_array_elements(order_details.features) AS elem
    WHERE elem->>'code' = 'form';

    -- If the form feature is configured, reminder is enabled, and has an interval, extract it.
    IF v_form_settings IS NOT NULL AND
       (v_form_settings->>'reminder_is_enabled')::boolean IS TRUE AND
       v_form_settings->>'reminder_interval_seconds' IS NOT NULL
    THEN
        reminder_interval_seconds := (v_form_settings->>'reminder_interval_seconds')::bigint;
    END IF;
  END IF;

  -- 5. If the new deadline is in the future AND reminders are enabled (reminder_interval_seconds is set),
  --    create a new reminder email in the queue with the updated target time.
  IF p_new_deadline > NOW() AND reminder_interval_seconds IS NOT NULL THEN
    v_interval := make_interval(secs => reminder_interval_seconds);

    INSERT INTO public.queue_emails (
      target_time,
      code,
      data,
      organization,
      occasion,
      unit
    )
    VALUES (
      p_new_deadline - v_interval,
      'TICKET_ORDER_REMINDER',
      jsonb_build_object('order_id', order_details.id),
      order_details.organization,
      order_details.occasion,
      order_details.unit
    );
  END IF;

END;
$$;


ALTER FUNCTION "public"."set_payment_deadline"("p_payment_info_id" bigint, "p_new_deadline" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_saved_program"("p_occasion" bigint, "p_event_ids" bigint[], "p_mode" "text") RETURNS bigint[]
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
    v_actor UUID := auth.uid();
    v_ids BIGINT[];
    v_saved BIGINT[];
BEGIN
    IF v_actor IS NULL OR p_mode NOT IN ('join', 'remove', 'replace')
       OR cardinality(COALESCE(p_event_ids, '{}')) > 5000
       OR NOT EXISTS (
           SELECT 1 FROM public.occasion_users ou
           WHERE ou.occasion = p_occasion AND ou."user" = v_actor
       ) THEN
        RAISE insufficient_privilege USING MESSAGE = 'invalid saved-program command';
    END IF;

    SELECT COALESCE(array_agg(DISTINCT input.event_id ORDER BY input.event_id), '{}')
    INTO v_ids
    FROM unnest(COALESCE(p_event_ids, '{}')) AS input(event_id);

    IF EXISTS (
        SELECT 1 FROM unnest(v_ids) AS input(event_id)
        LEFT JOIN public.events e
          ON e.id = input.event_id AND e.occasion = p_occasion
        WHERE e.id IS NULL
    ) THEN
        RAISE invalid_parameter_value
            USING MESSAGE = 'saved program contains cross-scope events';
    END IF;

    PERFORM pg_advisory_xact_lock(hashtextextended(
        'saved-program:' || v_actor::text || ':' || p_occasion::text, 0));

    IF p_mode = 'replace' THEN
        DELETE FROM public.event_users_saved es USING public.events e
        WHERE es.event = e.id AND es."user" = v_actor
          AND e.occasion = p_occasion AND NOT es.event = ANY(v_ids);
    ELSIF p_mode = 'remove' THEN
        DELETE FROM public.event_users_saved es
        WHERE es."user" = v_actor AND es.event = ANY(v_ids);
    END IF;

    IF p_mode IN ('join', 'replace') THEN
        INSERT INTO public.event_users_saved(event, "user")
        SELECT input.event_id, v_actor
        FROM unnest(v_ids) AS input(event_id)
        ON CONFLICT DO NOTHING;
    END IF;

    SELECT COALESCE(array_agg(es.event ORDER BY es.event), '{}') INTO v_saved
    FROM public.event_users_saved es JOIN public.events e ON e.id = es.event
    WHERE es."user" = v_actor AND e.occasion = p_occasion;
    RETURN v_saved;
END;
$$;


ALTER FUNCTION "public"."set_saved_program"("p_occasion" bigint, "p_event_ids" bigint[], "p_mode" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_saved_program_client_sync_v1"("p_occasion" bigint, "p_event_ids" bigint[], "p_mode" "text", "p_command_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor UUID := auth.uid();
  v_response JSONB;
  v_revision BIGINT;
  v_payload JSONB;
BEGIN
  v_response := public.set_saved_program_client_sync_v1_transactional(
    p_occasion, p_event_ids, p_mode, p_command_id
  );

  IF jsonb_array_length(v_response #> '{sync,replacements}') = 0 THEN
    SELECT source_revision INTO v_revision
    FROM public.client_sync_private_scopes
    WHERE component = 'private_program'
      AND occasion = p_occasion
      AND user_id = v_actor;

    IF v_revision IS NOT NULL THEN
      SELECT jsonb_build_object(
        'signedIn', (
          SELECT COALESCE(jsonb_agg(eu.event ORDER BY eu.event), '[]'::jsonb)
          FROM public.event_users eu
          JOIN public.events e ON e.id = eu.event
          WHERE eu."user" = v_actor AND e.occasion = p_occasion
        ),
        'saved', (
          SELECT COALESCE(jsonb_agg(es.event ORDER BY es.event), '[]'::jsonb)
          FROM public.event_users_saved es
          JOIN public.events e ON e.id = es.event
          WHERE es."user" = v_actor AND e.occasion = p_occasion
        )
      ) INTO v_payload;

      v_response := jsonb_set(
        v_response,
        '{sync,replacements}',
        jsonb_build_array(jsonb_build_object(
          'component', 'private_program',
          'revision', v_revision,
          'payload', v_payload
        ))
      );
    END IF;
  END IF;

  RETURN v_response;
END;
$$;


ALTER FUNCTION "public"."set_saved_program_client_sync_v1"("p_occasion" bigint, "p_event_ids" bigint[], "p_mode" "text", "p_command_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_saved_program_client_sync_v1_transactional"("p_occasion" bigint, "p_event_ids" bigint[], "p_mode" "text", "p_command_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_actor uuid:=auth.uid(); v_ids bigint[]; v_before bigint[]; v_after bigint[];
  v_changed_ids bigint[]; v_begin jsonb; v_hash text; v_commit jsonb;
  v_private_revision bigint; v_live_revision bigint; v_private_payload jsonb;
  v_live_payload jsonb; v_response jsonb;
  v_is_publishable boolean;
BEGIN
  IF v_actor IS NULL OR p_mode NOT IN ('join','remove','replace')
    OR cardinality(COALESCE(p_event_ids,'{}'))>5000
    OR NOT EXISTS (SELECT 1 FROM public.occasion_users ou
      WHERE ou.occasion=p_occasion AND ou."user"=v_actor) THEN
    RAISE insufficient_privilege USING MESSAGE='invalid saved-program command';
  END IF;
  SELECT NOT o.is_hidden INTO STRICT v_is_publishable
  FROM public.occasions o WHERE o.id=p_occasion;
  SELECT COALESCE(array_agg(DISTINCT input.event_id ORDER BY input.event_id),'{}')
    INTO v_ids
    FROM unnest(COALESCE(p_event_ids,'{}')) AS input(event_id);
  IF EXISTS (
    SELECT 1
    FROM unnest(v_ids) AS input(event_id)
    LEFT JOIN public.events e
      ON e.id=input.event_id AND e.occasion=p_occasion
    WHERE e.id IS NULL
  ) THEN
    RAISE invalid_parameter_value USING MESSAGE='saved program contains cross-scope events';
  END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,
    'eventIds',to_jsonb(v_ids),'mode',p_mode)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'program.saved.'||p_mode,
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'saved-program:'||v_actor::text||':'||p_occasion::text,0));
  SELECT COALESCE(array_agg(es.event ORDER BY es.event),'{}') INTO v_before
    FROM public.event_users_saved es JOIN public.events e ON e.id=es.event
    WHERE es."user"=v_actor AND e.occasion=p_occasion;
  IF p_mode='replace' THEN
    DELETE FROM public.event_users_saved es USING public.events e
      WHERE es.event=e.id AND es."user"=v_actor AND e.occasion=p_occasion
        AND NOT es.event=ANY(v_ids);
    INSERT INTO public.event_users_saved(event,"user")
      SELECT input.event_id,v_actor
      FROM unnest(v_ids) AS input(event_id)
      ON CONFLICT DO NOTHING;
  ELSIF p_mode='join' THEN
    INSERT INTO public.event_users_saved(event,"user")
      SELECT input.event_id,v_actor
      FROM unnest(v_ids) AS input(event_id)
      ON CONFLICT DO NOTHING;
  ELSE
    DELETE FROM public.event_users_saved es
      WHERE es."user"=v_actor AND es.event=ANY(v_ids);
  END IF;
  SELECT COALESCE(array_agg(es.event ORDER BY es.event),'{}') INTO v_after
    FROM public.event_users_saved es JOIN public.events e ON e.id=es.event
    WHERE es."user"=v_actor AND e.occasion=p_occasion;
  IF v_before=v_after THEN
    v_response:=jsonb_build_object('status','unchanged','code',200,
      'data',jsonb_build_object('saved',to_jsonb(v_after)),
      'mutation',jsonb_build_object('commandId',p_command_id,'receiptId',p_command_id,
        'commitId',NULL,'replayed',false,'occurredAt',clock_timestamp()),
      'sync',jsonb_build_object('replacements','[]'::jsonb));
    RETURN public.finish_client_mutation_v1(p_command_id,v_response,NULL);
  END IF;
  SELECT array_agg(DISTINCT changed.event_id ORDER BY changed.event_id)
    INTO v_changed_ids
    FROM (
      (SELECT unnest(v_before) event_id EXCEPT SELECT unnest(v_after))
      UNION
      (SELECT unnest(v_after) event_id EXCEPT SELECT unnest(v_before))
    ) changed;
  v_commit:=public.record_client_sync_commit_v1(p_occasion,'program.saved.'||p_mode,
    'saved_program',jsonb_build_array(jsonb_build_object('entityType','saved_program',
      'entityId',v_actor,'operation','update','safeLabel','Saved program',
      'changedFields',jsonb_build_array('event_ids'))),
    CASE WHEN v_is_publishable THEN ARRAY['live_public'] ELSE '{}'::text[] END,
    jsonb_build_array(jsonb_build_object('component','private_program','userId',v_actor)),
    CASE WHEN v_is_publishable THEN (
      SELECT jsonb_agg(jsonb_build_object(
        'component','live_public','entityId',changed.event_id
      ))
      FROM unnest(v_changed_ids) AS changed(event_id)
    ) ELSE '[]'::jsonb END,'user',NULL);
  SELECT source_revision INTO v_private_revision FROM public.client_sync_private_scopes
    WHERE component='private_program' AND occasion=p_occasion AND user_id=v_actor;
  SELECT jsonb_build_object(
    'signedIn',(SELECT COALESCE(jsonb_agg(eu.event ORDER BY eu.event),'[]'::jsonb)
      FROM public.event_users eu JOIN public.events e ON e.id=eu.event
      WHERE eu."user"=v_actor AND e.occasion=p_occasion),
    'saved',to_jsonb(v_after)) INTO v_private_payload;
  IF v_is_publishable THEN
    SELECT source_revision INTO v_live_revision FROM public.client_sync_scopes
      WHERE component='live_public' AND scope_type='occasion' AND scope_id=p_occasion;
    INSERT INTO public.event_public_state
      (occasion,event,participant_count,saved_count,remaining_capacity,revision,projected_at)
    SELECT e.occasion,e.id,count(DISTINCT eu."user"),count(DISTINCT es."user"),
      CASE WHEN e.max_participants IS NULL THEN NULL
        ELSE GREATEST(e.max_participants-count(DISTINCT eu."user"),0) END,
      v_live_revision,clock_timestamp()
    FROM public.events e LEFT JOIN public.event_users eu ON eu.event=e.id
    LEFT JOIN public.event_users_saved es ON es.event=e.id
    WHERE e.occasion=p_occasion AND e.id=ANY(v_changed_ids)
    GROUP BY e.occasion,e.id,e.max_participants
    ON CONFLICT (occasion,event) DO UPDATE SET participant_count=EXCLUDED.participant_count,
      saved_count=EXCLUDED.saved_count,remaining_capacity=EXCLUDED.remaining_capacity,
      revision=EXCLUDED.revision,projected_at=EXCLUDED.projected_at;
    SELECT jsonb_build_object(
      'events',COALESCE(jsonb_agg(jsonb_build_object('eventId',s.event,
        'participantCount',s.participant_count,'savedCount',s.saved_count,
        'remainingCapacity',s.remaining_capacity) ORDER BY s.event),'[]'::jsonb),
      'cleaning',(SELECT COALESCE(jsonb_agg(jsonb_build_object('placeId',c.place,
        'status',c.status,'openReportCount',c.open_report_count) ORDER BY c.place),'[]'::jsonb)
        FROM public.cleaning_public_state c WHERE c.occasion=p_occasion))
      INTO v_live_payload FROM public.event_public_state s JOIN public.events e ON e.id=s.event
      WHERE s.occasion=p_occasion AND NOT e.is_hidden;
  END IF;
  v_response:=jsonb_build_object('status','applied','code',200,
    'data',jsonb_build_object('saved',to_jsonb(v_after)),
    'mutation',jsonb_build_object('commandId',p_command_id,'receiptId',p_command_id,
      'commitId',v_commit->>'commitId','replayed',false,'occurredAt',v_commit->>'occurredAt'),
    'sync',jsonb_build_object('replacements',
      CASE WHEN v_is_publishable THEN jsonb_build_array(jsonb_build_object(
        'component','live_public','revision',v_live_revision,
        'payload',v_live_payload)) ELSE '[]'::jsonb END ||
      jsonb_build_array(jsonb_build_object('component','private_program',
        'revision',v_private_revision,'payload',v_private_payload))));
  RETURN public.finish_client_mutation_v1(p_command_id,v_response,
    (v_commit->>'commitId')::uuid);
END; $$;


ALTER FUNCTION "public"."set_saved_program_client_sync_v1_transactional"("p_occasion" bigint, "p_event_ids" bigint[], "p_mode" "text", "p_command_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_user_password"("usr" "uuid", "oc" bigint, "password" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
  declare
  encrypted_pw text;
BEGIN
    IF (SELECT get_is_manager_on_occasion(oc)) <> TRUE AND (SELECT get_is_admin_on_occasion(oc)) <> TRUE THEN
        RETURN NULL;
    END IF;

    IF (select get_exists_on_occasion_user(usr, oc)) <> TRUE THEN
       RETURN NULL;
    END IF;

    encrypted_pw := crypt(password, gen_salt('bf'));

    UPDATE auth.users
    SET encrypted_password = encrypted_pw
    WHERE auth.users.id = usr;
    RETURN usr;
END;
$$;


ALTER FUNCTION "public"."set_user_password"("usr" "uuid", "oc" bigint, "password" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_user_password_token"("token" "uuid", "password" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
#variable_conflict use_variable
  declare
  user_id uuid;
  email text;
  encrypted_pw text;
BEGIN
    SELECT "user" INTO user_id FROM user_reset_token WHERE user_reset_token.token = token;
    IF user_id is NULL THEN
        RETURN json_build_object('code', 403);
    END IF;

    DELETE FROM user_reset_token WHERE "user" = user_id;

    encrypted_pw := crypt(password, gen_salt('bf'));

    UPDATE auth.users
    SET encrypted_password = encrypted_pw
    WHERE auth.users.id = user_id;

    SELECT email_readonly INTO email FROM user_info WHERE user_info.id = user_id;
    IF email is NULL THEN
        RETURN json_build_object('code', 404);
    END IF;

    RETURN json_build_object('code', 200, 'email', email);
END;
$$;


ALTER FUNCTION "public"."set_user_password_token"("token" "uuid", "password" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."setup_crons"("p_project_url" "text") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $_$
BEGIN
  -- Security Check
  IF auth.role() <> 'service_role' AND session_user <> 'postgres' THEN
      RAISE EXCEPTION 'Access Denied: Service role required.';
  END IF;

  -- Schedule the apply_planned_changes cron job (runs every minute)
  PERFORM cron.schedule(
    'apply_planned_changes',
    '*/1 * * * *',
    'SELECT apply_planned_changes()'
  );

  -- Schedule the synchronize_orders cron job (runs every 10 minutes)
  PERFORM cron.schedule(
      'synchronize_orders',
      '*/10 * * * *',
      format($$
        SELECT net.http_post(
          url := '%s/functions/v1/synchronize-orders'::text,
          body := jsonb_build_object('requestSecret', public.generate_request_secret(3600))
        );
      $$, p_project_url)
  );

  -- Schedule the process_email_queue cron job (runs every minute, if tasks exist)
  PERFORM cron.schedule(
      'process_email_queue',
      '*/1 * * * *',
      format(
        $$
          -- This query will only execute the http_post if the get_due_queue_emails() function
          -- returns a JSON array with one or more items.
          -- This is a more explicit check than 'IS NOT NULL' and directly verifies
          -- that there are emails to process.
          SELECT net.http_post(
            url := '%s/functions/v1/send-email',
            body := jsonb_build_object('processQueue', true, 'requestSecret', public.generate_request_secret(3600))
          )
          WHERE jsonb_array_length(public.get_due_queue_emails()) > 0;
        $$,
        p_project_url
      )
    );
END;
$_$;


ALTER FUNCTION "public"."setup_crons"("p_project_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."setup_external_source"("p_source_name" "text", "p_supabase_url" "text", "p_anon_key" "text", "p_cron_schedule" "text" DEFAULT '*/5 * * * *'::"text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
    v_job_name TEXT := 'sync_job_' || p_source_name;
BEGIN
    IF auth.role() <> 'service_role' AND session_user <> 'postgres' THEN
        RAISE EXCEPTION 'Access Denied: Service role required.';
    END IF;

    INSERT INTO public.external_sync_sources (source_name, supabase_url, anon_key, cron_schedule)
    VALUES (p_source_name, p_supabase_url, p_anon_key, p_cron_schedule)
    ON CONFLICT (source_name) DO UPDATE SET
        supabase_url = EXCLUDED.supabase_url,
        anon_key = EXCLUDED.anon_key,
        cron_schedule = EXCLUDED.cron_schedule;

    BEGIN
        PERFORM cron.unschedule(v_job_name);
    EXCEPTION WHEN OTHERS THEN
        NULL;
    END;

    PERFORM cron.schedule(
        v_job_name,
        p_cron_schedule,
        format('SELECT public.sync_source_via_http(%L)', p_source_name)
    );

    RETURN format('Source "%s" configured with %s schedule.', p_source_name, p_cron_schedule);
END;
$$;


ALTER FUNCTION "public"."setup_external_source"("p_source_name" "text", "p_supabase_url" "text", "p_anon_key" "text", "p_cron_schedule" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."setup_triggers"("p_project_url" "text") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $_$
BEGIN
  -- Security Check
  IF auth.role() <> 'service_role' AND session_user <> 'postgres' THEN
      RAISE EXCEPTION 'Access Denied: Service role required.';
  END IF;

  -- events
  EXECUTE 'DROP TRIGGER IF EXISTS handle_updated_at ON events';
  EXECUTE '
    CREATE TRIGGER handle_updated_at
    BEFORE UPDATE ON events
    FOR EACH ROW
    EXECUTE FUNCTION moddatetime(''updated_at'')
  ';

  -- icons
  EXECUTE 'DROP TRIGGER IF EXISTS handle_updated_at ON icons';
  EXECUTE '
    CREATE TRIGGER handle_updated_at
    BEFORE UPDATE ON icons
    FOR EACH ROW
    EXECUTE FUNCTION moddatetime(''updated_at'')
  ';

  -- information
  EXECUTE 'DROP TRIGGER IF EXISTS handle_updated_at ON information';
  EXECUTE '
    CREATE TRIGGER handle_updated_at
    BEFORE UPDATE ON information
    FOR EACH ROW
    EXECUTE FUNCTION moddatetime(''updated_at'')
  ';

  -- news
  EXECUTE 'DROP TRIGGER IF EXISTS handle_updated_at ON news';
  EXECUTE '
    CREATE TRIGGER handle_updated_at
    BEFORE UPDATE ON news
    FOR EACH ROW
    EXECUTE FUNCTION moddatetime(''updated_at'')
  ';

  -- occasions
  EXECUTE 'DROP TRIGGER IF EXISTS handle_updated_at ON occasions';
  EXECUTE '
    CREATE TRIGGER handle_updated_at
    BEFORE UPDATE ON occasions
    FOR EACH ROW
    EXECUTE FUNCTION moddatetime(''updated_at'')
  ';

  -- places
  EXECUTE 'DROP TRIGGER IF EXISTS handle_updated_at ON places';
  EXECUTE '
    CREATE TRIGGER handle_updated_at
    BEFORE UPDATE ON places
    FOR EACH ROW
    EXECUTE FUNCTION moddatetime(''updated_at'')
  ';

  -- user_info
  EXECUTE 'DROP TRIGGER IF EXISTS handle_updated_at ON user_info';
  EXECUTE '
    CREATE TRIGGER handle_updated_at
    BEFORE UPDATE ON user_info
    FOR EACH ROW
    EXECUTE FUNCTION moddatetime(''updated_at'')
  ';

  -- log_notifications HTTP trigger
  EXECUTE 'DROP TRIGGER IF EXISTS push_log_notifications ON log_notifications';
  EXECUTE format($trg$
    CREATE TRIGGER push_log_notifications
    AFTER INSERT ON log_notifications
    FOR EACH ROW
    EXECUTE FUNCTION supabase_functions.http_request(
      '%s/functions/v1/notify',
      'POST',
      '{"Content-type": "application/json"}',
      '{}',
      '1000'
    )
  $trg$, p_project_url);

END;
$_$;


ALTER FUNCTION "public"."setup_triggers"("p_project_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."shift_occasion_schedule_backward"("p_occasion_id" bigint, "p_hours_to_subtract" integer) RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    v_shift_interval INTERVAL;
BEGIN
    -- Ensure the number of hours is positive
    IF p_hours_to_subtract <= 0 THEN
        RAISE EXCEPTION 'Number of hours to subtract must be positive.';
    END IF;

    -- Create an interval from the given hours
    v_shift_interval := p_hours_to_subtract * INTERVAL '1 hour';

    -- 1. Shift the main occasion start and end times
    UPDATE public.occasions
    SET
        start_time = start_time - v_shift_interval,
        end_time = end_time - v_shift_interval,
        updated_at = now()
    WHERE id = p_occasion_id;

    -- 2. Shift all events associated with the occasion
    UPDATE public.events
    SET
        start_time = start_time - v_shift_interval,
        end_time = end_time - v_shift_interval,
        updated_at = now()
    WHERE occasion = p_occasion_id;

    -- 3. Shift all activity assignments for the occasion
    UPDATE public.activity_assignments
    SET
        start_time = start_time - v_shift_interval,
        end_time = end_time - v_shift_interval
    WHERE activity_id IN (SELECT id FROM public.activities WHERE occasion = p_occasion_id);


END;
$$;


ALTER FUNCTION "public"."shift_occasion_schedule_backward"("p_occasion_id" bigint, "p_hours_to_subtract" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sign_user_out_of_event"("ev" bigint, "usr" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    event_end_time TIMESTAMP;
BEGIN
    -- Existing checks for occasion user and editor
    IF (SELECT get_exists_on_occasion_user(usr, (SELECT occasion FROM events WHERE id = ev))) <> TRUE THEN
        RETURN json_build_object('code', 403);
    END IF;

    IF auth.uid() <> usr THEN
        IF NOT EXISTS (
            SELECT 1 FROM public.user_companions uc JOIN public.events ce ON ce.id=ev AND ce.occasion=uc.occasion WHERE uc."user"=auth.uid() AND uc.companion=usr AND COALESCE((public.get_companion_feature_policy_v1(uc.occasion)->>'is_enabled')::boolean,false) ) THEN
            IF (SELECT get_is_editor_on_occasion((SELECT occasion FROM events WHERE id = ev))) <> TRUE THEN
                    RETURN json_build_object('code', 403);
            END IF;
        END IF;
    END IF;

    -- Check if the user is signed in to the event
    IF (SELECT COUNT(*) FROM event_users WHERE event = ev AND "user" = usr) = 0 THEN
        RETURN json_build_object('code', 404, 'message', 'User is not signed into this event');
    END IF;

    -- Retrieve event end time
    SELECT end_time INTO event_end_time
    FROM events
    WHERE id = ev;

    -- Check if the event has already ended
    IF CURRENT_TIMESTAMP AT TIME ZONE 'UTC' > event_end_time THEN
        RETURN json_build_object('code', 201, 'message', 'Cannot sign out after the event has ended');
    END IF;

    -- Remove the user from the event
    DELETE FROM event_users WHERE event = ev AND "user" = usr;
    RETURN json_build_object('code', 200, 'message', 'User signed out successfully');
END;
$$;


ALTER FUNCTION "public"."sign_user_out_of_event"("ev" bigint, "usr" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sign_user_to_event"("ev" bigint, "usr" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
declare
  i_max_participants integer;
  current_participants integer;
  event_group_count integer;
  event_group integer;
  exclusive_event_count integer;
  already_in_count integer;
  current_men_participants integer;
  current_women_participants integer;
  b_split_for_men_women boolean;
  is_current_user_male boolean;

  registration_start timestamp;
  event_start_time timestamp;
  event_end_time timestamp;
  workshops_feature jsonb;
  e RECORD;

  v_occasion bigint;
  v_is_counseling boolean;
  counseling_feature jsonb;
  v_limit integer;
  v_active integer;

begin

  -- Check if the user already exists on the occasion
  IF (SELECT get_exists_on_occasion_user(usr, (SELECT occasion FROM events WHERE id = ev))) <> TRUE THEN

      -- Check if the occasion is open
      IF (SELECT is_open FROM occasions WHERE id = (SELECT occasion FROM events WHERE id = ev)) = TRUE THEN

          -- Add the user to the occasion
          PERFORM add_user_to_occasion((SELECT occasion FROM events WHERE id = ev), usr);

          -- Recheck if the user now exists on the occasion
          IF (SELECT get_exists_on_occasion_user(usr, (SELECT occasion FROM events WHERE id = ev))) <> TRUE THEN
              -- If user still doesn't exist, return a 403 response
              RETURN json_build_object('code', 403, 'message', 'Failed to add user to occasion');
          END IF;
      ELSE
          -- If the occasion is not open, return a 403 response
          RETURN json_build_object('code', 403, 'message', 'Occasion is not open');
      END IF;
  END IF;

  IF auth.uid() <> usr THEN
      IF NOT EXISTS (
        SELECT 1 FROM public.user_companions uc JOIN public.events ce ON ce.id=ev AND ce.occasion=uc.occasion WHERE uc."user"=auth.uid() AND uc.companion=usr AND COALESCE((public.get_companion_feature_policy_v1(uc.occasion)->>'is_enabled')::boolean,false)) THEN
          IF (SELECT get_is_editor_on_occasion((SELECT occasion FROM events WHERE id = ev))) <> TRUE THEN
            RETURN json_build_object('code', 403);
          END IF;
      END IF;
  END IF;

  -- Resolve the occasion and detect whether this event is a counseling slot.
  SELECT occasion, (data->>'is_counseling_slot')::boolean IS TRUE
    INTO v_occasion, v_is_counseling
  FROM events
  WHERE id = ev;

  IF v_is_counseling THEN
    -- Counseling slots use their own registration window from the "counseling"
    -- feature; the workshops gate (104/108) does not apply (decision R1).
    SELECT elem
      INTO counseling_feature
    FROM occasions,
         jsonb_array_elements(features) elem
    WHERE id = v_occasion
      AND elem->>'code' = 'counseling'
    LIMIT 1;

    -- (a) Feature must be present and enabled, else registration is closed.
    IF counseling_feature IS NULL
       OR (counseling_feature->>'is_enabled')::boolean IS NOT TRUE THEN
      RETURN json_build_object('code', 108);
    END IF;

    registration_start := (counseling_feature->>'registration_start_time')::timestamp;
    IF registration_start IS NOT NULL THEN
      IF CURRENT_TIMESTAMP AT TIME ZONE 'UTC' < registration_start THEN
        RETURN json_build_object('code', 104, 'events_registration_start', registration_start AT TIME ZONE 'UTC');
      END IF;
    END IF;

    -- (b) Limit of the user's future counseling bookings (0 = unlimited).
    v_limit := COALESCE((counseling_feature->>'max_active_bookings')::int, 1);
    IF v_limit > 0 THEN
      SELECT count(*)
        INTO v_active
      FROM event_users eu
      JOIN events e2 ON e2.id = eu.event
      WHERE eu."user" = usr
        AND e2.occasion = v_occasion
        AND (e2.data->>'is_counseling_slot')::boolean IS TRUE
        AND e2.end_time > CURRENT_TIMESTAMP AT TIME ZONE 'UTC';
      IF v_active >= v_limit THEN
        RETURN json_build_object('code', 109);
      END IF;
    END IF;
  ELSE
    -- Check registration start time from occasions.features for the "workshops" feature
    SELECT elem
    INTO workshops_feature
    FROM occasions,
         jsonb_array_elements(features) elem
    WHERE id = (SELECT occasion FROM events WHERE id = ev)
      AND elem->>'code' = 'workshops'
    LIMIT 1;

    IF workshops_feature IS NOT NULL THEN
      -- If the workshops feature is not enabled, do not allow sign in
      IF (workshops_feature->>'is_enabled')::boolean IS NOT TRUE THEN
        RETURN json_build_object('code', 108, 'message', 'Registration for workshops is not enabled');
      END IF;
      -- If start_time is provided, enforce registration start time
      registration_start := (workshops_feature->>'start_time')::timestamp;
      IF registration_start IS NOT NULL THEN
        IF CURRENT_TIMESTAMP AT TIME ZONE 'UTC' < registration_start THEN
          RETURN json_build_object('code', 104, 'events_registration_start', registration_start AT TIME ZONE 'UTC');
        END IF;
      END IF;
    END IF;
    -- If the workshops feature is not present or its start_time is null, sign in is enabled
  END IF;

  SELECT start_time, end_time INTO event_start_time, event_end_time
  FROM events
  WHERE id = ev;

  IF CURRENT_TIMESTAMP AT TIME ZONE 'UTC' > event_end_time THEN
    RETURN json_build_object('code', 100);
  END IF;

  SELECT count(*) FROM event_users eu WHERE eu.event = ev AND eu."user" = usr INTO already_in_count;
  IF already_in_count > 0 THEN
    RETURN json_build_object('code', 103);
  END IF;

  SELECT count(*) FROM exclusive_events WHERE event = ev INTO event_group_count;
  IF event_group_count > 0 THEN
    SELECT "group" FROM exclusive_events WHERE event = ev INTO event_group;
    SELECT count(*) FROM exclusive_events ee JOIN event_users eu ON ee.event = eu.event
      WHERE ee."group" = event_group AND eu."user" = usr INTO exclusive_event_count;
    IF exclusive_event_count > 0 THEN
      RETURN json_build_object('code', 102);
    END IF;
  END IF;

  -- Check if the event already has the maximum number of participants
  SELECT max_participants FROM events WHERE id = ev INTO i_max_participants;
  SELECT split_for_men_women FROM events WHERE id = ev INTO b_split_for_men_women;

  IF b_split_for_men_women THEN
    SELECT exists (SELECT sex FROM user_info WHERE id = usr AND sex = 'male') INTO is_current_user_male;
    SELECT count(*) FROM event_users eu JOIN user_info ei ON eu."user" = ei.id
      WHERE event = ev AND ei.sex = 'male' INTO current_men_participants;
    SELECT count(*) FROM event_users eu JOIN user_info ei ON eu."user" = ei.id
      WHERE event = ev AND ei.sex <> 'male' INTO current_women_participants;
    IF is_current_user_male AND current_men_participants >= (i_max_participants / 2) THEN
      RETURN json_build_object('code', 105);
    ELSIF NOT is_current_user_male AND current_women_participants >= (i_max_participants / 2) THEN
      RETURN json_build_object('code', 106);
    END IF;
  END IF;

  -- Loop through user_events to check for scheduling conflicts
  FOR e IN
      SELECT events.id, events.start_time, events.end_time
      FROM events
      JOIN event_users ON events.id = event_users.event
      WHERE event_users."user" = usr
  LOOP
      IF ((e.start_time < event_end_time AND e.start_time > event_start_time) OR
          (e.end_time < event_end_time AND e.end_time > event_start_time) OR
          (e.start_time = event_start_time) OR
          (e.end_time = event_end_time)) THEN
          RETURN json_build_object('code', 107);
      END IF;
  END LOOP;

  SELECT count(*) FROM event_users WHERE event = ev INTO current_participants;
  IF current_participants >= i_max_participants THEN
    RETURN json_build_object('code', 101);
  ELSE
    INSERT INTO event_users (event, "user") VALUES (ev, usr);
    RETURN json_build_object('code', 200);
  END IF;
END;
$$;


