CREATE OR REPLACE FUNCTION "public"."storno_ticket"("ticket_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    ticket_record RECORD;
    order_id BIGINT;
    ticket_price NUMERIC(10, 2) := 0;
    updated_tickets JSONB := '[]'::JSONB;
    original_data JSONB;
    ticket_data JSONB;
    product JSONB;
    remaining_opt_id BIGINT;
BEGIN
    -- Check if the ticket exists and fetch its associated data
    SELECT t.*, o.id AS order_id, o.data AS order_data, t.occasion
    INTO ticket_record
    FROM eshop.tickets t
    JOIN eshop.order_product_ticket opt ON opt.ticket = t.id
    JOIN eshop.orders o ON o.id = opt."order"
    WHERE t.id = ticket_id;

    IF NOT FOUND THEN
        RETURN JSONB_BUILD_OBJECT('code', 1001, 'message', 'Ticket not found');
    END IF;

    IF NOT get_is_editor_order_on_occasion(ticket_record.occasion) THEN
        RETURN JSONB_BUILD_OBJECT('code', 1002, 'message', 'Permission denied');
    END IF;

    -- Update ticket state to "storno"
    UPDATE eshop.tickets
    SET state = 'storno', updated_at = NOW()
    WHERE id = ticket_id;

    -- Nullify the relevant spot's order_product_ticket
    UPDATE eshop.spots
    SET order_product_ticket = NULL, secret = NULL, secret_expiration_time = NULL, updated_at = NOW(), resource = NULL, state = NULL
    WHERE order_product_ticket IN (
        SELECT id FROM eshop.order_product_ticket WHERE ticket = ticket_id
    );

    -- Find and keep one order_product_ticket and update its product to NULL
    SELECT id INTO remaining_opt_id
    FROM eshop.order_product_ticket
    WHERE ticket = ticket_id
    LIMIT 1;

    IF remaining_opt_id IS NOT NULL THEN
        UPDATE eshop.order_product_ticket
        SET product = NULL
        WHERE id = remaining_opt_id;

        -- Delete all other order_product_ticket records for the ticket
        DELETE FROM eshop.order_product_ticket
        WHERE ticket = ticket_id AND id != remaining_opt_id;
    END IF;

    -- Remove the ticket from orders.data and calculate the price reduction
    original_data := ticket_record.order_data;
    FOR ticket_data IN SELECT JSONB_ARRAY_ELEMENTS(original_data->'tickets') LOOP
        IF (ticket_data->>'id')::BIGINT = ticket_id THEN
            -- Calculate the price of all products in the ticket
            FOR product IN SELECT JSONB_ARRAY_ELEMENTS(ticket_data->'products') LOOP
                ticket_price := ticket_price + COALESCE((product->>'price')::NUMERIC, 0);
            END LOOP;
        ELSE
            -- Keep all other tickets
            updated_tickets := updated_tickets || ticket_data;
        END IF;
    END LOOP;

    -- Update the order's data and price
    UPDATE eshop.orders
    SET
        data = original_data || JSONB_BUILD_OBJECT('tickets', updated_tickets),
        price = COALESCE(price, 0) - ticket_price,
        updated_at = NOW()
    WHERE id = ticket_record.order_id;

    -- Save the change to orders_history
    INSERT INTO eshop.orders_history (
        "order",
        data,
        state,
        price,
        created_at
    )
    VALUES (
        ticket_record.order_id,
        original_data || JSONB_BUILD_OBJECT('tickets', updated_tickets),
        'ordered',
        COALESCE((SELECT price FROM eshop.orders WHERE id = ticket_record.order_id), 0),
        NOW()
    );

    -- Return success response
    RETURN JSONB_BUILD_OBJECT(
        'code', 200,
        'message', 'Ticket successfully cancelled',
        'ticket_id', ticket_id,
        'order_id', ticket_record.order_id,
        'price_reduction', ticket_price,
        'remaining_order_product_ticket', remaining_opt_id
    );
EXCEPTION
    WHEN OTHERS THEN
        RETURN JSONB_BUILD_OBJECT('code', 500, 'message', 'An error occurred', 'details', SQLERRM);
END;
$$;


ALTER FUNCTION "public"."storno_ticket"("ticket_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."storno_ticket_221"("ticket_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    ticket_record RECORD;
    order_id BIGINT;
    ticket_price NUMERIC(10, 2) := 0;
    updated_tickets JSONB := '[]'::JSONB;
    original_data JSONB;
    ticket_data JSONB;
    product JSONB;
    remaining_active_tickets_count BIGINT;
BEGIN
    -- Check if the ticket exists and fetch its associated data
    SELECT t.*, o.id AS order_id, o.data AS order_data, t.occasion
    INTO ticket_record
    FROM eshop.tickets t
    JOIN eshop.order_product_ticket opt ON opt.ticket = t.id
    JOIN eshop.orders o ON o.id = opt."order"
    WHERE t.id = ticket_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Ticket not found (ID: %)', ticket_id;
    END IF;

    IF NOT get_is_editor_order_on_occasion(ticket_record.occasion) THEN
        RAISE EXCEPTION 'Permission denied to storno ticket on occasion %', ticket_record.occasion;
    END IF;

    -- Check if this is the last non-storno ticket on the order.
    SELECT COUNT(t.id)
    INTO remaining_active_tickets_count
    FROM eshop.tickets t
    JOIN eshop.order_product_ticket opt ON opt.ticket = t.id
    WHERE opt."order" = ticket_record.order_id
      AND t.id != ticket_id
      AND (t.state IS NULL OR t.state != 'storno');

    -- If it is the last active ticket, storno the whole order instead and exit.
    IF remaining_active_tickets_count = 0 THEN
        PERFORM public.update_order_and_tickets_to_storno_ws_221(ticket_record.order_id);
        RETURN; -- Exit the function
    END IF;

    -- --- Proceed with single ticket storno ---

    -- *** REFACTORED PART ***
    -- Call the helper to storno the single ticket and its relations
    PERFORM internal_storno_tickets_221(ARRAY[ticket_id]);
    -- All the logic for tickets, spots, and occasion_users is now done.

    -- Remove the ticket from orders.data and calculate the price reduction
    original_data := ticket_record.order_data;
    FOR ticket_data IN SELECT JSONB_ARRAY_ELEMENTS(original_data->'tickets') LOOP
        IF (ticket_data->>'id')::BIGINT = ticket_id THEN
            -- Calculate the price of all products in the ticket
            FOR product IN SELECT JSONB_ARRAY_ELEMENTS(ticket_data->'products') LOOP
                ticket_price := ticket_price + COALESCE((product->>'price')::NUMERIC, 0);
            END LOOP;
        ELSE
            -- Keep all other tickets
            updated_tickets := updated_tickets || ticket_data;
        END IF;
    END LOOP;

    -- Update the order's data and price
    UPDATE eshop.orders
    SET
        data = original_data || JSONB_BUILD_OBJECT('tickets', updated_tickets),
        price = COALESCE(price, 0) - ticket_price,
        updated_at = NOW()
    WHERE id = ticket_record.order_id;

    -- Save the change to orders_history
    INSERT INTO eshop.orders_history (
        "order",
        data,
        state,
        price,
        created_at
    )
    VALUES (
        ticket_record.order_id,
        original_data || JSONB_BUILD_OBJECT('tickets', updated_tickets),
        'ordered',
        COALESCE((SELECT price FROM eshop.orders WHERE id = ticket_record.order_id), 0),
        NOW()
    );

END;
$$;


ALTER FUNCTION "public"."storno_ticket_221"("ticket_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."storno_tickets_bulk"("p_ticket_ids" bigint[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  PERFORM public.storno_tickets_client_sync_v1(
    p_ticket_ids,extensions.gen_random_uuid());
END; $$;


ALTER FUNCTION "public"."storno_tickets_bulk"("p_ticket_ids" bigint[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."storno_tickets_bulk_internal_v1"("p_ticket_ids" bigint[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_order_id BIGINT;
    v_occasion_id BIGINT;
    v_tickets_in_order BIGINT[];
    v_tickets_to_cancel_in_order BIGINT[];
    v_remaining_count INT;
    v_ticket_id_to_remove BIGINT;
    v_original_data JSONB;
    v_updated_tickets_json JSONB;
    v_ticket_elem JSONB;
    v_product_elem JSONB;
    v_removed_price NUMERIC(10, 2);
    v_current_price NUMERIC(10, 2);
BEGIN
    -- 1. Identify all unique orders involved in this batch AND their occasion
    -- We need the occasion ID to perform the security check
    FOR v_order_id, v_occasion_id IN
        SELECT DISTINCT o.id, o.occasion
        FROM eshop.tickets t
        JOIN eshop.order_product_ticket opt ON t.id = opt.ticket
        JOIN eshop.orders o ON opt."order" = o.id
        WHERE t.id = ANY(p_ticket_ids)
    LOOP
        -- 2. SECURITY CHECK
        -- Verify that the current user has editor permissions on the occasion associated with the order.
        IF NOT public.get_is_editor_order_on_occasion(v_occasion_id) THEN
            RAISE EXCEPTION 'Permission denied to storno tickets for order % on occasion %', v_order_id, v_occasion_id;
        END IF;

        -- 3. Get all active tickets currently in this order
        SELECT ARRAY_AGG(t.id)
        INTO v_tickets_in_order
        FROM eshop.tickets t
        JOIN eshop.order_product_ticket opt ON t.id = opt.ticket
        WHERE opt."order" = v_order_id
        AND (t.state IS NULL OR t.state != 'storno');

        -- 4. Get intersection: Tickets in this order that we want to cancel
        SELECT ARRAY_AGG(id)
        INTO v_tickets_to_cancel_in_order
        FROM UNNEST(v_tickets_in_order) AS id
        WHERE id = ANY(p_ticket_ids);

        -- 5. Calculate how many would remain
        v_remaining_count := array_length(v_tickets_in_order, 1) - array_length(v_tickets_to_cancel_in_order, 1);

        -- -----------------------------------------------------
        -- SCENARIO A: Full Order Cancellation
        -- -----------------------------------------------------
        IF v_remaining_count <= 0 THEN
            -- Helper function to cancel the entire order
            PERFORM update_order_and_tickets_to_storno_ws_221(v_order_id);

        -- -----------------------------------------------------
        -- SCENARIO B: Partial Cancellation (Modify Order)
        -- -----------------------------------------------------
        ELSE
            -- 1. Mark specific tickets as storno in DB
            PERFORM internal_storno_tickets_221(v_tickets_to_cancel_in_order);

            -- 2. Fetch Order Data
            SELECT data, price INTO v_original_data, v_current_price
            FROM eshop.orders WHERE id = v_order_id;

            v_updated_tickets_json := '[]'::JSONB;
            v_removed_price := 0;

            -- 3. Rebuild JSON data, filtering out cancelled tickets and summing price to remove
            FOR v_ticket_elem IN SELECT * FROM jsonb_array_elements(v_original_data->'tickets')
            LOOP
                v_ticket_id_to_remove := (v_ticket_elem->>'id')::BIGINT;

                -- If this ticket is one of the ones being cancelled
                IF v_ticket_id_to_remove = ANY(v_tickets_to_cancel_in_order) THEN
                    -- Sum up price to deduct
                    FOR v_product_elem IN SELECT * FROM jsonb_array_elements(v_ticket_elem->'products')
                    LOOP
                        v_removed_price := v_removed_price + COALESCE((v_product_elem->>'price')::NUMERIC, 0);
                    END LOOP;
                ELSE
                    -- Keep this ticket in the new JSON
                    v_updated_tickets_json := v_updated_tickets_json || v_ticket_elem;
                END IF;
            END LOOP;

            -- 4. Update Order (Data & Price)
            UPDATE eshop.orders
            SET
                data = v_original_data || JSONB_BUILD_OBJECT('tickets', v_updated_tickets_json),
                price = GREATEST(0, COALESCE(v_current_price, 0) - v_removed_price),
                updated_at = NOW()
            WHERE id = v_order_id;

            -- 5. Insert ONE history record for this modification
            INSERT INTO eshop.orders_history (
                "order",
                data,
                state,
                price,
                created_at
            )
            VALUES (
                v_order_id,
                v_original_data || JSONB_BUILD_OBJECT('tickets', v_updated_tickets_json),
                'ordered',
                GREATEST(0, COALESCE(v_current_price, 0) - v_removed_price),
                NOW()
            );
        END IF;
    END LOOP;
END;
$$;


ALTER FUNCTION "public"."storno_tickets_bulk_internal_v1"("p_ticket_ids" bigint[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."storno_tickets_client_sync_v1"("p_tickets" bigint[], "p_command_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_actor uuid:=auth.uid(); v_occasion bigint; v_begin jsonb; v_hash text;
  v_before_users uuid[];
BEGIN
  SELECT min(t.occasion) INTO v_occasion FROM eshop.tickets t
    WHERE t.id=ANY(p_tickets);
  IF v_actor IS NULL OR v_occasion IS NULL OR cardinality(p_tickets)=0
    OR (SELECT count(*) FROM eshop.tickets t
      WHERE t.id=ANY(p_tickets) AND t.occasion=v_occasion)
      <>cardinality(ARRAY(SELECT DISTINCT id FROM unnest(p_tickets) id))
    OR NOT public.get_is_editor_order_on_occasion(v_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'tickets',p_tickets)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'inventory.tickets.cancel',v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  SELECT COALESCE(array_agg(ou."user"),'{}'::uuid[]) INTO v_before_users
    FROM public.occasion_users ou WHERE ou.occasion=v_occasion;
  PERFORM public.storno_tickets_bulk_internal_v1(p_tickets);
  RETURN public.complete_profile_inventory_membership_mutation_v1(
    p_command_id,v_occasion,'inventory.tickets.cancel',
    jsonb_build_array(jsonb_build_object('entityType','ticket','entityId',NULL,
      'operation','update','safeLabel','Ticket cancellation',
      'changedFields',jsonb_build_array('state','membership','allocations'))),
    v_before_users,jsonb_build_object('ticketIds',to_jsonb(p_tickets)));
END; $$;


ALTER FUNCTION "public"."storno_tickets_client_sync_v1"("p_tickets" bigint[], "p_command_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_event_feedback"("p_event" bigint, "p_rating" "text", "p_note" "text" DEFAULT NULL::"text", "p_client_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT public.submit_event_feedback_internal_v1(
    p_event,p_rating,p_note,p_client_id);
$$;


ALTER FUNCTION "public"."submit_event_feedback"("p_event" bigint, "p_rating" "text", "p_note" "text", "p_client_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_event_feedback_client_sync_v1"("p_occasion" bigint, "p_event" bigint, "p_rating" "text", "p_note" "text", "p_client_id" "uuid", "p_command_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_actor uuid:=auth.uid(); v_client uuid; v_begin jsonb; v_hash text;
  v_result jsonb; v_before public.event_feedback%ROWTYPE;
  v_after public.event_feedback%ROWTYPE; v_private_impacts jsonb:='[]'::jsonb;
  v_replacements jsonb:='[]'::jsonb; v_operation text;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.events e
    WHERE e.id=p_event AND e.occasion=p_occasion) THEN
    RAISE invalid_parameter_value USING MESSAGE='feedback event outside occasion'; END IF;
  v_client:=CASE WHEN v_actor IS NULL THEN p_client_id ELSE NULL END;
  IF v_actor IS NULL AND v_client IS NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='anonymous client id required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',p_occasion,'event',p_event,'rating',p_rating,'note',p_note,
    'clientId',v_client)::text,'UTF8'),'sha256'),'hex');
  IF v_actor IS NULL THEN
    v_begin:=public.begin_anonymous_client_mutation_v1(p_command_id,
      'feedback.submit',p_occasion,v_client,v_hash);
  ELSE
    v_begin:=public.begin_client_mutation_v1(p_command_id,'feedback.submit',
      p_occasion,v_actor,v_hash);
  END IF;
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  PERFORM 1 FROM public.events e WHERE e.id=p_event FOR UPDATE;
  IF v_actor IS NULL THEN
    SELECT * INTO v_before FROM public.event_feedback f
      WHERE f.event=p_event AND f."user" IS NULL AND f.client_id=v_client
      FOR UPDATE;
  ELSE
    SELECT * INTO v_before FROM public.event_feedback f
      WHERE f.event=p_event AND f."user"=v_actor FOR UPDATE;
  END IF;
  v_result:=public.submit_event_feedback_internal_v1(
    p_event,p_rating,p_note,v_client);
  IF COALESCE((v_result->>'code')::integer,500)<>200 THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',
      CASE WHEN COALESCE((v_result->>'code')::integer,400) BETWEEN 100 AND 599
        THEN (v_result->>'code')::integer ELSE 400 END,
      jsonb_build_object('message',v_result->>'message'));
  END IF;
  SELECT * INTO STRICT v_after FROM public.event_feedback f
    WHERE f.id=(v_result#>>'{data,id}')::bigint;
  IF v_before.id IS NOT NULL AND v_before.rating IS NOT DISTINCT FROM v_after.rating
      AND v_before.note IS NOT DISTINCT FROM v_after.note
      AND v_before.data IS NOT DISTINCT FROM v_after.data THEN
    UPDATE public.event_feedback SET updated_at=v_before.updated_at
      WHERE id=v_after.id;
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
      jsonb_build_object('feedback',public.get_event_feedback_command_data_v1(v_after.id)));
  END IF;
  v_operation:=CASE WHEN v_before.id IS NULL THEN 'insert' ELSE 'update' END;
  IF v_actor IS NOT NULL AND EXISTS (SELECT 1 FROM public.occasion_users ou
    WHERE ou.occasion=p_occasion AND ou."user"=v_actor) THEN
    v_private_impacts:=jsonb_build_array(jsonb_build_object(
      'component','private_feedback','userId',v_actor));
    v_replacements:=jsonb_build_array(jsonb_build_object(
      'component','private_feedback','userId',v_actor,
      'payload',public.get_private_feedback_payload_v1(p_occasion,v_actor)));
  END IF;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'feedback.submit','feedback',jsonb_build_array(jsonb_build_object(
      'entityType','event_feedback','entityId',v_after.id,'operation',v_operation,
      'safeLabel','Event feedback','changedFields',jsonb_build_array('rating','note'))),
    '{}',v_private_impacts,'[]',jsonb_build_object(
      'feedback',public.get_event_feedback_command_data_v1(v_after.id)),
    '{}','[]',CASE WHEN v_actor IS NULL THEN 'unknown' ELSE 'user' END,NULL,
    v_replacements);
END; $$;


ALTER FUNCTION "public"."submit_event_feedback_client_sync_v1"("p_occasion" bigint, "p_event" bigint, "p_rating" "text", "p_note" "text", "p_client_id" "uuid", "p_command_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_event_feedback_internal_v1"("p_event" bigint, "p_rating" "text", "p_note" "text" DEFAULT NULL::"text", "p_client_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
    v_event public.events%ROWTYPE;
    v_user UUID := auth.uid();
    v_note TEXT := NULLIF(btrim(COALESCE(p_note, '')), '');
    v_is_limited BOOLEAN;
    v_is_editor BOOLEAN;
    v_feedback public.event_feedback%ROWTYPE;
BEGIN
    IF p_rating NOT IN ('happy', 'neutral', 'sad') THEN
        RETURN jsonb_build_object('code', 400, 'message', 'Invalid rating');
    END IF;

    IF char_length(COALESCE(v_note, '')) > 2000 THEN
        RETURN jsonb_build_object('code', 413, 'message', 'Feedback text is too long');
    END IF;

    SELECT *
    INTO v_event
    FROM public.events
    WHERE id = p_event
      AND is_hidden = false;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('code', 404, 'message', 'Event not found');
    END IF;

    IF NOT public.get_is_event_allowed(p_event) THEN
        RETURN jsonb_build_object('code', 403, 'message', 'Event is not available');
    END IF;

    IF NOT public.get_is_event_feedback_enabled_on_occasion(v_event.occasion) THEN
        RETURN jsonb_build_object('code', 404, 'message', 'Feedback feature is not enabled for this occasion');
    END IF;

    IF COALESCE(v_event.data->>'feedback_enabled', 'false') <> 'true' THEN
        RETURN jsonb_build_object('code', 404, 'message', 'Feedback is not enabled for this event');
    END IF;

    v_is_editor := public.get_is_editor_view_on_occasion(v_event.occasion);

    IF now() < v_event.start_time AND NOT v_is_editor THEN
        RETURN jsonb_build_object('code', 409, 'message', 'Feedback is not open yet');
    END IF;

    v_is_limited := COALESCE(v_event.max_participants, 0) > 0;
    IF v_is_limited AND NOT v_is_editor THEN
        IF v_user IS NULL THEN
            RETURN jsonb_build_object('code', 401, 'message', 'Sign in is required for feedback on this event');
        END IF;

        IF NOT EXISTS (
            SELECT 1
            FROM public.event_users eu
            WHERE eu.event = p_event
              AND eu."user" = v_user
        ) THEN
            RETURN jsonb_build_object('code', 403, 'message', 'Only signed-in participants can rate this event');
        END IF;
    END IF;

    IF v_user IS NULL AND p_client_id IS NULL THEN
        RETURN jsonb_build_object('code', 401, 'message', 'Client id is required for anonymous feedback');
    END IF;

    IF v_user IS NOT NULL THEN
        INSERT INTO public.event_feedback (event, occasion, "user", rating, note)
        VALUES (p_event, v_event.occasion, v_user, p_rating, v_note)
        ON CONFLICT (event, "user") WHERE "user" IS NOT NULL
        DO UPDATE SET
            rating = EXCLUDED.rating,
            note = EXCLUDED.note,
            updated_at = now()
        RETURNING * INTO v_feedback;
    ELSE
        INSERT INTO public.event_feedback (event, occasion, client_id, rating, note)
        VALUES (p_event, v_event.occasion, p_client_id, p_rating, v_note)
        ON CONFLICT (event, client_id) WHERE "user" IS NULL AND client_id IS NOT NULL
        DO UPDATE SET
            rating = EXCLUDED.rating,
            note = EXCLUDED.note,
            updated_at = now()
        RETURNING * INTO v_feedback;
    END IF;

    RETURN jsonb_build_object(
        'code', 200,
        'data', jsonb_build_object(
            'id', v_feedback.id,
            'event', v_feedback.event,
            'rating', v_feedback.rating,
            'note', v_feedback.note,
            'created_at', v_feedback.created_at,
            'updated_at', v_feedback.updated_at
        )
    );
END;
$$;


ALTER FUNCTION "public"."submit_event_feedback_internal_v1"("p_event" bigint, "p_rating" "text", "p_note" "text", "p_client_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."swap_spot_tickets"("spot_id_1" bigint, "spot_id_2" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  PERFORM public.swap_spot_tickets_client_sync_v1(
    spot_id_1,spot_id_2,extensions.gen_random_uuid());
END; $$;


ALTER FUNCTION "public"."swap_spot_tickets"("spot_id_1" bigint, "spot_id_2" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."swap_spot_tickets_client_sync_v1"("p_spot_1" bigint, "p_spot_2" bigint, "p_command_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_actor uuid:=auth.uid(); v_occasion bigint; v_begin jsonb; v_hash text;
  v_users uuid[];
BEGIN
  SELECT min(s.occasion) INTO v_occasion FROM eshop.spots s
    WHERE s.id IN (p_spot_1,p_spot_2);
  IF v_actor IS NULL OR p_spot_1 IS NULL OR p_spot_2 IS NULL
    OR p_spot_1=p_spot_2 OR v_occasion IS NULL
    OR (SELECT count(*) FROM eshop.spots s
      WHERE s.id IN (p_spot_1,p_spot_2) AND s.occasion=v_occasion)<>2
    OR NOT public.get_is_editor_order_on_occasion(v_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'spot1',p_spot_1,'spot2',p_spot_2)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'inventory.spots.swap',v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  SELECT COALESCE(array_agg(DISTINCT ou."user"),'{}'::uuid[]) INTO v_users
  FROM eshop.spots s JOIN eshop.order_product_ticket opt
    ON opt.id=s.order_product_ticket JOIN public.occasion_users ou
    ON ou.ticket=opt.ticket AND ou.occasion=v_occasion
  WHERE s.id IN (p_spot_1,p_spot_2);
  PERFORM public.swap_spot_tickets_internal_v1(p_spot_1,p_spot_2);
  RETURN public.complete_private_inventory_mutation_v1(p_command_id,v_occasion,
    'inventory.spots.swap',jsonb_build_array(jsonb_build_object(
      'entityType','spot_assignment','entityId',NULL,'operation','update',
      'safeLabel','Spot ticket swap','changedFields',jsonb_build_array(
        'order_product_ticket','product'))),v_users,jsonb_build_object(
          'spotIds',jsonb_build_array(p_spot_1,p_spot_2)));
END; $$;


ALTER FUNCTION "public"."swap_spot_tickets_client_sync_v1"("p_spot_1" bigint, "p_spot_2" bigint, "p_command_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."swap_spot_tickets_internal_v1"("spot_id_1" bigint, "spot_id_2" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    spot1 RECORD;
    spot2 RECORD;
    occasion_id_common BIGINT;
    has_permission BOOLEAN;
    now_time TIMESTAMP WITH TIME ZONE := NOW();
BEGIN
    -- 1. Input Validation
    IF spot_id_1 IS NULL OR spot_id_2 IS NULL THEN
        RAISE EXCEPTION 'Both spot_id_1 and spot_id_2 must be provided' USING ERRCODE = '22023';
    END IF;
    IF spot_id_1 = spot_id_2 THEN
        RAISE EXCEPTION 'Cannot swap a spot with itself' USING ERRCODE = '22023';
    END IF;

    -- 2. Fetch Spot Data
    SELECT * INTO spot1 FROM eshop.spots WHERE id = spot_id_1;
    IF NOT FOUND THEN RAISE EXCEPTION 'Spot 1 not found (ID: %)', spot_id_1 USING ERRCODE = 'P0002'; END IF;
    SELECT * INTO spot2 FROM eshop.spots WHERE id = spot_id_2;
    IF NOT FOUND THEN RAISE EXCEPTION 'Spot 2 not found (ID: %)', spot_id_2 USING ERRCODE = 'P0002'; END IF;

    -- 3. Permission and Occasion Check
    IF spot1.occasion IS NULL OR spot2.occasion IS NULL THEN
         RAISE EXCEPTION 'Spots are missing occasion information' USING ERRCODE = '22004';
    END IF;
    IF spot1.occasion <> spot2.occasion THEN
        RAISE EXCEPTION 'Spots do not belong to the same occasion (Spot1: %, Spot2: %)', spot1.occasion, spot2.occasion USING ERRCODE = 'P0001';
    END IF;
    occasion_id_common := spot1.occasion;

    -- Check permission
    BEGIN
        SELECT get_is_editor_order_on_occasion(occasion_id_common) INTO has_permission;
    EXCEPTION
        WHEN undefined_function THEN RAISE EXCEPTION 'Permission check function get_is_editor_order_on_occasion() does not exist.' USING ERRCODE = '42883';
        WHEN OTHERS THEN RAISE EXCEPTION 'Error during permission check: %', SQLERRM;
    END;
    IF has_permission <> TRUE THEN
        RAISE EXCEPTION 'User is not authorized to edit orders for this occasion' USING ERRCODE = '42501';
    END IF;

    -- 4. Main Swap Logic: Branch based on assignment status
    -- This logic is now greatly simplified by the helper functions.

    IF spot1.order_product_ticket IS NOT NULL AND spot2.order_product_ticket IS NOT NULL THEN
        -- ----------------------------------------------------------------
        -- CASE A: BOTH SPOTS ARE ASSIGNED
        -- ----------------------------------------------------------------

        -- Ticket 1 (from spot 1) moves to Spot 2, so it must adopt Spot 2's product.
        PERFORM public._swap_spots_update_ticket(spot1.order_product_ticket, spot2.product, spot_id_2);

        -- Ticket 2 (from spot 2) moves to Spot 1, so it must adopt Spot 1's product.
        PERFORM public._swap_spots_update_ticket(spot2.order_product_ticket, spot1.product, spot_id_1);

    ELSIF spot1.order_product_ticket IS NOT NULL OR spot2.order_product_ticket IS NOT NULL THEN
        -- ----------------------------------------------------------------
        -- CASE B/C: ONE SPOT IS ASSIGNED, ONE IS UNASSIGNED
        -- ----------------------------------------------------------------

        IF spot1.order_product_ticket IS NOT NULL THEN
            -- Spot 1 is assigned, Spot 2 is unassigned.
            -- Ticket 1 moves to Spot 2 and adopts Spot 2's product.
            PERFORM public._swap_spots_update_ticket(spot1.order_product_ticket, spot2.product, spot_id_2);
        ELSE
            -- Spot 2 is assigned, Spot 1 is unassigned.
            -- Ticket 2 moves to Spot 1 and adopts Spot 1's product.
            PERFORM public._swap_spots_update_ticket(spot2.order_product_ticket, spot1.product, spot_id_1);
        END IF;

    ELSE
        -- ----------------------------------------------------------------
        -- CASE D: BOTH SPOTS ARE UNASSIGNED
        -- ----------------------------------------------------------------
        -- Nothing to do.
        RETURN;
    END IF;

    -- 5. Final Spot Update
    -- This block runs for Cases A, B, and C.
    -- We ONLY swap the 'order_product_ticket' FK. The 'product' column
    -- on the spot (spot1.product, spot2.product) never changes.
    UPDATE eshop.spots
    SET
        order_product_ticket = CASE
            WHEN id = spot_id_1 THEN spot2.order_product_ticket -- Spot 1 gets Ticket 2
            WHEN id = spot_id_2 THEN spot1.order_product_ticket -- Spot 2 gets Ticket 1
        END
    WHERE id IN (spot_id_1, spot_id_2);

END;
$$;


ALTER FUNCTION "public"."swap_spot_tickets_internal_v1"("spot_id_1" bigint, "spot_id_2" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_source_via_http"("p_target_source_name" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_source text; v_result text:='';
BEGIN
  PERFORM public.require_client_sync_service_role_v1();
  FOR v_source IN SELECT s.source_name FROM public.external_sync_sources s
    WHERE p_target_source_name IS NULL OR s.source_name=p_target_source_name
    ORDER BY s.source_name LOOP
    v_result:=v_result||CASE WHEN v_result='' THEN '' ELSE E'\n' END||
      public.sync_source_via_http_client_sync_v1(v_source);
  END LOOP;
  RETURN v_result;
END; $$;


ALTER FUNCTION "public"."sync_source_via_http"("p_target_source_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_source_via_http_client_sync_v1"("p_source_name" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_organization bigint; v_before jsonb; v_after jsonb; v_result text;
  v_changed bigint[]; v_deleted bigint[]; v_units bigint[]; v_commit public.client_commits%ROWTYPE;
  v_occasion bigint; v_unit bigint; v_revision bigint;
BEGIN
  PERFORM public.require_client_sync_service_role_v1();
  IF nullif(btrim(p_source_name),'') IS NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='one external source is required'; END IF;
  PERFORM 1 FROM public.external_sync_sources s
    WHERE s.source_name=p_source_name FOR UPDATE;
  SELECT min(m.target_org_id),array_agg(DISTINCT m.target_unit_id ORDER BY m.target_unit_id)
    INTO v_organization,v_units FROM public.external_sync_maps m
    WHERE m.source_name=p_source_name;
  IF v_organization IS NULL OR EXISTS (SELECT 1 FROM public.external_sync_maps m
      WHERE m.source_name=p_source_name AND m.target_org_id<>v_organization) THEN
    RAISE invalid_parameter_value USING MESSAGE='external source must map to one organization';
  END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('id',o.id,'unit',o.unit,
    'row',to_jsonb(o)-'updated_at') ORDER BY o.id),'[]'::jsonb) INTO v_before
    FROM public.occasions o WHERE o.external_source=p_source_name;
  v_result:=public.sync_source_via_http_internal_v1(p_source_name);
  IF v_result LIKE 'Error:%' THEN
    RAISE external_routine_exception USING MESSAGE=v_result; END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('id',o.id,'unit',o.unit,
    'row',to_jsonb(o)-'updated_at') ORDER BY o.id),'[]'::jsonb) INTO v_after
    FROM public.occasions o WHERE o.external_source=p_source_name;
  IF v_before=v_after THEN RETURN v_result; END IF;
  SELECT ARRAY(SELECT COALESCE(a.id,b.id) FROM
    jsonb_to_recordset(v_after) a(id bigint,unit bigint,row jsonb)
    FULL JOIN jsonb_to_recordset(v_before) b(id bigint,unit bigint,row jsonb)
      ON a.id=b.id WHERE a.row IS DISTINCT FROM b.row ORDER BY 1)
    INTO v_changed;
  SELECT ARRAY(SELECT b.id FROM jsonb_to_recordset(v_before)
    b(id bigint,unit bigint,row jsonb) WHERE NOT EXISTS (
      SELECT 1 FROM jsonb_to_recordset(v_after) a(id bigint,unit bigint,row jsonb)
      WHERE a.id=b.id) ORDER BY b.id) INTO v_deleted;
  SELECT ARRAY(SELECT DISTINCT unit_id FROM (
    SELECT unit unit_id FROM jsonb_to_recordset(v_before)
      b(id bigint,unit bigint,row jsonb) WHERE id=ANY(v_changed)
    UNION SELECT unit FROM jsonb_to_recordset(v_after)
      a(id bigint,unit bigint,row jsonb) WHERE id=ANY(v_changed)
  ) units WHERE unit_id IS NOT NULL ORDER BY unit_id) INTO v_units;
  INSERT INTO public.client_commits
    (organization,actor_id,actor_display,actor_kind,source,change_class,reason)
  VALUES (v_organization,NULL,NULL,'service','occasion.external_sync',
    'configuration','external source '||p_source_name) RETURNING * INTO v_commit;
  INSERT INTO public.client_commit_items
    (commit_id,item_index,entity_type,entity_id,operation,safe_label,changed_fields)
  VALUES (v_commit.commit_id,0,'external_source',p_source_name,'sync',
    left(p_source_name,240),ARRAY['occasions']);
  FOREACH v_occasion IN ARRAY v_changed LOOP
    IF v_occasion=ANY(COALESCE(v_deleted,'{}'::bigint[])) THEN
      DELETE FROM public.client_projection_dirty_keys
        WHERE scope_type='occasion' AND scope_id=v_occasion;
      DELETE FROM public.client_sync_scopes
        WHERE scope_type='occasion' AND scope_id=v_occasion;
      DELETE FROM public.client_sync_private_scopes WHERE occasion=v_occasion;
      CONTINUE;
    END IF;
    INSERT INTO public.client_sync_scopes
      (component,scope_type,scope_id,source_revision)
    VALUES ('occasion_config','occasion',v_occasion,1)
    ON CONFLICT (component,scope_type,scope_id) DO UPDATE SET
      source_revision=public.client_sync_scopes.source_revision+1,updated_at=now()
    RETURNING source_revision INTO v_revision;
    INSERT INTO public.client_commit_components
      (commit_id,component,scope_type,scope_id,user_id,resulting_revision)
    VALUES (v_commit.commit_id,'occasion_config','occasion',v_occasion,NULL,v_revision);
  END LOOP;
  FOREACH v_unit IN ARRAY COALESCE(v_units,'{}'::bigint[]) LOOP
    PERFORM public.fanout_unit_catalog_v1(v_commit.commit_id,v_unit);
  END LOOP;
  RETURN v_result;
END; $$;


ALTER FUNCTION "public"."sync_source_via_http_client_sync_v1"("p_source_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_source_via_http_internal_v1"("p_target_source_name" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
    r_source RECORD;
    r_map RECORD;
    r_occ RECORD;
    v_response extensions.http_response;
    v_body jsonb;
    v_external_link TEXT;
    v_features JSONB;
    v_local_data JSONB;
    v_remaining_places INTEGER;
    v_count INTEGER := 0;
    v_synced_ids BIGINT[];
BEGIN
    IF auth.role() <> 'service_role' AND session_user <> 'postgres' THEN
        RAISE EXCEPTION 'Access Denied: Service role required.';
    END IF;

    FOR r_source IN
        SELECT * FROM public.external_sync_sources
        WHERE (p_target_source_name IS NULL OR source_name = p_target_source_name)
    LOOP
        v_synced_ids := ARRAY[]::BIGINT[];

        FOR r_map IN SELECT * FROM public.external_sync_maps WHERE source_name = r_source.source_name
        LOOP
            SELECT * INTO v_response FROM extensions.http((
                'POST',
                format('%s/rest/v1/rpc/get_sync_occasions', r_source.supabase_url),
                ARRAY[
                    extensions.http_header('apikey', r_source.anon_key),
                    extensions.http_header('Authorization', format('Bearer %s', r_source.anon_key))
                ],
                'application/json',
                json_build_object(
                    'p_organization_id', r_map.remote_org_id,
                    'p_unit_id', r_map.remote_unit_id
                )::text
            )::extensions.http_request);

            IF v_response.status <> 200 THEN
                RAISE NOTICE 'HTTP call failed for source % map %: status=%, body=%',
                    r_source.source_name, r_map.id, v_response.status, left(v_response.content, 200);
                CONTINUE;
            END IF;

            v_body := v_response.content::jsonb;

            FOR r_occ IN
                SELECT
                    (elem->>'id')::bigint AS id,
                    elem->>'link' AS link,
                    elem->>'title' AS title,
                    elem->>'description' AS description,
                    (elem->'data') AS data,
                    (elem->>'start_time')::timestamptz AS start_time,
                    (elem->>'end_time')::timestamptz AS end_time,
                    (elem->>'is_open')::boolean AS is_open,
                    (elem->>'is_hidden')::boolean AS is_hidden,
                    (elem->>'is_promoted')::boolean AS is_promoted,
                    (elem->'features') AS features,
                    (elem->>'created_at')::timestamptz AS created_at,
                    elem->>'form_link' AS form_link
                FROM jsonb_array_elements(v_body) AS elem
            LOOP
                v_synced_ids := array_append(v_synced_ids, r_occ.id);
                v_remaining_places := (r_occ.data->>'remaining_places')::INTEGER;

                INSERT INTO public.external_occasions_cache (external_id, link, remaining_places, raw_data, last_synced_at, source_name)
                VALUES (r_occ.id, r_occ.link, v_remaining_places, row_to_json(r_occ)::jsonb, NOW(), r_source.source_name)
                ON CONFLICT (source_name, external_id) DO UPDATE SET
                    link = EXCLUDED.link,
                    remaining_places = EXCLUDED.remaining_places,
                    raw_data = EXCLUDED.raw_data,
                    last_synced_at = NOW();

                SELECT COALESCE(jsonb_agg(elem), '[]'::jsonb) INTO v_features
                FROM jsonb_array_elements(r_occ.features) elem
                WHERE elem->>'code' <> 'form';

                SELECT elem INTO v_local_data
                FROM jsonb_array_elements(r_occ.features) elem
                WHERE elem->>'code' = 'form'
                LIMIT 1;

                IF (v_local_data->>'use_external_form')::boolean = true OR
                   (v_local_data->>'formUseExternal')::boolean = true OR
                   (v_local_data->'data'->>'use_external_form')::boolean = true OR
                   (v_local_data->'data'->>'formUseExternal')::boolean = true
                THEN
                    v_external_link := COALESCE(
                        v_local_data->>'external_form_link',
                        v_local_data->>'formExternalLink',
                        v_local_data->'data'->>'external_form_link',
                        v_local_data->'data'->>'formExternalLink'
                    );
                ELSE
                    v_external_link := r_map.remote_link_base || '/form/' || COALESCE(r_occ.form_link, r_occ.link);
                END IF;

                v_features := v_features || jsonb_build_array(jsonb_build_object(
                    'code', 'form',
                    'is_enabled', true,
                    'data', jsonb_build_object(
                        'use_external_form', true,
                        'external_form_link', v_external_link
                    )
                ));

                v_local_data := r_occ.data;
                IF v_local_data IS NULL THEN v_local_data := '{}'::jsonb; END IF;
                IF v_remaining_places IS NOT NULL THEN
                    v_local_data := jsonb_set(v_local_data, '{remaining_places}', to_jsonb(v_remaining_places));
                END IF;

                INSERT INTO public.occasions (
                    link, title, description, data, start_time, end_time,
                    is_open, is_hidden, is_promoted,
                    organization, unit, features,
                    created_at, updated_at,
                    external_source, external_id
                )
                VALUES (
                    r_occ.link, r_occ.title, r_occ.description, v_local_data,
                    r_occ.start_time, r_occ.end_time,
                    r_occ.is_open, r_occ.is_hidden, r_occ.is_promoted,
                    r_map.target_org_id, r_map.target_unit_id, v_features,
                    r_occ.created_at, NOW(),
                    r_source.source_name, r_occ.id
                )
                ON CONFLICT (external_source, external_id) DO UPDATE SET
                    link = EXCLUDED.link,
                    title = EXCLUDED.title,
                    description = EXCLUDED.description,
                    data = EXCLUDED.data,
                    start_time = EXCLUDED.start_time,
                    end_time = EXCLUDED.end_time,
                    is_open = EXCLUDED.is_open,
                    is_hidden = EXCLUDED.is_hidden,
                    features = EXCLUDED.features,
                    organization = EXCLUDED.organization,
                    unit = EXCLUDED.unit,
                    updated_at = NOW();
                v_count := v_count + 1;
            END LOOP;
        END LOOP;

        IF array_length(v_synced_ids, 1) > 0 THEN
            DELETE FROM public.occasions
            WHERE external_source = r_source.source_name
              AND NOT (external_id = ANY(v_synced_ids));
            DELETE FROM public.external_occasions_cache
            WHERE source_name = r_source.source_name
              AND NOT (external_id = ANY(v_synced_ids));
        ELSE
            DELETE FROM public.occasions WHERE external_source = r_source.source_name;
            DELETE FROM public.external_occasions_cache WHERE source_name = r_source.source_name;
        END IF;
    END LOOP;

    RETURN format('Synced %s occasions from %s.', v_count, COALESCE(p_target_source_name, 'ALL Sources'));
EXCEPTION WHEN OTHERS THEN
    RETURN format('Error: %s', SQLERRM);
END;
$$;


ALTER FUNCTION "public"."sync_source_via_http_internal_v1"("p_target_source_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."synchronize_my_schedule"("p_event_ids" bigint[], "p_join_mode" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_user_id UUID := auth.uid();
    event_id BIGINT;
BEGIN
    IF NOT p_join_mode THEN
        -- If not joining, clear all existing saved events for the user
        DELETE FROM public.event_users_saved eus
        WHERE eus."user" = v_user_id;
    END IF;

    -- Insert or Upsert the provided event IDs
    -- Only proceed if p_event_ids is not null and not empty
    IF p_event_ids IS NOT NULL AND array_length(p_event_ids, 1) > 0 THEN
        IF p_join_mode THEN
            -- Join mode: Insert new events, ignore conflicts (effectively an upsert for existence)
            FOREACH event_id IN ARRAY p_event_ids
            LOOP
                INSERT INTO public.event_users_saved (event, "user")
                VALUES (event_id, v_user_id)
                ON CONFLICT (event, "user") DO NOTHING;
            END LOOP;
        ELSE
            -- Not join mode (records for the user were already deleted): Insert all provided event_ids
            INSERT INTO public.event_users_saved (event, "user")
            SELECT unnest_val, v_user_id
            FROM unnest(p_event_ids) AS unnest_val;
        END IF;
    END IF;
END;
$$;


ALTER FUNCTION "public"."synchronize_my_schedule"("p_event_ids" bigint[], "p_join_mode" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."unassign_existing_companion_client_sync_v1"("p_occasion" bigint, "p_owner" "uuid", "p_companion" "uuid", "p_command_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE v_actor uuid:=auth.uid(); v_policy jsonb; v_begin jsonb; v_hash text;
BEGIN
  v_policy:=public.get_companion_feature_policy_v1(p_occasion);
  IF v_actor IS NULL OR NOT (public.get_is_manager_on_occasion(p_occasion)
      OR public.get_is_admin_on_occasion(p_occasion)) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion manager required';
  END IF;
  IF NOT COALESCE((v_policy->>'is_enabled')::boolean,false)
      OR NOT COALESCE((v_policy->>'allow_admin_assign')::boolean,false) THEN
    RAISE insufficient_privilege USING MESSAGE='admin companion assignment disabled';
  END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,
    'owner',p_owner,'companion',p_companion)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'profile.companion.unassign',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'companion-member:'||p_occasion::text||':'||least(p_owner::text,p_companion::text),0));
  DELETE FROM public.user_companions uc WHERE uc.occasion=p_occasion
    AND uc."user"=p_owner AND uc.companion=p_companion
    AND uc.origin='admin_assigned';
  IF NOT FOUND THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
      jsonb_build_object('owner',p_owner,'companion',p_companion));
  END IF;
  RETURN public.complete_private_profile_mutation_v1(p_command_id,p_occasion,
    'profile.companion.unassign',jsonb_build_array(jsonb_build_object(
      'entityType','companion_assignment','entityId',p_companion,'operation','delete',
      'safeLabel','Companion assignment','changedFields',jsonb_build_array('owner'))),
    ARRAY[p_owner],'{}','[]',jsonb_build_object('owner',p_owner,'companion',p_companion));
END $$;


ALTER FUNCTION "public"."unassign_existing_companion_client_sync_v1"("p_occasion" bigint, "p_owner" "uuid", "p_companion" "uuid", "p_command_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_account_deletion_job"("p_request_id" "uuid", "p_auth_deleted" boolean DEFAULT NULL::boolean, "p_onesignal_deleted" boolean DEFAULT NULL::boolean, "p_error_class" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE v_request public.account_deletion_requests%ROWTYPE;
BEGIN
  PERFORM public.require_service_role();
  UPDATE public.account_deletion_requests SET
    auth_deleted=coalesce(p_auth_deleted,auth_deleted),
    onesignal_deleted=coalesce(p_onesignal_deleted,onesignal_deleted),
    error_class=p_error_class,
    status=CASE
      WHEN public_deleted AND coalesce(p_auth_deleted,auth_deleted)
        AND coalesce(p_onesignal_deleted,onesignal_deleted) THEN 'completed'
      WHEN p_error_class IS NOT NULL THEN 'failed' ELSE 'deletion_pending' END,
    completed_at=CASE
      WHEN public_deleted AND coalesce(p_auth_deleted,auth_deleted)
        AND coalesce(p_onesignal_deleted,onesignal_deleted) THEN clock_timestamp()
      ELSE completed_at END,
    user_id=CASE
      WHEN public_deleted AND coalesce(p_auth_deleted,auth_deleted)
        AND coalesce(p_onesignal_deleted,onesignal_deleted) THEN NULL ELSE user_id END,
    updated_at=clock_timestamp()
  WHERE id=p_request_id AND status IN ('deletion_pending','failed')
  RETURNING * INTO v_request;
  IF v_request.id IS NULL THEN RAISE EXCEPTION 'account_deletion_request_state_conflict' USING ERRCODE = '55000'; END IF;
  RETURN jsonb_build_object('status',v_request.status);
END;
$$;


ALTER FUNCTION "public"."update_account_deletion_job"("p_request_id" "uuid", "p_auth_deleted" boolean, "p_onesignal_deleted" boolean, "p_error_class" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_activities"("p_occasion" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    eventsData      JSONB;
    placesData      JSONB;
    activitiesData  JSONB;
    apData          JSONB;
    aeData          JSONB;
    aaData          JSONB;
    usersData       JSONB;
BEGIN

   -- Authorization check
    IF (SELECT get_is_editor_view_on_occasion(p_occasion)) <> TRUE THEN
        RETURN jsonb_build_object('code', 403, 'message', 'User is not authorized to edit this occasion');
    END IF;

    -- (a) all events (including hidden)
    SELECT jsonb_agg(jsonb_build_object(
        'id',                e.id,
        'created_at',        e.created_at,
        'title',             e.title,
        'start_time',        e.start_time,
        'end_time',          e.end_time,
        'max_participants',  e.max_participants,
        'description',       e.description,
        'place',             e.place,
        'split_for_men_women', e.split_for_men_women,
        'is_group_event',    e.is_group_event,
        'updated_at',        e.updated_at,
        'is_hidden',         e.is_hidden,
        'occasion',          e.occasion,
        'type',              e.type,
        'data',              e.data
    )) INTO eventsData
    FROM public.events e
    WHERE e.occasion = p_occasion;

    -- (b) all places for this occasion
    SELECT jsonb_agg(jsonb_build_object(
        'id',           p.id,
        'title',        p.title,
        'description',  p.description,
        'type',         p.type,
        'created_at',   p.created_at,
        'coordinates',  p.coordinates,
        'is_hidden',    p.is_hidden,
        'updated_at',   p.updated_at,
        'occasion',     p.occasion
    )) INTO placesData
    FROM public.places p
    WHERE p.occasion = p_occasion;

    -- (c) all activities
    SELECT jsonb_agg(jsonb_build_object(
        'id',           a.id,
        'created_at',   a.created_at,
        'updated_at',   a.updated_at,
        'title',        a.title,
        'description',  a.description,
        'type',         a.type,
        'occasion',     a.occasion,
        'unit',         a.unit,
        'is_hidden',    a.is_hidden,
        'order',        a.order, -- Assuming 'order' column exists in activities table
        'data',         a.data
    )) INTO activitiesData
    FROM public.activities a
    WHERE a.occasion = p_occasion;

    -- (d) activity_assignment_places links
    SELECT jsonb_agg(jsonb_build_object(
        'activity_id', ap.activity_id,
        'place_id',    ap.place_id
    )) INTO apData
    FROM public.activity_assignment_places ap
    JOIN public.activities a ON ap.activity_id = a.id
    WHERE a.occasion = p_occasion;

    -- (e) activity_assignment_events links
    SELECT jsonb_agg(jsonb_build_object(
        'activity_id', ae.activity_id,
        'event_id',    ae.event_id
    )) INTO aeData
    FROM public.activity_assignment_events ae
    JOIN public.activities a ON ae.activity_id = a.id
    WHERE a.occasion = p_occasion;

    -- (f) activity_assignments
    SELECT jsonb_agg(jsonb_build_object(
        'id',          aa.id, -- Include the assignment's own UUID
        'activity_id', aa.activity_id,
        'user_info',   aa.user_info,
        'start_time',  aa.start_time,
        'end_time',    aa.end_time,
        'title',       aa.title,
        'description', aa.description,
        'data',        aa.data
    )) INTO aaData
    FROM public.activity_assignments aa
    JOIN public.activities a ON aa.activity_id = a.id -- Join to ensure assignments are for activities of the p_occasion
    WHERE a.occasion = p_occasion;

    -- (g) users for this occasion who are volunteers
    SELECT jsonb_agg(jsonb_build_object(
        'id',        ui.id,
        'name',      ui.name,
        'surname',   ui.surname,
        'sex',       ui.sex,
        'email',     ui.email_readonly -- Aliasing email_readonly to email
        -- Add other user_info fields here if needed, matching the jsonb_build_object
    )) INTO usersData
    FROM public.user_info ui
    JOIN public.occasion_users ou ON ui.id = ou."user"
    WHERE ou.occasion = p_occasion
      AND (ou.data->>'is_volunteer')::boolean = TRUE;

    -- (h) assemble
    RETURN jsonb_build_object(
      'code', 200,
      'data', jsonb_build_object(
        'events',                  COALESCE(eventsData, '[]'::jsonb),
        'places',                  COALESCE(placesData, '[]'::jsonb),
        'activities',              COALESCE(activitiesData, '[]'::jsonb),
        'activity_places',         COALESCE(apData, '[]'::jsonb),
        'activity_events',         COALESCE(aeData, '[]'::jsonb),
        'activity_assignments',    COALESCE(aaData, '[]'::jsonb),
        'user_info',                   COALESCE(usersData, '[]'::jsonb)
      )
    );
END;
$$;


ALTER FUNCTION "public"."update_activities"("p_occasion" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_activities"("p_occasion_id" bigint, "p_activities_data" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    activity_json RECORD;
    assignment_json_record RECORD;
    v_activity_id UUID;
    place_id_val BIGINT;
    event_id_val BIGINT;
    user_uuid UUID;
    assignment_id_uuid UUID;
    is_user_on_occasion BOOLEAN;

    db_activity_ids UUID[];
    incoming_activity_ids UUID[] := ARRAY[]::UUID[];
    activity_id_to_check UUID;

    incoming_assignment_ids_for_activity UUID[];
    db_assignment_id_to_check UUID;
BEGIN
    -- Authorization check
    IF (SELECT get_is_editor_on_occasion(p_occasion_id)) <> TRUE THEN
        RETURN jsonb_build_object('code', 403, 'message', 'User is not authorized to edit this occasion');
    END IF;

    -- 1. Determine activities to delete
    SELECT array_agg(id) INTO db_activity_ids FROM public.activities WHERE occasion = p_occasion_id;
    FOR activity_json IN SELECT * FROM jsonb_array_elements(p_activities_data) LOOP
        -- The ID is now always present, generated by the client
        incoming_activity_ids := array_append(incoming_activity_ids, (activity_json.value->>'id')::UUID);
    END LOOP;

    IF array_length(db_activity_ids, 1) > 0 THEN
        FOREACH activity_id_to_check IN ARRAY db_activity_ids LOOP
            IF NOT (activity_id_to_check = ANY(incoming_activity_ids)) THEN
                DELETE FROM public.activities WHERE id = activity_id_to_check;
            END IF;
        END LOOP;
    END IF;

    -- 2. Loop through each activity in the input JSON array to upsert
    FOR activity_json IN SELECT * FROM jsonb_to_recordset(p_activities_data) AS act(
        id UUID, -- All incoming activities now have a client-generated UUID
        title TEXT,
        description TEXT,
        type TEXT,
        is_hidden BOOLEAN,
        "order" INT,
        data JSONB,
        unit BIGINT,
        assignments JSONB
    )
    LOOP
        -- MODIFIED: Replaced separate INSERT and UPDATE with a single UPSERT statement.
        -- This is more efficient and handles both cases cleanly.
        INSERT INTO public.activities (id, title, description, type, occasion, unit, is_hidden, "order", data, created_at, updated_at)
        VALUES (
            activity_json.id, activity_json.title, activity_json.description, activity_json.type, p_occasion_id,
            activity_json.unit, activity_json.is_hidden, activity_json."order", activity_json.data, now(), now()
        )
        ON CONFLICT (id) DO UPDATE SET
            title = EXCLUDED.title,
            description = EXCLUDED.description,
            type = EXCLUDED.type,
            occasion = EXCLUDED.occasion,
            unit = EXCLUDED.unit,
            is_hidden = EXCLUDED.is_hidden,
            "order" = EXCLUDED."order",
            data = EXCLUDED.data,
            updated_at = now();

        -- Set v_activity_id for use in assignment logic below.
        v_activity_id := activity_json.id;

        -- Manage activity_assignments for the current activity
        incoming_assignment_ids_for_activity := ARRAY[]::UUID[];
        IF jsonb_typeof(activity_json.assignments) = 'array' THEN
            FOR assignment_json_record IN SELECT * FROM jsonb_array_elements(activity_json.assignments) LOOP
                 IF assignment_json_record.value->>'id' IS NOT NULL THEN
                    incoming_assignment_ids_for_activity := array_append(incoming_assignment_ids_for_activity, (assignment_json_record.value->>'id')::UUID);
                 END IF;
            END LOOP;
        END IF;

        FOR db_assignment_id_to_check IN SELECT id FROM public.activity_assignments WHERE activity_id = v_activity_id LOOP
            IF NOT (db_assignment_id_to_check = ANY(incoming_assignment_ids_for_activity)) THEN
                DELETE FROM public.activity_assignments WHERE id = db_assignment_id_to_check;
            END IF;
        END LOOP;

        -- Upsert assignments and their related places/events (This logic remains the same)
        IF jsonb_typeof(activity_json.assignments) = 'array' AND jsonb_array_length(activity_json.assignments) > 0 THEN
            FOR assignment_json_record IN SELECT * FROM jsonb_to_recordset(activity_json.assignments) AS ass(
                id TEXT,
                "user" TEXT,
                start_time TIMESTAMPTZ,
                end_time TIMESTAMPTZ,
                title TEXT,
                description TEXT,
                data JSONB,
                linked_place_ids JSONB,
                linked_event_ids JSONB
            )
            LOOP
                BEGIN
                    assignment_id_uuid := assignment_json_record.id::UUID;
                    IF assignment_json_record."user" IS NOT NULL THEN
                        user_uuid := assignment_json_record."user"::UUID;
                    ELSE
                        user_uuid := NULL;
                    END IF;
                EXCEPTION
                    WHEN invalid_text_representation THEN
                        RAISE WARNING 'Invalid UUID format for assignment ID: % or user: % for activity_id: %. Skipping assignment.', assignment_json_record.id, assignment_json_record."user", v_activity_id;
                        CONTINUE;
                    WHEN others THEN
                         RAISE WARNING 'Error parsing UUIDs for assignment ID: % or user: % for activity_id: %. Error: %. Skipping assignment.', assignment_json_record.id, assignment_json_record."user", v_activity_id, SQLERRM;
                        CONTINUE;
                END;

                IF user_uuid IS NOT NULL THEN
                    SELECT EXISTS (
                        SELECT 1 FROM public.occasion_users ou
                        WHERE ou.occasion = p_occasion_id AND ou."user" = user_uuid
                    ) INTO is_user_on_occasion;

                    IF NOT is_user_on_occasion THEN
                        RAISE WARNING 'User with UUID % is not associated with occasion_id %. Skipping assignment % for activity_id %.', user_uuid, p_occasion_id, assignment_id_uuid, v_activity_id;
                        CONTINUE;
                    END IF;
                END IF;

                INSERT INTO public.activity_assignments (
                    id, activity_id, "user", start_time, end_time, title, description, data
                ) VALUES (
                    assignment_id_uuid, v_activity_id, user_uuid, assignment_json_record.start_time,
                    assignment_json_record.end_time, assignment_json_record.title,
                    assignment_json_record.description, assignment_json_record.data
                )
                ON CONFLICT (id) DO UPDATE SET
                    activity_id = EXCLUDED.activity_id, "user" = EXCLUDED."user",
                    start_time = EXCLUDED.start_time, end_time = EXCLUDED.end_time,
                    title = EXCLUDED.title, description = EXCLUDED.description, data = EXCLUDED.data;

                DELETE FROM public.activity_assignment_places WHERE assignment_id = assignment_id_uuid;
                IF jsonb_typeof(assignment_json_record.linked_place_ids) = 'array' AND jsonb_array_length(assignment_json_record.linked_place_ids) > 0 THEN
                    FOR place_id_val IN SELECT jsonb_array_elements_text(assignment_json_record.linked_place_ids)::BIGINT LOOP
                        INSERT INTO public.activity_assignment_places (assignment_id, place_id)
                        VALUES (assignment_id_uuid, place_id_val)
                        ON CONFLICT (assignment_id, place_id) DO NOTHING;
                    END LOOP;
                END IF;

                DELETE FROM public.activity_assignment_events WHERE assignment_id = assignment_id_uuid;
                IF jsonb_typeof(assignment_json_record.linked_event_ids) = 'array' AND jsonb_array_length(assignment_json_record.linked_event_ids) > 0 THEN
                    FOR event_id_val IN SELECT jsonb_array_elements_text(assignment_json_record.linked_event_ids)::BIGINT LOOP
                        INSERT INTO public.activity_assignment_events (assignment_id, event_id)
                        VALUES (assignment_id_uuid, event_id_val)
                        ON CONFLICT (assignment_id, event_id) DO NOTHING;
                    END LOOP;
                END IF;

            END LOOP;
        END IF;
    END LOOP;

    RETURN jsonb_build_object('code', 200, 'message', 'Activities saved successfully.');

EXCEPTION
    WHEN others THEN
        RETURN jsonb_build_object('code', 500, 'message', 'Error saving activities: ' || SQLERRM || '. Details: ' || SQLSTATE);
END;
$$;


ALTER FUNCTION "public"."update_activities"("p_occasion_id" bigint, "p_activities_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_bank_account"("p_id" bigint, "p_account_number" "text", "p_title" "text", "p_type" "text" DEFAULT 'FIO'::"text", "p_supported_currencies" "text"[] DEFAULT NULL::"text"[]) RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_id bigint;
BEGIN
    IF p_id IS NULL THEN
        INSERT INTO eshop.bank_accounts (account_number, title, type, supported_currencies)
        VALUES (p_account_number, p_title, p_type, p_supported_currencies)
        RETURNING id INTO v_id;
    ELSE
        UPDATE eshop.bank_accounts
        SET
            account_number = p_account_number,
            title = p_title,
            type = p_type,
            supported_currencies = p_supported_currencies
        WHERE id = p_id
        RETURNING id INTO v_id;
    END IF;
    RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."update_bank_account"("p_id" bigint, "p_account_number" "text", "p_title" "text", "p_type" "text", "p_supported_currencies" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_bank_account"("p_id" bigint, "p_account_number" "text", "p_title" "text", "p_type" "text" DEFAULT 'FIO'::"text", "p_supported_currencies" "text"[] DEFAULT NULL::"text"[], "p_account_number_human_readable" "text" DEFAULT NULL::"text", "p_unit_id" bigint DEFAULT NULL::bigint) RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_id bigint;
    v_account_number text;
BEGIN
    -- Input normalization
    v_account_number := TRIM(p_account_number);

    IF p_id IS NULL THEN
        -- Creation: If p_unit_id is provided, enforce that creator is Manager of that unit
        IF p_unit_id IS NOT NULL THEN
             PERFORM check_is_manager_on_unit(p_unit_id);
        END IF;

        -- Check for duplicate account number on insert
        IF EXISTS (SELECT 1 FROM eshop.bank_accounts WHERE account_number = v_account_number) THEN
             RAISE EXCEPTION 'ACCOUNT_NUMBER_EXISTS';
        END IF;

        INSERT INTO eshop.bank_accounts (account_number, title, type, supported_currencies, account_number_human_readable)
        VALUES (v_account_number, p_title, p_type, p_supported_currencies, p_account_number_human_readable)
        RETURNING id INTO v_id;

        -- Automatically make the creator an Admin
        INSERT INTO eshop.bank_account_users (bank_account, "user", is_admin)
        VALUES (v_id, auth.uid(), true);

        -- Automatically link to unit if provided
        IF p_unit_id IS NOT NULL THEN
             INSERT INTO eshop.unit_bank_accounts (unit, bank_account, priority)
             VALUES (p_unit_id, v_id, 0);
        END IF;
    ELSE
        -- Check for duplicate account number on update (exclude current id)
        IF EXISTS (SELECT 1 FROM eshop.bank_accounts WHERE account_number = v_account_number AND id != p_id) THEN
             RAISE EXCEPTION 'ACCOUNT_NUMBER_EXISTS';
        END IF;

        -- Security Check: Caller must be an Admin of the bank account
        IF NOT EXISTS (
            SELECT 1 FROM eshop.bank_account_users
            WHERE bank_account = p_id AND "user" = auth.uid() AND is_admin = true
        ) THEN
            RAISE EXCEPTION 'Permission denied: Only bank account admins can update details.';
        END IF;

        UPDATE eshop.bank_accounts
        SET
            account_number = v_account_number,
            title = p_title,
            type = p_type,
            supported_currencies = p_supported_currencies,
            account_number_human_readable = p_account_number_human_readable,
            updated_at = NOW()
        WHERE id = p_id
        RETURNING id INTO v_id;
    END IF;
    RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."update_bank_account"("p_id" bigint, "p_account_number" "text", "p_title" "text", "p_type" "text", "p_supported_currencies" "text"[], "p_account_number_human_readable" "text", "p_unit_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_bank_account_token"("p_bank_account_id" bigint, "p_token" "text", "p_valid_until" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_secret_id bigint;
BEGIN
    SELECT secret INTO v_secret_id FROM eshop.bank_accounts WHERE id = p_bank_account_id;

    -- Security Check: Caller must be an Admin of the bank account
    IF NOT EXISTS (
        SELECT 1 FROM eshop.bank_account_users
        WHERE bank_account = p_bank_account_id AND "user" = auth.uid() AND is_admin = true
    ) THEN
        RAISE EXCEPTION 'Permission denied: Only bank account admins can update tokens.';
    END IF;

    -- Update validity date only if explicitly provided along with token or just standalone?
    -- Logic: If token is updated, invalidates expiry unless provided.

    IF p_token IS NOT NULL AND p_token <> '' THEN
        IF v_secret_id IS NOT NULL THEN
            UPDATE eshop.secrets
            SET secret = p_token,
                created_at = now(),
                expiry_date = p_valid_until
            WHERE id = v_secret_id;

            UPDATE eshop.bank_accounts
            SET is_fetch_enabled = true,
                updated_at = NOW()
            WHERE id = p_bank_account_id;
        ELSE
            INSERT INTO eshop.secrets (secret, expiry_date)
            VALUES (p_token, p_valid_until)
            RETURNING id INTO v_secret_id;

            UPDATE eshop.bank_accounts
            SET secret = v_secret_id,
                is_fetch_enabled = true,
                updated_at = NOW()
            WHERE id = p_bank_account_id;
        END IF;
    ELSE
        -- If only updating validity date
        IF p_valid_until IS NOT NULL AND v_secret_id IS NOT NULL THEN
             UPDATE eshop.secrets
             SET expiry_date = p_valid_until
             WHERE id = v_secret_id;

             UPDATE eshop.bank_accounts
             SET is_fetch_enabled = true,
                 updated_at = NOW()
             WHERE id = p_bank_account_id;
        END IF;
    END IF;
END;
$$;


ALTER FUNCTION "public"."update_bank_account_token"("p_bank_account_id" bigint, "p_token" "text", "p_valid_until" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_bank_account_user"("p_bank_account_id" bigint, "p_user_email" "text", "p_is_admin" boolean, "p_is_support" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_user_id uuid;
BEGIN
    -- Security Check: Caller must be an Admin of the bank account
    IF NOT EXISTS (
        SELECT 1 FROM eshop.bank_account_users
        WHERE bank_account = p_bank_account_id AND "user" = auth.uid() AND is_admin = true
    ) THEN
        RAISE EXCEPTION 'Permission denied: Only bank account admins can manage users.';
    END IF;

    -- Find user by email (assuming email_readonly is populated and unique-ish for lookup)
    -- In a real app, might want a better user lookup, but this fits the pattern
    SELECT id INTO v_user_id FROM public.user_info WHERE email_readonly = p_user_email LIMIT 1;

    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'User not found';
    END IF;

    -- If both flags are false or null, remove the user
    IF (p_is_admin IS NULL OR p_is_admin = false) AND (p_is_support IS NULL OR p_is_support = false) THEN
        DELETE FROM eshop.bank_account_users
        WHERE bank_account = p_bank_account_id AND "user" = v_user_id;
    ELSE
        IF EXISTS (SELECT 1 FROM eshop.bank_account_users WHERE bank_account = p_bank_account_id AND "user" = v_user_id) THEN
            UPDATE eshop.bank_account_users
            SET is_admin = COALESCE(p_is_admin, false), is_support = COALESCE(p_is_support, false)
            WHERE bank_account = p_bank_account_id AND "user" = v_user_id;
        ELSE
            INSERT INTO eshop.bank_account_users (bank_account, "user", is_admin, is_support)
            VALUES (p_bank_account_id, v_user_id, COALESCE(p_is_admin, false), COALESCE(p_is_support, false));
        END IF;
    END IF;
END;
$$;


ALTER FUNCTION "public"."update_bank_account_user"("p_bank_account_id" bigint, "p_user_email" "text", "p_is_admin" boolean, "p_is_support" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_blueprint"("input_data" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  RETURN public.update_blueprint_client_sync_v1(
    input_data,extensions.gen_random_uuid())->'data';
END; $$;


ALTER FUNCTION "public"."update_blueprint"("input_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_blueprint_client_sync_v1"("p_blueprint" "jsonb", "p_command_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_actor uuid:=auth.uid(); v_occasion bigint; v_blueprint bigint;
  v_begin jsonb; v_hash text; v_users uuid[]; v_result jsonb;
BEGIN
  IF p_blueprint IS NULL OR jsonb_typeof(p_blueprint)<>'object'
    OR octet_length(p_blueprint::text)>8388608 THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid blueprint aggregate'; END IF;
  v_occasion:=NULLIF(p_blueprint->>'occasion','')::bigint;
  v_blueprint:=NULLIF(p_blueprint->>'id','')::bigint;
  IF v_actor IS NULL OR v_occasion IS NULL
    OR NOT public.get_is_editor_order_on_occasion(v_occasion)
    OR (v_blueprint IS NOT NULL AND NOT EXISTS (SELECT 1 FROM eshop.blueprints b
      WHERE b.id=v_blueprint AND b.occasion=v_occasion)) THEN
    RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',v_occasion,'blueprint',p_blueprint)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'inventory.blueprint.save',v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  SELECT COALESCE(array_agg(DISTINCT ou."user"),'{}'::uuid[]) INTO v_users
  FROM public.occasion_users ou JOIN eshop.order_product_ticket opt
    ON opt.ticket=ou.ticket JOIN eshop.spots s
    ON s.order_product_ticket=opt.id
  WHERE ou.occasion=v_occasion AND s.occasion=v_occasion;
  v_result:=public.update_blueprint_internal_v1(p_blueprint);
  IF COALESCE((v_result->>'code')::integer,500)<>200 THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',
      CASE WHEN COALESCE((v_result->>'code')::integer,500) BETWEEN 100 AND 599
        THEN (v_result->>'code')::integer ELSE 400 END,v_result); END IF;
  RETURN public.complete_private_inventory_mutation_v1(p_command_id,v_occasion,
    'inventory.blueprint.save',jsonb_build_array(jsonb_build_object(
      'entityType','blueprint','entityId',v_result->>'blueprint_id',
      'operation',CASE WHEN v_blueprint IS NULL THEN 'insert' ELSE 'update' END,
      'safeLabel',left(p_blueprint->>'title',240),'changedFields',jsonb_build_array(
        'spots','configuration'))),v_users,v_result);
END; $$;


ALTER FUNCTION "public"."update_blueprint_client_sync_v1"("p_blueprint" "jsonb", "p_command_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_blueprint_internal_v1"("input_data" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    blueprint_id BIGINT;
    updated_objects JSONB := '[]'::JSONB;
    object_data JSONB;
    spot_id BIGINT;
    now TIMESTAMP WITH TIME ZONE := NOW();
    spot RECORD;
    spot_ids_in_objects BIGINT[] := ARRAY[]::BIGINT[];
    existing_spot_ids BIGINT[];
    occasion_id BIGINT;
    organization_id BIGINT;
    product_id BIGINT;
    spot_title TEXT; -- Updated variable name for title
BEGIN
    -- Validate input data
    IF input_data IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('code', 4001, 'message', 'Input data is missing');
    END IF;

    -- Get occasion ID from input data
    IF input_data->>'occasion' IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('code', 4002, 'message', 'Missing occasion ID in input data');
    END IF;

    occasion_id := (input_data->>'occasion')::BIGINT;

    IF (SELECT get_is_editor_order_on_occasion(occasion_id)) <> TRUE THEN
        RETURN jsonb_build_object('code', 403, 'message', 'User is not authorized to edit this occasion');
    END IF;

    -- Get organization ID from input data
    IF input_data->>'organization' IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('code', 4003, 'message', 'Missing organization ID in input data');
    END IF;

    organization_id := (input_data->>'organization')::BIGINT;

    -- Get blueprint ID
    blueprint_id := NULLIF(input_data->>'id', '')::BIGINT;

    IF blueprint_id IS NULL THEN
        -- Create a new blueprint
        INSERT INTO eshop.blueprints (
            created_at
        )
        VALUES (
            now
        )
        RETURNING id INTO blueprint_id;
    END IF;

    -- Process objects in input_data->'objects'
    IF input_data->'objects' IS NOT NULL THEN
        FOR object_data IN SELECT * FROM JSONB_ARRAY_ELEMENTS(input_data->'objects') LOOP
            -- Handle "spot" type objects
            IF object_data->>'type' = 'spot' THEN
                -- Extract spot title
                spot_title := object_data->>'title';

                -- Validate product_id
                product_id := NULL;
                IF object_data ? 'product' AND object_data->>'product' IS NOT NULL THEN
                    product_id := (object_data->>'product')::BIGINT;

                    -- Ensure the product exists in eshop.products
                    IF NOT EXISTS (
                        SELECT 1
                        FROM eshop.products
                        WHERE id = product_id AND occasion = occasion_id
                    ) THEN
                        product_id := NULL;
                    END IF;
                END IF;

                -- Return error for invalid or missing product_id
                IF product_id IS NULL THEN
                    RETURN JSONB_BUILD_OBJECT(
                        'code', 4004,
                        'message', 'Invalid or missing product. Ensure the product exists and is part of the occasion.',
                        'details', JSONB_BUILD_OBJECT(
                            'product_id', NULL,
                            'object', object_data
                        )
                    );
                END IF;

                -- Collect spot IDs from objects
                IF object_data ? 'id' AND object_data->>'id' IS NOT NULL THEN
                    spot_ids_in_objects := spot_ids_in_objects || (object_data->>'id')::BIGINT;

                    -- Update the spot's product and title if applicable
                    UPDATE eshop.spots
                    SET
                        product = product_id,
                        title = spot_title,
                        updated_at = now
                    WHERE id = (object_data->>'id')::BIGINT;
                ELSE
                    -- Create a new spot if ID is null
                    INSERT INTO eshop.spots (
                        created_at,
                        updated_at,
                        occasion,
                        blueprint,
                        title,
                        product
                    )
                    VALUES (
                        now,
                        now,
                        occasion_id,
                        blueprint_id,
                        spot_title,
                        product_id
                    )
                    RETURNING id INTO spot_id;

                    -- Append the new spot ID to the list
                    spot_ids_in_objects := spot_ids_in_objects || spot_id;

                    -- Update the object with the new spot ID
                    object_data := jsonb_set(object_data, '{id}', TO_JSONB(spot_id));
                END IF;

                -- Remove title and product from the object before adding to updated_objects
                object_data := object_data - 'title' - 'product';
            END IF;

            -- Add updated object to the updated_objects array
            updated_objects := updated_objects || object_data;
        END LOOP;
    END IF;

    -- Get all spot IDs currently associated with the blueprint
    SELECT ARRAY_AGG(id) INTO existing_spot_ids
    FROM eshop.spots
    WHERE blueprint = blueprint_id;

    IF existing_spot_ids IS NULL THEN
        existing_spot_ids := ARRAY[]::BIGINT[];
    END IF;

    -- Identify and validate spots to delete
    FOR spot_id IN SELECT unnest(existing_spot_ids) LOOP
        IF NOT spot_id = ANY(spot_ids_in_objects) THEN
            -- Fetch the spot
            SELECT * INTO spot FROM eshop.spots WHERE id = spot_id;

            -- Check conditions for deletion
            IF (spot.secret_expiration_time IS NULL OR spot.secret_expiration_time < now OR spot.secret IS NULL)
               AND spot.order_product_ticket IS NULL THEN
                -- Safe to delete
                DELETE FROM eshop.spots WHERE id = spot.id;
            ELSE
                -- Spot cannot be deleted, return error
                RETURN JSONB_BUILD_OBJECT(
                    'code', 4031,
                    'message', 'Cannot delete spot due to invalid state',
                    'spot_id', spot.id,
                    'details', JSONB_BUILD_OBJECT(
                        'secret', spot.secret,
                        'secret_expiration_time', spot.secret_expiration_time,
                        'order_product_ticket', spot.order_product_ticket
                    )
                );
            END IF;
        END IF;
    END LOOP;

    -- Update blueprint's objects field
    UPDATE eshop.blueprints
    SET
        updated_at = now,
        data = input_data->'data',
        title = input_data->>'title',
        configuration = input_data->'configuration',
        groups = input_data->'groups',
        objects = updated_objects,
        background_svg = (input_data->>'background_svg')::TEXT,
        occasion = occasion_id,
        organization = organization_id
    WHERE id = blueprint_id;

    -- Return success response
    RETURN JSONB_BUILD_OBJECT(
        'code', 200,
        'message', 'Blueprint updated successfully',
        'blueprint_id', blueprint_id,
        'updated_objects', updated_objects
    );

EXCEPTION
    WHEN OTHERS THEN
        RETURN JSONB_BUILD_OBJECT('code', 5001, 'message', SQLERRM);
END;
$$;


ALTER FUNCTION "public"."update_blueprint_internal_v1"("input_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_email_template"("p_data" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_occ   bigint;
  v_unit  bigint;
  v_org   bigint;
  v_code  text;
  v_existing_id bigint;
BEGIN
  -- Extract values from input JSON.
  v_occ  := CASE WHEN p_data ? 'occasion' THEN (p_data ->> 'occasion')::bigint ELSE NULL END;
  v_unit := CASE WHEN p_data ? 'unit' THEN (p_data ->> 'unit')::bigint ELSE NULL END;
  -- If no organization is provided, default to 1.
  v_org  := CASE WHEN p_data ? 'organization' THEN (p_data ->> 'organization')::bigint ELSE 1 END;
  v_code := p_data ->> 'code';

  -- Permission Checks
  IF v_occ IS NOT NULL THEN
     IF (SELECT public.get_is_editor_on_occasion(v_occ)) IS NOT TRUE
        AND (SELECT public.get_is_editor_order_on_occasion(v_occ)) IS NOT TRUE THEN
        RAISE EXCEPTION 'Permission denied: User is not an editor of this occasion.';
     END IF;
  ELSIF v_unit IS NOT NULL THEN
     IF (SELECT public.get_is_editor_on_unit(v_unit)) IS NOT TRUE THEN
        RAISE EXCEPTION 'Permission denied: User is not an editor of this unit.';
     END IF;
  END IF;

  -- Try to find an existing email template matching the given context and code.
  SELECT id
    INTO v_existing_id
  FROM public.email_templates
  WHERE
    ((occasion = v_occ) OR (occasion IS NULL AND v_occ IS NULL))
    AND ((unit = v_unit) OR (unit IS NULL AND v_unit IS NULL))
    AND ((organization = v_org) OR (organization IS NULL AND v_org IS NULL))
    AND code = v_code
  LIMIT 1;

  IF FOUND THEN
    -- Update the existing record.
    UPDATE public.email_templates
    SET
      html    = p_data ->> 'html',
      subject = p_data ->> 'subject',
      title   = p_data ->> 'title'
    WHERE id = v_existing_id;
  ELSE
    -- Insert a new record.
    INSERT INTO public.email_templates (
      html,
      occasion,
      subject,
      organization,
      code,
      unit,
      title
    )
    VALUES (
      p_data ->> 'html',
      v_occ,
      p_data ->> 'subject',
      v_org,
      v_code,
      v_unit,
      p_data ->> 'title'
    );
  END IF;
END;
$$;


ALTER FUNCTION "public"."update_email_template"("p_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_entity_email_banner"("p_entity_type" "text", "p_entity_id" bigint, "p_banner_url" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
declare
    v_org_id bigint;
    v_entity_title text;
    v_new_html text;
begin
    -- 1. Validate Entity Type and Permissions
    if p_entity_type = 'occasion' then
        if (public.get_is_editor_on_occasion(p_entity_id) IS NOT TRUE
            AND public.get_is_editor_order_on_occasion(p_entity_id) IS NOT TRUE) then
            perform public.raise_error('permission_denied');
        end if;

        -- Update Occasion Data
        update public.occasions
        set data = jsonb_set(coalesce(data, '{}'), '{email_banner}', to_jsonb(p_banner_url))
        where id = p_entity_id
        returning organization, title into v_org_id, v_entity_title;

    elsif p_entity_type = 'unit' then
        if (public.get_is_editor_on_unit(p_entity_id) IS NOT TRUE) then
            perform public.raise_error('permission_denied');
        end if;

        -- Update Unit Data
        update public.units
        set data = jsonb_set(coalesce(data, '{}'), '{email_banner}', to_jsonb(p_banner_url))
        where id = p_entity_id
        returning organization, title into v_org_id, v_entity_title;

    else
        raise exception 'Invalid entity type: %', p_entity_type;
    end if;

    -- 2. Handle HTML Wrapper Logic
    if p_banner_url is not null then
        -- Construct Custom HTML
        v_new_html := '<div style="font-family: Arial, sans-serif; font-size: 16px; max-width: 680px; margin: 0 auto;">';
        v_new_html := v_new_html || '<div style="text-align: center;">';
        v_new_html := v_new_html || '<img src="' || p_banner_url || '" alt="' || coalesce(v_entity_title, 'Banner') || '" style="width: 100%; height: auto; display: block;">';
        v_new_html := v_new_html || '</div>';
        v_new_html := v_new_html || '<div style="margin-top: 10px; margin-bottom: 10px;">';
        v_new_html := v_new_html || '{{content}}';
        v_new_html := v_new_html || '</div></div>';

        -- Upsert Wrapper
        if p_entity_type = 'occasion' then
             -- For occasion, check existing wrapper
            if exists (select 1 from public.email_wrappers where occasion = p_entity_id) then
                update public.email_wrappers set html = v_new_html where occasion = p_entity_id;
            else
                insert into public.email_wrappers (occasion, organization, unit, title, html)
                values (p_entity_id, v_org_id, (select unit from occasions where id = p_entity_id), 'Occasion Banner Wrapper', v_new_html);
            end if;
        elsif p_entity_type = 'unit' then
             -- For unit (occasion is null)
            if exists (select 1 from public.email_wrappers where unit = p_entity_id and occasion is null) then
                update public.email_wrappers set html = v_new_html where unit = p_entity_id and occasion is null;
            else
                insert into public.email_wrappers (occasion, organization, unit, title, html)
                values (null, v_org_id, p_entity_id, 'Unit Banner Wrapper', v_new_html);
            end if;
        end if;
    else
        -- 3. Banner Removed -> Delete Wrapper
        if p_entity_type = 'occasion' then
            delete from public.email_wrappers where occasion = p_entity_id;
        elsif p_entity_type = 'unit' then
            delete from public.email_wrappers where unit = p_entity_id and occasion is null;
        end if;
    end if;
end;
$$;


ALTER FUNCTION "public"."update_entity_email_banner"("p_entity_type" "text", "p_entity_id" bigint, "p_banner_url" "text") OWNER TO "postgres";


