CREATE OR REPLACE FUNCTION "public"."update_product_client_sync_v1"("p_product" "jsonb", "p_command_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_actor uuid:=auth.uid(); v_product bigint; v_occasion bigint;
  v_begin jsonb; v_hash text; v_users uuid[];
BEGIN
  IF p_product IS NULL OR jsonb_typeof(p_product)<>'object'
    OR octet_length(p_product::text)>524288 THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid product aggregate'; END IF;
  v_product:=NULLIF(p_product->>'id','')::bigint;
  IF v_product IS NOT NULL THEN
    SELECT p.occasion INTO v_occasion FROM eshop.products p WHERE p.id=v_product;
  ELSE
    SELECT pt.occasion INTO v_occasion FROM eshop.product_types pt
      WHERE pt.id=NULLIF(p_product->>'product_type','')::bigint;
  END IF;
  IF v_actor IS NULL OR v_occasion IS NULL
    OR NOT public.get_is_editor_order_on_occasion(v_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',v_occasion,'product',p_product)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'inventory.product.save',v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  IF v_product IS NOT NULL THEN
    SELECT COALESCE(array_agg(DISTINCT ou."user"),'{}'::uuid[]) INTO v_users
    FROM eshop.order_product_ticket opt JOIN public.occasion_users ou
      ON ou.ticket=opt.ticket AND ou.occasion=v_occasion
    WHERE opt.product=v_product;
  ELSE v_users:='{}'::uuid[]; END IF;
  v_product:=public.update_product_internal_v1(p_product);
  RETURN public.complete_private_inventory_mutation_v1(p_command_id,v_occasion,
    'inventory.product.save',jsonb_build_array(jsonb_build_object(
      'entityType','product','entityId',v_product,'operation',
      CASE WHEN p_product->>'id' IS NULL THEN 'insert' ELSE 'update' END,
      'safeLabel',left(p_product->>'title',240),'changedFields',jsonb_build_array(
        'configuration'))),v_users,jsonb_build_object('productId',v_product));
END; $$;


ALTER FUNCTION "public"."update_product_client_sync_v1"("p_product" "jsonb", "p_command_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_product_internal_v1"("p_input" "jsonb") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_product_id BIGINT;
  v_occasion_id BIGINT;
  v_product_type_id BIGINT;
  v_existing_price NUMERIC;
  v_input_price NUMERIC;
  v_effective_price NUMERIC;
  v_input_deposit NUMERIC;
BEGIN
  -- Extract product id from the input JSON
  v_product_id := (p_input->>'id')::BIGINT;

  -- Try to find the product to determine if we are updating or creating.
  -- This also gets the *current* occasion for the permission check on UPDATE.
  IF v_product_id IS NOT NULL THEN
    SELECT pt.occasion, p.price
    INTO v_occasion_id, v_existing_price
    FROM eshop.products p
    JOIN eshop.product_types pt ON p.product_type = pt.id
    WHERE p.id = v_product_id;
  END IF;

  -- CASE 1: Product was found (v_product_id was not null and existed)
  IF FOUND THEN
    -- We are UPDATING.

    -- Ensure the caller has permission to edit this product's *current* occasion.
    -- This function is expected to raise an exception on failure.
    PERFORM public.check_is_editor_order_on_occasion(v_occasion_id);

    -- VALIDATION: deposit amount must be less than effective price (input price overrides existing)
    v_input_price := NULLIF(p_input->>'price', '')::NUMERIC;
    v_effective_price := COALESCE(v_input_price, v_existing_price);
    v_input_deposit := NULLIF(p_input->'data'->'deposit'->>'amount', '')::NUMERIC;
    IF v_input_deposit IS NOT NULL AND v_input_deposit > 0
       AND v_effective_price IS NOT NULL AND v_input_deposit >= v_effective_price THEN
      RAISE EXCEPTION '%', jsonb_build_object(
          'code', 'DEPOSIT_AMOUNT_TOO_HIGH',
          'message', 'Deposit amount (' || v_input_deposit || ') must be less than price (' || v_effective_price || ').'
      )::text;
    END IF;

    -- Update only the fields that are provided in the input JSON.
    -- COALESCE is used to keep the existing value if a new one isn't provided.
    -- NULLIF is added to safely handle empty strings '' during casting.
    UPDATE eshop.products p
    SET
      occasion      = COALESCE(NULLIF(p_input->>'occasion', '')::BIGINT, p.occasion),
      title         = COALESCE(p_input->>'title',         p.title),
      description   = COALESCE(p_input->>'description',   p.description),
      price         = COALESCE(NULLIF(p_input->>'price', '')::NUMERIC, p.price),
      currency_code = COALESCE(p_input->>'currency_code', p.currency_code),
      data          = COALESCE(p_input->'data',           p.data),
      product_type  = COALESCE(NULLIF(p_input->>'product_type', '')::BIGINT, p.product_type),
      "order"       = COALESCE(NULLIF(p_input->>'order', '')::INT,  p."order"),
      maximum       = COALESCE(NULLIF(p_input->>'maximum', '')::INT, p.maximum),
      is_hidden     = COALESCE(NULLIF(p_input->>'is_hidden', '')::BOOLEAN, p.is_hidden),
      updated_at    = NOW()
    WHERE p.id = v_product_id;

    -- Return the ID of the updated product on success.
    RETURN v_product_id;

  -- CASE 2: Product was NOT found (v_product_id was NULL or was an ID that doesn't exist)
  ELSE
    -- We are CREATING, as per the request.

    -- 1. Get the product_type from the JSON.
    v_product_type_id := (p_input->>'product_type')::BIGINT;

    -- 2. Validate product_type is provided (it's required for creation).
    IF v_product_type_id IS NULL THEN
      RAISE EXCEPTION '%', jsonb_build_object(
          'code', 'PRD422',
          'message', 'Field "product_type" is required when creating a new product.'
      )::text;
    END IF;

    -- 3. Find the occasion for the *new* product_type to check permissions.
    SELECT occasion
    INTO v_occasion_id
    FROM eshop.product_types
    WHERE id = v_product_type_id;

    -- 4. Handle invalid product_type.
    IF NOT FOUND THEN
      RAISE EXCEPTION '%', jsonb_build_object(
          'code', 'PTY404',
          'message', 'Product type with ID ' || v_product_type_id || ' not found.'
      )::text;
    END IF;

    -- 5. Ensure the caller has permission to create a product on this occasion.
    PERFORM public.check_is_editor_order_on_occasion(v_occasion_id);

    -- 6. VALIDATION: deposit amount must be less than price (both from input on CREATE)
    v_input_price := NULLIF(p_input->>'price', '')::NUMERIC;
    v_input_deposit := NULLIF(p_input->'data'->'deposit'->>'amount', '')::NUMERIC;
    IF v_input_deposit IS NOT NULL AND v_input_deposit > 0
       AND v_input_price IS NOT NULL AND v_input_deposit >= v_input_price THEN
      RAISE EXCEPTION '%', jsonb_build_object(
          'code', 'DEPOSIT_AMOUNT_TOO_HIGH',
          'message', 'Deposit amount (' || v_input_deposit || ') must be less than price (' || v_input_price || ').'
      )::text;
    END IF;

    -- 7. Insert the new product.
    -- We ignore the `id` from the JSON (v_product_id) and let the sequence generate a new one.
    -- We use NULLIF to safely cast potentially empty strings.
    INSERT INTO eshop.products (
      occasion,
      title,
      description,
      price,
      currency_code,
      data,
      product_type,
      "order",
      maximum,
      is_hidden
      -- created_at and updated_at are assumed to have defaults (e.g., NOW())
    )
    VALUES (
      v_occasion_id,
      p_input->>'title',
      p_input->>'description',
      NULLIF(p_input->>'price', '')::NUMERIC,
      p_input->>'currency_code',
      p_input->'data',
      v_product_type_id, -- We already extracted and validated this
      NULLIF(p_input->>'order', '')::INT,
      NULLIF(p_input->>'maximum', '')::INT,
      -- Default to 'false' if is_hidden is not provided on create
      COALESCE(NULLIF(p_input->>'is_hidden', '')::BOOLEAN, false)
    )
    RETURNING id INTO v_product_id; -- Get the newly created ID

    -- Return the ID of the newly created product.
    RETURN v_product_id;

  END IF;
END;
$$;


ALTER FUNCTION "public"."update_product_internal_v1"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_product_inventory_contexts"("p_product_id" bigint, "p_contexts" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  PERFORM public.update_product_inventory_contexts_client_sync_v1(
    p_product_id,p_contexts,extensions.gen_random_uuid());
END; $$;


ALTER FUNCTION "public"."update_product_inventory_contexts"("p_product_id" bigint, "p_contexts" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_product_inventory_contexts_client_sync_v1"("p_product_id" bigint, "p_contexts" "jsonb", "p_command_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_actor uuid:=auth.uid(); v_occasion bigint; v_begin jsonb; v_hash text;
  v_users uuid[];
BEGIN
  SELECT p.occasion INTO v_occasion FROM eshop.products p WHERE p.id=p_product_id;
  IF v_actor IS NULL OR v_occasion IS NULL OR p_contexts IS NULL
    OR jsonb_typeof(p_contexts)<>'array' OR jsonb_array_length(p_contexts)>1000
    OR octet_length(p_contexts::text)>1048576
    OR EXISTS (SELECT 1 FROM jsonb_array_elements(p_contexts) c
      LEFT JOIN public.inventory_contexts ic
        ON ic.id=(c->>'inventory_context_id')::bigint
      LEFT JOIN public.inventory_pools ip ON ip.id=ic.inventory_pool
      WHERE ip.occasion IS DISTINCT FROM v_occasion
        OR COALESCE((c->>'quantity')::integer,0)<0)
    OR NOT public.get_is_editor_order_on_occasion(v_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='inventory editor required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'productId',p_product_id,'contexts',p_contexts)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'inventory.product.contexts',v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  SELECT COALESCE(array_agg(DISTINCT ou."user"),'{}'::uuid[]) INTO v_users
  FROM eshop.order_product_ticket opt JOIN public.occasion_users ou
    ON ou.ticket=opt.ticket AND ou.occasion=v_occasion
  WHERE opt.product=p_product_id;
  PERFORM public.update_product_inventory_contexts_internal_v1(
    p_product_id,p_contexts);
  RETURN public.complete_private_inventory_mutation_v1(p_command_id,v_occasion,
    'inventory.product.contexts',jsonb_build_array(jsonb_build_object(
      'entityType','product_inventory_context','entityId',p_product_id,
      'operation','update','safeLabel','Product inventory contexts',
      'changedFields',jsonb_build_array('contexts'))),v_users,
    jsonb_build_object('productId',p_product_id));
END; $$;


ALTER FUNCTION "public"."update_product_inventory_contexts_client_sync_v1"("p_product_id" bigint, "p_contexts" "jsonb", "p_command_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_product_inventory_contexts_internal_v1"("p_product_id" bigint, "p_contexts" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_occasion_id BIGINT;
  v_order_id BIGINT;
BEGIN
    -- Get the occasion ID from the product that is being modified.
    SELECT pt.occasion INTO v_occasion_id
    FROM eshop.products p
    JOIN eshop.product_types pt ON p.product_type = pt.id
    WHERE p.id = p_product_id;

    -- If the product is not found, raise an error.
    IF NOT FOUND THEN
        RAISE EXCEPTION '%', jsonb_build_object(
            'code', 'PI404',
            'message', 'Product with ID ' || p_product_id || ' not found.'
        )::text;
    END IF;

    -- Permission check. This function is expected to throw on failure.
    PERFORM public.check_is_editor_order_on_occasion(v_occasion_id);

    -- If permission check passes, proceed with the update.
    -- First, remove all existing inventory context associations.
    DELETE FROM eshop.product_inventory_contexts
    WHERE product = p_product_id;

    -- Then, insert the new associations from the provided JSON array.
    IF jsonb_array_length(p_contexts) > 0 THEN
      INSERT INTO eshop.product_inventory_contexts (product, inventory_context, quantity)
      SELECT
        p_product_id,
        (context ->> 'inventory_context_id')::bigint,
        (context ->> 'quantity')::integer
      FROM jsonb_array_elements(p_contexts) AS context;
    END IF;


    -- After updating the product's context associations, re-run allocations
    -- for all orders that contain this product.
    FOR v_order_id IN
      SELECT DISTINCT opt."order"
      FROM eshop.order_product_ticket opt
      WHERE opt.product = p_product_id
    LOOP
      -- This will re-evaluate spot allocations for each affected order.
      PERFORM apply_allocations(v_order_id);
    END LOOP;

END;
$$;


ALTER FUNCTION "public"."update_product_inventory_contexts_internal_v1"("p_product_id" bigint, "p_contexts" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_resource"("p_input" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_resource_id BIGINT;
  v_occasion_id BIGINT;
  v_inventory_pool_id BIGINT;
BEGIN
  -- Extract resource and inventory pool IDs from the JSON input.
  v_resource_id := (p_input->>'id')::BIGINT;
  v_inventory_pool_id := (p_input->>'inventory_pool')::BIGINT;

  -- An inventory pool is mandatory for any create or update operation.
  IF v_inventory_pool_id IS NULL THEN
      RAISE EXCEPTION '%', jsonb_build_object('code', 'R001', 'message', 'Inventory pool is a required field.')::text;
  END IF;

  -- Derive occasion_id from the parent inventory_pool.
  SELECT p.occasion
  INTO v_occasion_id
  FROM public.inventory_pools p
  WHERE p.id = v_inventory_pool_id;

  -- Raise an error if the specified inventory pool doesn't exist.
  IF NOT FOUND THEN
      RAISE EXCEPTION '%', jsonb_build_object('code', 'R002', 'message', 'Inventory Pool with ID ' || v_inventory_pool_id || ' not found.')::text;
  END IF;

  -- Unified permission check for both create and update paths.
  -- This function is expected to throw an exception on failure.
  PERFORM public.check_is_editor_order_on_occasion(v_occasion_id);

  -- Determine whether to UPDATE an existing resource or CREATE a new one.
  IF v_resource_id IS NOT NULL THEN
    -------------------
    -- UPDATE PATH --
    -------------------
    UPDATE public.resources r
    SET
      title = COALESCE(p_input->>'title', r.title),
      capacity = COALESCE((p_input->>'capacity')::INT, r.capacity),
      booking_rules = COALESCE(p_input->'booking_rules', r.booking_rules),
      inventory_pool = v_inventory_pool_id,
      updated_at = NOW()
    WHERE r.id = v_resource_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION '%', jsonb_build_object('code', 'R003', 'message', 'Resource with ID ' || v_resource_id || ' not found.')::text;
    END IF;
  ELSE
    -------------------
    -- CREATE PATH --
    -------------------
    INSERT INTO public.resources (occasion, inventory_pool, title, capacity, booking_rules)
    VALUES (v_occasion_id, v_inventory_pool_id, p_input->>'title', (p_input->>'capacity')::INT, p_input->'booking_rules')
    RETURNING id INTO v_resource_id;
  END IF;

  -- After creating or updating the resource, synchronize the spots.
  PERFORM public.adjust_spot_capacity_for_pool(v_inventory_pool_id);

END;
$$;


ALTER FUNCTION "public"."update_resource"("p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_scan_code"("occasion_link" "text", "new_scan_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    occasion_id BIGINT;
    occasions_hidden_id BIGINT;
BEGIN
    -- 1. Retrieve occasion_id using occasion_link
    SELECT id
    INTO occasion_id
    FROM public.occasions
    WHERE link = occasion_link;

    -- 2. Check if occasion_link is valid
    IF occasion_id IS NULL THEN
        RETURN jsonb_build_object(
            'code', 404,
            'message', 'Occasion link does not exist.'
        );
    END IF;

    -- 3. Verify if the user is an editor on the occasion
    IF NOT get_is_editor_order_on_occasion(occasion_id) THEN
        RETURN jsonb_build_object(
            'code', 403,
            'message', 'User is not authorized to edit this occasion.'
        );
    END IF;

    -- 4. Check if occasions_hidden exists for the occasion
    SELECT o.occasion_hidden
    INTO occasions_hidden_id
    FROM public.occasions o
    WHERE o.id = occasion_id;

    IF occasions_hidden_id IS NOT NULL THEN
        -- Update existing scan_code
        UPDATE public.occasions_hidden
        SET secret = new_scan_code
        WHERE id = occasions_hidden_id;
    ELSE
        -- Insert new occasions_hidden record
        INSERT INTO public.occasions_hidden (secret)
        VALUES (new_scan_code)
        RETURNING id INTO occasions_hidden_id;

        -- Update the occasion to link to the new occasions_hidden
        UPDATE public.occasions
        SET occasion_hidden = occasions_hidden_id
        WHERE id = occasion_id;
    END IF;

    -- 5. Return a success message
    RETURN jsonb_build_object(
        'code', 200,
        'message', 'Scan code updated successfully.'
    );

EXCEPTION
    WHEN OTHERS THEN
        -- Handle any unexpected exceptions
        RETURN jsonb_build_object(
            'code', 500,
            'message', 'An unexpected error occurred.',
            'detail', SQLERRM
        );
END;
$$;


ALTER FUNCTION "public"."update_scan_code"("occasion_link" "text", "new_scan_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_service_item"("oc" bigint, "type" "text", "code" "text", "new_title" "text", "new_reference" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN RETURN public.update_service_item_client_sync_v1(
  oc,type,code,new_title,new_reference,extensions.gen_random_uuid())->'data'; END; $$;


ALTER FUNCTION "public"."update_service_item"("oc" bigint, "type" "text", "code" "text", "new_title" "text", "new_reference" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_service_item_client_sync_v1"("p_occasion" bigint, "p_type" "text", "p_code" "text", "p_title" "text", "p_reference" bigint, "p_command_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_actor uuid:=auth.uid(); v_begin jsonb; v_hash text; v_result jsonb;
  v_before jsonb; v_after jsonb;
BEGIN
  IF v_actor IS NULL OR p_type NOT IN ('food','accommodation')
    OR nullif(btrim(p_code),'') IS NULL OR length(p_code)>100
    OR length(COALESCE(p_title,''))>500
    OR NOT public.get_is_manager_on_occasion(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion manager required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',p_occasion,'type',p_type,'code',p_code,'title',p_title,
    'reference',p_reference)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'occasion.service.update',p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  SELECT o.services INTO v_before FROM public.occasions o
    WHERE o.id=p_occasion FOR UPDATE;
  v_result:=public.update_service_item_internal_v1(
    p_occasion,p_type,p_code,p_title,p_reference);
  IF COALESCE((v_result->>'code')::integer,500)<>200 THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',
      404,v_result); END IF;
  SELECT o.services INTO v_after FROM public.occasions o WHERE o.id=p_occasion;
  IF v_before IS NOT DISTINCT FROM v_after THEN
    RETURN public.complete_client_mutation_outcome_v1(
      p_command_id,'unchanged',200,v_result); END IF;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'occasion.service.update','configuration',jsonb_build_array(jsonb_build_object(
      'entityType','occasion_service','entityId',p_code,'operation','update',
      'safeLabel',left(p_title,240),'changedFields',jsonb_build_array('services'))),
    ARRAY['occasion_config'],'[]','[]',v_result);
END; $$;


ALTER FUNCTION "public"."update_service_item_client_sync_v1"("p_occasion" bigint, "p_type" "text", "p_code" "text", "p_title" "text", "p_reference" bigint, "p_command_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_service_item_internal_v1"("oc" bigint, "type" "text", "code" "text", "new_title" "text", "new_reference" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  updated_services JSONB;
BEGIN

  IF (SELECT get_is_manager_on_occasion(oc)) <> TRUE THEN
    RETURN jsonb_build_object('code', 403);
  END IF;

  -- Check if the code exists within the specified type
  IF NOT EXISTS (
    SELECT 1
    FROM public.occasions,
         jsonb_array_elements(occasions.services->type) AS item
    WHERE occasions.id = oc
      AND (item->>'code') = code
  ) THEN
    -- If code does not exist, return an error response
    RETURN jsonb_build_object(
      'code', 404,
      'message', 'Service item not found'
    );
  END IF;

  -- Update the specified service item
  updated_services := (
    SELECT jsonb_agg(
      CASE
        WHEN (item->>'code') = code THEN
          item || jsonb_build_object('title', new_title, 'reference', new_reference)
        ELSE
          item
      END
    )
    FROM public.occasions,
         jsonb_array_elements(occasions.services->type) AS item
    WHERE occasions.id = oc
  );

  -- Apply the updated services JSON to the specified type
  UPDATE public.occasions
  SET services = jsonb_set(
    services,
    ARRAY[type],
    updated_services,
    true
  )
  WHERE id = oc;

  -- Return success response
  RETURN jsonb_build_object(
    'code', 200,
    'message', 'Service item updated successfully'
  );
END;
$$;


ALTER FUNCTION "public"."update_service_item_internal_v1"("oc" bigint, "type" "text", "code" "text", "new_title" "text", "new_reference" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_speaker"("p_occasion" bigint, "p_speaker" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
    v_speaker_id BIGINT;
    v_row        public.speakers%ROWTYPE;
    v_title      TEXT;
BEGIN
    -- Only editors of the occasion may write speakers.
    IF NOT public.get_is_editor_on_occasion(p_occasion) THEN
        RETURN jsonb_build_object('code', 403);
    END IF;

    IF p_speaker ? 'id' AND (p_speaker->>'id') IS NOT NULL THEN
        -- UPDATE — guarded by occasion to prevent cross-occasion edits.
        v_speaker_id := (p_speaker->>'id')::BIGINT;

        UPDATE public.speakers s SET
            title       = COALESCE(p_speaker->>'title', s.title),
            subtitle    = CASE WHEN p_speaker ? 'subtitle'    THEN p_speaker->>'subtitle'              ELSE s.subtitle    END,
            description = CASE WHEN p_speaker ? 'description'  THEN p_speaker->>'description'           ELSE s.description END,
            image       = CASE WHEN p_speaker ? 'image'       THEN p_speaker->>'image'                 ELSE s.image       END,
            "order"     = CASE WHEN p_speaker ? 'order'       THEN (p_speaker->>'order')::BIGINT       ELSE s."order"     END,
            is_hidden   = CASE WHEN p_speaker ? 'is_hidden'   THEN (p_speaker->>'is_hidden')::BOOLEAN  ELSE s.is_hidden   END,
            data        = CASE WHEN p_speaker ? 'data'        THEN p_speaker->'data'                   ELSE s.data        END
        WHERE s.id = v_speaker_id AND s.occasion = p_occasion
        RETURNING s.* INTO v_row;

        IF NOT FOUND THEN
            RETURN jsonb_build_object('code', 404);
        END IF;
    ELSE
        -- INSERT — a non-empty title is required.
        v_title := p_speaker->>'title';
        IF v_title IS NULL OR btrim(v_title) = '' THEN
            RETURN jsonb_build_object('code', 400);
        END IF;

        INSERT INTO public.speakers (occasion, title, subtitle, description, image, "order", is_hidden, data)
        VALUES (
            p_occasion,
            v_title,
            p_speaker->>'subtitle',
            p_speaker->>'description',
            p_speaker->>'image',
            COALESCE((p_speaker->>'order')::BIGINT, 0),
            COALESCE((p_speaker->>'is_hidden')::BOOLEAN, FALSE),
            COALESCE(p_speaker->'data', '{}'::jsonb)
        )
        RETURNING * INTO v_row;

        v_speaker_id := v_row.id;
    END IF;

    -- Atomically replace competence links when a 'topics' array is supplied
    -- (may be empty). Only topics of this occasion are accepted; foreign or
    -- unknown ids are silently ignored.
    IF p_speaker ? 'topics' THEN
        DELETE FROM public.speaker_topic_links WHERE speaker = v_speaker_id;

        INSERT INTO public.speaker_topic_links (speaker, topic)
        SELECT v_speaker_id, t.id
        FROM public.speaker_topics t
        WHERE t.occasion = p_occasion
          AND t.id IN (
            SELECT elem::BIGINT
            FROM jsonb_array_elements_text(p_speaker->'topics') AS elem
          );
    END IF;

    RETURN jsonb_build_object(
        'code', 200,
        'data', to_jsonb(v_row) || jsonb_build_object(
            'topics', COALESCE((
                SELECT jsonb_agg(stl.topic ORDER BY stl.topic)
                FROM public.speaker_topic_links stl
                WHERE stl.speaker = v_speaker_id
            ), '[]'::jsonb)
        )
    );
END;
$$;


ALTER FUNCTION "public"."update_speaker"("p_occasion" bigint, "p_speaker" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_speaker_topic"("p_occasion" bigint, "p_topic" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
    v_topic_id BIGINT;
    v_row      public.speaker_topics%ROWTYPE;
    v_title    TEXT;
BEGIN
    -- Only editors of the occasion may write the area catalog.
    IF NOT public.get_is_editor_on_occasion(p_occasion) THEN
        RETURN jsonb_build_object('code', 403);
    END IF;

    IF p_topic ? 'id' AND (p_topic->>'id') IS NOT NULL THEN
        -- UPDATE — guarded by occasion to prevent cross-occasion edits.
        v_topic_id := (p_topic->>'id')::BIGINT;

        UPDATE public.speaker_topics t SET
            title     = COALESCE(p_topic->>'title', t.title),
            "order"   = CASE WHEN p_topic ? 'order'     THEN (p_topic->>'order')::BIGINT        ELSE t."order"   END,
            is_hidden = CASE WHEN p_topic ? 'is_hidden' THEN (p_topic->>'is_hidden')::BOOLEAN   ELSE t.is_hidden END
        WHERE t.id = v_topic_id AND t.occasion = p_occasion
        RETURNING t.* INTO v_row;

        IF NOT FOUND THEN
            RETURN jsonb_build_object('code', 404);
        END IF;
    ELSE
        -- INSERT — a non-empty title is required. Areas have no code/key; the
        -- only identifier is the hidden primary key id.
        v_title := p_topic->>'title';
        IF v_title IS NULL OR btrim(v_title) = '' THEN
            RETURN jsonb_build_object('code', 400);
        END IF;

        INSERT INTO public.speaker_topics (occasion, title, "order", is_hidden)
        VALUES (
            p_occasion,
            v_title,
            COALESCE((p_topic->>'order')::BIGINT, 0),
            COALESCE((p_topic->>'is_hidden')::BOOLEAN, FALSE)
        )
        RETURNING * INTO v_row;
    END IF;

    RETURN jsonb_build_object('code', 200, 'data', to_jsonb(v_row));
END;
$$;


ALTER FUNCTION "public"."update_speaker_topic"("p_occasion" bigint, "p_topic" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_spot"("p_spot_data" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_spot_id bigint;
    updated_spot eshop.spots;
BEGIN
    v_spot_id := (p_spot_data->>'id')::bigint;

    -- Permission checks should be added here based on your application's security model

    UPDATE eshop.spots
    SET
        title = p_spot_data->>'title',
        state = p_spot_data->>'state',
        inventory_context = (p_spot_data->>'inventory_context')::bigint,
        resource = (p_spot_data->>'resource')::bigint,
        resource_slot = (p_spot_data->>'resource_slot')::bigint
    WHERE id = v_spot_id
    RETURNING * INTO updated_spot;

    RETURN to_jsonb(updated_spot);
EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object('code', 500, 'message', SQLERRM);
END;
$$;


ALTER FUNCTION "public"."update_spot"("p_spot_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_spot_assignments"("p_changes" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  PERFORM public.update_spot_assignments_client_sync_v1(
    p_changes,extensions.gen_random_uuid());
END; $$;


ALTER FUNCTION "public"."update_spot_assignments"("p_changes" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_spot_assignments_client_sync_v1"("p_changes" "jsonb", "p_command_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_actor uuid:=auth.uid(); v_occasion bigint; v_begin jsonb; v_hash text;
  v_users uuid[]; v_spot_ids bigint[]; v_resource_ids bigint[];
BEGIN
  IF p_changes IS NULL OR jsonb_typeof(p_changes)<>'array'
    OR jsonb_array_length(p_changes)=0 OR jsonb_array_length(p_changes)>1000
    OR octet_length(p_changes::text)>1048576 THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid spot assignment batch'; END IF;
  SELECT ARRAY(SELECT DISTINCT value::bigint FROM jsonb_array_elements(p_changes) c
    CROSS JOIN LATERAL jsonb_each_text(c) e
    WHERE e.key IN ('old_spot_id','new_spot_id') AND nullif(e.value,'') IS NOT NULL),
    ARRAY(SELECT DISTINCT (c->>'resource_id')::bigint
      FROM jsonb_array_elements(p_changes) c)
    INTO v_spot_ids,v_resource_ids;
  SELECT min(r.occasion) INTO v_occasion FROM public.resources r
    WHERE r.id=ANY(v_resource_ids);
  IF v_actor IS NULL OR v_occasion IS NULL
    OR (SELECT count(DISTINCT r.occasion) FROM public.resources r
      WHERE r.id=ANY(v_resource_ids))<>1
    OR (SELECT count(*) FROM public.resources r WHERE r.id=ANY(v_resource_ids))
      <>cardinality(v_resource_ids)
    OR (SELECT count(*) FROM eshop.spots s WHERE s.id=ANY(v_spot_ids))
      <>cardinality(v_spot_ids)
    OR EXISTS (SELECT 1 FROM eshop.spots s WHERE s.id=ANY(v_spot_ids)
      AND s.occasion<>v_occasion)
    OR NOT public.get_is_editor_order_on_occasion(v_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='inventory editor required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',v_occasion,'changes',p_changes)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'inventory.spots.assign',v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  SELECT COALESCE(array_agg(DISTINCT ou."user"),'{}'::uuid[]) INTO v_users
  FROM eshop.spots s JOIN eshop.order_product_ticket opt
    ON opt.id=s.order_product_ticket JOIN public.occasion_users ou
    ON ou.ticket=opt.ticket AND ou.occasion=v_occasion
  WHERE s.id=ANY(v_spot_ids);
  PERFORM public.update_spot_assignments_internal_v1(p_changes);
  RETURN public.complete_private_inventory_mutation_v1(p_command_id,v_occasion,
    'inventory.spots.assign',jsonb_build_array(jsonb_build_object(
      'entityType','spot_assignment','entityId',NULL,'operation','update',
      'safeLabel','Spot assignments','changedFields',jsonb_build_array(
        'resource','resource_slot'))),v_users,jsonb_build_object(
          'changedCount',jsonb_array_length(p_changes)));
END; $$;


ALTER FUNCTION "public"."update_spot_assignments_client_sync_v1"("p_changes" "jsonb", "p_command_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_spot_assignments_internal_v1"("p_changes" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_change jsonb;
    v_occasion_id bigint;
    v_checked_occasion_id bigint;
    v_old_spot_id bigint;
    v_new_spot_id bigint;
    v_resource_id bigint;
    v_resource_slot_id bigint;
BEGIN
    -- Ensure the input is a valid JSON array.
    IF jsonb_typeof(p_changes) != 'array' THEN
        RAISE EXCEPTION 'Input must be a JSONB array.';
    END IF;

    -- Loop through each change object in the JSONB array.
    FOR v_change IN SELECT * FROM jsonb_array_elements(p_changes)
    LOOP
        -- Extract IDs from the current change object.
        v_old_spot_id := (v_change->>'old_spot_id')::bigint;
        v_new_spot_id := (v_change->>'new_spot_id')::bigint;
        v_resource_id := (v_change->>'resource_id')::bigint;
        v_resource_slot_id := (v_change->>'resource_slot_id')::bigint;

        -- On the first iteration, determine the occasion from the resource and check permissions.
        IF v_occasion_id IS NULL THEN
            SELECT occasion INTO v_occasion_id
            FROM public.resources
            WHERE id = v_resource_id;

            IF v_occasion_id IS NULL THEN
                RAISE EXCEPTION 'Resource with ID % not found.', v_resource_id;
            END IF;

            -- Permission check.
            IF NOT get_is_editor_order_on_occasion(v_occasion_id) THEN
                RAISE EXCEPTION 'User is not authorized to modify assignments for this occasion.';
            END IF;
        END IF;

        -- Un-assign the old spot if one was specified.
        IF v_old_spot_id IS NOT NULL THEN
            UPDATE eshop.spots
            SET
                resource = NULL,
                resource_slot = NULL,
                updated_at = now()
            WHERE id = v_old_spot_id;
        END IF;

        -- Assign the new spot to the resource/slot if one was specified.
        IF v_new_spot_id IS NOT NULL THEN
            UPDATE eshop.spots
            SET
                resource = v_resource_id,
                resource_slot = v_resource_slot_id,
                updated_at = now()
            WHERE id = v_new_spot_id;
        END IF;
    END LOOP;
END;
$$;


ALTER FUNCTION "public"."update_spot_assignments_internal_v1"("p_changes" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_ticket_note_hidden"("ticket_id" bigint, "new_note_hidden" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    occasion_id bigint;
BEGIN
    -- Retrieve the occasion_id from the ticket
    SELECT occasion INTO occasion_id FROM eshop.tickets WHERE id = ticket_id;

    -- Check if occasion_id was successfully retrieved
    IF occasion_id IS NULL THEN
        RETURN jsonb_build_object('code', 404, 'message', 'Ticket not found or occasion not specified');
    END IF;

    -- Check if the user has the right to edit the given occasion
    IF (get_is_editor_order_on_occasion(occasion_id)) <> TRUE THEN
        -- Return an error if the user is not authorized
        RETURN jsonb_build_object('code', 403, 'message', 'User is not authorized to edit this occasion');
    END IF;

    -- Proceed to update note_hidden if the user is authorized
    UPDATE eshop.tickets
    SET note_hidden = new_note_hidden, updated_at = now()
    WHERE id = ticket_id;

    -- Check if the update was successful
    IF FOUND THEN
        RETURN jsonb_build_object('code', 200, 'message', 'Update successful');
    ELSE
        RETURN jsonb_build_object('code', 404, 'message', 'Ticket not found');
    END IF;
END;
$$;


ALTER FUNCTION "public"."update_ticket_note_hidden"("ticket_id" bigint, "new_note_hidden" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_ticket_products_client_sync_v1"("p_ticket" bigint, "p_products" "jsonb", "p_command_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_actor uuid:=auth.uid(); v_occasion bigint; v_begin jsonb; v_hash text;
  v_users uuid[]; v_result jsonb;
BEGIN
  SELECT t.occasion INTO v_occasion FROM eshop.tickets t WHERE t.id=p_ticket;
  IF v_actor IS NULL OR v_occasion IS NULL OR p_products IS NULL
    OR jsonb_typeof(p_products)<>'array' OR jsonb_array_length(p_products)>1000
    OR octet_length(p_products::text)>1048576
    OR NOT public.get_is_editor_order_on_occasion(v_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'ticket',p_ticket,'products',p_products)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'inventory.ticket.products',v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  SELECT COALESCE(array_agg(ou."user"),'{}'::uuid[]) INTO v_users
    FROM public.occasion_users ou
    WHERE ou.occasion=v_occasion AND ou.ticket=p_ticket;
  v_result:=public.update_ticket_products_internal_v1(p_ticket,p_products);
  RETURN public.complete_private_inventory_mutation_v1(p_command_id,v_occasion,
    'inventory.ticket.products',jsonb_build_array(jsonb_build_object(
      'entityType','ticket_products','entityId',p_ticket,'operation','update',
      'safeLabel','Ticket products','changedFields',jsonb_build_array(
        'products','allocations'))),v_users,v_result);
END; $$;


ALTER FUNCTION "public"."update_ticket_products_client_sync_v1"("p_ticket" bigint, "p_products" "jsonb", "p_command_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_ticket_products_internal_v1"("p_ticket_id" bigint, "p_products" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'eshop', 'extensions'
    AS $_$
DECLARE
  v_order_id         bigint;
  v_occasion_id      bigint;
  v_payment_info_id  bigint;
  v_currency_code    char(3);
  v_state            text;
  v_old_data         jsonb;
  v_new_data         jsonb;
  v_sum_old          numeric := 0;
  v_sum_new          numeric := 0;
  v_diff             numeric;
  v_products_json    jsonb;
  v_old_products     jsonb;
  v_old_ids          bigint[];
  v_new_ids          bigint[];
  v_paid             numeric;
  v_price            numeric;
  v_new_state        text;
  v_occasion_features jsonb;
  v_form_settings     jsonb;
  v_deadline_duration_seconds bigint;
  v_new_deadline      timestamptz;
  v_current_products_for_compare jsonb;
BEGIN
  /* 0) Lookup & permission */
  SELECT opt."order", o.occasion, o.payment_info, o.currency_code, o.data, o.state, occ.features
    INTO v_order_id, v_occasion_id, v_payment_info_id, v_currency_code, v_old_data, v_state, v_occasion_features
  FROM eshop.order_product_ticket AS opt
  JOIN eshop.orders              AS o   ON o.id = opt."order"
  JOIN public.occasions          AS occ ON occ.id = o.occasion
  WHERE opt.ticket = p_ticket_id
  LIMIT 1;

  IF NOT FOUND THEN
    RAISE EXCEPTION '%', jsonb_build_object('code', 404, 'message', 'Ticket not linked to any order')::text;
  END IF;

  IF NOT get_is_editor_order_on_occasion(v_occasion_id) THEN
    RAISE EXCEPTION '%', jsonb_build_object('code', 403, 'message', 'Not authorized')::text;
  END IF;

  /* Check for negative prices in the input */
  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_products) AS p
    WHERE (p.value->>'price')::numeric < 0
  ) THEN
    RAISE EXCEPTION '%', jsonb_build_object('code', 400, 'message', 'Product prices cannot be negative.')::text;
  END IF;

  /* get old products for the ticket */
  SELECT jsonb_path_query_first(v_old_data, '$.tickets[*] ? (@.id == $tid).products', jsonb_build_object('tid', p_ticket_id))
  INTO v_old_products;
  v_old_products := COALESCE(v_old_products, '[]'::jsonb);

  /* compute old/new ID arrays and check for changes */
  SELECT array_agg((p->>'id')::bigint) INTO v_old_ids FROM jsonb_array_elements(v_old_products) p;
  SELECT array_agg((p->>'id')::bigint) INTO v_new_ids FROM jsonb_array_elements(p_products) p;

  -- Create a comparable representation of products (id and price)
  SELECT COALESCE(jsonb_agg(jsonb_build_object('id', p->'id', 'price', p->'price') ORDER BY (p->>'id')::int), '[]'::jsonb)
  INTO v_current_products_for_compare
  FROM jsonb_array_elements(v_old_products) p;

  -- If product sets (ID and price) are identical, bail early.
  IF v_current_products_for_compare = (
    SELECT COALESCE(jsonb_agg(jsonb_build_object('id', p->'id', 'price', p->'price') ORDER BY (p->>'id')::int), '[]'::jsonb)
    FROM jsonb_array_elements(p_products) p
  ) THEN
    RETURN jsonb_build_object('code',200,'data',v_old_data, 'message', 'No changes detected.');
  END IF;

  /* 1) old subtotal */
  SELECT COALESCE(SUM((p->>'price')::numeric), 0)
  INTO v_sum_old
  FROM jsonb_array_elements(v_old_products) AS p;

  /* 2) new products JSON + subtotal (FIXED HERE) */
  -- We now find the matching old product and merge it (||) with the new data.
  -- This preserves 'spot_title', 'spot_id' or any other extra fields.
  SELECT
    jsonb_agg(
      -- Start with the old product object if it exists (for this ID)
      COALESCE(
        (
           SELECT old_p
           FROM jsonb_array_elements(v_old_products) AS old_p
           WHERE (old_p->>'id')::bigint = p_info.id
           LIMIT 1
        ),
        '{}'::jsonb
      )
      ||
      -- Overwrite with refreshed/new standard fields
      jsonb_build_object(
        'id',            p_info.id,
        'type',          pt.type,
        'price',         (p_new.data->>'price')::numeric, -- Use price from input
        'title',         p_info.title,
        'type_title',    pt.title,
        'currency_code', p_info.currency_code
      )
    ),
    COALESCE(SUM((p_new.data->>'price')::numeric), 0)
  INTO v_products_json, v_sum_new
  FROM jsonb_array_elements(p_products) AS p_new(data)
  JOIN eshop.products           AS p_info ON p_info.id = (p_new.data->>'id')::bigint
  LEFT JOIN eshop.product_types AS pt     ON pt.id = p_info.product_type
  WHERE p_info.occasion = v_occasion_id;

  v_products_json := COALESCE(v_products_json, '[]'::jsonb);

  /* 3) rewrite just that ticket’s products array in orders.data */
  SELECT jsonb_set(
    v_old_data,
    '{tickets}',
    (
      SELECT jsonb_agg(
        CASE WHEN (tckt->>'id')::bigint = p_ticket_id
             THEN jsonb_set(tckt, '{products}', v_products_json)
             ELSE tckt
        END
      )
      FROM jsonb_array_elements(v_old_data->'tickets') AS tckt
    )
  ) INTO v_new_data;

  UPDATE eshop.orders
     SET data = v_new_data
   WHERE id = v_order_id;

  /* Update the ticket timestamp */
  UPDATE eshop.tickets
     SET updated_at = now()
   WHERE id = p_ticket_id;

  /* 4) granularly update the link‐table rows */
  v_old_ids := COALESCE(v_old_ids, ARRAY[]::bigint[]);
  v_new_ids := COALESCE(v_new_ids, ARRAY[]::bigint[]);

  -- Before deleting order_product_ticket rows, nullify the reference in eshop.spots
  UPDATE eshop.spots s
     SET order_product_ticket = NULL
  WHERE s.order_product_ticket IN (
      SELECT opt.id
      FROM eshop.order_product_ticket opt
      WHERE opt.ticket = p_ticket_id
        AND opt.product IN (SELECT unnest FROM unnest(v_old_ids) EXCEPT SELECT unnest FROM unnest(v_new_ids))
  );

  -- Delete link-table rows for products that were removed.
  DELETE FROM eshop.order_product_ticket
  WHERE ticket = p_ticket_id
    AND product IN (SELECT unnest FROM unnest(v_old_ids) EXCEPT SELECT unnest FROM unnest(v_new_ids));

  -- Insert new link-table rows for products that were added.
  INSERT INTO eshop.order_product_ticket ("order", ticket, product)
  SELECT v_order_id, p_ticket_id, new_pid
    FROM (SELECT unnest FROM unnest(v_new_ids) EXCEPT SELECT unnest FROM unnest(v_old_ids)) AS t(new_pid)
  ON CONFLICT DO NOTHING;

  /* 5) adjust payment_info.amount and order.price by the delta */
  v_diff := v_sum_new - v_sum_old;
  IF v_diff <> 0 THEN
      UPDATE eshop.payment_info
         SET amount = amount + v_diff
       WHERE id = v_payment_info_id;
      UPDATE eshop.orders
         SET price      = COALESCE(price,0) + v_diff,
             updated_at = now()
       WHERE id = v_order_id;
  END IF;

  /* 5a) decide new state based on money received */
  SELECT COALESCE(pi.paid,0), o.price
    INTO v_paid, v_price
    FROM eshop.orders o
    LEFT JOIN eshop.payment_info pi ON o.payment_info = pi.id
   WHERE o.id = v_order_id;

  v_new_state := CASE
                   WHEN v_paid >= v_price AND v_price > 0 THEN 'paid'
                   WHEN v_price <= 0 THEN 'paid'
                   ELSE 'ordered'
                 END;

  IF v_new_state = 'paid' THEN
    IF NOT EXISTS (
      SELECT 1 FROM eshop.tickets t
      JOIN eshop.order_product_ticket opt ON opt.ticket = t.id
      WHERE opt."order" = v_order_id AND t.state <> 'sent'
    ) THEN
      v_new_state := 'sent';
    END IF;
  END IF;

  UPDATE eshop.orders
     SET state      = v_new_state,
         updated_at = now()
   WHERE id = v_order_id;

  IF v_price > 0 THEN
    -- If there's a balance due, set/update the payment deadline.
    SELECT elem INTO v_form_settings
    FROM jsonb_array_elements(v_occasion_features) AS elem
    WHERE elem->>'code' = 'form';

    v_deadline_duration_seconds := COALESCE(
        (v_form_settings->>'deadline_duration_seconds')::bigint,
        604800 -- Default to 7 days (604800 seconds) if not specified
    );

    v_new_deadline := now() + make_interval(secs => v_deadline_duration_seconds);
    PERFORM public.set_payment_deadline(v_payment_info_id, v_new_deadline);
  ELSE
    -- If the order is free or paid off, clear the payment deadline.
    PERFORM public.set_payment_deadline(v_payment_info_id, NULL);
  END IF;

  PERFORM apply_allocations(v_order_id);

  /* 6) append history */
  INSERT INTO eshop.orders_history("order", data, state, price, currency_code)
  VALUES (
    v_order_id,
    v_new_data,
    v_new_state,
    (SELECT price FROM eshop.orders WHERE id = v_order_id),
    v_currency_code
  );

  RETURN jsonb_build_object('code',200,'data',v_new_data);
END;
$_$;


ALTER FUNCTION "public"."update_ticket_products_internal_v1"("p_ticket_id" bigint, "p_products" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_ticket_products_ws"("p_ticket_id" bigint, "p_product_ids" bigint[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_order_id         bigint;
  v_occasion_id      bigint;
  v_payment_info_id  bigint;
  v_currency_code    char(3);
  v_state            text;
  v_old_data         jsonb;
  v_new_data         jsonb;
  v_sum_old          numeric := 0;
  v_sum_new          numeric := 0;
  v_diff             numeric;
  v_products_json    jsonb;
  v_old_ids          bigint[];
  v_new_ids          bigint[];
  v_paid             numeric;
  v_price            numeric;
  v_new_state        text;
  v_occasion_features jsonb;
  v_form_settings     jsonb;
  v_deadline_duration_seconds bigint;
  v_new_deadline      timestamptz;
BEGIN
  /* 0) Lookup & permission */
  SELECT opt."order", o.occasion, o.payment_info, o.currency_code, o.data, o.state, occ.features
    INTO v_order_id, v_occasion_id, v_payment_info_id, v_currency_code, v_old_data, v_state, v_occasion_features
  FROM eshop.order_product_ticket AS opt
  JOIN eshop.orders              AS o   ON o.id = opt."order"
  JOIN public.occasions          AS occ ON occ.id = o.occasion
  WHERE opt.ticket = p_ticket_id
  LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('code',404,'message','Ticket not linked to any order');
  END IF;
  IF NOT get_is_editor_order_on_occasion(v_occasion_id) THEN
    RETURN jsonb_build_object('code',403,'message','Not authorized');
  END IF;

  /* compute old/new ID arrays and bail early if identical */
  SELECT array_agg((product_obj->>'id')::bigint ORDER BY (product_obj->>'id')::bigint)
    INTO v_old_ids
  FROM jsonb_array_elements(
         CASE WHEN jsonb_typeof(v_old_data->'tickets') = 'array'
              THEN v_old_data->'tickets'
              ELSE '[]'::jsonb END
       ) AS ticket(ticket_obj)
  CROSS JOIN LATERAL jsonb_array_elements(
         CASE WHEN jsonb_typeof(ticket.ticket_obj->'products') = 'array'
              THEN ticket.ticket_obj->'products'
              ELSE '[]'::jsonb END
       ) AS prod(product_obj)
  WHERE (ticket.ticket_obj->>'id')::bigint = p_ticket_id;

  SELECT array_agg(pid ORDER BY pid)
    INTO v_new_ids
  FROM unnest(p_product_ids) AS pid;

  IF v_old_ids IS NOT DISTINCT FROM v_new_ids THEN
    RETURN jsonb_build_object('code',200,'data',v_old_data);
  END IF;

  /* 1) old subtotal */
  SELECT COALESCE(SUM((product_obj->>'price')::numeric),0)
    INTO v_sum_old
  FROM jsonb_array_elements(
         CASE WHEN jsonb_typeof(v_old_data->'tickets') = 'array'
              THEN v_old_data->'tickets'
              ELSE '[]'::jsonb END
       ) AS ticket(ticket_obj)
  CROSS JOIN LATERAL jsonb_array_elements(
         CASE WHEN jsonb_typeof(ticket.ticket_obj->'products') = 'array'
              THEN ticket.ticket_obj->'products'
              ELSE '[]'::jsonb END
       ) AS prod(product_obj)
  WHERE (ticket.ticket_obj->>'id')::bigint = p_ticket_id;

  /* 2) new products JSON + subtotal */
  SELECT
    jsonb_agg(jsonb_build_object(
      'id',            p.id,
      'type',          pt.type,
      'price',         p.price,
      'title',         p.title,
      'type_title',    pt.title,
      'currency_code', p.currency_code
    )),
    COALESCE(SUM(p.price),0)
  INTO v_products_json, v_sum_new
  FROM unnest(p_product_ids) AS pid
  JOIN eshop.products           AS p  ON p.id = pid
  LEFT JOIN eshop.product_types AS pt ON pt.id = p.product_type
  WHERE p.occasion = v_occasion_id;

  /* 3) rewrite just that ticket’s products array in orders.data */
  SELECT jsonb_set(
    v_old_data,
    '{tickets}',
    COALESCE(
      (
        SELECT jsonb_agg(
          CASE WHEN (tckt->>'id')::bigint = p_ticket_id
               THEN tckt || jsonb_build_object('products', COALESCE(v_products_json, '[]'::jsonb))
               ELSE tckt
          END
        )
        FROM jsonb_array_elements(
               CASE WHEN jsonb_typeof(v_old_data->'tickets') = 'array'
                    THEN v_old_data->'tickets'
                    ELSE '[]'::jsonb END
             ) AS tckt
      ),
      '[]'::jsonb
    )
  ) INTO v_new_data;

  UPDATE eshop.orders
     SET data = v_new_data
   WHERE id = v_order_id;

  /* 4) granularly update the link‐table rows */
  UPDATE eshop.spots
     SET order_product_ticket = NULL
   WHERE order_product_ticket IN (
      SELECT opt.id
      FROM eshop.order_product_ticket opt
      WHERE opt.ticket = p_ticket_id
        AND opt.product IN (
          SELECT unnest FROM unnest(v_old_ids)
          EXCEPT
          SELECT unnest FROM unnest(p_product_ids)
        )
   );

  DELETE FROM eshop.order_product_ticket
   WHERE ticket = p_ticket_id
     AND product IN (
        SELECT unnest FROM unnest(v_old_ids)
        EXCEPT
        SELECT unnest FROM unnest(p_product_ids)
     );

  IF cardinality(p_product_ids) > 0 THEN
    DELETE FROM eshop.order_product_ticket
    WHERE ticket = p_ticket_id AND product IS NULL;
  END IF;

  INSERT INTO eshop.order_product_ticket ("order", ticket, product)
  SELECT v_order_id, p_ticket_id, new_pid
    FROM (
      SELECT unnest FROM unnest(p_product_ids)
      EXCEPT
      SELECT unnest FROM unnest(v_old_ids)
    ) AS t(new_pid);

  IF cardinality(p_product_ids) = 0 THEN
    INSERT INTO eshop.order_product_ticket("order", ticket, product)
      SELECT v_order_id, p_ticket_id, NULL
      WHERE NOT EXISTS (SELECT 1 FROM eshop.order_product_ticket WHERE ticket = p_ticket_id);
  END IF;

  /* 5) adjust payment_info.amount and order.price by the delta */
  v_diff := v_sum_new - v_sum_old;
  UPDATE eshop.payment_info
     SET amount = amount + v_diff
   WHERE id = v_payment_info_id;
  UPDATE eshop.orders
     SET price      = COALESCE(price,0) + v_diff,
         updated_at = now()
   WHERE id = v_order_id;

  /* 5a) decide new state based on money received */
  SELECT COALESCE(paid,0) INTO v_paid
    FROM eshop.payment_info
   WHERE id = v_payment_info_id;
  SELECT price INTO v_price
    FROM eshop.orders
   WHERE id = v_order_id;

  v_new_state := CASE
                   WHEN v_paid >= v_price THEN 'paid'
                   ELSE 'ordered'
                 END;

  IF v_new_state = 'paid' THEN
    IF NOT EXISTS (
      SELECT 1 FROM eshop.tickets t
      JOIN eshop.order_product_ticket opt ON opt.ticket = t.id
      WHERE opt."order" = v_order_id AND t.state <> 'sent'
    ) THEN
      v_new_state := 'sent';
    END IF;
  END IF;

  UPDATE eshop.orders
     SET state      = v_new_state,
         updated_at = now()
   WHERE id = v_order_id;

  -- if we just rolled a formerly‐paid/sent order back into 'ordered' because price increased,
  -- call the dedicated function to set a new deadline and requeue the reminder.
  IF v_new_state = 'ordered' THEN
    -- Find the 'form' feature settings to get the deadline duration
    SELECT elem INTO v_form_settings
    FROM jsonb_array_elements(v_occasion_features) AS elem
    WHERE elem->>'code' = 'form';

    -- Extract duration, with a default of 7 days (604800 seconds) if not specified
    v_deadline_duration_seconds := COALESCE(
        (v_form_settings->>'deadline_duration_seconds')::bigint,
        604800
    );

    v_new_deadline := now() + make_interval(secs => v_deadline_duration_seconds);

    -- Call the dedicated function to set the deadline and requeue the reminder
    PERFORM public.set_payment_deadline(v_payment_info_id, v_new_deadline);
  END IF;

  /* 6) append history */
  INSERT INTO eshop.orders_history("order", data, state, price, currency_code)
  VALUES (
    v_order_id,
    v_new_data,
    (SELECT state FROM eshop.orders WHERE id = v_order_id),
    v_price,
    v_currency_code
  );

  RETURN jsonb_build_object('code',200,'data',v_new_data);

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('code',500,'message',SQLERRM);
END;
$$;


