    CONSTRAINT "client_commit_items_operation_check" CHECK (("operation" = ANY (ARRAY['insert'::"text", 'update'::"text", 'delete'::"text", 'import'::"text", 'publish'::"text"])))
);


ALTER TABLE "public"."client_commit_items" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."client_commits" (
    "commit_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "occasion" bigint,
    "unit" bigint,
    "organization" bigint,
    "occurred_at" timestamp with time zone DEFAULT "clock_timestamp"() NOT NULL,
    "actor_id" "uuid",
    "actor_display" "text",
    "actor_kind" "text" NOT NULL,
    "source" "text" NOT NULL,
    "change_class" "text" NOT NULL,
    "client_version" "text",
    "correlation_id" "uuid",
    "db_role" "name" DEFAULT CURRENT_USER NOT NULL,
    "reason" "text",
    CONSTRAINT "client_commits_actor_kind_check" CHECK (("actor_kind" = ANY (ARRAY['user'::"text", 'system'::"text", 'service'::"text", 'break_glass'::"text", 'unknown'::"text"]))),
    CONSTRAINT "client_commits_check" CHECK (((((("occasion" IS NOT NULL))::integer + (("unit" IS NOT NULL))::integer) + (("organization" IS NOT NULL))::integer) = 1))
);


ALTER TABLE "public"."client_commits" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."client_mutation_receipts" (
    "command_id" "uuid" NOT NULL,
    "command_name" "text" NOT NULL,
    "occasion" bigint,
    "unit" bigint,
    "actor_id" "uuid",
    "actor_client_id" "uuid",
    "request_sha256" "text" NOT NULL,
    "status" "text" DEFAULT 'processing'::"text" NOT NULL,
    "response" "jsonb",
    "commit_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "clock_timestamp"() NOT NULL,
    "completed_at" timestamp with time zone,
    CONSTRAINT "client_mutation_receipts_check" CHECK ((((("actor_id" IS NOT NULL))::integer + (("actor_client_id" IS NOT NULL))::integer) = 1)),
    CONSTRAINT "client_mutation_receipts_check1" CHECK ((((("occasion" IS NOT NULL))::integer + (("unit" IS NOT NULL))::integer) = 1)),
    CONSTRAINT "client_mutation_receipts_check2" CHECK (((("status" = 'processing'::"text") AND ("response" IS NULL) AND ("completed_at" IS NULL)) OR (("status" = 'completed'::"text") AND ("response" IS NOT NULL) AND ("completed_at" IS NOT NULL)))),
    CONSTRAINT "client_mutation_receipts_command_name_check" CHECK (("command_name" ~ '^[a-z][a-z0-9_.]{2,95}$'::"text")),
    CONSTRAINT "client_mutation_receipts_request_sha256_check" CHECK (("request_sha256" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "client_mutation_receipts_status_check" CHECK (("status" = ANY (ARRAY['processing'::"text", 'completed'::"text"])))
);


ALTER TABLE "public"."client_mutation_receipts" OWNER TO "postgres";


